INSERT INTO steps (id, recipe_id, step_number , instruction) VALUES
(8065, 185350, 2, '加入適量鹽、薑片、大蔥、1湯匙紹興酒和擠上檸檬汁，醃20分鐘。'),
(8066, 185350, 3, '泡辣椒剁碎，雞蛋打散，備用。'),
(8067, 185350, 4, '醃好的魚片加入蛋液拌勻，將魚片均勻沾上粟粉，備用。'),
(8068, 185350, 5, '鍋中倒入油，油溫微熱時，放入魚片，煎至兩面金黃色盛出。'),
(8069, 185350, 6, '鍋中倒入油，加熱，放入泡辣椒碎，加入蔥花、薑和蒜蓉，炒香。'),
(8070, 185350, 7, '放入煎好的魚，倒入餘下紹興酒、生抽、老抽、鹽、糖和醋，炒勻，最後淋入生粉水，即成。'),
(8071, 186148, 1, '魚湯湯底：洗淨魚頭及魚骨，將魚頭及魚骨浸在鹽水30分鐘以清除多餘的血塊，瀝乾備用。'),
(8072, 186148, 2, '準備一個大鍋，用中高火燒熱鍋，加入橄欖油，加入洋蔥、西芹及蒜頭炒5分鐘至軟身。'),
(8073, 186148, 3, '加入魚頭、魚骨、月桂葉及黑胡椒粒，拌勻後煮2分鐘。'),
(8074, 186148, 4, '加入水直至蓋過所有材料，煮滾後轉小火煮45分鐘。'),
(8075, 186148, 5, '加入鹽調味，隔走所有湯渣，備用。'),
(8076, 186148, 6, '西班牙海鮮幼麵：用廚紙印乾虎蝦，用鹽和黑胡椒調味。'),
(8077, 186148, 7, '準備一個西班牙燴飯鍋或平底鍋，用中高火燒熱鍋，加入1湯匙橄欖油，加入虎蝦，每邊煎1-2分鐘或直至變成金黃色，備用。'),
(8078, 186148, 8, '用同一個鍋，加入2湯匙橄欖油，用中火中加入洋蔥、蒜蓉和番茄炒15-20分鐘至軟身。'),
(8079, 186148, 9, '加入西班牙原味香腸煮2分鐘，與此同時，將白酒倒入番紅花絲，浸透備用。'),
(8080, 186148, 10, '在鍋中加入麵條並拌勻，煮3分鐘直至麵條與其他食材充分拌勻；加入西班牙甜紅椒粉。'),
(8081, 186148, 11, '加入預先浸有番紅花絲的白酒，拌勻並煮至白酒完全揮發，加入蜆。'),
(8082, 186148, 12, '倒入魚湯，份量要浸過麵條及蜆；煮滾後轉中火煮10分鐘，直至湯汁完全被食材吸收。過程中略為攪拌，以防麵條粘在鍋底上。'),
(8083, 186148, 13, '如果湯汁蒸發得太快，可以加入適量魚湯，煮至蜆開口煮熟。'),
(8084, 186148, 14, '當所有蜆開口煮熟及大部分湯汁收乾後，加入虎蝦煮4分鐘或直至虎蝦煮熟，加入鹽和黑胡椒調味。'),
(8085, 186148, 15, '熄火，灑上番茜碎及放上切好的檸檬裝飾，即成。'),
(8086, 186127, 1, '雞肉用海鹽和白胡椒醃最少30分鐘'),
(8087, 186127, 2, '海蜇用水沖洗表面鹽份，再用清水浸半個鐘，以助除掉海蜇鹹味'),
(8088, 186127, 3, '將海蜇摺疊或捲起切絲'),
(8089, 186127, 4, '於滾水內加薑和蔥，再將海蜇汆水約2分鐘，撈起'),
(8090, 186127, 5, '用凍水浸海蜇約1小時（期間可放入雪櫃）讓海蜇發漲'),
(8091, 186127, 6, '於滾水內加薑和蔥，再加入雞脾，用大火煮5分鐘，熄火，再蓋蓋焗20分鐘'),
(8092, 186127, 7, '紅蘿蔔去皮切幼絲，青瓜去籽切幼絲，蔥切成粒備用'),
(8093, 186127, 8, '雞脾放涼後可手撕備用'),
(8094, 186127, 9, '海蜇發漲後撈起，用廚房紙印乾表面水份'),
(8095, 186127, 10, '將雞粉、麻油、白醋、糖與海蜇撈勻，再加入青瓜、紅蘿蔔同雞絲拌勻'),
(8096, 186127, 11, '最後灑上蔥花和芝麻即成'),
(8097, 186126, 1, '將洋蔥切件；甘筍去皮切件；蘑菇切片；蒜頭拍扁；蘋果及薯仔去皮切粒備用。'),
(8098, 186126, 2, '將牛肋條切件，用廚房紙印乾後加鹽和黑胡椒調味。'),
(8099, 186126, 3, '在Lagostina高速煲（7公升）內加入橄欖油加熱，放入牛肋條煎至金黃色，取出備用。'),
(8100, 186126, 4, '加入洋蔥、甘筍、蘑菇及蒜頭，炒2分鐘。'),
(8101, 186126, 5, '加入番茄膏、月桂葉及麵粉炒勻，煮1分鐘。'),
(8102, 186126, 6, '倒入黑啤，拌勻至醬汁幼滑。'),
(8103, 186126, 7, '加入牛肉湯、牛肋條、百里香及迷迭香，用鹽、糖及黑胡椒調味。'),
(8104, 186126, 8, '關上高速煲蓋，調至高壓模式。以大火烹煮至「紅色壓力指示針」升起，及從壓力閥開始發出嘶嘶聲算起，改以中火烹煮15分鐘，排氣即成。'),
(8105, 186126, 9, '當牛肋條在烹煮時，在另一Lagostina高速煲（7公升）內，加入2杯水。將切好的蘋果及薯仔放入蒸架內，然後放入高速煲。'),
(8106, 186126, 10, '關上高速煲蓋，調至高壓模式。以大火烹煮8分鐘。'),
(8107, 186126, 11, '排氣後，將蒸至腍身的蘋果及薯仔取出，放入大碗內壓成蓉，加入鹽、黑胡椒及牛油拌勻，再加入牛奶拌至幼滑。'),
(8108, 186126, 12, '將蘋果薯蓉上碟，放上牛肋條及醬汁，灑上番茜碎，即成。'),
(8109, 186125, 1, '先將魚鰾用水浸大約20-30分鐘。'),
(8110, 186125, 2, '見呈海綿狀態，沖洗乾淨切件，備用。'),
(8111, 186125, 3, '沖菜洗乾淨切絲，備用。'),
(8112, 186125, 4, '排骨汆水，見浮起污糟泡泡後，將排骨沖洗乾淨。'),
(8113, 186125, 5, '水滾後放入排骨。'),
(8114, 186125, 6, '浸泡之乾瑤柱用中大火煲20分鐘。'),
(8115, 186125, 7, '之後加入魚鰾。'),
(8116, 186125, 8, '加入沖菜。'),
(8117, 186125, 9, '加入蔥段。'),
(8118, 186125, 10, '加入大地魚粉，繼續煲15分鐘。'),
(8119, 186125, 11, '最後可按個人口味加入鹽，但沖菜已有鹹味，建議無需添加。'),
(8120, 186128, 1, '準備一個鍋，加入地瓜粉、黑糖粉及清水拌勻。'),
(8121, 186128, 2, '用中火邊煮邊攪拌至開始濃稠，轉中低火煮至成呈透明的泥狀。'),
(8122, 186128, 3, '將麵糊倒入已掃油的蒸模，用中低火蒸15-20分鐘。'),
(8123, 186128, 4, '放涼後脫模切件，沾上黃豆粉，即成。'),
(8124, 186129, 1, '將泰國糯米浸洗3小時。瀝乾備用。'),
(8125, 186129, 2, '預備拌飯椰漿。將椰漿 、鹽及細砂糖用中火煮至微滾備用。'),
(8126, 186129, 3, '預備一個已掃油的蒸碟，放上糯米，用中高火蒸30-35分鐘。'),
(8127, 186129, 4, '趁熱拌入椰漿，蓋上保鮮紙靜置15分鐘。'),
(8128, 186129, 5, '預備淋面椰漿。將準備一個鍋，加入椰漿、細砂糖及粘米粉不斷攪拌，用中火煮至濃稠。'),
(8129, 186129, 6, '糯米飯上碟，放上芒果肉及淋上椰漿，即成。'),
(8130, 186130, 1, '煮滾1000毫升水，加入西米煮6-8分鐘，熄火，蓋上鍋蓋焗25分鐘，過冷河備用。'),
(8131, 186130, 2, '將紫薯蓉搓成球狀後壓扁備用。'),
(8132, 186130, 3, '將馬蹄粉及清水拌勻，加入砂糖拌勻，加入西米及菜油拌勻。'),
(8133, 186130, 4, '將模具掃上油，加入西米糊至6成滿，加入紫薯蓉，再加入西米糊鋪平。'),
(8134, 186130, 5, '用中高火蒸10-12分鐘至呈透明，脫模即成。'),
(8135, 185441, 1, '芫茜及辣椒切碎備用。'),
(8136, 185441, 2, '擠出青檸汁，備用。'),
(8137, 185441, 3, '3/4的青檸汁加入魚露及辣椒拌勻，調成蘸料汁。'),
(8138, 185441, 4, '蝦去頭尾，去殼，只留蝦肉，用刀身將蝦肉剁成蝦蓉。'),
(8139, 185441, 5, '加入芫茜、蛋清、餘下的青檸汁、生粉、胡椒粉和鹽，拌至起筋，冷藏15分鐘。'),
(8140, 185441, 6, '取出冷藏好的蝦蓉，搓成小餅狀，每一個都均勻粘滿麵包糠。'),
(8141, 185441, 7, '平底鍋放入油，油溫微熱時，放入蝦餅，用中小火煎至兩面金黃色及熟透。'),
(8142, 185441, 8, '搭配調好的蘸料汁，即成。'),
(8143, 185455, 1, '酸菜洗淨瀝乾切碎，煙肉切小片，蔥切成蔥花。'),
(8144, 185455, 2, '鍋中倒入油，加熱，放入煙肉用中小火煎至上色。'),
(8145, 185455, 3, '倒入蔥花和酸菜，中火炒1分鐘，放入雜豆和白飯。'),
(8146, 185455, 4, '炒至白飯粒鬆散，倒入生抽，炒勻即成。'),
(8147, 186139, 1, '將嫩豆腐、香蕉一起放進滾水裡煮30秒，之後搗碎。'),
(8148, 186139, 2, '把嫩豆腐混合物和蛋黃放進容器裡拌勻。'),
(8149, 186139, 3, '等蒸鍋裡的水滾了以後，把布甸混合物放進去，轉小火蒸20分鐘。'),
(8150, 186015, 1, '預熱焗爐至攝氏220度。將士多啤梨切片。'),
(8151, 186015, 2, '士多啤梨丶砂糖和粟粉拌勻成內餡，備用。'),
(8152, 186015, 3, '將雞蛋打發成蛋液。'),
(8153, 186015, 4, '用叉子在酥皮上戳洞。'),
(8154, 186015, 5, '酥皮邊緣預留約3cm作批邊，把士多啤梨餡放在中央位置，將批皮向內摺。'),
(8155, 186015, 6, '然後掃上一層蛋液，再灑上適量砂糖。'),
(8156, 186015, 7, '放入焗爐焗15分鐘，取出後灑上糖霜，即成。'),
(8157, 186086, 1, '撻皮食譜：牛油加糖打至發白, 加蛋黃及蛋白打勻'),
(8158, 186086, 2, '篩入低筋粉拌勻至成團'),
(8159, 186086, 3, '撻皮團放入雪櫃冰格急凍15-20分鐘，同時預熱焗爐180度'),
(8160, 186086, 4, '取出撻皮團分成6份，壓入撻皮模'),
(8161, 186086, 5, '用牛油紙相隔,擺入紅豆壓著撻皮 放入焗爐焗10分鐘, 取出牛油紙及紅豆繼續焗5分鐘至金黃，取出放涼'),
(8162, 186086, 6, '餡料A (芝士餡)：忌廉芝士回溫放軟，把忌廉芝士、淡忌廉、原味乳酪、煉奶放入搞拌機搞拌至滑身'),
(8163, 186086, 7, '分成3份，一份加入抺茶粉拌勻，一份加入竹炭粉拌勻'),
(8164, 186086, 8, '將餡料A放入撻皮中'),
(8165, 186086, 9, '餡料B (朱古力餡)：朱古力及淡忌廉隔熱水(約40-50度)座溶至滑身'),
(8166, 186086, 10, '放入撻皮中'),
(8167, 186086, 11, '裝飾部份：座溶朱古力；放入朱古力圓片作眼晴；朱古力放入唧袋畫上卡通公仔造型'),
(8168, 186074, 1, '小丸子做法：先把所有材料全倒入大盆中。'),
(8169, 186074, 2, '用匙攪拌成團，再用手搓直至麵團光滑。'),
(8170, 186074, 3, '芒果丸子也是同樣做法，只是用芒果汁取代水分。'),
(8171, 186074, 4, '未煮時用保鮮紙蓋住，避免抽乾水分。'),
(8172, 186074, 5, '煲滾水後，加入搓好的小丸子煮。開頭半分鐘用大匀攪拌，讓丸子們不會黏著和黏鍋底。'),
(8173, 186074, 6, '用中大火煮，一浮起，即可撈起。放進冰水浸10分鐘，瀝乾備用。'),
(8174, 186074, 7, '淡忌廉糖水做法：用熱水把糖融化，放置一旁，令溫度降暖。'),
(8175, 186074, 8, '然後加入淡忌廉拌匀，糖水即成，放入雪櫃雪凍。'),
(8176, 186074, 9, '西米做法：西米預先浸水半小時，水的高度浸過西米高少許。'),
(8177, 186074, 10, '煲一大煲滾水，加入浸好的西米。然後用中大火煮，要不時攪拌以防痴底。'),
(8178, 186074, 11, '煮至西米中間只剩下一小白點後，關火蓋上焗10-15分鐘。用餘溫令到西米熟透。'),
(8179, 186074, 12, '西米煮好後，即可撈起放進冰水浸10分鐘。瀝乾後加入淡忌廉糖水中。'),
(8180, 186074, 13, '組裝：把西米露倒入碗中，放入小丸子。'),
(8181, 186074, 14, '芒果起肉切粒，放上西米露中。'),
(8182, 186074, 15, '放上一球雪糕並撒上杏仁碎，即成。'),
(8183, 186065, 1, '將酸梅去核及壓碎；蔥一半切段、一半切粒；蒜頭拍扁；辣椒切絲；橙刨皮及榨汁備用。'),
(8184, 186065, 2, '鴨件用生抽、老抽及砂糖醃30分鐘備用。'),
(8185, 186065, 3, '用中高火燒熱Lagostina煎鍋，加少許油，將鴨件煎至金黃色，上碟備用，鴨油倒入碗內備用。'),
(8186, 186065, 4, '在煎鍋內加入100毫升水煮滾，大約2分鐘，熄火，將醬汁備用。'),
(8187, 186065, 5, '在Lagostina高速煲（7公升）內加入2湯匙鴨油用中火燒熱。加入酸梅、薑片、蔥段及蒜頭爆香2分鐘。'),
(8188, 186065, 6, '加入鴨件、磨豉醬、橙皮、橙汁、冰糖、鹽及黑胡椒碎拌勻，加入備用鴨汁和水至剛好蓋過鴨件。'),
(8189, 186065, 7, '蓋上高速煲蓋，調至肉類模式。以大火烹煮至「紅色壓力指示針」升起及壓力閥開始發出嘶嘶聲響，便轉至細火煮20分鐘。'),
(8190, 186065, 8, '排氣，打開鍋蓋，如有需要，加入生粉水埋芡，煮2分鐘直至收汁。'),
(8191, 186065, 9, '上碟。灑上蔥花、橙皮及辣椒裝飾，即成。'),
(8192, 185260, 1, '將牛奶放入鍋內煮至微滾，放入茶包，蓋上鍋蓋，焗4分鐘，取出茶包。'),
(8193, 185260, 2, '將煉奶及奶奶拌勻。'),
(8194, 185260, 3, '杯子加入冰塊，倒入奶茶，即成。'),
(8195, 185307, 1, '魚膠片浸水，隔水加熱座溶，備用；牛油隔水加熱至溶化，備用。'),
(8196, 185307, 2, '將消化餅乾裝入保鮮袋用擀麵棍壓碎。'),
(8197, 185307, 3, '加入牛油拌勻。'),
(8198, 185307, 4, '準備一個6寸的模具，鋪上錫紙，倒入餅乾碎壓實，放入雪櫃冷藏至定型。'),
(8199, 185307, 5, '忌廉芝士用打蛋器打散，加入細砂糖、玫瑰醬、切成粒的士多啤梨和牛奶，拌勻。'),
(8200, 185307, 6, '分三次加入淡忌廉拌勻，再加入魚膠片溶液拌勻。'),
(8201, 185307, 7, '倒進消化餅乾的模具裡，至8分滿，放入雪櫃冷藏一晚至定型。'),
(8202, 185307, 8, '用熱毛巾在模具外圍捂熱一會，方便脫模，灑上額外的乾玫瑰花裝飾，即成。'),
(8203, 186052, 1, '預熱焗爐至攝氏180度，焗盤鋪上牛油紙備用。'),
(8204, 186052, 2, '將牛奶及無鹽牛油用中低火煮滾，離火後馬上加入木薯粉，快手拌勻備用。'),
(8205, 186052, 3, '將糯米粉、細砂糖、泡打粉、巴馬臣芝士碎及雞蛋拌勻。'),
(8206, 186052, 4, '加入木薯粉糰搓揉成麵糰，分成20克重的小球。'),
(8207, 186052, 5, '放上焗盤，放入焗爐焗20分鐘或至金黃色，即成。'),
(8208, 186053, 1, '將西蘭花洗淨切件備用。'),
(8209, 186053, 2, '預熱焗爐至攝氏200度。'),
(8210, 186053, 3, '煮滾一鍋水，加少許鹽，加入西蘭花汆水1分鐘，撈起瀝乾備用。'),
(8211, 186053, 4, '用中火燒熱鍋，加入牛油煮至溶化，加入麵粉炒勻，加入牛奶及20克水牛芝士碎煮至幼滑。'),
(8212, 186053, 5, '加入鹽、黑胡椒及西蘭花拌勻。'),
(8213, 186053, 6, '倒入焗碗，灑上餘下的水牛芝士碎，放入焗爐焗5-6分鐘或至表面金黃色，即成。'),
(8214, 186054, 1, '蔥切粒。'),
(8215, 186054, 2, '預熱焗爐至攝氏180度，焗盤鋪上牛油紙備用。'),
(8216, 186054, 3, '將忌廉芝士、蔥粒、蟹肉 、甜椒粉、鹽、蛋黃醬及青檸汁拌勻，放入雪櫃冷藏30分鐘。'),
(8217, 186054, 4, '將適量餡料放上雲吞皮，四邊沾上水，對角包好。'),
(8218, 186054, 5, '掃上橄欖油，放上焗盤，放入焗爐焗12-15分鐘或至金黃色即成。'),
(8219, 185848, 1, '黃心及紫心蕃薯洗淨、刨去外皮後，分別切成小塊，蒸20分鐘至軟身，然後壓成雙色蕃薯蓉，再加入適量牛油及糖拌勻好。'),
(8220, 185848, 2, '木薯粉過篩後置於碗中，加入糖拌勻，慢慢逐少加入熱水拌勻，再搓揉成木薯粉團。'),
(8221, 185848, 3, '兩種顏色的蕃薯蓉分別平均分為5份，並搓成圓球狀，而木薯粉團平均分為10份。'),
(8222, 185848, 4, '將每份木薯粉團搓成圓球狀，再壓成小窩狀，包入1份蕃薯蓉餡料。'),
(8223, 185848, 5, '將包好的水晶包放在碟上，蒸15分鐘即成。'),
(8224, 186060, 1, '韓式燒粟米做法：預熱焗爐至攝氏200度，焗盤鋪上錫紙。將粟米蒸熟，鋪上其他材料，放入焗盤焗5分鐘或至芝士溶化，即成。'),
(8225, 186060, 2, '煙肉芝士燒粟米做法：預熱焗爐至攝氏200度，焗盤鋪上錫紙。將粟米蒸熟，鋪上其他材料，放入焗盤焗5-8分鐘至芝士溶化，即成。'),
(8226, 186060, 3, '薯片脆脆粟米做法：將粟米蒸熟，鋪上其他材料，即成。'),
(8227, 186060, 4, '大阪燒粟米做法：將粟米蒸熟，鋪上其他材料，即成。'),
(8228, 185843, 1, '首先將所有調味料鐘碎或者放入攪拌機打碎'),
(8229, 185843, 2, '然後將五花腩港乾淨之後，印乾水份'),
(8230, 185843, 3, '將手㩒住，然後喺中間橫切，將五花腩每層切得更薄、更加入味'),
(8231, 185843, 4, '切好後洒上調味料'),
(8232, 185843, 5, '將五花腩卷，準備一條白綿繩，把燒肉綁成卷狀或獨立每條繩綁結也可'),
(8233, 185843, 6, '預熱190度焗爐焗1小時'),
(8234, 185919, 1, '預熱焗爐至攝氏180度。'),
(8235, 185919, 2, '2. 用油薄薄地掃滿雲吞皮，放入鬆餅模，以180度焗5-8分鐘至呈金黃色，備用。'),
(8236, 185919, 3, '3. 將芒果切粒，士多啤梨切半。'),
(8237, 185919, 4, '4. 將紫薯茸唧入撻皮內，放上水果，即成。'),
(8238, 185312, 1, '新鮮菠菜去掉根和黃葉，洗淨後汆水，撈出瀝乾備用。'),
(8239, 185312, 2, '將蒜瓣切碎；燒熱鍋，加入油，用小火爆香蒜蓉。'),
(8240, 185312, 3, '放入菠菜，快炒片刻，倒入魚露。'),
(8241, 185312, 4, '炒勻，熄火，即成。'),
(8242, 185495, 1, '將三黃雞洗淨，用鹽將雞全身抹勻。'),
(8243, 185495, 2, '薄薄掃一層生抽，加入2片薑片醃1小時以上。'),
(8244, 185495, 3, '將打好結的蔥、2片薑片及雞（帶皮的部位朝下放，如果是全雞就腳朝向上）放入電飯煲內膽，蓋上蓋子。'),
(8245, 185495, 4, '按電飯鍋的煮飯鍵，等電飯鍋跳掣後，再按一次煮飯鍵至跳制即成（如果是全雞，可以按三次煮飯鍵），稍微放涼後，撕成適合的大小，上碟即成。'),
(8246, 185847, 1, '絲瓜洗淨去皮去絲，切成小段備用。'),
(8247, 185847, 2, '生薑切成薑蓉備用。'),
(8248, 185847, 3, '櫻花蝦用油爆炒，盛起備用。'),
(8249, 185847, 4, '熱鍋中加入油，加生薑炒香，再加入絲瓜段，炒3-5分鐘，加入用少許櫻花蝦、鹽及糖調味，絲瓜略軟後可上碟。'),
(8250, 185847, 5, '最後將餘下的櫻花蝦撒在絲瓜上。'),
(8251, 185840, 1, '先製作抹茶戚風蛋糕，先分開蛋黃和蛋白。'),
(8252, 185840, 2, '把植物油以小火加熱至出現油紋（約70度）。'),
(8253, 185840, 3, '把低筋麵粉和抹茶粉放入碗中，再加入植物油，拌勻（小心熱油）。'),
(8254, 185840, 4, '把蛋黃逐隻加入到麵糊，拌勻。'),
(8255, 185840, 5, '再逐少加入牛奶，攪拌至順滑。'),
(8256, 185840, 6, '蛋白以電動打蛋器打至起泡，再逐少加入糖打至企身（硬性發泡）。'),
(8257, 185840, 7, '把1/4蛋白拌入抹茶麵糊中，再倒回蛋白中，輕輕拌勻。'),
(8258, 185840, 8, '把麵糊倒入6寸戚風蛋糕模中，再用竹籤以打圈放式於麵糊劃一圈，令麵糊分佈更平均。'),
(8259, 185840, 9, '放入焗爐，預熱180度，焗20-25分鐘至全熟（中層）；取出蛋糕，倒扣放涼。'),
(8260, 185840, 10, '把蛋糕脫模，再切成小件，每件中間都?一小刀，備用。'),
(8261, 185840, 11, '把淡忌廉加入糖打至企身，再夾入蛋糕中作餡料；最後撒上抹茶粉和淋上紅豆蓉，完成！'),
(8262, 185850, 1, '將海綿蛋糕切片, 塗上一層果醬後，再鋪上另一層蛋糕。'),
(8263, 185850, 2, '用小火加熱牛奶及棉花糖，一直攪拌直至兩者混合。'),
(8264, 185850, 3, '將棉花糖溶液分成兩份，小份的加入竹炭粉調成黑色。'),
(8265, 185850, 4, '將黑色棉花糖溶液倒入白色棉花糖溶液中，輕輕攪拌並且保持紋理。'),
(8266, 185850, 5, '將棉花糖溶液淋上蛋糕面，即成。'),
(8267, 185736, 1, '將雞柳洗淨印乾，剁碎備用；馬蹄去皮切碎；蔥切粒。'),
(8268, 185736, 2, '雞肉加入鹽、生抽、蛋白、胡椒粉及麻油醃30鐘。'),
(8269, 185736, 3, '加入粟米粒、馬蹄、燕麥片及蔥粒拌勻，用手撻打至起膠。'),
(8270, 185736, 4, '分成小球，搓成餅狀。'),
(8271, 185736, 5, '用中火燒熱鍋，加少許油，加入肉餅煎至兩面金黃色，即成。'),
(8272, 185738, 1, '將芫茜切碎。 將蝦滑、鹽、紹興酒、胡椒粉、粟米粒及芫茜拌勻。'),
(8273, 185738, 2, '腐皮剪成壽司紫菜大小 ，用濕廚房紙抹乾淨。在腐皮上放上壽司紫菜，抹上蝦滑鋪平，卷起。'),
(8274, 185738, 3, '用中高火蒸8-10分鐘至熟。'),
(8275, 185738, 4, '用中火燒熱鍋，加少許油，加入腐皮卷煎至金黃色，切件即成。'),
(8276, 185740, 1, '老黃瓜去囊切件；粟米切段；紅蘿蔔去皮切件；赤小豆、眉豆、蜜棗及腰果浸洗備用。'),
(8277, 185740, 2, '粟米鬚浸洗瀝乾，放入煲湯袋。'),
(8278, 185740, 3, '準備一個鍋，加入粟米鬚、老黃瓜、粟米、紅蘿蔔、赤小豆、眉豆、蜜棗、腰果及適量清水，用中火煮滾。'),
(8279, 185740, 4, '蓋上鍋蓋，轉中低火煮1小時，加少許鹽調味，即成。'),
(8280, 185006, 1, '春筍洗淨去皮，滾刀切件（切一刀，轉一下，再切一刀，直至切完）；蔥切段。'),
(8281, 185006, 2, '五花腩洗淨切件（切成均勻約1厘米左右的厚度）。'),
(8282, 185006, 3, '煮滾一鍋水，放入筍塊，煮1分鐘，撈出，瀝乾水份。'),
(8283, 185006, 4, '鍋中放入油，油溫微熱時，放入切好的五花腩，中火炒至金黃色。'),
(8284, 185006, 5, '放入蔥段、筍、生抽、老抽、紹興酒和砂糖。'),
(8285, 185006, 6, '加水蓋過食材，大火煮滾後，轉小火，煮20分鐘，收乾湯汁即成。'),
(8286, 185224, 1, '將魷魚清理乾淨，切圈備用。'),
(8287, 185224, 2, '魷魚加入鹽、胡椒粉、豉油及砂糖拌勻，加入一隻雞蛋，拌勻備用。'),
(8288, 185224, 3, '將另外一隻雞蛋打勻，將醃製好的魷魚沾上蛋液和麵粉。'),
(8289, 185224, 4, '油鍋加熱，放入魷魚炸2分鐘至金黃色，撈出，即成。'),
(8290, 185686, 1, '免治豬肉加入醃料攪勻，醃肉20分鐘。'),
(8291, 185686, 2, '蟲草花浸洗10分鐘後，切成小段備用。'),
(8292, 185686, 3, '將蟲草花及粟米加入豬肉攪勻，製成餃子的餡料。'),
(8293, 185686, 4, '每隻餃子大約用一湯匙的餡料。'),
(8294, 185686, 5, '將餡料包進餃子皮，用少量水沾濕餃子皮邊沿。'),
(8295, 185686, 6, '對折皮邊把餃子封口。'),
(8296, 185686, 7, '將包好的餃子放上碟上，加熱蒸15分鐘即成。'),
(8297, 185683, 1, '首先將蜜糖加入黑朱古力拌混調整甜度，然後用微波爐或隔水加熱方式將朱古力煮溶。'),
(8298, 185683, 2, '將所有材料包括紅腰豆、朱古力、雞蛋和泡打粉加入攪拌機打至順滑。布朗尼的基本蛋糕糊就預備好了！'),
(8299, 185683, 3, '將蛋糕糊加入焗盤掃均勻，加入紅桑子和杏仁碎。'),
(8300, 185683, 4, '用匙羹將材料輕輕壓一壓，就可以放進已預熱至150度焗爐焗18-20分鐘。'),
(8301, 185683, 5, '出爐後將布朗尼拿出放涼切件，超濃郁又健康的高纖布朗尼就完成啦！'),
(8302, 185684, 1, '將乾冬菇浸軟及去蒂；小棠菜洗淨切半備用；煮滾一鍋水，加入小棠菜煮熟，撈起上碟。'),
(8303, 185684, 2, '用中火燒熱鍋，加入水及冠珍蠔油皇拌勻。'),
(8304, 185684, 3, '加入冬菇，菇頂朝上，炆8分鐘。'),
(8305, 185684, 4, '將冬菇翻面，再炆7分鐘，上碟。'),
(8306, 185684, 5, '熄火，將醬汁淋上冬菇及小棠菜，即成。'),
(8307, 185704, 1, '混合白飯和飯素。'),
(8308, 185704, 2, '手沾點開水，把飯團握圓。'),
(8309, 185704, 3, '把紫菜剪至適當大小的長方形和表情貼在飯團上。'),
(8310, 185646, 1, '將番茄及洋蔥切件；蒜頭切成蓉備用。'),
(8311, 185646, 2, '將豬軟骨洗淨抹乾。煮滾一鍋水，加入紹興酒、薑及豬軟骨，將豬軟骨汆水5分鐘，撈起備用。'),
(8312, 185646, 3, '用中火燒熱鍋，加少許油，加入蒜頭及洋蔥炒香。'),
(8313, 185646, 4, '加入豬軟骨炒香，加入一半番茄、茄汁、喼汁、生抽、黃糖及水拌勻後煮滾。'),
(8314, 185646, 5, '蓋上鍋蓋，轉中低火煮40分鐘。'),
(8315, 185646, 6, '打開鍋蓋，加入餘下的番茄拌勻，再煮10分鐘，即成。'),
(8316, 185647, 1, '將番茄切件；甘筍去皮切件；南瓜去皮去籽切件；紅衫魚用廚房紙完全印乾，用少許鹽及胡椒粉醃5分鐘，兩面拍上生粉。'),
(8317, 185647, 2, '用中火燒熱鍋，加少許油，加入薑片炒香。加入紅衫魚煎至兩面金黃色。'),
(8318, 185647, 3, '準備一個大鍋，加入紅衫魚及熱水，用大火煮8-10分鐘。'),
(8319, 185647, 4, '加入番茄、南瓜及甘筍煮滾，蓋上鍋蓋，轉中低火煮45分鐘。'),
(8320, 185647, 5, '加少許鹽調味，即成。'),
(8321, 185648, 1, '將大蝦洗淨去殼去腸，保留尾部及蝦頭；蒜頭、番茜及洋蔥切碎。'),
(8322, 185648, 2, '將番茄底部輕輕界十字。準備一鍋水，加入番茄煮1-2分鐘。撈起浸入冰水後去皮切粒。'),
(8323, 185648, 3, '煮滾一鍋水，加少許鹽，加入意粉煮至軟硬適中。'),
(8324, 185648, 4, '用中火燒熱鍋，加少許油，加入大蝦煎熟，加少許鹽及黑胡椒調味。'),
(8325, 185648, 5, '用同一個鍋，加少許油，加入蝦頭，用中火爆香。'),
(8326, 185648, 6, '加入蒜頭及洋蔥炒香。'),
(8327, 185648, 7, '加入番茄煮15-20分鐘或至醬汁濃稠。'),
(8328, 185648, 8, '取出蝦頭，加入茄膏、辣椒粉、鹽及黑胡椒及2湯匙煮意粉水拌勻。'),
(8329, 185648, 9, '加入意粉及淡忌廉拌勻，加入大蝦炒勻。'),
(8330, 185648, 10, '上碟，灑上番茜碎，即成。'),
(8331, 184836, 1, '魷魚洗乾淨切圈，蝦去殼去蝦腸，備用。'),
(8332, 184836, 2, '準備煎炒鍋，放入油，加熱，炒香蒜蓉、辣豆瓣醬和乾辣椒。'),
(8333, 184836, 3, '放入魷魚圈、元貝和蝦，拌勻。'),
(8334, 184836, 4, '加入炒麵、豉油和砂糖，調味，即成。'),
(8335, 185645, 1, '將豬肺在水喉流水灌洗，用叉在豬肺表面打孔，讓污水排出，反覆灌洗；豬肺切件後汆水，撈起瀝乾。'),
(8336, 185645, 2, '用白鑊加入薑片，把豬肺炒至略為乾身。'),
(8337, 185645, 3, '白果去衣及去芯，浸15分鐘備用。'),
(8338, 185645, 4, '將雞腳洗淨，瘦肉、金華火腿切件，加入水1.5-2公升，連同豬肺及白果燉煮2小時。'),
(8339, 185645, 5, '甜杏仁加水用攪拌機打成漿，過篩備用。'),
(8340, 185645, 6, '最後把杏汁加入豬肺湯中，湯汁加熱至翻滾，加少許鹽調味即成。'),
(8341, 185644, 1, '將草莓洗淨去蒂；抹乾備用。'),
(8342, 185644, 2, '將淡忌廉倒入碗中，打發期間分三次加入砂糖，直至八成企身。'),
(8343, 185644, 3, '方包上鋪上打發好的忌廉和草莓。'),
(8344, 185644, 4, '再鋪上忌廉和方包。'),
(8345, 185644, 5, '固定後切開。'),
(8346, 185628, 1, '高筋粉、糖、鹽、水、酵母混合搓成麵糰，再加入橄欖油搓至柔軟而不黏手，再蓋上保鮮紙置室溫發酵至2倍大(約1小時)。'),
(8347, 185628, 2, '葱、糖、鹽、橄欖油混合造成香葱醬。'),
(8348, 185628, 3, '取出麵糰排氣，再擀平成長方型，一半搽上香葱醬，一半鋪上片裝芝士。'),
(8349, 185628, 4, '將麵糰平均切成10-12份，一份葱麵糰、一份芝士麵糰梅花間竹地叠起，平放入模具或烤盤再發酵至2倍大。'),
(8350, 185628, 5, '完成第二次發酵後掃上蛋液。'),
(8351, 185628, 6, '放入已預熱焗爐用190℃焗20-25分鐘即成。'),
(8352, 186439, 1, '粟米火腿滋味燕麥：1. 用適量清水沖好即食燕麥；2. 加入粟米蓉及三文治火腿粒拌勻，放入微波爐加熱2分鐘，即成。'),
(8353, 186439, 2, '榨菜肉鬆古早燕麥：1. 用適量熱水沖好即食燕麥；2. 伴以即食木耳榨菜及肉鬆享用，即成。'),
(8354, 186439, 3, '黑糖薑母養生燕麥：1. 用220毫升熱水沖好黑糖薑母磚，加入即食燕麥沖好；2. 伴以杏仁片及杞子享用，即成。'),
(8355, 186439, 4, '香濃朱古力燕麥：1. 用牛奶沖好燕麥，加入朱古力，放入微波爐加熱2分鐘；2. 伴以香蕉享用，即成。'),
(8356, 185595, 1, '把肉醬放入大碗內，加入迷迭香、黑椒粉、鹽及豆蔻粉混和'),
(8357, 185595, 2, '焗盤上包上錫紙，然後放上肉醬'),
(8358, 185595, 3, '放上一層芝士'),
(8359, 185595, 4, '再放上一層火腿'),
(8360, 185595, 5, '卷成肉卷'),
(8361, 185595, 6, '在錫紙上放上一煙肉，放上肉卷捲起'),
(8362, 185595, 7, '加入迷迭香在肉卷兩旁，連錫紙入已預熱180°C焗爐焗30分鐘'),
(8363, 185595, 8, '除去錫紙後再以180°C焗30分鐘'),
(8364, 185595, 9, '切片後上碟完成'),
(8365, 185579, 1, '將蒜頭切碎；指天椒及蔥切粒。'),
(8366, 185579, 2, '海中蝦去腸，剪去鬚和蝦腳，洗淨印乾。'),
(8367, 185579, 3, '加入鹽及胡椒粉醃10分鐘，加入生粉拌勻。'),
(8368, 185579, 4, '用中火燒熱鍋，加入適量油，加入蒜頭，用中低火炸至金黃色，撈起備用。'),
(8369, 185579, 5, '用中火燒熱另一個鍋，加入1湯匙蒜油，加人蝦煎熟，加入紹興酒煮至酒精蒸發。'),
(8370, 185579, 6, '加入蒜頭、麵包糠、指天椒及蔥粒炒勻，即成。'),
(8371, 185582, 1, '將陳皮浸軟括去囊後切絲；蔥切絲；粉絲浸軟瀝乾備用。'),
(8372, 185582, 2, '將鮑魚仔及鮑魚殻刷乾淨，除去內臟，洗淨瀝乾後用刀輕輕在表面界花。'),
(8373, 185582, 3, '將粉絲放上蒸碟。'),
(8374, 185582, 4, '放上鲍鱼及洒上陈皮，用中高火蒸5分钟或至熟。'),
(8375, 185582, 5, '洒上葱丝，淋上熟油及蒸鱼豉油，即成。'),
(8376, 185588, 1, '將洋蔥及蔥切絲；鰻魚切件。'),
(8377, 185588, 2, '用中火燒熱鍋，加少許油，加入洋蔥炒香。'),
(8378, 185588, 3, '加入鰹魚高湯、日本豉油、日本料理酒、味醂及黃糖，放上鰻魚煮滾。'),
(8379, 185588, 4, '加入略略打發的雞蛋， 用中低火煮至蛋液半凝固。'),
(8380, 185588, 5, '灑上蔥絲，即成。'),
(8381, 184925, 1, '蔥薑蒜洗淨，切碎備用。'),
(8382, 184925, 2, '茶樹菇洗淨，撕成細絲。'),
(8383, 184925, 3, '鍋內倒油，放入乾辣椒和花椒，小火加熱到辣椒和花椒變色，撈出，保留底油。'),
(8384, 184925, 4, '倒入蔥薑蒜，改中火煸炒出香味，放茶樹菇絲，中小火炒到茶樹菇絲變軟變乾。'),
(8385, 184925, 5, '倒入雞絲、豆豉辣醬和鹽，炒勻後繼續炒1-2分鐘。'),
(8386, 184925, 6, '倒入花生碎和芝麻，炒勻，熄火即成。'),
(8387, 184952, 1, '蒜苗洗乾淨，蒜白（上面白色部分）切絲，蒜苗葉（下面綠色部分）切碎；大蔥切絲備用。'),
(8388, 184952, 2, '製作牛肉高湯：準備鑄鐵湯鍋，放入水、牛肉、昆布、蒜和花椒，大火煮30分鐘，先取出昆布，接著用中火悶燉1小時。'),
(8389, 184952, 3, '牛肉湯鍋熄火，取出牛肉，將牛肉切片備用；湯底去除其他湯料，備用。'),
(8390, 184952, 4, '製作辣醬：準備一個鍋，放入麻油和蒜蓉，炒香，放入辣椒粉、蒜苗葉、黑胡椒、鯷魚、豉油和鹽，拌勻。'),
(8391, 184952, 5, '加入洋蔥、蒜白、牛肉、高湯和豆芽，煮滾。'),
(8392, 184952, 6, '上碟，即成。'),
(8393, 185590, 1, '木瓜切开兩半，挖去木瓜核，放置碗中備用。'),
(8394, 185590, 2, '木瓜先蒸15分鐘。'),
(8395, 185590, 3, '將蛋白、杏奶及糖攪勻。'),
(8396, 185590, 4, '把混合好的杏奶蛋漿倒在木瓜的中空位置。'),
(8397, 185590, 5, '再用中小火蒸15分鐘，杏奶蛋漿凝固即成。'),
(8398, 185564, 1, '牛油取出回軟，加糖打至泛白，慢慢加入蛋液'),
(8399, 185564, 2, '麵粉及朱古力粉過篩放入'),
(8400, 185564, 3, '用刮刀直切外翻拌勻'),
(8401, 185564, 4, '狗仔造型'),
(8402, 185564, 5, '取出待涼再加多朱古力粒裝飾作眼晴'),
(8403, 185510, 1, '預熱焗爐至攝氏220度，焗盤焗上錫紙備用。'),
(8404, 185510, 2, '將2/3包馬拉黃咖哩牛腩、白飯、雞蛋及巴馬臣芝士粉拌勻。'),
(8405, 185510, 3, '整成球狀，裹上麵包糠。'),
(8406, 185510, 4, '放入焗爐焗15分鐘或至表面金黃色。'),
(8407, 185510, 5, '將餘下的馬拉黃咖哩牛腩加熱，配上焗好的飯球享用，即成。'),
(8408, 185511, 1, '預熱焗爐至攝氏200度，焗盤焗上錫紙備用。'),
(8409, 185511, 2, '薯仔去皮切片蒸軟，趁熱壓成蓉。'),
(8410, 185511, 3, '加入洛根紅咖哩羊腩拌勻，捏成餅狀。'),
(8411, 185511, 4, '將粟米片放入密實袋，用麵棍壓碎。'),
(8412, 185511, 5, '將雞蛋打發，薯餅順序沾上中筋麵粉、蛋液及粟米片，放上焗盤。'),
(8413, 185511, 6, '放入焗爐焗10分鐘，取出反轉另一面，再焗5分鐘，即成。'),
(8414, 185512, 1, '預熱焗爐至攝氏200度，焗盤焗上錫紙備用。'),
(8415, 185512, 2, '將茄子及蘑菇切片。'),
(8416, 185512, 3, '茄子用鹽及黑胡椒調味，灑上適量橄欖油。'),
(8417, 185512, 4, '抹上意大利肉醬及放上蘑菇。'),
(8418, 185512, 5, '灑上水牛芝士碎。'),
(8419, 185512, 6, '放入焗爐焗10-12分鐘，即成。'),
(8420, 183706, 1, '玉子豆腐切件，紅蘿蔔切片，白蘑菇一開四，備用。'),
(8421, 183706, 2, '燒熱油鍋，豆腐沾上少許麵粉，炸至上色，備用。'),
(8422, 183706, 3, '準備一個鍋，加入少許油，炒香薑蒜，加入免治豬肉，炒至出油，加入白蘑菇、蝦仁及紅蘿蔔，炒勻，加入蠔油、辣椒醬、豉油、清酒、100毫升水、砂糖、鹽及胡椒粉，煮3分鐘，備用。'),
(8423, 183706, 4, '準備鐵板，加入適量油，加熱，加入雞蛋、玉子豆腐、肉醬，灑上蔥花，即成。'),
(8424, 185080, 1, '薯仔去皮切件，金菇切掉根部，大蔥切段，備用。'),
(8425, 185080, 2, '煮滾一鍋水，加入豬骨、一半蒜、一半薑及一半大蔥，汆水3分鐘。'),
(8426, 185080, 3, '將豬骨、大蔥、薑、蒜及辣醬放入鍋中。'),
(8427, 185080, 4, '加入薯仔、泡菜及大醬，加入水蓋過食材，蓋上鍋蓋，用中小火燜煮1小時。'),
(8428, 185080, 5, '加入金菇、茼蒿及紫蘇葉，煮2分鐘，即成。'),
(8429, 185509, 1, '雪蓮子、雪耳及桃膠可以預早一晚浸發，然後把桃膠中的黑色雜質去除，沖洗乾淨。雪耳去除根部，撕細後沖洗。'),
(8430, 185509, 2, '木瓜先去皮去核，把木瓜肉切成正方體。'),
(8431, 185509, 3, '水滾後，把撕細的雪耳、浸過及洗淨的雪蓮子及桃膠、木瓜肉和水放在水中，以中火煲煮大約35分鐘。'),
(8432, 185509, 4, '最後加入冰糖，溶化後即可。'),
(8433, 185476, 1, '煙肉切粒備用'),
(8434, 185476, 2, '將蛋打散後加入芝士碎攪勻，用海鹽和黑椒調味（喜歡較香濃的醬汁可以按喜好增加芝士份量）'),
(8435, 185476, 3, '意粉按包裝指示煮至al dente'),
(8436, 185476, 4, '煮意粉期間，將煙肉粒放入冷鑊，用中高火爆香，加入蒜頭'),
(8437, 185476, 5, '當煙肉煎到香脆時，加入意粉及少許意粉水拌勻，離火，取出蒜頭'),
(8438, 185476, 6, '待稍為降溫後，加入芝士蛋漿拌勻'),
(8439, 185476, 7, '最後刨少少芝士碎上面意粉上'),
(8440, 185503, 1, '將適量水掃在圓形日式年糕上。'),
(8441, 185503, 2, '灑上黃糖和花生碎。'),
(8442, 185503, 3, '放入焗爐以攝氏160度焗5分鐘，即成。'),
(8443, 185504, 1, '拆開豬手包裝袋慢慢解凍。'),
(8444, 185504, 2, '豬手解凍後，放在盤上，加入啤酒、鹽、黑椒、蒜及香料醃味。'),
(8445, 185504, 3, '焗爐預先用350度預熱。'),
(8446, 185504, 4, '豬手放入焗爐內用165度焗4小時。首1小時後將豬手取出，淋上啤酒令它保持濕潤。'),
(8447, 185504, 5, '外皮開始脆身時每隔45分鐘淋上啤酒，後段時間再淋上啤酒，調高至焗爐最高溫度（約250-300度）再焗10-15分鐘令外皮焗至表面脆香即可。'),
(8448, 185504, 6, '傳統焗豬手會加入酸椰菜或烤薯，或你可加入各類蔬菜如蘿蔔、青瓜一齊略焗。'),
(8449, 185502, 1, '將材料放入攪拌機，打至幼滑即成。'),
(8450, 185432, 1, '蝴蝶粉和粟米粒先放在熱水中，加少許鹽烚8-9分鐘後取出備用。'),
(8451, 185432, 2, '三文魚煎熟然後壓散，紫洋蔥切粒，車厘茄切片。'),
(8452, 185432, 3, '將所有材料拌勻，放涼即可。'),
(8453, 185431, 1, '將鮮沙薑切片，蒜頭拍扁去衣，乾蔥去衣開邊，蔥切段，指天椒切絲，雞洗乾淨，吸乾水份'),
(8454, 185431, 2, '用醃料拌勻雞件'),
(8455, 185431, 3, '放入雪櫃醃半小時'),
(8456, 185431, 4, '燒熱鑊，加入一湯匙油'),
(8457, 185431, 5, '中慢火將雞兩面煎至金黃色'),
(8458, 185431, 6, '盛起備用'),
(8459, 185431, 7, '用回原鑊先將蒜頭、乾蔥、薑片、辣椒、蔥段爆香'),
(8460, 185431, 8, '加入雞件略炒'),
(8461, 185431, 9, '接著放入鮮沙薑片以及半碗水'),
(8462, 185431, 10, '蓋回鑊蓋以中火焗5分鐘，見水份接近收乾即成'),
(8463, 185444, 1, '將白朱古力隔熱水座溶。'),
(8464, 185444, 2, '加入淡忌廉拌勻。'),
(8465, 185444, 3, '加入焙茶粉拌勻。'),
(8466, 185444, 4, '倒入現成撻殼內。'),
(8467, 185444, 5, '放入雪櫃冷藏1小時或至軟心狀態，即成。'),
(8468, 185363, 1, '把中筋麵粉、玉桂粉、泡打粉、糖、鹽、燕麥片及橄欖油放入大碗入混和。'),
(8469, 185363, 2, '加入蘋果絲及榛子混和做成餅底。'),
(8470, 185363, 3, '焗盤上放上牛油紙，然後放上麵糊，焗爐預熱170°C焗1小時。'),
(8471, 185363, 4, '出爐後塗上榛子朱古力醬。'),
(8472, 185363, 5, '放上野莓。'),
(8473, 185363, 6, '洒上糖霜便完成。'),
(8474, 185400, 1, '將茄膏塗在餃子皮。'),
(8475, 185400, 2, '按次序放上水牛芝士、蕃茄粒、水牛芝士。'),
(8476, 185400, 3, '將餃子皮捲成甜筒形。'),
(8477, 185400, 4, '掃上蛋黃液。'),
(8478, 185400, 5, '放入焗爐以180度焗10分鐘。'),
(8479, 185400, 6, '灑上羅勒葉碎，即成。'),
(8480, 185341, 1, '泡菜及蒜頭切碎備用。'),
(8481, 185341, 2, '免治豬肉加入生抽、黃糖、胡椒粉 、鹽、薑蓉、蒜蓉、紹興酒及麻油攪拌至至膠，醃30分鐘。'),
(8482, 185341, 3, '加入泡菜及水牛芝士拌勻。'),
(8483, 185341, 4, '將適量餡料放上餃子皮，放上蝦仁， 在餃子皮邊沾少許水，打摺包成餃子。'),
(8484, 185341, 5, '用中火燒熱鍋，加少許油，加入餃子煎1分鐘。'),
(8485, 185341, 6, '加入75毫升熱水，蓋上鍋蓋煎4-5分鐘。'),
(8486, 185341, 7, '打開鍋蓋再煎1分鐘，即成。'),
(8487, 185342, 1, '將蔥切粒；甘筍去皮磨成蓉。'),
(8488, 185342, 2, '免治豬肉加入生抽、黃糖、胡椒粉 、鹽、薑蓉、蒜蓉、紹興酒及麻油攪拌至起膠，醃30分鐘 。'),
(8489, 185342, 3, '加入蔥粒拌勻。'),
(8490, 185342, 4, '將適量餡料放上餃子皮，對摺，中間點用水黏好。'),
(8491, 185342, 5, '右邊餃子皮向內摺，黏緊成金魚眼睛。'),
(8492, 185342, 6, '左邊用手指壓平，兩邊向內摺成金魚尾巴。'),
(8493, 185342, 7, '剪出金魚尾巴。'),
(8494, 185342, 8, '金魚眼睛放上甘筍蓉。'),
(8495, 185342, 9, '在蒸籠上放上牛油紙，放上餃子，蓋上蓋子，用中高火蒸8-10分鐘，即成。'),
(8496, 185343, 1, '將薯仔去皮切細粒；洋蔥及蒜頭切碎備用。'),
(8497, 185343, 2, '用中火燒熱鍋，加少許油，加入蒜蓉炒香，加入洋蔥炒香。'),
(8498, 185343, 3, '加入薯仔炒熟，加入咖哩粉及黃薑粉炒勻，完全放涼備用。'),
(8499, 185343, 4, '免治豬肉用生抽、黃糖、胡椒粉、麻油及鹽醃30分鐘，加入咖哩薯仔洋蔥拌勻。'),
(8500, 185343, 5, '將適量餡料放上餃子皮，在餃子皮邊沾少許水，包成餃子。'),
(8501, 185343, 6, '用中火燒熱鍋，加少許油，加入餃子煎1分鐘。'),
(8502, 185343, 7, '加入75毫升熱水，蓋上鍋蓋煎4-5分鐘。'),
(8503, 185343, 8, '打開鍋蓋再煎1分鐘，即成。'),
(8504, 185183, 1, '用大火煮滾一鍋水，放入洗淨的排骨汆水至變色，撈出，用清水沖洗乾淨，瀝乾。'),
(8505, 185183, 2, '準備另一個鍋，放入排骨，倒入清水至沒過排骨，放入薑片、蒜蓉辣醬、老抽及砂糖拌勻。'),
(8506, 185183, 3, '用大火煮滾，轉中小火，繼續燉約45分鐘。'),
(8507, 185183, 4, '轉大火繼續煮5分鐘，至湯汁略粘稠，出鍋即成。'),
(8508, 185187, 1, '製作新鮮梨汁：將梨洗淨去皮榨汁。'),
(8509, 185187, 2, '製作醃肉醬汁：將梨汁、生抽、麻油、薑蓉、蒜蓉、鹽、砂糖及蜜糖拌勻。'),
(8510, 185187, 3, '將牛柳切片，約5毫米厚的，加入醃肉醬汁拌勻，放入雪櫃冷藏1小時。'),
(8511, 185187, 4, '焗盤上鋪上烘焙紙，將牛肉逐片均勻地放在焗盤上，倒入少許剩餘醬汁，放入預熱至攝氏200度的焗爐焗約8分鐘，中間拿出翻面一次。'),
(8512, 185187, 5, '將肉放到烤架上翻面，再烤2分鐘。此步驟可省略。'),
(8513, 185335, 1, '將麵粉過篩，加入雞蛋、脫脂奶、奇亞籽攪拌至幼滑，放置20分鐘讓奇亞籽吸收水分。'),
(8514, 185335, 2, '把粉漿倒入易潔平底鍋中，用中火每邊煎4-5分鐘至金黃色。'),
(8515, 185335, 3, '煎完上碟後，加上乳酪和藍莓，灑上少許糖霜及放上薄荷葉裝飾即成。'),
(8516, 185336, 1, '準備法式三文魚肉醬：將三文魚柳去皮；蔥深綠色的部分切段，白色及淺綠色的部分切粒；檸檬切2片，其他備用。'),
(8517, 185336, 2, '準備一個小鍋，加入白酒、水、2片檸檬、深綠色的蔥段、鹽及黑胡椒，煮滾。'),
(8518, 185336, 3, '轉小火，加入三文魚柳，蓋上鍋蓋煮1分鐘，熄火，靜置10分鐘。'),
(8519, 185336, 4, '取出三文魚柳放在碟上印乾，再放入雪櫃冷藏最少20分鐘或過夜。'),
(8520, 185336, 5, '將紅蔥頭切碎；用刮刀將牛油攪至軟身及幼滑。'),
(8521, 185336, 6, '加入紅蔥頭、蔥粒、芥末籽醬、蛋黃醬、蜜糖、檸檬汁、水瓜柳、鹽及黑胡椒拌勻。'),
(8522, 185336, 7, '將煙三文魚切條；從雪櫃取出三文魚柳切塊。'),
(8523, 185336, 8, '將三文魚及煙三文魚加入蛋黃醬混合物輕輕攪拌，小心不要將三文魚弄得太散。'),
(8524, 185336, 9, '將刁草及細香蔥切碎，加到三文魚肉醬拌勻。'),
(8525, 185336, 10, '倒入密實瓶內，放入雪櫃冷藏最少15分鐘，伴以法包或餅乾享用。'),
(8526, 185336, 11, '準備青瓜及青蘋果沙律：將青瓜切薄片；蘋果去芯，切成幼條。'),
(8527, 185336, 12, '準備一個碗，放入青瓜、蘋果、白酒醋、砂糖、鹽及黑胡椒拌勻，即可與三文魚肉醬及法包一同伴食。'),
(8528, 185316, 1, '低筋粉、泡打粉、鹽拌勻及過篩。'),
(8529, 185316, 2, '蛋和糖用低速打成淺黃色。'),
(8530, 185316, 3, '慢慢加入橄欖油及黑陳醋醬，最後倒入牛奶。'),
(8531, 185316, 4, '分2-3次將粉類混入濕料拌勻。'),
(8532, 185316, 5, '差不多完全混合時加入開心果碎，直至不見粉粒。'),
(8533, 185316, 6, '把麵糊倒入烤模裏，灑上開心果碎。'),
(8534, 185316, 7, '放進已預熱焗爐中，用180℃焗20-25分鐘。'),
(8535, 185338, 1, '在鬆餅焗盤上掃油。'),
(8536, 185338, 2, '放入適量車打芝士碎和水牛芝士碎。'),
(8537, 185338, 3, '倒入一湯匙蛋白。'),
(8538, 185338, 4, '灑上適量黑胡椒碎。'),
(8539, 185338, 5, '放入焗爐以180度焗10分鐘。'),
(8540, 185304, 1, '枸杞子、紅棗先浸30分鐘，隔水備用；豬潤洗淨，冷水浸泡15分鐘後，將豬潤切成片；牛肉洗淨，切碎。'),
(8541, 185304, 2, '鍋中放適量1.5升清水加熱，加薑片、枸杞子、紅棗先煮15分鐘，再加豬潤及牛肉煮10-15分鐘。'),
(8542, 185304, 3, '加鹽調味即成。'),
(8543, 185257, 1, '將蟹棒撕成絲；鮮冬菇洗淨去蒂切片。'),
(8544, 185257, 2, '用中火燒熱鍋，加少許油，加入鮮冬菇炒至軟身，盛起放涼備用。'),
(8545, 185257, 3, '將雞蛋打發，加入鮮冬菇及1/2蟹棒拌勻。'),
(8546, 185257, 4, '用中火燒熱鍋，加少許油，加入蛋液，不停用筷子攪拌，煮至半凝固，熄火，放上飯面。'),
(8547, 185257, 5, '將雞湯、白醋、日本料理酒、日本豉油、味醂、蠔油及黃糖拌勻，倒入鍋中用中火煮滾。'),
(8548, 185257, 6, '加入餘下的蟹棒及生粉水，起芡，淋上蛋面即成。'),
(8549, 185282, 1, '先製作抹茶忌廉，混合抹茶粉和熱水，備用。'),
(8550, 185282, 2, '淡忌廉（鮮奶油）加入糖，打發至也成企身。'),
(8551, 185282, 3, '再加入抹茶醬拌勻，冷藏備用（4°C）。'),
(8552, 185282, 4, '製作熱香餅，混合蛋、鹽、砂糖、牛奶和植物油/牛油溶液。'),
(8553, 185282, 5, '最後篩入低筋麵粉、泡打粉和抹茶粉，拌勻。'),
(8554, 185282, 6, '以中小火燒熱鑊，再薄薄掃上一層油。'),
(8555, 185282, 7, '定點倒入麵糊，以中小火煎約 1-1.5分鐘至熱香餅面出現氣泡。'),
(8556, 185282, 8, '番轉熱香餅，再煎約20-30秒。'),
(8557, 185282, 9, '煎好後把抹茶忌廉淋上熱香餅上，完成！'),
(8558, 185294, 1, '將咖啡粉放在濾紙內。'),
(8559, 185294, 2, '倒入熱水，擷取出咖啡液，待涼備用。'),
(8560, 185294, 3, '將淡忌廉加入砂糖打至軟性發泡狀態。'),
(8561, 185294, 4, '馬司卡邦芝士攪拌均勻，加入淡忌廉拌勻。'),
(8562, 185294, 5, '把咖啡液掃在手指餅上。'),
(8563, 185294, 6, '把馬司卡邦芝士混合物擠在手指餅上。'),
(8564, 185294, 7, '灑上無糖可可粉，即成。'),
(8565, 185263, 1, '將罐頭白桃切成薄片；6吋蛋糕模鋪上牛油紙備用。'),
(8566, 185263, 2, '將消化餅碎及無鹽牛油溶液拌勻，鋪入蛋糕模壓成餅底，放入雪櫃冷藏30分鐘備用。'),
(8567, 185263, 3, '製作忌廉芝士層。將12克魚膠片用凍水浸軟，隔熱水座溶備用。'),
(8568, 185263, 4, '將淡忌廉打發至七成企身。'),
(8569, 185263, 5, '將忌廉芝士及糖粉用電動打蛋器打至軟身。'),
(8570, 185263, 6, '加入魚膠片溶液及維記白桃乳酪飲品拌勻。'),
(8571, 185263, 7, '加入已打發的淡忌廉拌勻，倒入蛋糕模，放入雪櫃冷藏3小時或至凝固。'),
(8572, 185263, 8, '製作白桃啫喱面。將4克魚膠片用凍水浸軟，隔熱水座溶。'),
(8573, 185263, 9, '將罐頭白桃糖水、水及天然粉紅色素粉末拌勻，加入魚膠片溶液拌勻。'),
(8574, 185263, 10, '在忌廉芝士層鋪上白桃片砌成花朵形狀，倒上魚膠溶液，放入雪櫃冷藏1小時或至凝固，脫模即成。'),
(8575, 185256, 1, '將蒜頭切片。'),
(8576, 185256, 2, '牛柳粒用生抽、砂糖、胡椒粉、油及生粉醃30分鐘。'),
(8577, 185256, 3, '用中火燒熱鍋，加少許油，將蒜片煎至金黃色，盛起備用。'),
(8578, 185256, 4, '用同一個鍋，加入牛柳粒，用中高火將四面煎香。'),
(8579, 185256, 5, '加入蒜片，用中火炒勻，鋪上飯面即成。'),
(8580, 185255, 1, '將牛肉片切段；翠玉瓜及甘筍切絲；鮮冬菇去蒂切片；蒜頭切成蓉備用。'),
(8581, 185255, 2, '牛肉加入生抽、白醋、砂糖及麻油醃10分鐘。'),
(8582, 185255, 3, '用中火燒熱鍋，加少許油，加入甘筍絲炒軟， 盛起備用。'),
(8583, 185255, 4, '用同一個鍋，加入翠玉瓜炒軟，加少許鹽調味，盛起備用。'),
(8584, 185255, 5, '用同一個鍋，加入鮮冬菇炒軟，加入生抽、砂糖及麻油調味，盛起備用。'),
(8585, 185255, 6, '用同一個鍋，加入牛肉炒熟，盛起備用。'),
(8586, 185255, 7, '煮滾一鍋水，加入大豆芽煮3-4分鐘，撈起瀝乾，加少許鹽及1/2茶匙麻油拌勻備用。'),
(8587, 185255, 8, '將牛肉、 翠玉瓜、甘筍、鮮冬菇、大豆芽及涼拌菠菜鋪上飯面。'),
(8588, 185255, 9, '用中火燒熱另一個鍋，加少許油，加入雞蛋煎成太陽蛋，放上飯面。'),
(8589, 185255, 10, '將韓式辣醬、生抽、白醋、砂糖、麻油及蒜蓉拌勻，拌飯享用。'),
(8590, 183707, 1, '五花肉洗淨，汆水取出瀝乾。'),
(8591, 183707, 2, '背部刺上小孔，抹上白酒和老抽，放入油鍋炸至金黃色。'),
(8592, 183707, 3, '準備炒鍋，放入油，加熱，炒香薑蒜、八角、肉桂、豆豉，加入紹興酒、老抽、1500毫升水、五花肉、1湯匙蠔油、鹽和雞粉，燜煮40分鐘，保留湯汁。'),
(8593, 183707, 4, '梅菜浸水變軟，瀝乾水份，切碎；另取一個鍋子，炒香蒜蓉，加入梅菜、餘下蠔油、鹽和雞粉，炒勻。'),
(8594, 183707, 5, '煮好的五花肉切片，沾上湯汁；碟上放上少許花椒、五花肉和梅菜鋪平，淋上湯汁。'),
(8595, 183707, 6, '放入蒸鍋，蒸20分鐘，取出，倒扣，即成。'),
(8596, 185037, 1, '雞腎清洗乾淨，切薄片，加入鹽、紹興酒、1湯匙生抽及胡椒粉，醃15分鐘。'),
(8597, 185037, 2, '泡椒、蒜及薑切碎。'),
(8598, 185037, 3, '鍋中倒入油，加熱，放入薑蒜、泡椒及雞腎，加入餘下的生抽、老抽、砂糖，用大火快炒約3分鐘。'),
(8599, 185037, 4, '加入生粉水，炒勻，即成。'),
(8600, 185251, 1, '先把藜麥、黑白芝麻用中火炒6-8分鐘。'),
(8601, 185251, 2, '番薯去皮切成一口大小，然後在鍋中加點油，放入番薯塊炒7-8分鐘至金黃色，中途需蓋上蓋子把番薯焗至熟透，也要翻動一下番薯避免煎焦。'),
(8602, 185251, 3, '紅糖和蜜糖加入熱水拌勻。'),
(8603, 185251, 4, '倒進鍋內，再轉大火一直炒至變成焦糖和黏稠。'),
(8604, 185251, 5, '灑上烘過的藜麥和黑白芝麻，即可上碟。'),
(8605, 185212, 1, '將洋蔥切絲；蘑菇及紅尖椒切片；煙肉切粒備用。'),
(8606, 185212, 2, '將腐乳及紹興酒拌勻備用。'),
(8607, 185212, 3, '將淡忌廉、蛋黃、鹽及黑胡椒拌勻備用。'),
(8608, 185212, 4, '煮滾一鍋水，加入鹽及意粉，將意粉煮至軟硬適中，瀝乾備用。'),
(8609, 185212, 5, '用中火燒熱鍋，加入煙肉炒香，加入洋蔥及蘑菇炒香。'),
(8610, 185212, 6, '加入腐乳炒香 。'),
(8611, 185212, 7, '加入意粉及紅尖椒炒勻。'),
(8612, 185212, 8, '熄火，加入淡忌廉混合物拌勻，即成。'),
(8613, 185245, 1, '豆腐忌廉：先用小火將豆腐煮10分鐘，然後撈起隔水'),
(8614, 185245, 2, '將豆腐切件，於上方放置重物壓水1小時。豆腐之後會變得乾身，方便調整忌廉質地'),
(8615, 185245, 3, '先將豆腐、糖和牛奶放入攪拌機打至順滑。然後加入百利甜酒及咖啡酒調味，記住刮一刮杯邊，然後再次攪拌均勻即可'),
(8616, 185245, 4, '海綿蛋糕：先將蛋白和蛋黃分開。將10克糖、淡味油和牛奶逐一加入蛋黃，將每種材料充分攪勻'),
(8617, 185245, 5, '篩入低筋麵粉，輕輕攪拌至無粉粒即可'),
(8618, 185245, 6, '開始製作蛋白霜。分三次將餘下的砂糖加入蛋白，先用低速打發，蛋白起泡時加入第一次砂糖。蛋白變得綿密時加入第二次砂糖，轉高速打發。蛋白出現紋路時加入第三次砂糖'),
(8619, 185245, 7, '打至企身（硬性發泡）即可'),
(8620, 185245, 8, '分三次將蛋白霜加入蛋黃糊混合。用切拌手法將其攪勻，可避免蛋白消泡，令海綿蛋糕保持柔軟'),
(8621, 185245, 9, '將麵糊倒入焗盆掃均勻。輕拍焗盤去除起泡，然後放入已預熱180度的焗爐焗10分鐘'),
(8622, 185245, 10, '沖調即溶咖啡及咖啡酒備用'),
(8623, 185245, 11, '組裝蛋糕：蛋糕放涼後切成模具大小。依次序放入一片海綿蛋糕、掃上咖啡、加入忌廉，重複以上步驟一次'),
(8624, 185245, 12, '蓋上錫紙冷藏1小時成型'),
(8625, 185245, 13, '最後灑上濃郁可可粉，豆腐提拉米蘇就完成了'),
(8626, 185211, 1, '預熱焗爐至攝氏200度。'),
(8627, 185211, 2, '將腸粉切段；洋蔥、甘筍及蒜頭切碎。'),
(8628, 185211, 3, '用中火燒熱鍋，加少許油，加入蒜頭、洋蔥及甘筍炒香。'),
(8629, 185211, 4, '加入免治豬肉及免治牛肉炒香。'),
(8630, 185211, 5, '加入番茄意粉醬、巴馬臣芝士粉、鹽及黑胡椒煮15分鐘或至收汁。'),
(8631, 185211, 6, '加入腸粉炒勻。'),
(8632, 185211, 7, '預備一個焗盤，鋪上一層腸粉，灑上水牛芝士碎，重覆此步驟至滿。'),
(8633, 185211, 8, '放入焗爐焗15-20分鐘或至表面金黃色，即成。'),
(8634, 185210, 1, '將蒜頭切成蓉；指天椒切粒。'),
(8635, 185210, 2, '雞翼洗淨抹乾，用生抽、玫瑰露、黃糖、鹽、胡椒粉、生粉及麻油醃至少1小時。'),
(8636, 185210, 3, '將鹹蛋黃蒸4-5分鐘及壓碎。'),
(8637, 185210, 4, '用中火燒熱鍋，加少許油，加入雞翼將兩面煎至金黃色及熟透。'),
(8638, 185210, 5, '用中火燒熱另一個鍋，加入牛油煮至溶化，加入蒜頭及指天椒炒香。'),
(8639, 185210, 6, '加入鹹蛋黃炒至起泡，加入雞翼拌勻，即成。'),
(8640, 179160, 1, '大蔥一半切碎，蒜頭切成蓉，備用；準備一個鍋，加入適量水、花椒、薑、另一半大蔥、紹興酒及豬耳，煮40分鐘。'),
(8641, 179160, 2, '取出豬耳降溫，切絲。'),
(8642, 179160, 3, '加入大蔥碎、蒜蓉、豉油、麻油、青椒油、黑醋、胡椒粉、鹽、砂糖、雞粉及花椒油，拌勻。'),
(8643, 179160, 4, '加入油炸花生及芫茜，拌勻即成。'),
(8644, 183221, 1, '排骨切件，放入滾水中汆水，取出洗乾淨，瀝乾備用。'),
(8645, 183221, 2, '準備一個平底鍋，加入油、薑及排骨，煎至排骨上色。'),
(8646, 183221, 3, '加入紹興酒、老抽、冰糖、鎮江香醋及水，燜煮20分鐘。'),
(8647, 183221, 4, '加入胡椒粉及鹽調味，上碟，灑上白芝麻及蔥粒，即成。'),
(8648, 185184, 1, '粉絲置水中，浸泡半小時後，隔水備用。'),
(8649, 185184, 2, '燒熱水把乾荷葉放入水中煮軟，撈起用清水沖洗乾淨。'),
(8650, 185184, 3, '將一半蒜蓉加進鑊中，加油炒香成熟蒜；然後將生熟蒜混合，加入鹽備用。'),
(8651, 185184, 4, '海蝦洗淨，將蝦背?開，挑去蝦腸，剪去頭、鬚及腳，印乾備用。'),
(8652, 185184, 5, '將荷葉鋪在竹籠內，底層鋪上粉絲，再鋪上海蝦及生熟蒜，然後將荷葉封好，隔水蒸15-20分鐘。'),
(8653, 185184, 6, '加入芫茜及適量麻油、豉油調味，即成。'),
(8654, 185206, 1, '紅酒燉牛頰肉：將洋蔥、紅蘿蔔及西芹切塊，蒜頭及細香蔥切碎；切走牛頰肉多餘筋膜，印乾水分，用鹽及黑胡椒調味。'),
(8655, 185206, 2, '準備一個厚底深鍋，用中高火燒熱橄欖油，放入牛頰肉煎至兩面金黃色。取出煎好的牛頰肉，用錫紙蓋好保溫。'),
(8656, 185206, 3, '燒熱同一個鍋， 加入洋蔥、紅蘿蔔及西芹，炒15分鐘至軟身。'),
(8657, 185206, 4, '加入蒜蓉及茄膏炒勻，再加入百里香、迷迭香、月桂葉，拌勻後煮3分鐘。'),
(8658, 185206, 5, '倒入紅酒，攪拌並將鍋底的焦刮起，煮至微滾後，再煮2分鐘。'),
(8659, 185206, 6, '加入煎好的牛頰肉及牛肉湯 。'),
(8660, 185206, 7, '煮滾後，蓋上鍋蓋用中低火燉3小時或直至牛頰肉軟稔熟透，加入鹽及黑胡椒調味。'),
(8661, 185206, 8, '取出牛頰肉，用小火將醬汁煮至稠身。'),
(8662, 185206, 9, '將牛頰肉上碟，灑上細香蔥，伴以薯蓉享用。'),
(8663, 185206, 10, '香滑薯蓉：準備一個大鍋，放入水及適量鹽煮滾，再放入已去皮切塊的薯仔，煮15-20分鐘或直至薯仔變得非常軟稔。'),
(8664, 185206, 11, '熄火，瀝乾薯仔，倒去鍋內的水，再將薯仔放回鍋內。'),
(8665, 185206, 12, '加入牛油拌勻及壓成蓉，分數次加入牛奶拌勻，直至薯蓉變得幼滑。'),
(8666, 185206, 13, '加入鹽及黑胡椒調味，可按個人喜好，加入額外的牛奶做出更幼滑的薯蓉。'),
(8667, 185143, 1, '將牛奶用低火煮熱。'),
(8668, 185143, 2, '加入三文飯糰，拆散再拌勻。'),
(8669, 185143, 3, '加入蝦仁煮至熟透。'),
(8670, 185143, 4, '加入淡忌廉和水牛芝士拌勻，即成。'),
(8671, 185155, 1, '將蔥切粒；雞蛋打發；蒜頭切成蓉備用。'),
(8672, 185155, 2, '免治豬肉用生抽、砂糖、胡椒粉、生粉及麻油醃15分鐘。'),
(8673, 185155, 3, '用中火燒熱鍋，加少許油，加入蒜蓉炒香。'),
(8674, 185155, 4, '加入免治豬肉炒熟，加入白飯炒至鬆散。'),
(8675, 185155, 5, '加入蛋液炒至飯粒裹上蛋漿。'),
(8676, 185155, 6, '加入欖菜、蔥粒及鹽炒勻，即成。'),
(8677, 185188, 1, '指天椒半隻去籽，其餘切絲；蒜頭拍扁去衣；水滖後將蜆煮1分半鐘。'),
(8678, 185188, 2, '見蜆殼呈半開口狀態可以熄火。'),
(8679, 185188, 3, '將水隔開。'),
(8680, 185188, 4, '之後將蜆殼打開，另一半蜆殼掉去，處理好的蜆肉備用。'),
(8681, 185188, 5, '鍋燒熱下油2湯匙。'),
(8682, 185188, 6, '先將蒜頭炒香。'),
(8683, 185188, 7, '再落糖略炒。'),
(8684, 185188, 8, '加入蜆肉'),
(8685, 185188, 9, '加入2湯匙水及魚露。'),
(8686, 185188, 10, '加入辣椒炒香。'),
(8687, 185188, 11, '此時落半份金不換繼續炒。'),
(8688, 185188, 12, '最後加入其餘金不換便可上碟。'),
(8689, 185153, 1, '將芫茜及蔥切碎備用。'),
(8690, 185153, 2, '珍珠蠔用生粉抓洗，沖洗乾淨。煮滾一鍋水，加入紹興酒，加入珍珠蠔汆水20秒，瀝乾備用。'),
(8691, 185153, 3, '將鴨蛋打發，加入清水拌勻，逐少加入番薯粉拌勻。'),
(8692, 185153, 4, '加入芫茜、蔥、珍珠蠔、鹽及胡椒粉拌勻。'),
(8693, 185153, 5, '用中高火燒熱鍋，加入適量油，倒入蛋漿，以半煎炸方式煎至兩面金黃色。'),
(8694, 185153, 6, '伴以魚露享用，即成。'),
(8695, 184669, 1, '將雞蛋放入滾水煮6分鐘，用冰水冷卻，剝去外殼。'),
(8696, 184669, 2, '放進密實袋，加入豉油、味醂、砂糖及適量水，然後將密實袋封好，放過夜後切半。'),
(8697, 184669, 3, '預熱焗爐至攝氏190度；將麵條放入滾水中煮熟，撈起過冷河。'),
(8698, 184669, 4, '加入黑胡椒、豉油、麻油及砂糖拌勻。'),
(8699, 184669, 5, '鬆餅模掃一層油，將麵條份成6等份，放入鬆餅模中，焗20分鐘。'),
(8700, 184669, 6, '麵杯從鬆餅模中脫模，放上煎熟的煙肉、車厘茄及溏心蛋，即可。'),
(8701, 185136, 1, '粟米去皮切件；淮山及紅棗浸洗；瘦肉汆水。'),
(8702, 185136, 2, '煮滾2000毫升水，加入所有材料，用文火煮大約1.5小時，加鹽調味即可。'),
(8703, 185089, 1, '將香蕉切粒備用。'),
(8704, 185089, 2, '將低筋麵粉、無糖可可粉及泡打粉過篩，加入砂糖拌勻。'),
(8705, 185089, 3, '加入雞蛋拌勻，分次加入牛奶拌勻至沒有顆粒，加入菜油拌勻。'),
(8706, 185089, 4, '用低火燒熱鱆魚燒電熱鍋，掃上油，倒入麵糊至7成滿。'),
(8707, 185089, 5, '加入香蕉及朱古力粒，倒入麵糊蓋上饀料，用低火烤3-4分鐘。'),
(8708, 185089, 6, '用竹籤翻面及整圓，再烤2-3分鐘。'),
(8709, 185089, 7, '上碟，灑上糖霜，即成。'),
(8710, 185126, 1, '將牛油和砂糖打發均勻。'),
(8711, 185126, 2, '分2次拌入蛋黃液 。'),
(8712, 185126, 3, '加入低筋麵粉拌勻，備用。'),
(8713, 185126, 4, '白方包一開四。'),
(8714, 185126, 5, '將蘋果山楂蜜茶塗在白方包，蓋上另一塊白方包。'),
(8715, 185126, 6, '塗上牛油混合物，界出交叉紋路。'),
(8716, 185126, 7, '放入焗爐以攝氏180度焗10分鐘，即成。'),
(8717, 185144, 1, '蛋白與蛋黃分開，蛋白放入大碗內打至企身，加入蛋黃發至均勻。'),
(8718, 185144, 2, '在另一大碗內加入中筋麵粉及泡打粉過篩。'),
(8719, 185144, 3, '將麵粉加入蛋漿、橄欖油、牛奶拌勻。'),
(8720, 185144, 4, '加入芝士粉、鹽、胡椒粉、香草、車厘茄及菠菜蓉拌勻。'),
(8721, 185144, 5, '焗盤內塗上牛油及洒上麵粉，將多餘的麵粉倒出。'),
(8722, 185144, 6, '放入八成麵糊，放上半邊車厘茄裝飾。'),
(8723, 185144, 7, '預熱焗爐180°C焗35分鐘便完成。'),
(8724, 184650, 1, '將醬汁材料拌勻成醬汁，備用。'),
(8725, 184650, 2, '準備一個煎鍋，加入適量油，放入漢堡牛扒，用中小火煎10分鐘，至肉餅熟透，盛起備用。'),
(8726, 184650, 3, '煎鍋中放入少量油，放入菠蘿片及牛油，菠蘿正反兩面各煎2分鐘，盛起備用；煙肉煎至金黃色；盛起備用。'),
(8727, 184650, 4, '在漢堡麵包面放上芝士，放入焗爐用攝氏180度焗3-5分鐘。'),
(8728, 184650, 5, '在漢堡麵包底抹上醬汁，放上菠蘿、漢堡牛扒及煙肉。'),
(8729, 184650, 6, '放上漢堡麵包面，即成。'),
(8730, 185088, 1, '將洋蔥、番茄及紅燈籠椒切粒；蒜頭及番茜切碎；蝦洗淨去腸；青口洗淨印乾；白酒浸番紅花；檸檬切角備用。'),
(8731, 185088, 2, '用中火燒熱電熱鍋，加少許油，加入西班牙辣肉腸炒香，加入甜椒粉炒勻。'),
(8732, 185088, 3, '加入蒜頭及洋蔥炒香，加入番茄和紅燈籠椒炒香。'),
(8733, 185088, 4, '加入西班牙米炒勻及鋪平，加入白酒及番紅花煮至酒精揮發，加入海鮮高湯煮滾，加少許鹽及黑胡椒調味。'),
(8734, 185088, 5, '蓋上鍋蓋，轉低火煮10分鐘。'),
(8735, 185088, 6, '打開鍋蓋，鋪上海鮮，蓋上鍋蓋，再煮8-10分鐘或至熟透 。'),
(8736, 185088, 7, '灑上番茜，鋪上檸檬，即成。'),
(8737, 183740, 1, '預熱焗爐至攝氏200度；薯仔洗乾淨，放入滾水煮25分鐘，備用。'),
(8738, 183740, 2, '煙肉切粒，煎至金色，備用。'),
(8739, 183740, 3, '將煮好的薯仔去皮壓成蓉，加入牛奶、淡忌廉、鹽及黑胡椒，拌勻。'),
(8740, 183740, 4, '準備焗模，加入薯蓉至7分滿，鋪平，灑上煙肉及水牛芝士。'),
(8741, 183740, 5, '放入焗爐焗8-10分鐘，至芝士溶化，即成。'),
(8742, 185087, 1, '將雞蛋打發；椰菜切碎；熟鱆魚、紅薑及蔥切粒。'),
(8743, 185087, 2, '將蛋液 、鰹魚高湯、牛奶、鰹魚醬油、已過篩的低筋麵粉及鹽拌勻，靜置15分鐘。'),
(8744, 185087, 3, '用中火燒熱鱆魚燒電熱鍋，掃上油，倒入麵糊至8成滿， 灑上椰菜，加入熟鱆魚、蔥花及紅薑，再加入麵糊至滿。'),
(8745, 185087, 4, '麵糊開始凝固時，用竹籤界開，將多餘的麵糊收圓，將鱆魚燒翻面90度，再次倒入麵糊，將鱆魚燒整圓。'),
(8746, 185087, 5, '加上少許油，不時用竹籤將鱆魚燒整圓，燒至金黃色，上碟。'),
(8747, 185087, 6, '掃上鱆魚燒醬，唧上蛋黃醬，灑上紫菜粉及木魚碎，即成。'),
(8748, 185091, 1, '青邊鮑解凍後洗淨抺乾，剪去咀及群邊。'),
(8749, 185091, 2, '放進保鮮袋，抽真空後以攝氏75度，慢煮40小時。'),
(8750, 185091, 3, '取出鮑魚切成薄片，排好在碟上。'),
(8751, 185091, 4, '保鮮袋中的鮑魚汁，加入清酒、蠔油、麻油及砂糖煮滾，加生粉水埋芡，倒在鮑魚片上即成。'),
(8752, 185047, 1, '將魚膠粉、伯爵茶茶葉及鮮奶拌勻，隔熱水座溶。'),
(8753, 185047, 2, '將黑朱古力隔熱水座溶。'),
(8754, 185047, 3, '將淡忌廉及糖粉用電動打蛋器打發至8成企身。'),
(8755, 185047, 4, '加入黑朱古力，篩入魚膠粉溶液，加入朱古力酒及拌勻。'),
(8756, 185047, 5, '放入唧花袋，唧入甜品杯，放入雪櫃冷藏1小時，即成。'),
(8757, 185077, 1, '將急凍酥皮切成9個正方形。'),
(8758, 185077, 2, '塗上白汁意粉醬。'),
(8759, 185077, 3, '放上蝦仁和水牛芝士碎。'),
(8760, 185077, 4, '掃上蛋液。'),
(8761, 185077, 5, '放入焗爐以180度焗15分鐘，即成。'),
(8762, 185046, 1, '將2個伯爵茶茶包泡在熱水5分鐘。取出茶包，加入45毫升淡忌廉及1湯匙糖粉拌勻備用。'),
(8763, 185046, 2, '將餘下的淡忌廉用電動打蛋器打發至8成企身備用。'),
(8764, 185046, 3, '馬斯卡彭芝士用電動打蛋器打發至鬆軟，加入糖粉打勻。'),
(8765, 185046, 4, '倒出餘下的伯爵茶茶葉，加入1/2湯匙熱水拌勻至微濕狀態，加入芝士混合物中拌勻。'),
(8766, 185046, 5, '加入淡忌廉、橙皮及威士忌拌勻，放入擠花袋 。'),
(8767, 185046, 6, '將手指餅乾浸泡在伯爵茶約1-2秒。在甜品杯擠上一層伯爵芝士，鋪入手指餅乾，再擠上一層伯爵芝士，重覆此動作直至鋪滿甜品杯。'),
(8768, 185046, 7, '放入雪櫃冷藏2小時，灑上裝飾用可可粉，即成。'),
(8769, 180978, 1, '薑切絲；指天椒切片；蔥切碎；大蔥切件。'),
(8770, 180978, 2, '準備湯鍋，加入水，將大蔥、薑及雞髀放入鍋內，燜煮20-25分鐘，取出切件，上碟。'),
(8771, 180978, 3, '準備碗，放入蒜蓉、指天椒、蔥及花生碎，淋上熱油，加入花椒油、生抽、蠔油、麻油、醋、芫茜及鹽，拌勻。'),
(8772, 180978, 4, '淋上雞髀，即成。'),
(8773, 184958, 1, '預熱焗爐至攝氏200度；蔥白切碎；蒜切成蓉。'),
(8774, 184958, 2, '將豬肋排、所有醃料、蔥白、薑及蒜均勻，密封好，放入雪櫃冷藏醃製4小時以上。'),
(8775, 184958, 3, '將醃好的豬肋排均勻放入刷上油的玻璃烤盤上。'),
(8776, 184958, 4, '鋪上錫紙，烤焗約45分鐘左右，即成。'),
(8777, 185045, 1, '預熱焗爐至攝氏180度，焗盤鋪上牛油紙備用。'),
(8778, 185045, 2, '將牛油及糖粉用電動打蛋器打發至軟滑，加入雲呢拿香油拌勻。'),
(8779, 185045, 3, '加入蛋黃拌勻，加入伯爵茶茶葉拌勻，篩入粟粉及低筋麵粉，拌勻。'),
(8780, 185045, 4, '整形成圓條狀的麵團，放入雪櫃冷藏1小時至硬身。'),
(8781, 185045, 5, '切成0.5厘米厚，放上焗盤，放入焗爐焗10-12分鐘至表面金黃色，放涼後即成。'),
(8782, 185044, 1, '麵包一開四後，放入焗爐用攝氏200度烘6-7分鐘至金黃色的脆身多士。'),
(8783, 185044, 2, '薯仔去皮切粒後，放隔水蒸15分鐘至軟身。'),
(8784, 185044, 3, '多士從焗爐取出後，放上撕細塊的煙三文魚。'),
(8785, 185044, 4, '把低脂蛋黃醬、芥末醬、鹽和煮過的薯仔拌勻成沙律，然後放在多士上。'),
(8786, 185044, 5, '灑上煙肉碎，即成。'),
(8787, 184982, 1, '將餃子皮煮熟。'),
(8788, 184982, 2, '然後浸冰水，瀝乾水備用。'),
(8789, 184982, 3, '士多啤梨切片，備用。'),
(8790, 184982, 4, '將黃豆粉、肉桂粉和砂糖拌勻。'),
(8791, 184982, 5, '把餃子皮沾上黃豆粉混合物。'),
(8792, 184982, 6, '包入紅豆蓉和士多啤梨，對摺，即成。'),
(8793, 185000, 1, '將雞胸肉及洋蔥切件；青燈籠椒及紅燈籠椒去籽切件；芒果起肉切粒；蒜頭切成蓉備用。'),
(8794, 185000, 2, '雞胸肉用鹽及胡椒粉醃30分鐘。'),
(8795, 185000, 3, '用中火燒熱鍋，加少許油，加入蒜蓉、薑蓉及洋蔥炒香。'),
(8796, 185000, 4, '加入雞胸肉炒香，加入咖喱粉及黃薑粉炒香。'),
(8797, 185000, 5, '加入青燈籠椒、紅燈籠椒及雞湯煮滾。'),
(8798, 185000, 6, '加入芒果及椰漿煮2分鐘，即成。'),
(8799, 184999, 1, '預熱焗爐至攝氏200度，焗盤鋪上牛油紙備用。'),
(8800, 184999, 2, '將忌廉芝士、糖粉、雲呢拿油及檸檬汁打勻備用。'),
(8801, 184999, 3, '將急凍酥皮切成9等分，摺成鑽石形。'),
(8802, 184999, 4, '在中間放上適量忌廉芝士、藍莓果醬、新鮮藍莓及杏仁片。'),
(8803, 184999, 5, '將雞蛋打發，加1湯匙水拌勻。酥皮掃上蛋液，放上焗盤。'),
(8804, 184999, 6, '放入焗爐焗12-15分鐘至表面金黃色，即成。'),
(8805, 184797, 1, '慢慢加入水到糯米粉，搓成麵糰，分成兩份。'),
(8806, 184797, 2, '在其中一份麵糰中，放入紅麴粉揉勻，備用。'),
(8807, 184797, 3, '各取2個麵糰的一小部分，混合，揉搓成小球狀。'),
(8808, 184797, 4, '放入水中煮至浮起，撈出，備用。'),
(8809, 184797, 5, '準備湯鍋，放入適量水，加熱，放入冰糖和桂花，煮開，加入雞蛋煮成蛋花。'),
(8810, 184797, 6, '加入湯圓和酒釀，熄火即成。'),
(8811, 184878, 1, '將食材清洗乾淨，白蘑菇切件，芹菜切成小段，乾蔥切件，紅辣椒切粒。'),
(8812, 184878, 2, '電飯煲內刷上沙甸魚油，加入蒜末，備用。'),
(8813, 184878, 3, '將白米洗淨，放入電飯煲內，加入車厘茄、白蘑菇、乾蔥、沙甸魚、鹽及雞湯。'),
(8814, 184878, 4, '燜煮40分鐘，取出，灑上芹菜、紅辣椒及白芝麻，拌勻，上碟，即成。'),
(8815, 184998, 1, '預熱焗爐至攝氏200度，焗盤鋪上錫紙備用。'),
(8816, 184998, 2, '豬頸肉洗淨抹乾，用1湯匙生抽、老抽、玫瑰露、砂糖及麻油醃至少1小時。'),
(8817, 184998, 3, '將豬頸肉放上焗盤，放入焗爐每面焗10分鐘。'),
(8818, 184998, 4, '將士多啤梨、餘下的生抽及茄汁打成蓉 。'),
(8819, 184998, 5, '豬頸肉掃上士多啤梨汁，每面焗5分鐘，即成。'),
(8820, 184596, 1, '將雞髀切粒。'),
(8821, 184596, 2, '雞蛋用攪拌機打發，加入少許鹽，攪拌至完全起泡。'),
(8822, 184596, 3, '用平底鍋加熱少律油，倒入洋蔥翻炒片刻，倒入雞肉炒至變色，加入茄汁、生抽及胡椒粉炒勻。'),
(8823, 184596, 4, '加入白飯，並輕力拌勻。'),
(8824, 184596, 5, '將蛋液倒入另一個鍋內，用小火煎熟。'),
(8825, 184596, 6, '將白飯倒入蛋皮中，鋪平，用小火煎3分鐘。'),
(8826, 184596, 7, '用右半邊蛋皮將左半邊白飯包裹起來，即成。'),
(8827, 184967, 1, '將魚膠片浸軟，瀝乾水備用。'),
(8828, 184967, 2, '將水和黃糖以小火加熱至溶解，關火。'),
(8829, 184967, 3, '加入魚膠片攪拌至溶化。'),
(8830, 184967, 4, '加入梅酒拌勻。'),
(8831, 184967, 5, '將脆梅放入模內，倒入梅酒混合物並冷藏3小時或至凝固，即成。'),
(8832, 184943, 1, '將清水加入冰糖，用中火將冰糖煮至溶化，放涼備用。'),
(8833, 184943, 2, '準備一鍋水，放入蒸架及放入蒸碗，用中高火將水煮滾。'),
(8834, 184943, 3, '將雞蛋打發，加入冰糖水拌勻，過濾後倒入蒸碗，蓋上錫紙。'),
(8835, 184943, 4, '用中低火蒸15分鐘或至熟，即成。'),
(8836, 184868, 1, '預熱焗爐至攝氏190度。'),
(8837, 184868, 2, '雞蛋加入胡椒粉打發，備用。'),
(8838, 184868, 3, '準備煎鍋，加入適量油，放入水餃，大火煎至底部上色，倒入適量的水，燜煮5分鐘。'),
(8839, 184868, 4, '倒入準備好的蛋液，在餃子表面刷上茄汁。'),
(8840, 184868, 5, '加入青豆、粟米及芝士，放入焗爐焗約6分鐘。'),
(8841, 184868, 6, '取出，灑上蔥粒即成。'),
(8842, 184942, 1, '將牛奶、雞蛋、細砂糖及雲呢拿香油拌勻。'),
(8843, 184942, 2, '將麵包浸在牛奶中6-8小時，並放入雪櫃冷藏。'),
(8844, 184942, 3, '預熱焗爐至攝氏180度。'),
(8845, 184942, 4, '用中火燒熱鍋，加入牛油煮至融化，加入麵包煎至兩面金黃色。'),
(8846, 184942, 5, '將麵包放上焗盤，放入焗爐焗10分鐘。'),
(8847, 184942, 6, '淋上楓糖，即成。'),
(8848, 184944, 1, '將蔥切粒；瑤柱浸軟撕成絲備用。'),
(8849, 184944, 2, '將雞蛋打發，加入浸瑤柱水拌勻。'),
(8850, 184944, 3, '將瑤柱絲放入蒸碟，蛋液過濾後加入，蓋上保鮮紙。'),
(8851, 184944, 4, '用中高火蒸12-15分鐘。'),
(8852, 184944, 5, '用中火燒熱鍋，加入油及蒸魚豉油煮滾。'),
(8853, 184944, 6, '蒸蛋灑上蔥粒，伴以豉油享用 。'),
(8854, 184938, 1, '日本南瓜去皮，1/3刨絲備用。'),
(8855, 184938, 2, '另外2/3南瓜切件，蒸15分鐘至軟身，取出南瓜件壓成南瓜蓉。'),
(8856, 184938, 3, '用白鑊爆香南瓜籽仁，盛起備用。'),
(8857, 184938, 4, '南瓜蓉加入生粉、麵粉，邊攪拌邊加入清水，混成糊狀，再加入南瓜籽仁及南瓜絲。'),
(8858, 184938, 5, '隨個人喜愛，選擇製作甜或咸味煎餅，在麵粉糊加入少量糖／鹽。'),
(8859, 184938, 6, '平底鍋加適量的油，倒入及熨平麵粉糊，至直徑20cm及厚度約1cm。'),
(8860, 184938, 7, '用小火慢慢煎，至兩面金黃熟透即完成。'),
(8861, 184939, 1, '準備蜜汁紅蔥頭：將紅蔥頭去衣備用。'),
(8862, 184939, 2, '加入砵酒、意大利香醋、雞湯、月桂葉及蜜糖，煮滾後轉小火，煮至紅蔥頭軟身及如糖漿般稠身，大約30-40分鐘。'),
(8863, 184939, 3, '準備迷你焗薯批：預熱焗爐至攝氏180度。'),
(8864, 184939, 4, '薯仔去皮，切成厚度約2毫米的薄片，放入清水中浸泡5-10分鐘。'),
(8865, 184939, 5, '將牛油、蒜蓉、厚忌廉、2根百里香、鹽及黑胡椒用小火煮熱拌勻，約2-3分鐘。'),
(8866, 184939, 6, '在鬆餅模上掃上食油備用。'),
(8867, 184939, 7, '將薯仔薄片印乾水分，放入鬆餅模中至半滿，放上忌廉混合物，灑上芝士碎。繼續放上薯仔薄片直至鋪滿焗盤，再放上忌廉混合物及芝士碎。 重複以上步驟，直至用完薯仔薄片為止。'),
(8868, 184939, 8, '在薯仔表面上灑上百里香，用錫紙蓋好，放入焗爐焗35分鐘。'),
(8869, 184939, 9, '取出焗盤並取走錫紙，於薯批上灑上芝士碎，再放入焗爐焗10分鐘，或直至芝士溶化及變成金黃色。焗好後取出焗盤，靜置待涼5分鐘，再取出薯批。'),
(8870, 184939, 10, '準備香煎鴨胸：將蘆筍切去尾部、刨皮及切半。'),
(8871, 184939, 11, '印乾鴨胸肉。'),
(8872, 184939, 12, '用利刀將鴨皮?成菱形花紋，小心不要切入鴨肉中。'),
(8873, 184939, 13, '鴨胸肉用鹽及黑胡椒調味。'),
(8874, 184939, 14, '用中高火燒熱煎鍋，加入少許橄欖油，放入鴨胸，鴨皮向下。將鴨皮煎2-3分鐘，再轉小火煎5-6分鐘，直至變成金黃色為止。'),
(8875, 184939, 15, '取起鴨胸，倒出多餘油分。將鴨胸反轉，轉為中火。尺寸比較小的鴨胸，可以煎4分鐘至五成熟，較大件的鴨胸則可以煎10-12分鐘。'),
(8876, 184939, 16, '取出鴨胸放上砧板，蓋上錫紙，待涼5分鐘再切片。'),
(8877, 184939, 17, '用一個煎鍋，倒走煎鍋中的多餘油脂，放入蘆筍，加入鹽及黑胡椒調味，炒5分鐘，備用。'),
(8878, 184939, 18, '擺盤：薯批放在碟上，將3-4片鴨胸放於薯批旁邊。'),
(8879, 184939, 19, '將3粒紅蔥頭放上碟上，再放上蘆筍，在碟上淋上少許醬汁，最後放上灑上百里香，即成。'),
(8880, 184897, 1, '將雞蛋稍稍打發；雞腿肉切塊；洋蔥切絲；蔥切粒備用。'),
(8881, 184897, 2, '雞腿肉用鹽及胡椒粉醃10分鐘。'),
(8882, 184897, 3, '準備一個鍋，加入日本豉油、味醂、清酒、砂糖、鰹魚粉及清水，用中火煮滾。'),
(8883, 184897, 4, '加入洋蔥，用中低火煮3分鐘。'),
(8884, 184897, 5, '加入雞腿肉用中火煮滾，蓋上鍋蓋，轉中低火煮3-4分鐘至熟。'),
(8885, 184897, 6, '加入蛋液，蓋上鍋蓋煮 1-2分鐘或至蛋液凝固。'),
(8886, 184897, 7, '鋪上飯，灑上紫菜碎，即成。'),
(8887, 184932, 1, '將200克白朱古力隔熱水座溶，加入30克阿華田粉拌勻，備用。'),
(8888, 184932, 2, '將酥皮切成3份等份的長方形。'),
(8889, 184932, 3, '將阿華田粉灑在酥皮上，然後包入餘下的白朱古力並捲起。'),
(8890, 184932, 4, '放入焗爐以200°C焗20分鐘。'),
(8891, 184932, 5, '淋上阿華田朱古力。'),
(8892, 184932, 6, '灑上阿華田粉和無糖可可粉，即成。'),
(8893, 184896, 1, '將雞腿肉切件；雞蛋打發；洋蔥、烚蛋及溫室青瓜切粒。'),
(8894, 184896, 2, '雞腿肉用鹽及黑胡椒調味，沾上中筋麵粉及蛋液。'),
(8895, 184896, 3, '用中火燒熱鍋，加入適量油，油滾後加入雞腿肉半煎炸至熟透，放上廚紙印去多餘油分。'),
(8896, 184896, 4, '預備他他醬。將烚蛋 、洋蔥、溫室青瓜、蛋黃醬、鹽及黑胡椒拌勻。'),
(8897, 184896, 5, '準備一個鍋，加入米醋、日本豉油、味醂、日本料理酒及細砂糖煮至微滾備用。'),
(8898, 184896, 6, '雞腿肉趁熱沾上南蠻醋，淋上他他醬，即成。'),
(8899, 184277, 1, '牛肉、薑及洋蔥切碎，加入紹興酒、生抽、蠔油、砂糖、胡椒粉及鹽，拌勻備用。'),
(8900, 184277, 2, '準備鍋貼皮，放入牛肉餡，用手蘸水塗在鍋貼皮兩邊，然後將中間收口。'),
(8901, 184277, 3, '重覆以上步驟包好所有鍋貼，備用。'),
(8902, 184277, 4, '準備煎鍋，放入少許油，加熱，整齊放入鍋貼，大火加熱2分鐘。'),
(8903, 184277, 5, '加入1/3的水，蓋上鍋蓋燜煮9分鐘。'),
(8904, 184277, 6, '取出，灑上蔥粒即成。'),
(8905, 184895, 1, '將洋蔥切碎；薯仔去皮切片蒸軟。'),
(8906, 184895, 2, '將薯仔趁熱壓成蓉。'),
(8907, 184895, 3, '用中火燒熱鍋，加少許油，加入洋蔥炒香，加入免治牛肉炒熟，加少許鹽及黑胡椒調味，放涼備用。'),
(8908, 184895, 4, '加入薯蓉拌勻，捏成餅狀。'),
(8909, 184895, 5, '將雞蛋打發，薯餅順序沾上中筋麵粉、蛋液及麵包糠。'),
(8910, 184895, 6, '準備炸油鍋，用中火將薯餅炸至金黃色，放上廚紙印去多餘油分，即成。'),
(8911, 184883, 1, '將黑芝麻炒熟，加入孜然粉及五香粉，拌勻備用。'),
(8912, 184883, 2, '豬肉、燕麥、糖、鹽和生抽拌勻，醃約20分鐘。'),
(8913, 184883, 3, '豬肉搓成肉餅。'),
(8914, 184883, 4, '表面沾上芝麻調味粉。'),
(8915, 184883, 5, '放在油鑊中煎至兩面金黃色，即成。'),
(8916, 184844, 1, '將蔥切段。'),
(8917, 184844, 2, '豬扒洗淨抹乾，用刀背拍鬆。'),
(8918, 184844, 3, '加入生抽、紹興酒、水、砂糖、胡椒粉、麻油及生粉醃15分鐘。'),
(8919, 184844, 4, '用中火燒熱鍋，加入豬扒煎至兩面金黃色，轉中低火煎至熟透。'),
(8920, 184844, 5, '加入蔥段及DayDayCook雙重蔥油醬炒勻，即成。'),
(8921, 184874, 1, '將煙肉切半。'),
(8922, 184874, 2, '灑適量黑椒碎在煙肉上。'),
(8923, 184874, 3, '將煙肉捲起年糕條。'),
(8924, 184874, 4, '下油，將煙肉卷煎至金黃。'),
(8925, 184874, 5, '加入燒肉汁煮約2分鐘。'),
(8926, 184874, 6, '灑上水牛芝士碎，即成。'),
(8927, 184843, 1, '將豆卜切半。'),
(8928, 184843, 2, '將排骨沖水10分鐘，洗淨瀝乾後加入DayDayCook蝦米豆豉醬、生抽、紹興酒、砂糖、胡椒粉、麻油及生粉醃10分鐘。'),
(8929, 184843, 3, '在蒸碟放上豆卜及排骨。'),
(8930, 184843, 4, '用中高火蒸10-12分鐘或至熟透，即成。'),
(8931, 183652, 1, '將牛奶、粟粉及砂糖用小火加熱，攪拌至濃稠，熄火放涼，放入雪櫃冷藏至定型，切件備用。'),
(8932, 183652, 2, '製作麵糊：將麵粉、粟粉、泡打粉及鹽拌勻，慢慢加入水，拌勻，再加入油至光滑，備用。'),
(8933, 183652, 3, '準備油炸鍋，將鮮奶塊沾上麵糊，放入油鍋，炸至上色。'),
(8934, 183652, 4, '灑上糖粉，即成。'),
(8935, 184842, 1, '將貓耳朵浸洗；青瓜切件及拍扁。'),
(8936, 184842, 2, '青瓜加少許鹽拌勻醃30分鐘，洗去鹽分，瀝乾備用。'),
(8937, 184842, 3, '煮滾一鍋水，加入貓耳朵汆水2分鐘，撈起放入冰水冷卻，瀝乾備用。'),
(8938, 184842, 4, '將DayDayCook香菇酸辣醬、黑醋及砂糖拌勻，加入貓耳朵及青瓜拌勻，即成。'),
(8939, 184845, 1, '將叉燒及椰菜切絲；甘筍去皮切絲。'),
(8940, 184845, 2, '煮滾一鍋水，加少許油及鹽，加入新竹米粉汆水1-2分鐘，撈起瀝乾後焗10分鐘。'),
(8941, 184845, 3, '用中火燒熱鍋，加少許油，加入叉燒及甘筍炒香。'),
(8942, 184845, 4, '加入椰菜炒軟，加入雞湯煮滾。'),
(8943, 184845, 5, '加入米粉炒勻，加入DayDayCook 櫻花蝦菜脯醬及生抽 炒勻，即成。'),
(8944, 184849, 1, '番茄去蒂；牛肉切條，加入鹽、生抽和胡椒粉醃20分鐘。'),
(8945, 184849, 2, '白米洗淨後放在飯煲中，加入燕麥，然後加入水。'),
(8946, 184849, 3, '把番茄放在飯中間，再放入粟米及醃過的牛肉，再加入油和黑椒。'),
(8947, 184849, 4, '按煮飯模式，煮好後把番茄壓爛、拌勻即可。'),
(8948, 184791, 1, '將玉子豆腐切件；蔥切粒。'),
(8949, 184791, 2, '玉子豆腐沾上生粉。用中火燒熱鍋，加少許油，加入玉子豆腐煎至兩面金黃色。'),
(8950, 184791, 3, '加入蔥粒、生抽及砂糖炒勻。'),
(8951, 184791, 4, '加入麻油炒勻，即成。'),
(8952, 184840, 1, '粟米片放入食物袋輾碎，備用。'),
(8953, 184840, 2, '將希臘乳酪、牛奶和士多啤梨果醬拌勻。'),
(8954, 184840, 3, '先鋪一層粟米片碎，再鋪上乳酪混合物，按此順序再鋪1至2層。'),
(8955, 184840, 4, '放上士多啤梨，即成。'),
(8956, 184548, 1, '先準備蛋糕胚：用攪拌機將忌廉芝士、砂糖、雞蛋及麵粉拌勻。加入檸檬汁拌勻，再加入牛油溶液拌勻。'),
(8957, 184548, 2, '蘋果去皮去芯，切片，約5毫米厚。'),
(8958, 184548, 3, '將牛油、蘋果片、砂糖及紅糖用中火煮5分鐘，一邊煮一邊攪拌。'),
(8959, 184548, 4, '將蘋果片整齊地鋪在電飯煲裡，倒入煮好的蘋果糖漿。'),
(8960, 184548, 5, '將蛋糕胚麵糊倒入電飯鍋，煮40分鐘即成。'),
(8961, 184548, 6, '可配上乳酪、果醬及薄荷享用。'),
(8962, 184790, 1, '將蔥及洋蔥切粒。'),
(8963, 184790, 2, '將薯仔刨成絲，浸水15分鐘及瀝乾水分備用。'),
(8964, 184790, 3, '將免治牛肉用生抽、砂糖及黑胡椒醃10分鐘。'),
(8965, 184790, 4, '將薯絲、免治牛肉、洋蔥、蔥、雞蛋、鹽及中筋麵粉拌勻。'),
(8966, 184790, 5, '用中火燒熱鍋，加少許油，加入適量薯絲混合物煎至兩面金黃色，即成。'),
(8967, 184319, 1, '將硬豆腐及糯米粉放到碗中搓勻。'),
(8968, 184319, 2, '加入麵粉、砂糖、生粉及泡打粉，搓勻製成麵團。'),
(8969, 184319, 3, '將麵團分成15克左右的小麵團，搓成圓形。'),
(8970, 184319, 4, '在正方形烘焙紙上排列成圓圈。'),
(8971, 184319, 5, '準備油鍋，燒熱至攝氏160度，將麵團放入油中，炸約5分鐘或至上色。'),
(8972, 184319, 6, '炸好的冬甩可以依據個人喜好搭配裝飾食材，即成。'),
(8973, 184789, 1, '將雞翼洗淨抹乾，用生抽、紹興酒、鹽、胡椒粉、麻油及生粉醃30分鐘。'),
(8974, 184789, 2, '用中火燒熱鍋，加少許油，加入雞翼煎至兩面金黃色及熟透。'),
(8975, 184789, 3, '將柚子蜜及1湯匙水拌勻，加入鍋中炒勻，即成。'),
(8976, 184802, 1, '糯米洗淨，加少許水及油浸泡1小時。'),
(8977, 184802, 2, '紅棗擘開及蓮子去芯，浸泡1小時。'),
(8978, 184802, 3, '將春雞內外洗淨，切去內臟、雞頭、雞腳及多餘肥膏後，印乾備用；鮮人蔘洗淨，切去蘆頭；京蔥切段，蒜頭去衣。'),
(8979, 184802, 4, '混合一枝鮮人蔘、2粒蒜瓣、蓮子、4粒紅棗及糯米，加少許鹽調味後，醸進雞肚中，為不讓餡料漏出，用竹籤將雞肚封口。'),
(8980, 184802, 5, '把釀好的春雞，及餘下的鮮人蔘、紅棗、蒜頭、京蔥、生薑放進鐵鍋，加入清水，加熱至水翻滾。'),
(8981, 184802, 6, '轉文火煮2小時，撇走湯面油份，除去竹籤，加入少量鹽及白胡椒粉調味即成。'),
(8982, 184698, 1, '將桂圓浸洗；芋頭去皮切粒蒸軟 。將芋頭趁熱壓成蓉，加入黃糖及無鹽牛油拌勻。'),
(8983, 184698, 2, '加入牛奶拌勻，搓成8克重球狀。'),
(8984, 184698, 3, '逐少將暖水及油加入糯米粉，拌勻成不沾手的麵糰，分成10克重的球狀。輕輕壓平，包入芋蓉。'),
(8985, 184698, 4, '煮滾1000毫升清水，加入薑片、桂圓及黑糖，用中火煮10分鐘直至黑糖完全溶化。'),
(8986, 184698, 5, '煮滾一鍋水，加入湯丸煮至浮面。'),
(8987, 184698, 6, '將湯丸撈至薑湯再煮1-2分鐘，即成。'),
(8988, 184786, 1, '將魚膠片浸軟，瀝乾水備用。'),
(8989, 184786, 2, '牛奶和淡忌廉用小火煮至微熱，加入砂糖攪拌至溶解。'),
(8990, 184786, 3, '加入伯爵茶包並關火浸泡15分鐘。'),
(8991, 184786, 4, '取出茶包，加入魚膠片拌至溶解。'),
(8992, 184786, 5, '倒入器皿內，冷藏3小時或至凝固，即成 。'),
(8993, 184102, 1, '預熱焗爐至攝氏170度。'),
(8994, 184102, 2, '白麵包抹上花生醬，放上棉花糖。'),
(8995, 184102, 3, '焗10分鐘或至金黃色。'),
(8996, 184102, 4, '唧上朱古力醬，放上雜莓及麥片，即成。'),
(8997, 184697, 1, '將紫米浸洗1小時備用。'),
(8998, 184697, 2, '煮滾1200毫升清水，加入紫米用中火煮滾，蓋上鍋蓋，轉中低火煮40分鐘。'),
(8999, 184697, 3, '打開鍋蓋，加入冰糖煮至溶化，加入椰漿拌勻。'),
(9000, 184697, 4, '將糯米粉及粘米粉拌勻，慢慢加入熱水拌勻成不沾手的麵糰，搓成小丸子。'),
(9001, 184697, 5, '煮滾另一鍋水，加入小丸子煮至浮起 。'),
(9002, 184697, 6, '將小丸子加入紫米露煮1分鐘，即成。'),
(9003, 184179, 1, '將糯米粉及嫩豆腐拌勻。'),
(9004, 184179, 2, '分成6個圓球搓圓，用少許麵糰點綴成柴犬形狀。'),
(9005, 184179, 3, '放入滾水中煮4分鐘。'),
(9006, 184179, 4, '將豉油、味醂、砂糖及水加熱4分鐘至煮滾，放入生粉水勾芡。'),
(9007, 184179, 5, '將煮好的丸子，用芝麻及紫菜做柴犬造型，淋上醬汁裝飾，即成。'),
(9008, 184696, 1, '將紅豆洗淨，加入水至完全蓋過紅豆，放入雪櫃冷藏一晚。'),
(9009, 184696, 2, '煮滾清水，加入紅豆用中火煮滾。蓋上鍋蓋，轉中低火煮1.5小時。'),
(9010, 184696, 3, '打開鍋蓋，加入片糖煮至溶化。'),
(9011, 184696, 4, '用中火燒熱鍋，掃上油，加入年糕煎至兩面微微金黃。'),
(9012, 184696, 5, '放入紅豆湯，即成。'),
(9013, 184760, 1, '預熱焗爐至攝氏180度；準備一個20 x 20 cm 的焗盤，鋪上牛油紙備用。'),
(9014, 184760, 2, '準備一個大碗，加入麵粉、抹茶粉、泡打粉及鹽，將碗內所有材料拌勻備用。'),
(9015, 184760, 3, '將白朱古力及牛油放入同一個碗，用小火加熱隔水溶化。'),
(9016, 184760, 4, '準備另一個碗，加入砂糖、雞蛋及雲呢拿香油，充份拌勻後，加入已溶化的朱古力拌勻。'),
(9017, 184760, 5, '將朱古力混合物倒入麵粉混合物中拌勻。'),
(9018, 184760, 6, '加入朱古力粒拌勻。'),
(9019, 184760, 7, '將麵糊倒入焗盤，灑上杏仁碎，放入焗爐焗20-25分鐘。'),
(9020, 184760, 8, '取出焗盤待涼5分鐘，脫模，將蛋糕切成正方形，灑上糖霜，即成。'),
(9021, 184761, 1, '芥蘭洗淨，摘去花，瀝乾後斜切成段。'),
(9022, 184761, 2, '生薑磨蓉，隔出薑汁50毫升，加入酒及鹽。'),
(9023, 184761, 3, '燒熱炒鍋，加入油及蒜蓉炒香。'),
(9024, 184761, 4, '加入芥蘭用大火炒，加少許糖至略為轉綠色，最後加入薑汁酒炒至乾身即成。'),
(9025, 184726, 1, '將蒜頭切片；車厘茄切半。'),
(9026, 184726, 2, '煮滾一鍋水，加少許鹽，加入意粉煮至軟硬適中，撈起瀝乾備用。'),
(9027, 184726, 3, '用中火燒熱鍋，加少許油，加入虎蝦仁炒熟，加少許鹽及黑胡椒調味，盛起備用。'),
(9028, 184726, 4, '用同一個鍋，加少許油，加入蒜片用中火炒香。'),
(9029, 184726, 5, '加入意粉略炒，加入虎蝦仁、車厘茄及DayDayCook辣椒螃蟹醬炒勻，即成。'),
(9030, 184725, 1, '將蝦乾浸洗備用。'),
(9031, 184725, 2, '將茄子切件，用鹽水浸30分鐘備用。'),
(9032, 184725, 3, '用中火燒熱鍋，加少許油，加入茄子炒軟。'),
(9033, 184725, 4, '加入蝦乾及DayDayCook參巴醬炒勻。'),
(9034, 184725, 5, '加入魚露及黃糖炒勻，即成。'),
(9035, 184457, 1, '將焗爐預熱至攝氏180度。'),
(9036, 184457, 2, '將牛油及砂糖拌勻，加入雞蛋、香蕉及雲呢拿香油，繼續拌勻。'),
(9037, 184457, 3, '加入低筋麵粉、泡打粉及鹽拌勻，加入核桃拌勻。'),
(9038, 184457, 4, '將速溶咖啡及咖啡力嬌酒拌勻。'),
(9039, 184457, 5, '倒入方形模具，放入焗爐焗20分鐘。'),
(9040, 184457, 6, '將鮮忌廉及細砂糖用打蛋器打發。'),
(9041, 184457, 7, '將焗好的香蕉蛋糕切成1厘米厚方片，刷上咖啡液。'),
(9042, 184457, 8, '依次鋪上以下材料：蛋糕、忌廉、香蕉、蛋糕、忌廉、香蕉及忌廉。'),
(9043, 184457, 9, '灑上一層可可粉，即成。'),
(9044, 184724, 1, '將乾蔥及蒜頭拍扁；洋蔥、杏鮑菇切件；紅尖椒及香茅切片備用。'),
(9045, 184724, 2, '雞腿切件，洗淨抹乾，用生抽及紹興酒醃30分鐘備用。'),
(9046, 184724, 3, '用中火燒熱鍋，加少許油，加入蒜頭、乾蔥及洋蔥炒香。'),
(9047, 184724, 4, '加入雞腿炒香，加入餘下的紹興酒炒香。'),
(9048, 184724, 5, '加入杏鮑菇、紅尖椒、檸檬葉、香茅、一半番茄及DayDayCook冬陰功醬炒勻，蓋上鍋蓋，轉中低火煮10分鐘。'),
(9049, 184724, 6, '打開鍋蓋，加入餘下的番茄及金不換炒勻。'),
(9050, 184724, 7, '加入魚露及黃糖調味，即成。'),
(9051, 184717, 1, '將三文魚扒切粒；用生粉及水洗蠔2-3次直至蠔不再黏糊。'),
(9052, 184717, 2, '準備一個深鍋，加入茉莉香米、藜麥及水，加入少許鹽調味。用中高火煮滾後轉為小火，蓋上鍋蓋煮15-20分鐘，直至茉莉香米及藜麥熟透。上述步驟亦可改用電飯煲完成。'),
(9053, 184717, 3, '準備湯底：準備另一個深鍋，加入鰹魚粉、水及薑片，加入鹽及胡椒粉調味，再用中高火煮滾 。'),
(9054, 184717, 4, '轉至中火，加入三文魚及珍珠蠔煮至熟透。'),
(9055, 184717, 5, '將藜麥飯放入碗中，加入湯、三文魚及珍珠蠔，放上蔥粒及紫菜碎裝飾，即成。'),
(9056, 184718, 1, '將生薑及蒜頭切成蓉；白米洗淨瀝乾，備用；將鑊加熱，倒少許食油，後加入薑蓉、蒜蓉爆香。'),
(9057, 184718, 2, '再加入薑黃粉及白米拌勻後熄火。'),
(9058, 184718, 3, '將以上材料加入電飯煲中，加水，鋪上枸杞子後，開始煮熟米飯。'),
(9059, 184718, 4, '飯熟後加入少量鹽及黑椒粉調味即可。'),
(9060, 184708, 1, '將水和黑糖用中火煮至濃稠，備用。'),
(9061, 184708, 2, '將日式年糕放入窩夫機夾3分鐘。'),
(9062, 184708, 3, '淋上黑糖蜜，即成。'),
(9063, 184692, 1, '預熱焗爐至攝氏220度，焗盤鋪上錫紙備用。'),
(9064, 184692, 2, '將蒜頭、乾蔥及洋蔥切碎；生蠔開邊，沖淨及印乾水分備用。'),
(9065, 184692, 3, '用中火燒熱鍋，加入牛油煮至溶化，加入蒜頭、乾蔥及洋蔥炒香。'),
(9066, 184692, 4, '加入白酒煮至酒精揮發，加入厚忌廉煮滾。'),
(9067, 184692, 5, '熄火，加入嫩菠菜拌勻，加入鹽及黑胡椒調味。'),
(9068, 184692, 6, '加入一半巴馬臣芝士碎拌勻，放涼備用。'),
(9069, 184692, 7, '將嫩菠菜鋪上生蠔，灑上餘下的巴馬臣芝士碎。'),
(9070, 184692, 8, '放入焗爐焗5-6分鐘或至表面金黃色，即成。'),
(9071, 184691, 1, '預熱焗爐至攝氏180度，焗盤鋪上錫紙備用。'),
(9072, 184691, 2, '將蒜頭及百里香切碎。'),
(9073, 184691, 3, '將無鹽牛油溶液、蒜蓉、海鹽及百里香拌勻。'),
(9074, 184691, 4, '將龍蝦開邊洗淨瀝乾，放上焗盤，淋上白酒及灑上少許胡椒粉。'),
(9075, 184691, 5, '鋪上蒜蓉，放入焗爐焗5分鐘。'),
(9076, 184691, 6, '取出，鋪上水牛芝士碎，再用攝氏230度約焗5-6分鐘或至表面金黃色，即成。'),
(9077, 184325, 1, '蛋黃及臘腸切粒，備用。'),
(9078, 184325, 2, '雞肉切件，加入紹興酒、生抽、蠔油、胡椒粉、老抽及鹽拌勻，醃1小時。'),
(9079, 184325, 3, '將雞肉炒5分熟，加入臘腸、蛋黃及蝦米炒香。'),
(9080, 184325, 4, '加入砂糖及熟糯米拌勻。'),
(9081, 184325, 5, '將泡好的荷葉放入籠屜中，包上炒好的糯米飯，放入蒸鍋蒸20分鐘，即成。'),
(9082, 184690, 1, '預熱焗爐至攝氏180度，焗盤鋪上牛油紙備用。'),
(9083, 184690, 2, '將中筋麵粉、無糖可可粉及海鹽過篩及拌勻備用。'),
(9084, 184690, 3, '將牛油及糖粉用電動打蛋器打發至軟滑，加入雲呢拿香油拌勻。'),
(9085, 184690, 4, '將麵粉分次加入牛油中，用低速拌勻。'),
(9086, 184690, 5, '加入黑朱古力碎拌勻，整形成圓條狀的麵團，放入雪櫃冷藏1小時或至硬身。'),
(9087, 184690, 6, '切成0.5厘米厚，放上焗盤，放入焗爐焗10-12分鐘，放涼。'),
(9088, 184690, 7, '將黑朱古力隔熱水座溶。'),
(9089, 184690, 8, '將曲奇沾上適量黑朱古力，灑上海鹽，即成。'),
(9090, 184672, 1, '將洋蔥、西班牙辣肉腸及啡蘑菇切片；印乾雞腿肉，再用鹽及黑胡椒調味。'),
(9091, 184672, 2, '用中高火燒熱鍋，加入橄欖油，放入雞腿肉，雞皮向下，兩邊分別煎5分鐘，直至變成金黃色，盛起備用。'),
(9092, 184672, 3, '用同一個鍋，加入辣肉腸及洋蔥煮3分鐘，加入蒜蓉、啡蘑菇及甜紅椒粉，再煮2分鐘。'),
(9093, 184672, 4, '倒入雞湯及攪拌，煮1分鐘，加入雞腿肉，蓋上鍋蓋煮10分鐘或直至熟透。'),
(9094, 184672, 5, '加入淡忌廉拌勻，加入鹽及黑胡椒調味。'),
(9095, 184672, 6, '上碟，灑上番茜碎，即成。'),
(9096, 184673, 1, '將花菇浸軟；雞髀件去皮；紹菜切大塊；紅棗去核備用；花膠筒及海參浸發，去除內臟後洗淨。'),
(9097, 184673, 2, '放在鍋中加入適量水、3片薑及蔥汆水5-6分鐘，切件。'),
(9098, 184673, 3, '將所有材料（除花膠及海參外）洗淨，放入電飯煲用慢煮或炆燉模式煮1小時15分鐘。'),
(9099, 184673, 4, '加入花膠及海參，再煮45分鐘，即成。'),
(9100, 184635, 1, '將瑤柱浸軟撕成絲；蝦米浸洗後切碎。'),
(9101, 184635, 2, '將雞翼去骨，加入生抽、紹興酒、麻油、鹽及胡椒粉醃10分鐘。'),
(9102, 184635, 3, '用中火燒熱鍋，加少許油，加入瑤柱絲及蝦米炒香，加入米酒炒勻，盛起放涼。'),
(9103, 184635, 4, '將蝦膠、瑤柱絲及蝦米拌勻。'),
(9104, 184635, 5, '將蝦膠釀入雞翼。'),
(9105, 184635, 6, '用中火燒熱鍋，加少許油，加入雞翼煎至兩面金黃及全熟，即成。'),
(9106, 184684, 1, '將酥皮塗上日日煮雪梨洛神花蜜茶。'),
(9107, 184684, 2, '兩邊向內摺。'),
(9108, 184684, 3, '將酥皮切成1cm寬。'),
(9109, 184684, 4, '放入焗爐以攝氏200度焗10分鐘或至金黃。'),
(9110, 184684, 5, '將蝴蝶酥的兩邊分別沾上黑朱古力或白朱古力或綠茶朱古力，即成。'),
(9111, 184634, 1, '將蓮子、百合、桂圓、洋薏米、紅棗及紅豆浸洗；雪耳浸洗後撕成塊；栗子切半。'),
(9112, 184634, 2, '準備一個鍋，加入蓮子、百合、桂圓、洋薏米、栗子、紅棗、紅豆、雪耳及適量清水用中火煮滾。'),
(9113, 184634, 3, '蓋上鍋蓋，轉中低火煮45分鐘。'),
(9114, 184634, 4, '打開鍋蓋，加入冰糖調味及煮至融化，即成。'),
(9115, 184602, 1, '雞軟骨洗乾淨瀝乾，蔥洗淨後切小段。將雞軟骨、蔥段及薑片放入容器中。'),
(9116, 184602, 2, '倒入紹興酒、生抽、蠔油、椒鹽、砂糖、辣椒粉、孜然粉、鹽及孜然粒，拌勻後放入密封容器內雪櫃醃30分鐘。'),
(9117, 184602, 3, '預熱焗爐至攝氏220度。'),
(9118, 184602, 4, '取燒烤盤，鋪上錫紙，均勻刷上一層油，將醃製好的雞軟骨平鋪在錫紙上。'),
(9119, 184602, 5, '放入烤箱中層，220度烤20分鐘左右。取出，撒上蔥粒即可。'),
(9120, 184633, 1, '將蜜瓜去籽去皮切件；乾螺頭、瑤柱、無花果、沙參及玉竹浸洗；果皮浸軟去囊備用。'),
(9121, 184633, 2, '煮滾一鍋水，加入乾螺頭、薑及米酒，將乾螺頭汆水5分鐘備用。'),
(9122, 184633, 3, '煮滾另一鍋水，加入雞腳及瘦肉汆水4分鐘，撈起瀝乾備用。'),
(9123, 184633, 4, '準備一個鍋，加入乾螺頭、雞腳、瘦肉、蜜瓜、花膠、瑤柱、無花果、玉竹、沙參、果皮及適量清水用中火煮滾。'),
(9124, 184633, 5, '蓋上鍋蓋，用中低火煮2小時。'),
(9125, 184633, 6, '打開鍋蓋，加少許鹽調味，即成。'),
(9126, 184619, 1, '將洋蔥切薄片，車厘茄切半，蜆浸在凍鹽水30分鐘吐沙及刷洗乾淨，備用。'),
(9127, 184619, 2, '用中高火燒熱鍋，加入橄欖油，加入蒜蓉及洋蔥炒2分鐘。'),
(9128, 184619, 3, '加入車厘茄及一半羅勒炒2分鐘。'),
(9129, 184619, 4, '加入番茄膏、生抽、鹽 、黑胡椒及砂糖炒勻，再加入蜆。'),
(9130, 184619, 5, '快炒1分鐘，倒入白酒，再煮3分鐘或直至蜆開口煮熟。'),
(9131, 184619, 6, '熄火，加入餘下的羅勒拌勻，即成。'),
(9132, 184623, 1, '冬菇蝦米用200毫升水浸2小時，保留浸冬菇和蝦米的水，冬菇去蒂切件備用。'),
(9133, 184623, 2, '將海參浸發，去除內臟後洗淨，放在鍋中加入適量水、3片薑及蔥汆水5-6分鐘，切件。'),
(9134, 184623, 3, '燒熱另一鍋，加少許油，加入生菜、1/2茶匙紅糖炒1分鐘，蓋上鍋蓋煮約1分鐘至軟身，上碟備用。'),
(9135, 184623, 4, '將大半浸冬菇蝦米水、蠔油、生抽、1/2茶匙紅糖拌勻。'),
(9136, 184623, 5, '燒熱鍋，加少許油，加入2片薑及蝦米爆香，加入海參及冬菇，爆炒1分鐘，加入蠔油，蓋上鍋蓋煮10-12分鐘。'),
(9137, 184623, 6, '打開鍋蓋，如果太乾可以加少許水炒勻，在碗中將餘下的浸冬菇蝦米水加生粉拌至溶化，倒進鍋中打芡，炒至收汁。'),
(9138, 184623, 7, '將海參及冬菇上碟，放在生菜上，即成。'),
(9139, 184568, 1, '將榨菜、蒜頭、乾蔥及蔥切碎。'),
(9140, 184568, 2, '煮滾一鍋水，加入關廟麵煮至軟硬適中，過冷河備用。'),
(9141, 184568, 3, '將芝麻醬、辣豆瓣醬、醬油膏、花椒油、麻油、黑米醋及砂糖拌勻備用。'),
(9142, 184568, 4, '用中火燒熱鍋，加少許油，加入蒜頭、乾蔥及薑蓉炒香。'),
(9143, 184568, 5, '加入免治豬肉、蝦皮及榨菜炒至豬肉熟透。'),
(9144, 184568, 6, '加入雞湯及清水煮滾，加入醬汁拌勻再煮滾。'),
(9145, 184568, 7, '倒上麵條，灑上花生碎及蔥粒，即成。'),
(9146, 184615, 1, '在白方包的四邊唧上沙律醬。'),
(9147, 184615, 2, '把椰菜絲放在白方包的中間。'),
(9148, 184615, 3, '在椰菜絲中間挖一個洞，把雞蛋倒入。'),
(9149, 184615, 4, '放上紅薑絲。'),
(9150, 184615, 5, '放入焗爐，以160度焗10分鐘。'),
(9151, 184615, 6, '淋上大阪燒醬和灑上木魚碎即成。'),
(9152, 184569, 1, '將蔥切段；蒜頭切成蓉；指天椒及芫茜切碎；雞翼洗淨抹乾，用鹽醃10分鐘備用。'),
(9153, 184569, 2, '煮滾一鍋水，加入薑、蔥段、花椒粒、八角及雞翼，用中火煮5分鐘，熄火焗15分鐘。'),
(9154, 184569, 3, '撈起放入冰水冷卻，瀝乾備用。'),
(9155, 184569, 4, '用中火將油加熱，淋上花椒粉及蒜蓉拌勻。'),
(9156, 184569, 5, '加入生抽、辣椒油、黑醋、砂糖、指天椒及薑蓉拌勻。'),
(9157, 184569, 6, '淋上雞翼，灑上芫茜碎，即成。'),
(9158, 184567, 1, '將蝦去腸及洗淨抹乾；蒜頭切碎；蔥及乾辣椒切粒。'),
(9159, 184567, 2, '將豉油、米醋及砂糖拌勻備用。'),
(9160, 184567, 3, '用中火燒熱鍋，加少許油，加入花椒粒及乾辣椒炒香。'),
(9161, 184567, 4, '加入蒜頭、薑蓉及蔥炒香。'),
(9162, 184567, 5, '加入蝦及米酒，將蝦炒熟。'),
(9163, 184567, 6, '加入醬汁炒勻，加少許鹽調味，即成。'),
(9164, 184572, 1, '將鮮山藥洗淨，去皮，切成如手指大小的條狀，放入清水中浸泡，水中加入幾滴白醋。'),
(9165, 184572, 2, '煮熱一鍋水，加入山藥及少許冰糖煮10分鐘後熄火，再浸入開水中冷卻。'),
(9166, 184572, 3, '冰糖加入少量水煮溶，加入桂花，加入少許生粉水打成芡，成為桂花糖漿。'),
(9167, 184572, 4, '山藥冷卻後印乾，在碟上整齊排列好，再淋上桂花糖漿即成。'),
(9168, 184573, 1, '將洋蔥切片，番茄切件，指天椒去籽切絲，奶油南瓜去皮切粒，虎蝦剝殼去腸，備用。'),
(9169, 184573, 2, '用中火燒熱鍋，加入油，加入洋蔥、蒜蓉及紅辣椒，炒3分鐘直至變軟。'),
(9170, 184573, 3, '加入咖喱粉炒香，加入番茄及南瓜，煮2分鐘。'),
(9171, 184573, 4, '加入雞湯，煮至滾起後轉小火，蓋上鍋蓋，煮15分鐘或直至南瓜變軟。'),
(9172, 184573, 5, '加入蝦肉，煮3分鐘。');
INSERT INTO steps (id, recipe_id, step_number , instruction) VALUES
(9173, 184573, 6, '加入椰奶、青檸汁及青檸皮拌勻。加入鹽、砂糖及黑胡椒調味。'),
(9174, 184573, 7, '上碟，灑上芫荽碎即成。可配白飯或法包一同享用。'),
(9175, 184565, 1, '將麵包用麵棍輾平，然後用圓形模切成圓形麵包片。'),
(9176, 184565, 2, '把麵包片放在鬆餅焗盤中。'),
(9177, 184565, 3, '雞蛋打散，加入砂糖和牛奶拌勻。'),
(9178, 184565, 4, '把焦糖牛奶糖放在麵包撻皮內。'),
(9179, 184565, 5, '將蛋液倒入麵包撻模內。'),
(9180, 184565, 6, '以攝氏180度焗10分鐘或至蛋液凝固。'),
(9181, 177900, 1, '將溫室青瓜及紫洋蔥切絲；番茄切片；羅勒葉、蒜頭及指天椒切碎。'),
(9182, 177900, 2, '煮滾一鍋水，加入麵條煮至軟硬適中，放入冰水冷卻，撈起瀝乾，備用。'),
(9183, 177900, 3, '用同一鍋水，加入蝦仁煮熟，放入冰水冷卻，撈起瀝乾備用。'),
(9184, 177900, 4, '預備醬汁：將魚露、檸檬汁、生抽、砂糖、蒜蓉、指天椒、羅勒葉及水拌勻。'),
(9185, 177900, 5, '加進麵條拌勻，上碟。'),
(9186, 177900, 6, '鋪上番茄、紫洋蔥、溫室清瓜及蝦仁。 即成。'),
(9187, 177182, 1, '將韮菜及蝦仁切碎。將韮菜、蝦仁、免治豬肉、麻油、生抽、鹽、胡椒粉、砂糖及生粉用手拌勻。'),
(9188, 177182, 2, '將4塊餃子皮排成一行，用生粉水固定重疊部份，餡料放在中間。'),
(9189, 177182, 3, '將餃子皮往上對摺，從右至左捲成玫瑰花型，用生粉水固定，將多餘的餃子皮向外翻。'),
(9190, 177182, 4, '用中火燒熱鍋，加少許油，加入餃子用中小火煎2分鐘。'),
(9191, 177182, 5, '加入少許清水煮滾，蓋上鍋蓋，用中火煮熟，即成。'),
(9192, 176901, 1, '將雞蛋打發，加入鹽及砂糖打勻。'),
(9193, 176901, 2, '用中火燒熱鍋，加少許油，加入蛋液炒成滑蛋備用。'),
(9194, 176901, 3, '將厚切麵包兩面塗上牛油。用同一個鍋，加入麵包用慢火煎至兩面金黃色，盛起備用。'),
(9195, 176901, 4, '用同一個鍋，加少許油，加入火腿及煙肉煎熟。'),
(9196, 176901, 5, '製作蟹柳芝麻醬：將蟹柳、芝麻醬及蛋黃醬拌勻。'),
(9197, 176901, 6, '製作蜜糖芥末醬：將蜜糖及法式芥末拌勻。'),
(9198, 176901, 7, '製作煙肉三文治：在麵包上依次鋪上芝士、青瓜、蟹柳芝麻醬、煙肉、炒蛋及椰菜，放上另一塊麵包，用三文治包裝紙包好，對切即成。'),
(9199, 176901, 8, '製作火腿三文治：在麵包上依次鋪上芝士、青瓜、蜜糖芥末醬、火腿、炒蛋及椰菜，放上另一塊麵包，用三文治包裝紙包好，對切即成。'),
(9200, 184509, 1, '預熱焗爐至攝氏180度，焗盤鋪上牛油紙備用。'),
(9201, 184509, 2, '用電動打蛋器將牛油、忌廉芝士及砂糖攪拌至幼滑。'),
(9202, 184509, 3, '加入雞蛋、檸檬汁及檸檬皮攪拌均勻。'),
(9203, 184509, 4, '加入麵粉及燕麥，用刮刀拌勻，放入雪櫃冷藏15-20分鐘。'),
(9204, 184509, 5, '用匙羹舀出麵糰，放上焗盤，灑上適量杏仁片。'),
(9205, 184509, 6, '放入焗爐焗10-12分鐘，取出後放上架上待涼10分鐘，即成。'),
(9206, 184510, 1, '將紅棗去核，蓮子去芯備用；將花膠筒浸發，洗淨後放在鍋中加入適量水、3片薑及蔥汆水5-6分鐘，切件。'),
(9207, 184510, 2, '將所有材料（除了花膠及冰糖）放在燉盅內。'),
(9208, 184510, 3, '隔水煮滾，轉文火燉45分鐘。'),
(9209, 184510, 4, '加入花膠及冰糖，再燉30分鐘至花膠軟身，即成。'),
(9210, 184438, 1, '預熱焗爐至攝氏180度，焗盤鋪上牛油紙備用。'),
(9211, 184438, 2, '將蘋果去皮切粒。'),
(9212, 184438, 3, '用中火燒熱鍋， 加入蘋果及黃糖拌勻，煮至蘋果軟身。'),
(9213, 184438, 4, '加入檸檬汁及肉桂粉拌勻，放涼備用。'),
(9214, 184438, 5, '將適量蘋果放上雲吞皮包好，放上焗盤，掃上橄欖油。'),
(9215, 184438, 6, '放入焗爐焗6-8分鐘或至金黃色，即成。'),
(9216, 184491, 1, '將春卷皮切開為2張長方形。'),
(9217, 184491, 2, '在春卷皮中間塗上榛子醬。'),
(9218, 184491, 3, '灑上適量椰絲，並捲起。'),
(9219, 184491, 4, '以攝氏150度焗8分鐘，待涼，即成。'),
(9220, 184436, 1, '預熱焗爐至攝氏210度，焗盤鋪上牛油紙備用。'),
(9221, 184436, 2, '將水餃皮放上焗盤，掃上橄欖油。'),
(9222, 184436, 3, '灑上巴馬臣芝士碎、紫菜粉及七味粉。'),
(9223, 184436, 4, '放入焗爐焗5分鐘或至金黃色，即成。'),
(9224, 184031, 1, '番茄用滾水汆水至褪皮，去蒂切件備用；薯仔去皮，切件備用。'),
(9225, 184031, 2, '牛腩切件，用滾水汆水，備用。'),
(9226, 184031, 3, '準備炒鍋，加入蔥、薑炒香，加入洋蔥及番茄炒勻。'),
(9227, 184031, 4, '加入牛腩、薯仔、生抽、茄膏、冰糖及鹽，加入滾水拌勻，蓋上鍋蓋燜煮1-2小時。'),
(9228, 184031, 5, '打開鍋蓋，加入米線煮3分鐘，加入胡椒粉調味，放上蔥粒及芫茜，即成。'),
(9229, 184435, 1, '將蔥切粒。'),
(9230, 184435, 2, '將蔥、麻油及鹽拌勻。'),
(9231, 184435, 3, '將適量蔥粒放上水餃皮。'),
(9232, 184435, 4, '邊緣沾上水，蓋上另一塊水餃皮粘好，用叉刺數下。'),
(9233, 184435, 5, '用中火燒熱鍋，加少許油，加入蔥油餡餅煎至兩面金黃色，即成。'),
(9234, 184433, 1, '將魚柳用鹽及黑胡椒調味，煙肉切碎，大蔥洗淨切片，備用。'),
(9235, 184433, 2, '用中火燒熱鍋，加入一半牛油，加入煙肉及大蔥炒3分鐘，直至大蔥軟身。'),
(9236, 184433, 3, '加入青豆煮1分鐘，倒入白酒煮2分鐘。'),
(9237, 184433, 4, '加入淡忌廉，加入鹽及黑胡椒調味，煮2分鐘直至忌廉變稠，令醬汁可沾上青豆，蓋上鍋蓋保溫，備用。'),
(9238, 184433, 5, '準備另一隻鍋，用中高火燒熱鍋，加入少許橄欖油，放入魚柳，魚皮向下，煎3分鐘直至魚皮變成金黃色及香脆。'),
(9239, 184433, 6, '將魚柳反轉煎2分鐘或直至剛剛熟透，加入剩餘的牛油煮溶，再將溶化的牛油重複淋上魚肉。'),
(9240, 184433, 7, '將配菜上碟，再放上魚柳，即成。'),
(9241, 184434, 1, '羊肉洗淨切件，放入一鍋滾水中汆水1分鐘，瀝乾備用。'),
(9242, 184434, 2, '京蔥斜切成小段，加入油、生薑片，在鍋中輕輕炒熱。'),
(9243, 184434, 3, '加入羊肉及2公升冷水用大火煮滾，加入已搗碎的白胡椒。'),
(9244, 184434, 4, '將滾出的泡沫舀出來，直到沸騰的湯完全變清後，轉文火煲1小時左右。'),
(9245, 184434, 5, '加入適量鹽調味即可。'),
(9246, 184404, 1, '將蘋果削皮切粒，加入檸檬汁拌勻防止氧化。'),
(9247, 184404, 2, '把蘋果粒、砂糖和牛油倒進鍋內以中火加熱。'),
(9248, 184404, 3, '煮至蘋果軟身後加入肉桂粉多煮2分鐘， 放涼備用。'),
(9249, 184404, 4, '將方包輾平，包入蘋果餡。'),
(9250, 184404, 5, '用叉子壓邊，用刀在表面切2個小開口，並塗上蛋液。'),
(9251, 184404, 6, '以攝氏180度焗10分鐘或至金黃色，即成。'),
(9252, 184333, 1, '預熱焗爐至攝氏230度，焗盤放上牛油紙備用。'),
(9253, 184333, 2, '將薯仔切成角，浸冰水30分鐘，印乾備用。'),
(9254, 184333, 3, '將意大利香草碎、蒜粉、甜椒粉、巴馬臣芝士碎及海鹽拌勻。'),
(9255, 184333, 4, '薯角加入橄欖油拌勻，加入調味料拌勻。'),
(9256, 184333, 5, '鋪上焗盤，放入焗爐焗18-25分鐘至表面金黃色即成。'),
(9257, 184332, 1, '將指天椒去籽切碎；蒜頭及香茅切碎備用。'),
(9258, 184332, 2, '將三文魚扒洗淨抹乾，用鹽及胡椒粉醃10分鐘。'),
(9259, 184332, 3, '用中火燒熱鍋，加少許油，加入三文魚扒煎至兩面金黃色，上碟。'),
(9260, 184332, 4, '用中火燒熱另一個鍋，加少許油，加入蒜頭、指天椒、香茅及薑蓉炒香。'),
(9261, 184332, 5, '加入魚露、青檸汁及黃糖煮滾，淋上三文魚扒，即成。'),
(9262, 184334, 1, '將帶子、蝦仁及菜心莖切粒；鮮冬菇去蒂切粒。'),
(9263, 184334, 2, '帶子及蝦仁用鹽、胡椒粉及麻油醃10分鐘。'),
(9264, 184334, 3, '將蛋白輕輕打發，加入150毫升雞湯拌勻，倒入蒸碟內。'),
(9265, 184334, 4, '用廚房紙吸走表面的泡沫，包上保鮮紙，用中高火蒸10分鐘。'),
(9266, 184334, 5, '用中火燒熱鍋，加少許油，加入帶子、蝦仁、鮮冬菇及菜心莖炒熟。'),
(9267, 184334, 6, '加入餘下的雞湯煮滾，加入生粉水起芡。'),
(9268, 184334, 7, '淋上蛋白，即成。'),
(9269, 184324, 1, '海帶先浸開，切碎備用。'),
(9270, 184324, 2, '三文魚略煎熟後，壓成魚鬆備用。'),
(9271, 184324, 3, '冷飯放入攪拌機中攪至米蓉，加入三文魚碎、海帶碎、芝士碎及鹽，搓成圓餅型。'),
(9272, 184324, 4, '把每一塊米餅包上一片紫菜。'),
(9273, 184324, 5, '用中火燒熱平底鍋，加少許油，米餅煎約3分鐘至金黃色，即成。'),
(9274, 184343, 1, '用中高火燒熱鍋，加入橄欖油，加入洋蔥及蒜蓉炒至軟身。'),
(9275, 184343, 2, '加入薑蓉、月桂葉及黃薑粉炒 1分鐘。'),
(9276, 184343, 3, '加入薯仔及椰菜花炒1分鐘。'),
(9277, 184343, 4, '加入雞湯煮滾後轉中小火，蓋上鍋蓋，煮20分鐘或直至蔬菜變軟。'),
(9278, 184343, 5, '熄火，取出月桂葉，用攪拌器將湯料打至幼滑。'),
(9279, 184343, 6, '加入鹽及黑胡椒調味，如果湯汁太稠身，可以加入適量雞湯。'),
(9280, 184343, 7, '上碟，灑上細香蔥，即成。'),
(9281, 184309, 1, '將蛋白輕輕打勻。'),
(9282, 184309, 2, '分兩次加入山水鮮豆漿拌勻。'),
(9283, 184309, 3, '倒入燉盅，蓋上錫紙。'),
(9284, 184309, 4, '用中火蒸10-12分鐘，熄火後靜置2分鐘，即成。'),
(9285, 184318, 1, '將砂糖及20毫升熱水拌勻至溶解。'),
(9286, 184318, 2, '將焙茶茶包放入250毫升熱水中泡5分鐘。'),
(9287, 184318, 3, '將牛奶加熱，用電動起泡機打成綿密奶泡。'),
(9288, 184318, 4, '準備一隻杯，按次序加入糖水、焙茶及奶泡，即成。'),
(9289, 184271, 1, '將茄子及杏鮑菇切件；蝦乾浸洗；蒜頭切碎備用。'),
(9290, 184271, 2, '茄子用盐水浸30分钟备用；用中火燒熱鍋，加少許油，加入茄子炒至軟身，盛起備用。'),
(9291, 184271, 3, '用中火燒熱另一個鍋，加少許油，加入蒜頭及蝦乾炒香。'),
(9292, 184271, 4, '加入杏鮑菇及適量水炒至軟身。'),
(9293, 184271, 5, '加入茄子、XO醬及砂糖炒勻，即成。'),
(9294, 184270, 1, '將乾蔥及蒜頭拍扁；洋蔥切件；乾冬菇浸軟及切半；蔥切段。'),
(9295, 184270, 2, '雞件洗淨抹乾，用生抽、老抽、砂糖、生粉及麻油醃1小時。'),
(9296, 184270, 3, '用中火燒熱鍋，加少許油，加入蒜頭、乾蔥及洋蔥炒香。'),
(9297, 184270, 4, '加入雞件炒香，加入紹興酒炒勻，蓋上鍋蓋煮5-8分鐘。'),
(9298, 184270, 5, '打開鍋蓋 ，加入冬菇炒勻，蓋上鍋蓋再煮5-8分鐘。'),
(9299, 184270, 6, '將蠔油、砂糖 、生粉及水拌勻。'),
(9300, 184270, 7, '打開鍋蓋，加入調味料炒至收汁，加入蔥段炒勻，即成。'),
(9301, 184272, 1, '將青燈籠椒及洋蔥切絲；金菇洗淨去蒂；蒜頭切成蓉；粉絲浸軟備用。'),
(9302, 184272, 2, '用中火燒熱鍋，加少許油，加入蒜頭、洋蔥及青燈籠椒炒香。'),
(9303, 184272, 3, '加入牛肉及花生沙爹醬炒至牛肉半熟。'),
(9304, 184272, 4, '加入金菇、粉絲及適量水煮滾。'),
(9305, 184272, 5, '加入老抽及麻油拌勻，即成。'),
(9306, 184283, 1, '預熱焗爐至攝氏220度。'),
(9307, 184283, 2, '將豬柳印乾，準備一個碗，將豬柳放入碗中，均勻抹上鹽、黑胡椒、孜然粉、黃糖調味。'),
(9308, 184283, 3, '用中高火燒熱鍋，加入少許橄欖油，加入豬柳，每邊煎2分鐘或直至金黃色。'),
(9309, 184283, 4, '取出豬柳，放入已鋪上錫紙的焗盤，放入焗爐焗12-15分鐘，或直至熟透。'),
(9310, 184283, 5, '準備醬汁：用同一隻煎鍋，加入乾蔥炒1分鐘，加入白酒煮至淨下一半份量，轉小火，加入牛油拌勻，加入鹽及黑胡椒調味，再灑上番茜碎。'),
(9311, 184283, 6, '取出豬柳，靜置10分鐘，將豬柳切片，淋上醬汁享用，即成。'),
(9312, 29021, 1, '冬菇及雲耳浸至軟身，冬菇去蒂切條，雲耳切細件。'),
(9313, 29021, 2, '雞扒洗淨，瀝乾，去皮及脂肪，切絲，備用。'),
(9314, 29021, 3, '辣椒洗淨，瀝乾，切粒。'),
(9315, 29021, 4, '在大碗內加入雞絲、冬菇及雲耳，加入雞肉醃料拌勻。再加薑絲醃15分鐘。'),
(9316, 29021, 5, '洗淨米，調好米水，放入電飯煲至水滾，將雞及配料及辣椒粒舖於米上，蓋上煮至熟透，灑上蔥花焗兩分鐘，即成。'),
(9317, 184135, 1, '預熱焗爐至攝氏180度；將鬆餅紙杯放入鬆餅模中，備用。'),
(9318, 184135, 2, '用打蛋器將雞蛋及幼黃糖打發3分鐘，直至變成淺啡色。'),
(9319, 184135, 3, '加入牛奶、植物油、楓糖漿及薑蓉，再用打蛋器拌勻。'),
(9320, 184135, 4, '準備另一個碗，倒入麵粉、泡打粉、鹽、薑粉及肉桂粉拌勻，再將蛋漿倒入碗中，用刮刀拌勻，毋須擔心麵糊有少許結塊。'),
(9321, 184135, 5, '將紅莓加入麵糊拌勻，倒入已放上鬆餅紙杯的鬆餅模，放入焗爐焗12-15分鐘，或直至金黃色及完全升起。'),
(9322, 184135, 6, '取出焗好的鬆餅，靜置5分鐘，脫模，待涼15分鐘，灑上糖霜，即成。'),
(9323, 184113, 1, '將螺片浸軟洗淨；無花果及紅棗浸洗備用。'),
(9324, 184113, 2, '煮滾一鍋水，加入薑片、螺片及瘦肉，將螺片及瘦肉汆水3分鐘，撈起瀝乾備用。'),
(9325, 184113, 3, '將西洋參、螺片、瘦肉、無花果、紅棗及適量水用中火煮滾。'),
(9326, 184113, 4, '蓋上鍋蓋，轉中小火煮2小時。'),
(9327, 184113, 5, '加少許鹽調味，即成。'),
(9328, 184169, 1, '將黑朱古力隔水溶化。'),
(9329, 184169, 2, '加入淡忌廉拌勻。'),
(9330, 184169, 3, '加入冧酒輕力拌勻。'),
(9331, 184169, 4, '在長方形盤上鋪上牛油紙，加入朱古力漿。'),
(9332, 184169, 5, '放入雪櫃冷藏至凝固，脫模，灑上無糖可可粉。'),
(9333, 184169, 6, '切成約2x2厘米正方形，即成。'),
(9334, 184112, 1, '將荷葉浸軟；乾冬菇浸軟去蒂切片；金華火腿切片；蔥切段備用。'),
(9335, 184112, 2, '雞件用生抽、紹興酒、砂糖、鹽、胡椒粉、生粉及麻油醃1小時。'),
(9336, 184112, 3, '將荷葉鋪上蒸籠，放入薑片、蔥段、雞件、冬菇及金華火腿，包好。'),
(9337, 184112, 4, '中高火蒸20-25分鐘，即成。'),
(9338, 184103, 1, '【白菜豬肉水餃做法】'),
(9339, 184103, 2, '白菜切碎，加入鹽出水，洗淨瀝乾水份，備用。製作餡料：將豬肉、白菜、薑蓉、麻油、生抽、紅蘿蔔、蔥粒及鹽拌勻。'),
(9340, 184103, 3, '餃子皮中心加入適量餡料包好，備用。'),
(9341, 184103, 4, '煮滾一鍋水，加入餃子，用中小火煮至餃子浮起，即成。'),
(9342, 184103, 5, '【芝麻湯圓做法】'),
(9343, 184103, 6, '將黑芝麻粉、砂糖及牛油拌勻，揉成10克大小的圓球，備用。'),
(9344, 184103, 7, '將糯米粉及暖水拌勻，分成15克大小的圓球，放入掌心，壓扁，取一個芝麻球，放入麵糰中間，捏緊收口。'),
(9345, 184103, 8, '煮滾一鍋水，加入芝麻湯圓，煮5分鐘，即成。'),
(9346, 184111, 1, '將乾冬菇浸軟去蒂，保留浸冬菇水；蒜頭拍扁；蔥切段備用。'),
(9347, 184111, 2, '煮滾一鍋水，加入3片薑、蔥段及鵝掌，將鵝掌汆水10分鐘，瀝乾備用。'),
(9348, 184111, 3, '用中火燒熱鍋，加少許油，加入餘下的薑片及蒜頭炒香，加入冬菇炒香。'),
(9349, 184111, 4, '加入紹興酒炒勻，加入鵝掌、適量浸冬菇水、蠔油、老抽及冰糖煮滾。'),
(9350, 184111, 5, '蓋上鍋蓋，轉中小火炆1.5小時。'),
(9351, 184111, 6, '加入生粉水起芡，即成。'),
(9352, 29011, 1, '番茄去蒂，洗淨，瀝乾，切件。'),
(9353, 29011, 2, '牛肉洗淨，瀝乾，切片，用牛肉醃料醃好。'),
(9354, 29011, 3, '洋蔥去衣，切件；辣椒洗淨，瀝乾，切粒。'),
(9355, 29011, 4, '燒熱易潔鑊，下油，放入番茄件、洋蔥件和鹽略炒，加入糖、辣椒粒、脫脂奶、咖喱粉和月桂葉，煮至番茄軟身。'),
(9356, 29011, 5, '再加入牛肉片，煮至牛肉片熟透，上碟，即成。'),
(9357, 184115, 1, '免治牛肉先用鹽和黑椒醃20分鐘，然後放在平底鍋中略炒。'),
(9358, 184115, 2, '加入茄膏及少許水，再加入月桂葉、少許鹽和糖，以中火煮1分鐘熄火。'),
(9359, 184115, 3, '把肉醬，和雞蛋及切片的車厘茄拌勻備用，取走月桂葉。'),
(9360, 184115, 4, '水煮滾後加少許油，餃子皮逐塊放在水中煮半分鐘後取出，放在白開水中冷卻備用。'),
(9361, 184115, 5, '焗盤放上牛油紙，先塗一層肉醬打底。'),
(9362, 184115, 6, '放一層餃子皮，再放一層肉醬，然後放一層水牛芝士；再重複放一層餃子皮，一層肉醬，然後一層水牛芝士，做四層後把巴馬臣芝士及餘下的水牛芝士放在表面。'),
(9363, 184115, 7, '以攝氏190度焗30分鐘後即可。'),
(9364, 184095, 1, '將厚切方包切條，放入焗爐用攝氏180度焗15分鐘或至金黃色。'),
(9365, 184095, 2, '將白朱古力隔熱水坐溶，篩入綠茶粉拌勻。'),
(9366, 184095, 3, '將方包條沾滿綠茶朱古力。'),
(9367, 184095, 4, '趁朱古力未完全乾透，沾上杏仁碎，即成。'),
(9368, 28061, 1, '將番茄洗淨去蒂，切4件。'),
(9369, 28061, 2, '三色椒及紅洋蔥，切絲。'),
(9370, 28061, 3, '將低脂沙律醬及辣椒拌勻。'),
(9371, 28061, 4, '燒熱鑊，用1茶匙橄欖油將番茄煮爛，拿掉番茄皮，灑上香草成番茄蓉。'),
(9372, 28061, 5, '用橄欖油將三色椒絲及紅洋蔥絲炒至半熟。'),
(9373, 28061, 6, '燒熱鑊，將墨西哥玉米餅加熱。'),
(9374, 28061, 7, '將番茄蓉及辣沙律醬塗改於墨西哥玉米餅上，放上已熟火雞肉、三色椒絲及紅洋蔥絲，捲起即成。'),
(9375, 28061, 8, '小貼士：1. 用油煮番茄可以有助吸收抗氧化物茄紅素；2. 煮熟避免染上李斯特菌影響胎兒安全。'),
(9376, 184061, 1, '預熱焗爐至攝氏200度。'),
(9377, 184061, 2, '準備白醬：用中高火燒熱鍋，加入橄欖油、洋蔥及蒜蓉炒3分鐘或直至軟身。'),
(9378, 184061, 3, '加入麵粉拌勻，確保所有麵粉與洋蔥拌勻，一邊加入雞湯，一邊保持攪拌，直至完全拌勻至幼滑。'),
(9379, 184061, 4, '轉中小火，煮2分鐘，加入牛奶攪勻，煮至微滾，加入鹽、黑胡椒、急凍雜菜及細香蔥拌勻。'),
(9380, 184061, 5, '印乾帶子及蝦，切成小塊，加入鹽及黑胡椒調味，放入碗裡，加入白醬拌勻。'),
(9381, 184061, 6, '攤開酥皮，將焗盤放上酥皮上，用刀切出合適尺寸的酥皮，再將已切好的酥皮鋪上焗盤上，沿邊緣按壓封口，用刀在表面割開十字形的開口，以便滲出蒸氣。'),
(9382, 184061, 7, '放入焗爐焗20分鐘，直至酥皮變成金黃色，即成。'),
(9383, 183954, 1, '將洋蔥切粒；大蝦洗淨去腸備用。'),
(9384, 183954, 2, '用中火燒熱鍋，加少許油，加入洋蔥炒香 。'),
(9385, 183954, 3, '加入意大利米炒2-3分鐘，加入白酒。'),
(9386, 183954, 4, '加入墨魚汁拌勻，加入魚湯蓋過米粒，用小火煮滾至米粒吸收湯汁。'),
(9387, 183954, 5, '重覆加魚湯的步驟及煮至飯熟透，加入牛油拌勻，上碟。'),
(9388, 183954, 6, '用中火燒熱另一個鍋，加少許油，加入大蝦煎熟，用鹽及黑胡椒調味。'),
(9389, 183954, 7, '放上意大利飯，即成。'),
(9390, 184021, 1, '用熱水將可可粉攪拌至溶化。'),
(9391, 184021, 2, '用小火將130毫升牛奶加熱至輕微冒煙，加入熱可可拌勻。'),
(9392, 184021, 3, '將咖啡及可可牛奶混合。'),
(9393, 184021, 4, '用小火將150毫升牛奶加熱至至輕微冒煙，熄火，用電動起泡機打成綿滑奶泡。'),
(9394, 184021, 5, '將奶泡倒入咖啡中。'),
(9395, 184021, 6, '將棉花糖放在摩卡咖啡上裝飾，即成。'),
(9396, 183955, 1, '將馬蹄粉、粘米粉及250毫升水拌勻，過篩備用。'),
(9397, 183955, 2, '準備一個鍋，加入冰糖及餘下的水煮至冰糖融化。'),
(9398, 183955, 3, '加入芝麻粉拌勻，趁熱加入馬蹄粉漿拌勻。'),
(9399, 183955, 4, '倒入已掃油的模具，用大火隔水蒸1小時或至熟透， 切件即成。'),
(9400, 183953, 1, '預熱焗爐至攝氏180度；焗盤鋪上牛油紙備用。'),
(9401, 183953, 2, '將低筋麵粉、粟粉及竹炭粉拌勻。'),
(9402, 183953, 3, '用電動打蛋器將牛油及糖霜打至發白。'),
(9403, 183953, 4, '分次加入蛋液拌勻，篩入麵粉混合物，輕輕拌勻。'),
(9404, 183953, 5, '放入唧袋，在焗盤唧上曲奇 。'),
(9405, 183953, 6, '放入焗爐焗10-12分鐘，放涼即成。'),
(9406, 183994, 1, '將羊扒印乾，切去多餘脂肪，脂肪留起備用。羊扒加入鹽及黑胡椒調味，備用。'),
(9407, 183994, 2, '保留原粒蒜頭，毋須去皮；洗淨印乾蒜頭及法國邊豆。'),
(9408, 183994, 3, '用中高火燒熱鍋，加入橄欖油，加入羊脂肪、法國邊豆、蒜頭炒3分鐘，加入鹽及黑胡椒調味 。'),
(9409, 183994, 4, '將已炒香的法國邊豆及蒜頭推到一旁，加入羊扒，每邊煎2分鐘或直至金黃色。加入檸檬皮、橙皮及百里香煮1分鐘。'),
(9410, 183994, 5, '將羊扒及青豆上碟備用；加入1/2個檸檬汁、1整個橙汁、砂糖、鹽及黑胡椒，煮2分鐘至略為收汁。'),
(9411, 183994, 6, '將醬汁及蒜頭淋上羊扒，即成。'),
(9412, 183995, 1, '菠菜洗淨先汆水半分鐘，切碎備用，蝦仁壓扁後剁成蝦蓉備用。'),
(9413, 183995, 2, '把蝦蓉、菠菜碎、燕麥、紅椒粉、鹽、胡椒粉攪拌均勻。'),
(9414, 183995, 3, '把兩種芝士碎放在混好的蝦蓉中心，把芝士碎包起然後搓成圓餅狀。'),
(9415, 183995, 4, '燒熱平底鍋，加少許油，中火把兩面煎至金黃色即成。'),
(9416, 183952, 1, '將豆腐加入糯米粉搓成粉糰。'),
(9417, 183952, 2, '將粉糰分成3等分，分別加入綠茶粉及士多啤梨粉到2個粉糰搓勻。'),
(9418, 183952, 3, '將粉糰搓成小球。'),
(9419, 183952, 4, '煲滾一鍋水，加入糰子煮至浮起。'),
(9420, 183952, 5, '撈起浸冰水，用竹籤串起，配上黃豆粉享用。'),
(9421, 177835, 1, '將雞腿肉及黃燈籠椒切件；乾蔥拍扁；豆卜切半；紅尖椒切片；蔥切段；雞腿肉用1湯匙紹興酒、生抽、老抽、1茶匙砂糖、胡椒粉、生粉及1湯匙DayDayCook蝦米豆豉醬醃20分鐘。'),
(9422, 177835, 2, '用中火燒熱鍋，加少許油，加入蒜蓉及乾蔥炒香。'),
(9423, 177835, 3, '加入雞腿肉炒至半熟。'),
(9424, 177835, 4, '加入黃燈籠椒、紅尖椒、紫洋蔥、豆卜及餘下的DayDayCook蝦米豆豉醬炒勻。'),
(9425, 177835, 5, '加入餘下的紹興酒、砂糖及蠔油煮滾。'),
(9426, 177835, 6, '蓋上鍋蓋，轉至中小火煮5分鐘或至雞肉熟透。'),
(9427, 177835, 7, '加入蔥段炒勻，即成。'),
(9428, 177837, 1, '將蔥切粒；蒜頭切成蓉；雞蛋打發。'),
(9429, 177837, 2, '蝦仁用紹興酒、鹽及胡椒粉醃10分鐘。'),
(9430, 177837, 3, '用中火燒熱鍋，加少許油，加入蒜蓉炒香，加入蝦仁炒至八成熟，盛起備用。'),
(9431, 177837, 4, '用同一個鍋，加少許油，加入隔夜飯炒至鬆散，加入蛋液炒勻，直至飯粒裹上蛋漿。'),
(9432, 177837, 5, '加入蝦仁及DayDayCook 櫻花蝦菜脯醬炒勻。'),
(9433, 177837, 6, '加入鹽及蔥粒炒勻，即成。'),
(9434, 177834, 1, '將豬肉、木耳切絲；薯仔去皮刨成絲；指天椒切碎；將薯絲放入冷水浸15分鐘，去除澱粉質；豬肉用生抽、鹽、砂糖及生粉醃15分鐘。'),
(9435, 177834, 2, '用中火燒熱鍋，加少許油，加入豬肉炒熟。'),
(9436, 177834, 3, '加入木耳、薯絲及指天椒拌炒。'),
(9437, 177834, 4, '加入DayDayCook香菇酸辣醬及鎮江醋炒勻，即成。'),
(9438, 27761, 1, '將黑胡椒粉灑於羊扒上。'),
(9439, 27761, 2, '露荀洗淨瀝乾，切段。'),
(9440, 27761, 3, '意大利青瓜洗淨瀝乾，切片。'),
(9441, 27761, 4, '紅燈龍椒洗淨瀝乾，切件。'),
(9442, 27761, 5, '放蒜片、百里香及橄欖油於易潔鑊中炒香，灑上鹽，放進羊扒煎至半熟，再灑上鹽於扒上，將扒反轉，煎至轉色。'),
(9443, 27761, 6, '放橄欖油及蒜蓉於易潔鑊中炒香，再放進露荀及意大利青瓜，灑上鹽，炒至軟身，再放入紅燈龍椒略炒, 即成。'),
(9444, 27761, 7, '小貼士：1. 紅燈籠椒含豐富維他命C，烹調時間越短越能保存；2. 若果孕婦喜歡較生既羊扒，建議去有商譽既食材店舖買，因為佢地處理食材會較衞生，盡量避免購買雪藏或經反覆解凍的羊扒，咁就食得安心。'),
(9445, 183931, 1, '將牛柳印乾切條，加入鹽及黑胡椒調味。'),
(9446, 183931, 2, '用高火將牛油及橄欖油加熱，加入牛柳炒至半熟，盛起備用。'),
(9447, 183931, 3, '用同一個鍋，加入少許油，加入洋蔥、蒜蓉及雜菌炒3分鐘至軟身。'),
(9448, 183931, 4, '加入第戎芥末及紅椒粉拌勻，加入白酒煮1分鐘。'),
(9449, 183931, 5, '加入牛肉湯，煮滾，轉小火煮5分鐘。'),
(9450, 183931, 6, '加入牛肉，用小火煮至牛肉熟透。'),
(9451, 183931, 7, '熄火，加入酸忌廉拌勻，加入鹽及黑胡椒調味。'),
(9452, 183931, 8, '將煮好的牛柳及醬汁上碟，灑上番茜碎，加上額外份量的紅椒粉，配上白飯，即成。'),
(9453, 177730, 1, '將洋蔥切成絲；雞蛋打散；蒜頭切成蓉；蔥切段備用。'),
(9454, 177730, 2, '將肉蟹洗淨，拆開蟹蓋後切成6件，蟹腳切開2段，蟹鉗用刀拍幾下。'),
(9455, 177730, 3, '用中高火燒熱鍋，加少許油，加入薑片及蒜蓉炒香，加入洋蔥炒香。'),
(9456, 177730, 4, '加入DayDayCook辣椒螃蟹醬、茄汁及砂糖炒香。'),
(9457, 177730, 5, '加入肉蟹炒勻，加入水煮滾，蓋上鍋蓋煮15-20分鐘。'),
(9458, 177730, 6, '打開鍋蓋，加入蛋液拌勻，加入蔥段炒勻，上碟。'),
(9459, 177730, 7, '即成'),
(9460, 177729, 1, '將大蝦洗淨後去頭去殼去腸；洋蔥切絲；蒜頭切成蓉。'),
(9461, 177729, 2, '用中火燒熱鍋，加少許油，加入蒜蓉及洋蔥炒香。加入DayDayCook 參巴醬炒香。'),
(9462, 177729, 3, '加入大蝦炒熟。'),
(9463, 177729, 4, '加入生粉水起芡，上碟。'),
(9464, 177729, 5, '即成'),
(9465, 177728, 1, '將草菇切半；魷魚切圈；番茄切件；香茅切段；南薑切片；蒜頭切成蓉；指天椒切碎。將大蝦去頭去殼去腸，保留蝦頭備用。'),
(9466, 177728, 2, '用中火燒熱鍋，加少許油，加入蒜蓉及蝦頭炒香。'),
(9467, 177728, 3, '取出蝦頭，加入水、香茅、南薑、檸檬葉、草菇、秀珍菇、指天椒、番茄及DayDayCook冬陰功醬煮滾，蓋上鍋蓋，轉中小火煮15分鐘。'),
(9468, 177728, 4, '打開鍋蓋，轉至中火，加入大蝦、魷魚及椰奶，煮至海鮮熟透。'),
(9469, 177728, 5, '熄火，加入青檸汁拌勻。'),
(9470, 177728, 6, '即成'),
(9471, 28071, 1, '將雞髀肉去皮去脂肪，切絲。'),
(9472, 28071, 2, '韭菜洗淨切段。'),
(9473, 28071, 3, '韓式泡菜切小塊。'),
(9474, 28071, 4, '將韓式年糕放入熱水2分鐘泡軟，用手將韓式年糕分開。'),
(9475, 28071, 5, '燒熱鑊，炒香蒜蓉，加入雞絲炒至金黃色，倒進紹興酒，再放入泡菜炒勻。'),
(9476, 28071, 6, '放入韓式年糕，加入半碗水及半碗清雞湯以小火拌炒，再加入所有調味料拌炒均勻，待湯汁收至少許，放入韭菜段，拌炒均勻即可熄火起鍋。'),
(9477, 28071, 7, '小貼士：1. 由於泡菜鹽份高，要避免積水就要減少用鹽或豉油：2. 年糕主要成份是白米，可能代替飯，大概3份之以2碗年糕相等於一碗飯的熱量。'),
(9478, 183720, 1, '紫薯切粒後隔水蒸10分鐘後，和一半脫脂奶放入攪拌機攪成紫薯蓉備用；大帶子及魷魚洗淨備用。'),
(9479, 183720, 2, '意大利大米及白酒用中大火煮3分鐘。'),
(9480, 183720, 3, '鰹魚汁加水開成500毫升高湯，先將一半加進意大利大米中，不斷炒，讓大米吸收高湯。'),
(9481, 183720, 4, '蓋上鍋蓋1-2分鐘，米飯變濃稠後再加入另一半高湯，蓋上鍋蓋煮4-5 分鐘、然後加入紫薯蓉和脫脂奶、魷魚圈，重覆炒5分鐘至濃稠。'),
(9482, 183720, 5, '米粒變半透明後，轉小火加入巴馬臣芝士碎及鹽和黑胡椒拌勻，上碟。'),
(9483, 183720, 6, '把帶子煎香後放在意大利飯上面，加些香草碎拌碟，即成。'),
(9484, 183755, 1, '將香橙番茄配菜的所有材料拌勻，備用。'),
(9485, 183755, 2, '將三文魚柳印乾，加入鹽及黑胡椒調味。'),
(9486, 183755, 3, '用中火燒熱鍋，加入橄欖油，加入三文魚柳，每邊煎2-3分鐘至半熟。'),
(9487, 183755, 4, '上碟，伴以香橙番茄配菜享用。'),
(9488, 183702, 1, '將已溶化的牛油加入餅碎拌匀，鋪在模內壓實。'),
(9489, 183702, 2, '用小火加熱淡忌廉。'),
(9490, 183702, 3, '熄火，加入朱古力拌勻。'),
(9491, 183702, 4, '倒入5吋蛋糕模內，放入雪櫃冷藏2小時至凝固。'),
(9492, 183702, 5, '灑上糖霜，即成。'),
(9493, 183654, 1, '將雞腳洗淨；瑤柱、淮山、杞子及圓肉浸洗；蔥切段備用。'),
(9494, 183654, 2, '煮滾一鍋水，加入薑片、蔥段、米酒及花膠汆水3分鐘，撈起沖洗乾淨。'),
(9495, 183654, 3, '滾另一鍋水，加入豬腱及雞腳汆水5分鐘，撈起備用。'),
(9496, 183654, 4, '將花膠、雞腳、豬腱、瑤柱、淮山、杞子、圓肉及適量水，用中火煮滾。'),
(9497, 183654, 5, '蓋上鍋蓋，轉中小火煮2小時。 加少許鹽調味，即成。'),
(9498, 183655, 1, '將瑤柱浸軟及撕成絲；乾冬菇浸軟去蒂及切絲；竹笙浸軟切絲；金華火腿切碎；韭黃切段。'),
(9499, 183655, 2, '將雞湯及水煮滾。'),
(9500, 183655, 3, '加入瑤柱、冬菇、竹笙及金華火腿煮滾，轉中小火煮15-20分鐘。'),
(9501, 183655, 4, '加入馬蹄粉水拌勻，煮至濃稠。 加入韭黃煮1分鐘，即成。'),
(9502, 183656, 1, '將瑤柱浸軟及撕成絲，預留浸瑤柱水備用；乾冬菇浸軟去蒂及切粒；蝦米浸洗；魷魚乾浸洗及切粒； 蒜頭切成蓉。'),
(9503, 183656, 2, '荷葉浸水至軟身備用。'),
(9504, 183656, 3, '用中火燒熱鍋，加少許油，加入蒜頭及薑米炒香。'),
(9505, 183656, 4, '加入瑤柱、乾冬菇 、蝦米及魷魚乾炒香。'),
(9506, 183656, 5, '加入隔夜飯炒勻，加入適量浸瑤柱水炒至飯粒吸收水分。'),
(9507, 183656, 6, '加入老抽及鹽炒勻，將飯放上荷葉包好用中高火蒸30分鐘，即成。'),
(9508, 28051, 1, '下油炒香蒜蓉，將煙火腿炒至乾身, 少許金黃色拿起備用。'),
(9509, 28051, 2, '將薯仔, 去皮切片, 蒸15分鐘至叉可輕易插入。'),
(9510, 28051, 3, '用叉壓爛薯仔，趁熱放已炒香煙火腿、牛油、鹽、黑椒及低脂忌廉混合, 直至薯蓉滑身。'),
(9511, 28051, 4, '壓平於焗盤，用叉在平滑的面上輕力劃下直線, 灑上巴馬臣芝士碎, 放入焗爐200度15分鐘 至表面少許金黃即可。'),
(9512, 28051, 5, '小貼士：1. 煙火腿脂肪極低，但又帶有香的煙燻味，是代替煙肉的最佳選擇；2. 巴馬臣芝士相比車打芝士熱量較低，只要不要落太多，又可以好味，有不會太肥。'),
(9513, 183682, 1, '預熱焗爐至攝氏200度；準備一個焗盤，鋪上錫紙備用。'),
(9514, 183682, 2, '將牛扒印乾，加入鹽及黑胡椒調味，備用。'),
(9515, 183682, 3, '用刨將甘筍刨成長薄片，加入五香粉、鹽、黑胡椒及橄欖油拌勻，在焗盤排成一層，焗15分鐘或直至金黃色及軟身。'),
(9516, 183682, 4, '用中高火燒熱鍋，加入橄欖油，加入牛扒煎至喜愛的生熟程度，五成熟大約需要每邊煎4-6分鐘，上碟。'),
(9517, 183682, 5, '從焗爐取出甘筍，淋上楓糖漿，備用。'),
(9518, 183682, 6, '將牛油、蒜蓉及芫茜碎拌勻，放在牛扒上，伴以楓糖漿烤甘筍享用。'),
(9519, 183682, 7, '小貼士：1. 煎牛扒之前要預先將牛扒解凍，可以在前一晚放入雪櫃冷藏室解凍，解凍時間不多於4小時，否則容易滋生細菌；2. 要避免煎牛扒時滲出大量血水，可以在煎之前用廚房紙抹乾塊牛扒，還可以令調味料均勻抹在牛扒上。'),
(9520, 183661, 1, '牛奶用小火加熱，加入砂糖及篩入抹茶粉，煮至溶解，小心不要煮滾牛奶。'),
(9521, 183661, 2, '將雞蛋打發，分2次加入抹茶牛奶拌勻。'),
(9522, 183661, 3, '將蛋漿過篩，隔走雜質。'),
(9523, 183661, 4, '倒入容器至8分滿。'),
(9524, 183661, 5, '蓋上錫紙，用大火蒸2分鐘，熄火焗15分鐘即成。'),
(9525, 183606, 1, '紅蔥頭拍扁；蔥切段 。'),
(9526, 183606, 2, '將雞髀洗淨抹乾，沙薑粉及鹽拌勻，塗勻雞髀，醃30分鐘 。'),
(9527, 183606, 3, '將蔥段、紅蔥頭及薑片放入電飯煲，放入雞髀。'),
(9528, 183606, 4, '淋上紹興酒，按掣煮40分鐘，即成。'),
(9529, 183607, 1, '將蒜頭及乾蔥拍扁；排骨洗淨抹乾。'),
(9530, 183607, 2, '排骨用生抽及1/2湯匙紹興酒醃15分鐘。'),
(9531, 183607, 3, '用中火燒熱鍋，加少許油，加入薑片、蒜頭及乾蔥炒香。'),
(9532, 183607, 4, '加入排骨煎至兩面金黃色，加入餘下的紹興酒炒勻。'),
(9533, 183607, 5, '準備電飯煲，加入排骨、鎮江醋、冰糖、老抽及水，按掣煮45-60分鐘，即成。'),
(9534, 183608, 1, '將白蘿蔔去皮切件；蒜頭拍扁；蔥切段。'),
(9535, 183608, 2, '煮滾一鍋水，加入豬軟骨及蔥段汆水3分鐘，撈起瀝乾備用。'),
(9536, 183608, 3, '將可樂、生抽、老抽及紹興酒拌勻。'),
(9537, 183608, 4, '準備電飯煲，加入豬軟骨、白蘿蔔、蒜頭、薑、八角、桂皮及可樂，按掣煮45-60分鐘，即成。'),
(9538, 28041, 1, '燒滾一大鍋水，下1湯匙鹽，把意粉烚煮7分鐘，瀝乾水份待用。'),
(9539, 28041, 2, '煙三文魚切細塊。'),
(9540, 28041, 3, '蘑菇切片備用。'),
(9541, 28041, 4, '先燒熱油鑊，炒香蒜片，下蘑菇片快炒。'),
(9542, 28041, 5, '隨後下意粉、香草及清雞湯炒勻。'),
(9543, 28041, 6, '加入低脂忌廉、餐白酒及三文魚，煮勻。'),
(9544, 28041, 7, '最後熄火，加入一片低脂芝士粉拌勻即可上碟並灑上香草。'),
(9545, 183618, 1, '預熱焗爐至攝氏180度；準備一個焗盤，抹上牛油及均勻灑上額外份量的砂糖，備用。'),
(9546, 183618, 2, '將布冧去核切片，均勻沾上額外份量的砂糖，備用。'),
(9547, 183618, 3, '將麵粉、砂糖、鹽、雞蛋及雲呢拿香油拌勻，加入牛奶及忌廉拌勻成蛋漿。'),
(9548, 183618, 4, '將布冧在焗盤上排好，加入蛋漿，完全覆蓋布冧。'),
(9549, 183618, 5, '焗30-35分鐘或至金黃色。'),
(9550, 183618, 6, '靜置15分鐘，灑上糖粉，趁熱享用。'),
(9551, 183619, 1, '將士多啤梨及紅桑子切粒。'),
(9552, 183619, 2, '用攪拌機將三分之一果粒及黑糖粉打成蓉。'),
(9553, 183619, 3, '加入餘下的果粒拌勻，備用。'),
(9554, 183619, 4, '將燕麥片、牛奶及蜜糖拌勻，用攪拌機將燕麥片混合物及4湯匙果蓉徜微拌勻成燕麥糊。'),
(9555, 183619, 5, '準備一個玻璃杯，加入燕麥糊及果蓉，再加入燕麥糊。'),
(9556, 183619, 6, '放入雪櫃冷藏4小時。'),
(9557, 183619, 7, '加上士多啤梨及薄荷葉裝飾，即成。'),
(9558, 183598, 1, '將雞蛋及砂糖打發均勻。'),
(9559, 183598, 2, '加入牛奶拌勻。'),
(9560, 183598, 3, '篩入麵粉及泡打粉，拌勻。'),
(9561, 183598, 4, '入油輕力拌勻。'),
(9562, 183598, 5, '用小火燒熱平底鍋，掃上少許油。'),
(9563, 183598, 6, '加入1湯匙麵糊，煎至表面有氣泡。'),
(9564, 183598, 7, '反轉另一面煎20秒，上碟。'),
(9565, 183598, 8, '旁邊唧上忌廉，淋上桃膠龍眼黑糖蜜茶，即成。'),
(9566, 183555, 1, '將雞翼洗淨抹乾；蒜頭切成蓉；蔥切粒。'),
(9567, 183555, 2, '雞翼用生抽、米酒、黑胡椒、砂糖同蒜蓉醃1小時。'),
(9568, 183555, 3, '用中火燒熱鍋，加少許油，加入雞翼，用中小火煎至兩面金黃色及熟透。'),
(9569, 183555, 4, '灑上椒鹽及蔥花炒香，即成。'),
(9570, 183556, 1, '將白蘿蔔去皮磨成蓉；水菜及娃娃菜洗淨；洋蔥切件；豆腐切粒；本菇洗淨去蒂。'),
(9571, 183556, 2, '煮滾一鍋水，加入鰹魚昆布粉、味醂、日本料理酒及鹽煮滾。'),
(9572, 183556, 3, '加入白蘿蔔蓉煮2分鐘。'),
(9573, 183556, 4, '加入洋蔥、娃娃菜、豆腐、本菇及豬腩片煮5分鐘。'),
(9574, 183556, 5, '加入水菜煮1分鐘，即成。'),
(9575, 183557, 1, '將中筋麵粉過篩，加入細砂糖、無糖可可粉、泡打粉及鹽拌勻。'),
(9576, 183557, 2, '加入牛油及蘭姆酒拌勻，慢慢加入牛奶拌勻。'),
(9577, 183557, 3, '放入微波爐用中高火加熱2分鐘 。'),
(9578, 183557, 4, '灑上糖霜，即成。'),
(9579, 27771, 1, '蒜頭及磨菇切片，辣椒、芫茜及羅勒切碎，備用。'),
(9580, 27771, 2, '煲滾水，將意粉灼熱，盛起，過冷河，瀝乾，備用。'),
(9581, 27771, 3, '用鹽開水浸大蜆約30分鐘至大蜆吐沙，洗淨，瀝乾，備用。'),
(9582, 27771, 4, '燒熱易潔鑊，下油及牛油炒香蒜片，炒熟磨菇粒，放入大蜆，加入白酒及辣椒碎，待大蜆煮熟至開口，放入意粉，讓意粉吸收調味汁後，上碟，再於意粉上灑上碎辣椒乾，即成。'),
(9583, 183553, 1, '將意大利黑醋、第戎芥末、1/2湯匙橄欖油、蜜糖、鼠尾草及蒜蓉拌勻備用。'),
(9584, 183553, 2, '用廚房紙將雞腿肉印乾，於雞皮上灑上鹽及黑胡椒調味。'),
(9585, 183553, 3, '用中高火燒熱鍋，加入餘下的橄欖油，加入雞腿肉，雞皮向下，煮至雞皮脆身及金黃色，約6-8分鐘。'),
(9586, 183553, 4, '將雞腿反轉，無花果放在雞腿旁邊，加入意大利黑醋，煮滾，轉小火，蓋上鍋蓋，再煮8分鐘或直至雞肉熟透。'),
(9587, 183553, 5, '加入鹽及黑胡椒調味。'),
(9588, 183553, 6, '上碟，即成。'),
(9589, 183531, 1, '芝士火腿飯糰：將火腿粒煎香，加入白飯及鹽拌勻。'),
(9590, 183531, 2, '用保鮮紙包成飯糰。'),
(9591, 183531, 3, '將已切半的芝士鋪在飯糰上。'),
(9592, 183531, 4, '放入焗爐用攝氏200度焗5分鐘，即成。'),
(9593, 183531, 5, '泡菜煙肉飯糰：用保鮮紙將泡菜炒飯包成橢圓形。'),
(9594, 183531, 6, '用煙肉捲起飯糰。'),
(9595, 183531, 7, '加適量油在平底鍋，將飯糰煎香，即成。'),
(9596, 183531, 8, '三文魚鬆紫菜飯糰：將罐頭三文魚、飯素及白飯拌勻 。'),
(9597, 183531, 9, '用保鮮紙包成飯糰。'),
(9598, 183531, 10, '包上紫菜，即成。'),
(9599, 183085, 1, '將幼砂糖加入熱水拌勻至完全溶化，放涼。'),
(9600, 183085, 2, '將雞蛋及鮮奶拌勻，再加入糖水拌勻。'),
(9601, 183085, 3, '蛋液過篩，去除蛋液泡沫和雜質。'),
(9602, 183085, 4, '將撻皮鋪在 Bruno八爪魚丸盤上，撻皮內塗上蘋果山楂蜜茶，然後倒入蛋液，加蓋煮15-20分鐘即成。'),
(9603, 183236, 1, '將蒜頭切片；番茜切碎；蝦仁洗淨印乾。'),
(9604, 183236, 2, '煮滾一鍋水，加入鹽，加入意粉煮至軟硬適中，撈起瀝乾備用。'),
(9605, 183236, 3, '用中火燒熱鍋，加少許油，加入蝦仁炒熟，加少許鹽調味，盛起備用。'),
(9606, 183236, 4, '用同一個鍋，加入橄欖油及蒜片，不斷攪拌直至蒜片變成金黃色。'),
(9607, 183236, 5, '加入紅椒片及松子炒香。'),
(9608, 183236, 6, '加入意粉、蝦仁及番茜炒勻，加鹽及黑胡椒調味，即成。'),
(9609, 183237, 1, '將蘆筍削皮切段；蒜頭切碎；雞柳切絲備用。'),
(9610, 183237, 2, '雞柳用生抽、砂糖、胡椒粉、生粉及麻油醃10分鐘。'),
(9611, 183237, 3, '煮滾一鍋水，加入蘆筍汆水1分鐘，撈起瀝乾。'),
(9612, 183237, 4, '用中火燒熱鍋，加少許油，加入雞柳炒熟，盛起備用。'),
(9613, 183237, 5, '用同一個鍋，加少許油，加入薑片及蒜蓉炒香，加入蘆筍炒2分鐘。'),
(9614, 183237, 6, '加入紹興酒炒勻，加入雞柳及腰果炒勻，加少許鹽調味，即成。'),
(9615, 183238, 1, '預熱焗爐至攝氏150度，焗盤鋪上牛油紙備用。'),
(9616, 183238, 2, '將夏威夷果仁及杏仁切碎。'),
(9617, 183238, 3, '將牛油及糖粉拌勻至淡黃色。'),
(9618, 183238, 4, '加入雞蛋及雲呢拿香油，拌勻至漿狀。'),
(9619, 183238, 5, '分次篩入中筋麵粉及拌勻。'),
(9620, 183238, 6, '加入夏威夷果仁及杏仁拌勻。'),
(9621, 183238, 7, '整形成長條狀的麵團，放入雪櫃冷藏3-4小時或至硬身。'),
(9622, 183238, 8, '切成0.5厘米厚，放上焗盤，放入焗爐焗15-20分鐘或至金黃色，放涼即成。'),
(9623, 27281, 1, '糖加入蝦醬拌勻，備用。'),
(9624, 27281, 2, '露筍洗淨，瀝乾，切段，備用。'),
(9625, 27281, 3, '香茜洗淨，瀝乾，切碎，備用。'),
(9626, 27281, 4, '牛肉洗淨，瀝乾，切片，用醃料醃好，備用。'),
(9627, 27281, 5, '燒滾水，下露筍灼約半分鐘，盛起，備用。'),
(9628, 27281, 6, '燒熱鑊，炒香蒜片，炒牛肉片數下，再放蝦醬， 放進露筍炒至牛肉片熟透，加入黑椒碎，灑上香茜碎，上碟，即成。'),
(9629, 27281, 7, '小貼士：1. 蝦醬含高鹽份，所以不宜再額外加鹽，以防水腫；2. 有人喜歡挑牛頸脊來炒，貪其腍身，但其實脂肪含量非常高。'),
(9630, 183245, 1, '薑刮去皮，切成小塊，用刀拍鬆。'),
(9631, 183245, 2, '用小火燒熱鍋，把薑煎乾。然後，下少許油，把薑煎香，加少許鹽，帶出薑味又減少辣味。'),
(9632, 183245, 3, '把薑放入瓦鍋中，加入甜醋蓋過薑面，用中火煮滾後轉小火煮30分鐘，然後放在陰涼地方約一星期，讓薑醋入味。（最好浸3星期，每隔1星期煲滾一次，以防變壞）'),
(9633, 183245, 4, '（食豬腳前1天才放煮豬腳）豬腳放在水中，水滾後煮20分鐘，把水倒掉，豬腳瀝乾，出水後去毛較易，然後備用。'),
(9634, 183245, 5, '把浸了數天的薑醋大火煮滾，放入豬腳及黑糯米醋（讓豬腳更易稔），再滾後轉小火炆煮約1.5小時至軟稔。'),
(9635, 183245, 6, '煮豬腳時，把鵪鶉蛋放在一鍋冷水中，用中火煮至水滾後，轉小火續煮5分鐘，焗5分鐘，撈起放入冷水中冷卻，然後剝殼。'),
(9636, 183245, 7, '最後把鵪鶉蛋加入薑醋中，再中大火煮滾後熄火，約浸3小時後即成。食用前再稍稍加熱。'),
(9637, 183255, 1, '燒熱鍋，加入橄欖油、牛油、奶油南瓜、甘筍及洋蔥炒香，約炒5分鐘。'),
(9638, 183255, 2, '用刀背將香茅拍一拍，可以更出味。將香茅、薑、薑汁及月桂葉放入鍋中。'),
(9639, 183255, 3, '拌勻，煮1 分鐘，加入雞湯，蓋上鍋蓋，轉小火煮20分鐘。'),
(9640, 183255, 4, '取出香茅及月桂葉，用攪拌機將湯料攪拌至幼滑。'),
(9641, 183255, 5, '倒入鍋中，開小火，加入椰奶，加入鹽及胡椒粉調味。'),
(9642, 183255, 6, '上碟，灑上切碎的細香蔥及青檸皮，即成。'),
(9643, 183218, 1, '焗爐預熱至攝氏200度 。'),
(9644, 183218, 2, '將薯仔烚熟，放涼後在中間挖出一個洞，備用。'),
(9645, 183218, 3, '將火腿、香腸及蔥切粒，加入粟米粒及芝士碎拌勻。'),
(9646, 183218, 4, '將配料倒入薯仔，用錫紙包好焗20分鐘。'),
(9647, 183218, 5, '取走錫紙，灑上一層芝士碎，再焗至金黃色，即成。'),
(9648, 183084, 1, '準備一個玻璃杯，加入雪梨洛神花蜜茶及梳打水，有需要可加入適量冰塊。'),
(9649, 183084, 2, '加入雪糕，即成。'),
(9650, 183121, 1, '將乾蔥切碎；青瓜及泰國臘腸切片；雞蛋打發。'),
(9651, 183121, 2, '蝦仁用鹽、胡椒粉及砂糖醃10分鐘。'),
(9652, 183121, 3, '用中火燒熱鍋，加少許油，加入乾蔥炒香，加入泰國臘腸炒香，加入蝦仁炒至半熟。'),
(9653, 183121, 4, '加入隔夜飯炒至鬆散，加入蛋液炒勻，直至飯粒裹上蛋漿。'),
(9654, 183121, 5, '將蝦膏及少許水拌勻，加入飯中炒勻，加入魚露及砂糖炒勻。'),
(9655, 183121, 6, '上碟，鋪上肉鬆及青瓜片，即成。'),
(9656, 183122, 1, '將大蝦洗淨去腸； 粉絲浸軟；乾蔥、指天椒、蒜頭及芫茜莖切碎備用。'),
(9657, 183122, 2, '將白胡椒粒搗碎，加入蒜頭及芫茜莖搗碎。'),
(9658, 183122, 3, '將蠔油、老抽、魚露、水、麻油及砂糖拌勻備用。'),
(9659, 183122, 4, '用中火燒熱鍋，加少許油，加入薑片炒香，加入大蝦煎至半熟。'),
(9660, 183122, 5, '加入白胡椒粒、蒜頭、芫茜莖、乾蔥及指天椒炒香。'),
(9661, 183122, 6, '加入粉絲及醬汁炒勻，將大蝦鋪面。轉中高火煮至收汁。'),
(9662, 183122, 7, '熄火，蓋上鍋蓋焗2分鐘，即成。'),
(9663, 183123, 1, '雞翼洗淨抹乾。'),
(9664, 183123, 2, '加入青咖喱醬、椰奶、黃糖、魚露及青檸汁醃1小時。'),
(9665, 183123, 3, '用中火燒熱鍋，加少許油，加入雞翼，轉中小火煎至兩面金黃色，即成。'),
(9666, 26791, 1, '雞上髀肉去脂肪，洗淨，瀝乾，切件，用雞上脾肉醃料醃好。'),
(9667, 26791, 2, '菠蘿用水略沖，瀝乾，切小件。青椒去籽，洗淨，瀝乾，切件。洋蔥去衣，切件。蒜頭去衣，切片。將調味醬料拌勻。'),
(9668, 26791, 3, '燒熱易潔鑊，下半茶匙油，用中火炒香蒜片，放入雞上髀肉煎至半熟，放入黃酒、青椒件及洋蔥件，略炒至雞上髀肉全熟，盛起，洗淨鑊。'),
(9669, 26791, 4, '燒熱易潔鑊，下調味醬料，用細火煮滾，再放入雞件及洋蔥件等，炒勻至收汁，即成。'),
(9670, 183131, 1, '將雞湯及罐裝番茄煮滾，轉小火保温。'),
(9671, 183131, 2, '燒熱鍋，加入橄欖油、乾蔥、蒜蓉及西班牙辣肉腸炒香，炒約3分鐘。'),
(9672, 183131, 3, '加入意大利米炒勻，用中高火煮1分鐘。'),
(9673, 183131, 4, '加入紅酒拌勻，煮至紅酒幾乎收乾。'),
(9674, 183131, 5, '加入適量的番茄湯直至蓋過米粒，煮至米粒吸收湯汁，再加入下一勺番茄湯，直至番茄湯全部加入，整個過程約煮15分鐘。'),
(9675, 183131, 6, '煮至意大利飯熟透及煙韌，加入砂糖、鹽及黑胡椒調味。'),
(9676, 183131, 7, '上碟，灑上巴馬臣芝士碎及番茜碎，即成。'),
(9677, 183106, 1, '焗爐預熱至攝氏200度。'),
(9678, 183106, 2, '將忌廉芝士塗在白方包上。'),
(9679, 183106, 3, '將藍莓及藍莓果醬平均地鋪在其中一塊白方包上。'),
(9680, 183106, 4, '蓋上另一塊白方包，用刀背壓至四邊封好。'),
(9681, 183106, 5, '放上焗盤，塗上蛋液，放入焗爐焗10分鐘，即成。'),
(9682, 181996, 1, '將蔥切段；乾蔥拍扁備用。'),
(9683, 181996, 2, '用生粉及鹽將廣島蠔沖洗乾淨，印乾備用。'),
(9684, 181996, 3, '煮滾一鍋水，加入廣島蠔汆水1分鐘，撈起後完全印乾，沾上生粉。'),
(9685, 181996, 4, '用中火燒熱鍋，加少許油，加入廣島蠔煎至兩面金黃色，盛起。'),
(9686, 181996, 5, '用同一個鍋，加少許油，加入薑片、1/2蔥段及乾蔥炒香。 加入紹興酒炒勻，加入蠔油、生抽、砂糖、胡椒粉及適量水煮滾。'),
(9687, 181996, 6, '加入廣島蠔及餘下的蔥段炒勻，煮至收汁，即成。'),
(9688, 181997, 1, '將秋刀魚洗淨抹乾切段，沾上生粉。'),
(9689, 181997, 2, '將日本豉油、日本料理酒、味醂及黃糖拌勻。'),
(9690, 181997, 3, '用中火燒熱鍋，加少許油，加入秋刀魚煎至兩面金黃。'),
(9691, 181997, 4, '加入調味料，用中高火煮至收汁，即成。'),
(9692, 183075, 1, '將方包切成六角形，塗上牛油，兩片方包牛油向內夾起。'),
(9693, 183075, 2, '打發雞蛋，將方包浸入蛋液中。'),
(9694, 183075, 3, '用大火燒熱鍋，加入油，燒滾後轉小火，加入方包，一邊炸一邊翻轉。'),
(9695, 183075, 4, '待方包兩面微微上色，轉中火炸至兩面金黃色，上碟。'),
(9696, 183075, 5, '放上少許牛油，淋上桃膠龍眼黑糖蜜茶調味，即成。'),
(9697, 183075, 6, '小貼士：一定要夾起後才熄火，因為如果先熄火，油份會留在方包上，變得油淋淋。'),
(9698, 181995, 1, '將蒜頭切碎；乾蔥切片；洋蔥切絲；蔥切段。'),
(9699, 181995, 2, '肉蟹洗淨切件。'),
(9700, 181995, 3, '用中火燒熱鍋，加少許油，加入蒜蓉、乾蔥、薑片及洋蔥炒香。'),
(9701, 181995, 4, '轉中高火，加入黑胡椒炒香，加入蟹炒2分鐘。'),
(9702, 181995, 5, '沿鍋邊加入紹興酒，加入生抽、老抽、砂糖及水，用中火煮滾。'),
(9703, 181995, 6, '轉中小火，蓋上鍋蓋煮8-10分鐘或至蟹熟透。'),
(9704, 181995, 7, '加入蔥段及麻油炒勻，加入生粉水拌勻，起芡即成。'),
(9705, 181198, 1, '將雪梨去芯切件。'),
(9706, 181198, 2, '煮滾清水，加入冰糖煮至溶化，熄火後加入桂花焗20分鐘。'),
(9707, 181198, 3, '將糖水過篩，去掉桂花。'),
(9708, 181198, 4, '將雪梨及糖水加入燉盅，蓋好，燉30分鐘，即成。'),
(9709, 183063, 1, '蝦皮先在熱鍋中炒乾淨，約炒5-10分鐘。'),
(9710, 183063, 2, '把雞蛋打勻，然後用粉篩隔去蛋渣數次，令蛋汁更幼滑，打蛋時盡量筷子不要離蛋。'),
(9711, 183063, 3, '將鰹魚汁開成300毫升鰹魚高湯，加進蛋液．然後放進燉碗中。'),
(9712, 183063, 4, '把蝦皮放進蛋液中，然後蓋上燉碗蓋或封上保鮮紙。'),
(9713, 183063, 5, '水滾後用中火蒸10分鐘，關火後再焗5分鐘。'),
(9714, 183064, 1, '燒熱鍋，加入牛油、消化餅碎及杏仁片拌勻，烘2-3分鐘，熄火，灑上海鹽再拌勻，上碟備用。'),
(9715, 183064, 2, '用小火燒熱同一個鍋，加入蜜糖和水，不停攪拌以阻止燒焦。'),
(9716, 183064, 3, '當蜜糖開始煮滾，加入牛油拌勻。'),
(9717, 183064, 4, '加入啤梨排成一層，轉小火，煮3分鐘，將啤梨反轉煮至上色。'),
(9718, 183064, 5, '當啤梨幾乎熟透，加入黑莓，熄火上碟。'),
(9719, 183064, 6, '將雪糕上碟，淋上啤梨黑莓蜜糖醬，灑上海鹽杏仁消化餅，即成。'),
(9720, 181197, 1, '將蓮藕去皮切件；麥冬、沙參、玉竹及蜜棗浸洗。'),
(9721, 181197, 2, '將蓮藕、麥冬、沙參、玉竹、蜜棗及適量水用中火煮滾。'),
(9722, 181197, 3, '轉中小火，蓋上鍋蓋煮2個小時。'),
(9723, 181197, 4, '打開鍋蓋，加少許鹽調味，即成。'),
(9724, 183061, 1, '雞蛋用打蛋器打發5分鐘至企身。'),
(9725, 183061, 2, '用小火燒熱平底鍋，加入牛油煮溶，輕輕倒入蛋泡。'),
(9726, 183061, 3, '不要接觸蛋泡，煎至輕微冒煙，熄火，等1分鐘。'),
(9727, 183061, 4, '上碟，對摺，灑上味椒鹽，即成。'),
(9728, 181196, 1, '將無花果、百合及腰果浸洗；蘋果去芯切件；陳皮浸軟刮囊；雪耳浸洗去蒂備用。'),
(9729, 181196, 2, '將蘋果、無花果、百合、腰果、陳皮、雪耳及適量水用中火煮滾。'),
(9730, 181196, 3, '蓋上鍋蓋，轉中小火，煮1.5小時。'),
(9731, 181196, 4, '打開鍋蓋，加少許鹽調味，即成。'),
(9732, 181195, 1, '將菜乾浸洗乾淨瀝乾；紅蘿蔔去皮切件；瑤柱、陳腎及南北杏浸洗；陳皮浸軟刮囊備用。'),
(9733, 181195, 2, '煮滾一鍋水，加入瘦肉汆水5分鐘，撈起瀝乾。'),
(9734, 181195, 3, '將菜乾 、紅蘿蔔、瑤柱、陳腎、陳皮、南北杏、瘦肉及適量水用中火煮滾。'),
(9735, 181195, 4, '轉中小火，蓋上鍋蓋煮1.5小時。'),
(9736, 181195, 5, '打開鍋蓋，加少許鹽調味，即成。'),
(9737, 181194, 1, '將川貝、南北杏、蜜棗及無花果浸洗；雪耳浸洗及去蒂備用。'),
(9738, 181194, 2, '將生魚洗淨抹乾。用中火燒熱鍋，加少許油，加入薑片炒香，加入生魚煎至兩面金黃色。'),
(9739, 181194, 3, '加入適量熱水，用中高火煮30分鐘。'),
(9740, 181194, 4, '加入川貝、南北杏、蜜棗、無花果及雪耳煮滾。'),
(9741, 181194, 5, '蓋上鍋蓋，轉中小火煮2小時。'),
(9742, 181194, 6, '打開鍋蓋，加少許鹽調味，即成。'),
(9743, 181193, 1, '將木瓜去皮去籽切件；雪耳浸軟去蒂；羅漢果洗淨切半；無花果浸洗。'),
(9744, 181193, 2, '煮滾一鍋水，加入豬腱汆水5分鐘，撈起瀝乾。'),
(9745, 181193, 3, '將木瓜、雪耳、羅漢果、豬腱、無花果及適量水用中火煮滾。'),
(9746, 181193, 4, '轉中小火，蓋上鍋蓋煮1.5小時。'),
(9747, 181193, 5, '打開鍋蓋，加少許鹽調味，即成。'),
(9748, 181080, 1, '西蘭花切件；蒜頭切成蓉備用。'),
(9749, 181080, 2, '將帶子完全印乾，用紹興酒、鹽、胡椒粉醃10分鐘。'),
(9750, 181080, 3, '煮滾一鍋水，加入帶子汆水30秒，撈起瀝乾備用。'),
(9751, 181080, 4, '煮滾另一鍋水，加入西蘭花及鹽烚5分鐘，撈起瀝乾備用。'),
(9752, 181080, 5, '用中火燒熱鍋，加少許油，加入蒜頭炒香。'),
(9753, 181080, 6, '加入帶子快炒，加入西蘭花及XO醬炒勻，上碟即成。'),
(9754, 181079, 1, '青瓜切絲備用。'),
(9755, 181079, 2, '雞腿肉用薑汁及紹興酒醃至少2小時。'),
(9756, 181079, 3, '雞腿肉蒸15-20分鐘或至熟透，放涼後撕成絲。'),
(9757, 181079, 4, '將芝麻沙律醬、日本豉油、水及麻油拌勻。'),
(9758, 181079, 5, '將雞腿肉、青瓜、海蜇及醬汁拌勻。'),
(9759, 181079, 6, '上碟，灑上白芝麻，即成。'),
(9760, 181173, 1, '用中火將水煮滾，加入砂糖煮溶，加入大菜絲煮溶，加入檸檬汁拌勻，熄火，放涼備用。'),
(9761, 181173, 2, '準備自己喜歡的水果，切成1厘米正方體，'),
(9762, 181173, 3, '將水果放入球型模具，再倒入大菜糖水。'),
(9763, 181173, 4, '放入雪櫃冷藏1小時至凝固，脫模，即成。'),
(9764, 181078, 1, '將南瓜去皮去籽切粒。'),
(9765, 181078, 2, '煮滾一鍋水，加入西米煮5分鐘，期間不停攪拌。熄火，蓋上鍋蓋焗5分鐘至熟透，過冷水備用。'),
(9766, 181078, 3, '煮滾另一鍋水，加入小丸子煮至浮起，撈起放入冷水備用。'),
(9767, 181078, 4, '煮滾600毫升水，加入南瓜及冰糖煮20分鐘或至軟身，用手提攪拌器打至幼滑。'),
(9768, 181078, 5, '加入椰漿、西米及小丸子拌勻，煮1-2分鐘，即成。'),
(9769, 181077, 1, '蜆浸鹽水30分鐘吐沙備用。'),
(9770, 181077, 2, '將蝦洗淨去腸；花蟹洗淨切件；番茄及洋蔥切件；翠玉瓜切片；粉絲浸軟；娃娃菜撕開洗淨；蒜頭切碎。'),
(9771, 181077, 3, '將材料依次排入大同複合料理無水鍋中：娃娃菜、洋蔥、番茄、翠玉瓜、蒜蓉、粉絲、薑片、蝦、花蟹及蜆。'),
(9772, 181077, 4, '選擇加熱模式第5段火力，並蓋上金屬鍋蓋，時間設定10分鐘，即成。'),
(9773, 181076, 1, '將急凍響螺頭洗淨；百合、桂圓、杞子及淮山浸洗；陳皮浸洗刮囊備用。 煮滾一鍋水，加入響螺頭及瘦肉汆水5分鐘，撈起瀝乾備用。'),
(9774, 181076, 2, '準備陶瓷好易煲，加入響螺頭、瘦肉、百合、桂圓、杞子、淮山、陳皮及適量水。'),
(9775, 181076, 3, '觸摸「湯功能」紅色圖標燈，停止閃動後顯示 「-2：30」，表示煲湯程序開始。'),
(9776, 181076, 4, '待蜂鳴器響起，打開鍋蓋，加少許鹽調味，即成。'),
(9777, 181075, 1, '將陳皮浸軟刮囊，切絲；蒜頭切成蓉；蔥切粒備用。'),
(9778, 181075, 2, '將龍躉件洗淨抹乾，加入胡椒粉、鹽、生粉及油醃10分鐘。'),
(9779, 181075, 3, '放上蒸碟，鋪上蒜蓉及陳皮。用中高火隔水蒸6分鐘。'),
(9780, 181075, 4, '灑上蔥粒，將熱油及蒸魚豉油淋在蒸好的魚上， 即成。'),
(9781, 181003, 1, '將麥冬、無花果及南北杏浸洗瀝乾備用。 將雪梨去芯切件。'),
(9782, 181003, 2, '將雪梨、麥冬、無花果、南北杏及適量水用中火煮滾。'),
(9783, 181003, 3, '轉至中小火，蓋上鍋蓋，煮1小時，即成。'),
(9784, 181085, 1, '將藍青口洗淨備用。'),
(9785, 181085, 2, '用中火燒熱鍋，加入橄欖油，加入西班牙辣肉腸、洋蔥、蒜蓉、乾蔥、大蔥及甘筍炒香，煮5-8分鐘或至蔬菜變軟。'),
(9786, 181085, 3, '加入番茄、月桂葉及百里香，煮2分鐘，加入白酒及雞湯，煮滾，轉小火，蓋上鍋蓋，煮20分鐘至微滾。'),
(9787, 181085, 4, '加入青口，蓋上鍋蓋，再煮3分鐘。'),
(9788, 181085, 5, '加入厚忌廉拌勻，煮2-3分鐘，加入鹽、黑胡椒及砂糖調味，取走百里香及月桂葉，上碟，加上番茜碎裝飾。'),
(9789, 181087, 1, '紫米和水（1：2）在飯煲內煮熟；熟紫米 （有需要可加1-2湯匙水）在攪拌機內打勻成米漿。'),
(9790, 181087, 2, '米漿加入紅糖及1/2糯米粉先搓混，再加入另一半搓成不黏手的粉團。'),
(9791, 181087, 3, '（過程可以在工作枱上灑上糯米粉），分成小份， 搓成圓形壓扁成餅形。'),
(9792, 181087, 4, '加少許油，用中慢火在易潔鍋內煎至金黃色，可試一小塊沒有生粉味則為熟透。'),
(9793, 181002, 1, '將蓮藕及紅蘿蔔去皮切件；洋蔥切件；蒜頭拍扁；大蔥切片。'),
(9794, 181002, 2, '將梅頭肉洗淨切件，用1湯匙日本豉油、1湯匙清酒、1湯匙味醂、1/2湯匙砂糖及麻油醃15分鐘。'),
(9795, 181002, 3, '用中火燒熱鍋，加少許油，加入蒜頭及洋蔥炒香，加入梅頭肉炒香。'),
(9796, 181002, 4, '加入蓮藕及紅蘿蔔略炒。'),
(9797, 181002, 5, '加入水、餘下的日本豉油、清酒、砂糖及餘下的味醂煮滾。'),
(9798, 181002, 6, '轉中小火，蓋上鍋蓋，煮30分鐘。'),
(9799, 181002, 7, '打開鍋蓋，加入大蔥拌勻，即成。'),
(9800, 181070, 1, '以小火熱鍋，加入忌廉、牛奶、細砂糖煮至微溫。'),
(9801, 181070, 2, '將魚膠粉溶於50毫升熱水，加進鍋裡，不斷攪拌煮至融化。'),
(9802, 181070, 3, '布丁溶液倒入容器中，冷藏2小時至凝固。'),
(9803, 181070, 4, '芒果肉切成薄片，捲出花朵形狀，抹上檸檬汁防止氧化。'),
(9804, 181070, 5, '芒果花放上布丁，即成。'),
(9805, 180979, 1, '將燈籠椒及大蔥切粒，備用。'),
(9806, 180979, 2, '將排骨切件，放入碗中。'),
(9807, 180979, 3, '加入生抽、2湯匙蒜蓉、胡椒粉及紹興酒拌勻，醃2小時備用（若時間允許，醃製一晚更佳）。'),
(9808, 180979, 4, '沾上生粉，放入油鍋炸至金黃熟透。'),
(9809, 180979, 5, '用同一個鍋子，加入餘下的蒜蓉、大蔥及燈籠椒炒香。'),
(9810, 180979, 6, '加入排骨，翻炒2分鐘至均勻，上碟即成。'),
(9811, 181001, 1, '將馬蹄去皮切碎；木耳浸軟切碎。'),
(9812, 181001, 2, '將免治梅頭肉、蠔油、細砂糖、胡椒粉及紹興酒拌勻。'),
(9813, 181001, 3, '加入生粉水及麻油攪拌至起膠，用手撻打至有黏性。'),
(9814, 181001, 4, '加入馬蹄、木耳及即食麥片拌勻，放入雪櫃冷藏1-2小時。'),
(9815, 181001, 5, '放上蒸碟壓平，用中高火蒸15分鐘，即成。'),
(9816, 181000, 1, '將沙參、玉竹及無花果浸洗備用。'),
(9817, 181000, 2, '煮滾一鍋水，加入豬腱汆水5分鐘，撈起瀝乾備用。'),
(9818, 181000, 3, '將豬腱、沙參、玉竹、海底椰、無花果及適量水用中高火煮滾。'),
(9819, 181000, 4, '轉中小火，蓋上鍋蓋煮1小時。'),
(9820, 181000, 5, '打開鍋蓋，加少許鹽調味，即成。'),
(9821, 180999, 1, '芋頭去皮切件；乾蔥拍扁；蔥切段。'),
(9822, 180999, 2, '鴨件用紹興酒及生抽醃20分鐘。'),
(9823, 180999, 3, '芋頭沾上生粉。用中火燒熱鍋，加少許油，加入芋頭煎至兩面金黃色，盛起備用。'),
(9824, 180999, 4, '用中火燒熱另一個鍋，加少許油，加入鴨件煎香，盛起備用。'),
(9825, 180999, 5, '用同一個鍋，加少許油，加入薑片、乾蔥、蔥段及柱候醬炒香。'),
(9826, 180999, 6, '加入鴨件、適量水及冰糖拌勻，用中火煮滾。'),
(9827, 180999, 7, '轉中小火，蓋上鍋蓋煮30分鐘。'),
(9828, 180999, 8, '打開鍋蓋，加入芋頭煮10分鐘，即成。'),
(9829, 180998, 1, '用中火煮滾清水，加入黑芝麻粉煮5分鐘。加入冰糖煮溶。'),
(9830, 180998, 2, '將粘米粉及240毫升水拌勻。'),
(9831, 180998, 3, '轉中小火，慢慢加入鍋中拌勻，煮至濃稠，即成。'),
(9832, 26451, 1, '將牛肉切條，用生抽、生粉及糖醃好。'),
(9833, 26451, 2, '青瓜切絲。'),
(9834, 26451, 3, '滾水，放一茶匙雞粉，將素麵煮至軟身，過冷河。'),
(9835, 26451, 4, '易潔鑊用油爆香蒜蓉，放入牛肉條炒至熟透，盛起。'),
(9836, 26451, 5, '放入韓式辣醬及糖炒勻，再放入素麵煮勻，盛起。'),
(9837, 26451, 6, '加入青瓜絲及牛肉條，上碟，即成。'),
(9838, 26451, 7, '小貼士：青瓜最好買溫室小青瓜，仲要用食水沖洗，用切生果專用既刀同枮板處理，就會食得安心；瘦牛肉質地較韌，可以揀牛冧肉，就會比較軟林。'),
(9839, 180844, 1, '將洋蔥、啡蘑菇及白蘑菇粒；牛肝菌浸軟切粒。'),
(9840, 180844, 2, '用中火燒熱鍋，加入牛油煮至溶化，加入洋蔥炒香。'),
(9841, 180844, 3, '加入啡蘑菇、白蘑菇及牛肝菌炒香，加入中筋麵粉炒勻。'),
(9842, 180844, 4, '加入雞湯用中火煮滾，轉中小火煮30分鐘。'),
(9843, 180844, 5, '用攪拌機打成蓉，倒入鍋中，加入淡忌廉用中火煮至微滾。'),
(9844, 180844, 6, '加少許鹽及黑胡椒調味，即成。'),
(9845, 180997, 1, '預熱焗爐至攝氏180度；在模具噴上食油，並在底部鋪上牛油紙備用。'),
(9846, 180997, 2, '將砂糖及雞蛋打發至奶黃色及厚身 。'),
(9847, 180997, 3, '加入牛奶、橄欖油、檸檬汁及檸檬皮拌勻。'),
(9848, 180997, 4, '將麵粉及發粉過篩，加入雞蛋混合物拌勻。'),
(9849, 180997, 5, '將麵糊倒入模具，焗50分鐘或至金黃色，脫模及放涼，灑上糖霜，即成。'),
(9850, 180843, 1, '杏鮑菇切件；紅尖椒切片；蒜頭拍扁。'),
(9851, 180843, 2, '準備一個鍋，加入麻油，用中火加熱，加入薑片及蒜頭炒香。'),
(9852, 180843, 3, '加入杏鮑菇炒香。'),
(9853, 180843, 4, '加入豉油、米酒及冰糖拌勻煮至收汁。'),
(9854, 180843, 5, '加入紅尖椒及九層塔炒勻，上碟即成。'),
(9855, 180996, 1, '檸檬片切成8個小三角形，備用'),
(9856, 180996, 2, '平鋪煙三文魚，塗上芝士抹醬，放上沙律菜，捲成花狀。'),
(9857, 180996, 3, '在米餅放上三文魚卷，以檸檬片點綴。'),
(9858, 180996, 4, '灑上芝士碎，即成。'),
(9859, 180842, 1, '將乾冬菇浸軟去蒂；甘筍去皮切片；枝竹浸軟切段。'),
(9860, 180842, 2, '排骨洗淨後用生抽、1/2湯匙紹興酒、 胡椒粉、砂糖、生粉及麻油醃30分鐘。'),
(9861, 180842, 3, '用中火燒熱鍋，加少許油，加入薑片及南乳炒香。'),
(9862, 180842, 4, '加入排骨炒香，加入甘筍及冬菇炒香，加入紹興酒炒勻。'),
(9863, 180842, 5, '加入適量水及冰糖煮滾，轉中小火，蓋上鍋蓋煮20-25分鐘。'),
(9864, 180842, 6, '打開鍋蓋，加入枝竹再煮10分鐘。'),
(9865, 180842, 7, '加入蠔油拌勻，即成。'),
(9866, 180841, 1, '將蟲草花及腰果浸洗；紅蘿蔔去皮切件；粟米切件；舞茸浸洗去蒂備用。'),
(9867, 180841, 2, '準備一個鍋，加入紅蘿蔔、粟米、蟲草花、舞茸、腰果及適量水，用中火煮滾。'),
(9868, 180841, 3, '轉中小火，蓋上鍋蓋煮1小時。'),
(9869, 180841, 4, '加少許鹽調味，即成。'),
(9870, 180840, 1, '預熱焗爐至攝氏200度，焗盤鋪上牛油紙備用。'),
(9871, 180840, 2, '將蘑菇、蒜頭及洋蔥切碎。'),
(9872, 180840, 3, '用中火燒熱鍋，加少許油，加入蒜頭及洋蔥炒香。'),
(9873, 180840, 4, '加入蘑菇及百里香葉碎炒熟，加入巴馬臣芝士碎拌勻。'),
(9874, 180840, 5, '將雞蛋打發；酥皮掃上蛋液。'),
(9875, 180840, 6, '平均鋪上一層蘑菇及水牛芝士碎，緊緊捲起。'),
(9876, 180840, 7, '掃上蛋液，平均切成1吋厚，放上焗盤。'),
(9877, 180840, 8, '放入焗爐焗12-15分鐘或至金黃色，即成。'),
(9878, 180839, 1, '預熱焗爐至攝氏190度，焗盤放上鍚紙備用。'),
(9879, 180839, 2, '用廚房紙抹淨大啡菇後去蒂，放上焗盤。大啡菇加入黑胡椒調味，淋上少許橄欖油。'),
(9880, 180839, 3, '放上巴馬火腿，加入雞蛋。'),
(9881, 180839, 4, '放入焗爐焗15-20分鐘至雞蛋凝固。'),
(9882, 180839, 5, '取出，灑上番茜，即成。'),
(9883, 179195, 1, '將芥菜切段，將莖和葉分開；豆腐切粒。'),
(9884, 179195, 2, '豬肉用生抽、砂糖、麻油及生粉醃15分鐘。'),
(9885, 179195, 3, '煮滾一鍋水，加入薑片及芥菜莖，用中火煮滾。'),
(9886, 179195, 4, '加入豬肉片及芥菜葉煮15分鐘。'),
(9887, 179195, 5, '加入豆腐再煮5分鐘，加少許鹽調味，即成。'),
(9888, 180833, 1, '保留迷迭香頂部約1寸半的葉，摘走其餘葉片，留起1/3備用。'),
(9889, 180833, 2, '將迷迭香的莖末切尖，備用。'),
(9890, 180833, 3, '將迷迭香葉切碎，加入橙皮、橙汁、紅椒片、鹽、黑胡椒及橄欖油拌勻。'),
(9891, 180833, 4, '將豬頸肉及一半的迷迭香醬料拌勻，醃10分鐘。'),
(9892, 180833, 5, '將豬頸肉粒用迷迭香莖串起；用中火預熱平底鍋，放上豬頸肉串每邊烤12分鐘或至熟透。'),
(9893, 180833, 6, '上碟，配以餘下的迷迭香醬料享用。'),
(9894, 180834, 1, '把三文魚用平㡳鍋輕輕煎熟後壓碎成魚鬆。'),
(9895, 180834, 2, '把煮好的白飯、三文魚、紫菜碎、檸檬汁及鹽拌勻。'),
(9896, 180834, 3, '然後用濕手把飯搓成小球，放在焗盤上，掃上少許蛋液，灑上黑白芝麻。'),
(9897, 180834, 4, '以200度焗20-25分鐘即成。'),
(9898, 179194, 1, '將番茄、薯仔及洋蔥切粒。'),
(9899, 179194, 2, '牛肉用生抽、砂糖、胡椒粉、生粉及油醃10分鐘。'),
(9900, 179194, 3, '煮滾一鍋水，加入番茄、薯仔及洋蔥用中火煮滾，用中小火煮20分鐘。'),
(9901, 179194, 4, '加入牛肉片煮滾。'),
(9902, 179194, 5, '加少許鹽調味，即成。'),
(9903, 180828, 1, '煮滾一鍋水，加入金菇煮至軟化熟透，撈起瀝乾備用。'),
(9904, 180828, 2, '混合所有調味料，可依喜好加減份量。'),
(9905, 180828, 3, '將醬汁淋在金針菇上拌勻，即成。'),
(9906, 179193, 1, '將木瓜去皮切件；蔥切段。'),
(9907, 179193, 2, '準備一鍋水，加入排骨汆水5分鐘，撈起瀝乾備用。'),
(9908, 179193, 3, '魚尾洗淨抹乾後，用鹽、胡椒粉及紹興酒醃15分鐘。'),
(9909, 179193, 4, '用中高火燒熱鍋，加少許油，加入薑片、蔥段及魚尾煎至兩面金黃色。'),
(9910, 179193, 5, '將1500毫升水煮滾，加入排骨用中火煮15分鐘。'),
(9911, 179193, 6, '加入魚尾及木瓜煮20分鐘 。'),
(9912, 179193, 7, '加少許鹽調味，即成。'),
(9913, 179192, 1, '絲瓜去皮切件；草菇切粒；雞柳切絲備用。'),
(9914, 179192, 2, '雞柳用鹽、砂糖、胡椒粉及麻油醃10分鐘備用。'),
(9915, 179192, 3, '煮滾一鍋水，加入薑片、草菇及雞絲用中火煮滾。'),
(9916, 179192, 4, '加入絲瓜煮5分鐘。'),
(9917, 179192, 5, '加少許鹽調味，即成。'),
(9918, 179191, 1, '將鮮冬菇及金菇去蒂，鮮冬菇切片； 嫩豆腐切粒；蔥切幼粒備用。'),
(9919, 179191, 2, '味噌加入適量水拌勻備用。'),
(9920, 179191, 3, '將700毫升水及鰹魚汁用中火煮滾。'),
(9921, 179191, 4, '在高湯中加入鮮冬菇、金菇及嫩豆腐煮5分鐘。'),
(9922, 179191, 5, '加入味噌煮2分鐘，熄火，加入蔥粒，即成。'),
(9923, 179190, 1, '菠菜切段；豬膶洗淨切片；杞子浸洗備用。'),
(9924, 179190, 2, '豬膶用1茶匙生抽、1/2茶匙砂糖、胡椒粉、1茶匙紹興酒、薑蓉及1/4茶匙麻油醃10分鐘。'),
(9925, 179190, 3, '肉片用餘下的生抽、砂糖、紹興酒、生粉及麻油醃10分鐘。'),
(9926, 179190, 4, '煮滾一鍋水，加入薑片、肉片及杞子煮滾，轉中小火煮15分鐘。'),
(9927, 179190, 5, '轉中火，加入豬膶及菠菜煮滾，再煮2分鐘。'),
(9928, 179190, 6, '加少許鹽調味，即成。'),
(9929, 179127, 1, '將南棗、杞子及桂圓浸洗備用。'),
(9930, 179127, 2, '將南棗、桂圓、杞子及1000毫升水用中火煮滾。'),
(9931, 179127, 3, '蓋上鍋蓋，轉中小火煮15分鐘。'),
(9932, 179127, 4, '熄火，即成。'),
(9933, 180262, 1, '煮滾一鍋水，加少許鹽，加入意粉按包裝指示煮至軟硬適中(約10分鐘)，保留意粉水備用。'),
(9934, 180262, 2, '將蘆筍洗淨刨成長薄片，備用。'),
(9935, 180262, 3, '用中火燒熱鍋，加入牛油及橄欖油，加入蒜蓉炒香，加入紅椒片及蟹肉炒勻，煮2分鐘。'),
(9936, 180262, 4, '加入白酒，再煮2分鐘。'),
(9937, 180262, 5, '加入意粉炒勻。'),
(9938, 180262, 6, '加入蘆筍及適量意粉水拌勻，加入鹽及黑胡椒調味。'),
(9939, 180262, 7, '上碟，擠出檸檬汁，灑上檸檬皮及意大利番茜，即成。'),
(9940, 179126, 1, '將紫菜浸洗乾淨，瀝乾備用；豆腐切粒。'),
(9941, 179126, 2, '免治瘦肉用生抽、紹興酒、砂糖、胡椒粉、麻油及生粉醃15分鐘。'),
(9942, 179126, 3, '將雞湯、水及薑片用中火煮滾，用匙羹加入免治瘦肉煮3分鐘。'),
(9943, 179126, 4, '加入豆腐煮5分鐘，加入紫菜再次煮滾。'),
(9944, 179126, 5, '加少許鹽調味，即成。'),
(9945, 179206, 1, '用叉將鹹蛋黃壓碎。'),
(9946, 179206, 2, '將無鹽牛油及鹹蛋黃用小火煮5分鐘。'),
(9947, 179206, 3, '加入鮮忌廉、黃糖、鹽及辣椒粉，煮滾。'),
(9948, 179206, 4, '倒入玻璃容器，即成。'),
(9949, 179125, 1, '黑豆洗淨，用500毫升水浸過夜備用。'),
(9950, 179125, 2, '將黑豆連浸黑豆水加入鍋中，加入日本豉油、黑糖及味醂用中火煮滾。'),
(9951, 179125, 3, '蓋上鍋蓋，用中小火煮45分鐘。'),
(9952, 179125, 4, '打開鍋蓋，加入麥芽糖，煮至濃稠，上碟即成。'),
(9953, 179124, 1, '將核桃、芡實、淮山、杞子及蜜棗浸洗備用。'),
(9954, 179124, 2, '煮滾一鍋水，加入豬腱汆水5分鐘，撈起瀝乾備用。'),
(9955, 179124, 3, '將核桃、芡實、淮山、杞子、蜜棗、豬腱及適量水用中火煮滾。'),
(9956, 179124, 4, '蓋上鍋蓋，轉中小火煮1小時。'),
(9957, 179124, 5, '加少許鹽調味，即成。'),
(9958, 179123, 1, '刁草切碎備用。'),
(9959, 179123, 2, '三文魚洗淨抹乾，用鹽、黑胡椒及意大利香草調味。'),
(9960, 179123, 3, '用中火燒熱鍋，加少許油，加入三文魚煎至金黃色，上碟。'),
(9961, 179123, 4, '準備刁草乳酪醬。將希臘乳酪、刁草、檸檬皮、檸檬汁、橄欖油、鹽及黑胡椒伴勻。'),
(9962, 179123, 5, '即成。'),
(9963, 179122, 1, '南瓜去皮切粒；小米及杞子浸洗瀝乾備用。'),
(9964, 179122, 2, '煮滾一鍋水，加入小米用中火煮滾。'),
(9965, 179122, 3, '加入南瓜煮30分鐘。'),
(9966, 179122, 4, '加入杞子煮10分鐘。'),
(9967, 179122, 5, '加少許鹽調味，即成。'),
(9968, 178903, 1, '預熱焗爐至攝氏180度。'),
(9969, 178903, 2, '將洋蔥及蒜頭切碎。'),
(9970, 178903, 3, '魚柳用鹽及黑胡椒調味。'),
(9971, 178903, 4, '用中火燒熱鍋，加少許油，加入蒜頭及洋蔥炒軟，盛起放涼備用。'),
(9972, 178903, 5, '將蟹肉、蒜頭、洋蔥、麵包糠、蛋黃醬及甜椒粉拌勻。'),
(9973, 178903, 6, '將蟹肉平均鋪上魚柳，捲起放上焗盤，淋上少許橄欖油。'),
(9974, 178903, 7, '放入焗爐焗20-25分鐘或至熟透，即成。'),
(9975, 178902, 1, '魚柳抹乾切件；豆腐瀝水水分切件；豆豉及蒜頭切碎備用。'),
(9976, 178902, 2, '魚柳用鹽及胡椒粉醃10分鐘備用。'),
(9977, 178902, 3, '豆豉、蒜頭、蒸魚豉油及砂糖拌勻。'),
(9978, 178902, 4, '將豆腐鋪上碟，放上魚柳及豆豉。'),
(9979, 178902, 5, '用中高火蒸8-10分鐘，即成。'),
(9980, 179094, 1, '燒熱鍋，加少許油，加入洋蔥、蒜蓉及紅燈籠椒炒3分鐘至軟身，加入鹽及黑胡椒調味，盛起備用。'),
(9981, 179094, 2, '將蟹肉、洋蔥混合物、雞蛋、蛋黃醬、第戎芥末、喼汁、檸檬汁及紅辣椒粉拌勻。'),
(9982, 179094, 3, '加入鹽、黑胡椒及砂糖調味。'),
(9983, 179094, 4, '慢慢加入麵包糠，輕力拌勻。'),
(9984, 179094, 5, '將蟹肉混合物分成9份，放上鋪上牛油紙的碟上。'),
(9985, 179094, 6, '用中火燒熱鍋，加少許油，加入蟹肉餅，每邊煎3-5分鐘至兩面金黃色。'),
(9986, 179094, 7, '將他他醬材料拌勻。'),
(9987, 179094, 8, '蟹肉餅配以他他醬及檸檬角享用。'),
(9988, 179098, 1, '榴蓮起肉後在碎來壓成蓉。'),
(9989, 179098, 2, '把水牛芝士碎混合均勻。'),
(9990, 179098, 3, '用春卷皮把材料包好。'),
(9991, 179098, 4, '以蛋汁把封口封好。'),
(9992, 179098, 5, '放上焗盤，掃上蛋液，用叉刺上小孔。'),
(9993, 179098, 6, '預熱焗爐後，以180度焗15分鐘， 變成金黃色，即成。'),
(9994, 179098, 7, '高芷欣的營養小貼士：榴槤經過焗熟後，更能帶出香甜風味，味道更濃郁。'),
(9995, 179001, 1, '香蕉去皮切件，插入雪條棍，冷藏30分鐘以上。'),
(9996, 179001, 2, '準備兩個碗，分開倒入牛奶朱古力及白朱古力，將兩款朱古力座熱水至溶化。'),
(9997, 179001, 3, '將香蕉浸入朱古力醬中，灑上朱古力彩針，即成。'),
(9998, 178901, 1, '預熱焗爐至攝氏220度，焗盤鋪上牛油紙備用。'),
(9999, 178901, 2, '鱈魚柳用鹽及黑胡椒調味。'),
(10000, 178901, 3, '將麵包糠、巴馬臣芝士碎及意大利香草拌勻。雞蛋打發。鱈魚柳順序沾上中筋麵粉、蛋液及麵包糠混合物，輕輕壓緊。'),
(10001, 178901, 4, '放上焗盤，放入焗爐焗15-18分鐘或至表面金黃色，即成。'),
(10002, 178900, 1, '將豆角切幼粒；檸檬葉及芫茜切碎。'),
(10003, 178900, 2, '將鯪魚肉、檸檬葉、芫茜、紅咖哩醬、黃糖、胡椒粉及魚露拌勻。'),
(10004, 178900, 3, '將雞蛋打發。鯪魚肉加入豆角及蛋液拌勻至起膠，放入雪櫃冷藏1小時。'),
(10005, 178900, 4, '搓成餅狀。'),
(10006, 178900, 5, '用中火燒熱鍋，加少許油，加入魚餅煎至兩面金黃色，即成。'),
(10007, 178899, 1, '將石斑柳切件；紅燈籠椒及青燈籠椒去籽切件；洋蔥切件；蒜頭切成蓉備用。'),
(10008, 178899, 2, '石斑柳用鹽、1/2茶匙砂糖、胡椒粉、紹興酒、生粉、蛋白及油醃10分鐘。'),
(10009, 178899, 3, '用中火燒熱鍋，加少許油，加入石斑柳炒熟備用。'),
(10010, 178899, 4, '用同一個鍋，加少許油，加入薑片及蒜蓉炒香，加入豆豉及洋蔥炒香。'),
(10011, 178899, 5, '加入紅燈籠椒、青燈籠椒及石斑柳炒勻，即成。'),
(10012, 178898, 1, '將鯇魚腩洗淨抹乾切件；蔥切段；蒜頭及乾蔥切片備用。'),
(10013, 178898, 2, '鯇魚腩用薑蓉、紹興酒、生抽、砂糖及胡椒粉醃1小時。'),
(10014, 178898, 3, '將調味用的蠔油、老抽、砂糖及水拌勻備用。'),
(10015, 178898, 4, '鯇魚腩加入生粉拌勻。'),
(10016, 178898, 5, '用中火燒熱鍋，加入適量油，加入鯇魚腩半煎炸至熟透備用。'),
(10017, 178898, 6, '用中火燒熱另一個鍋，加少許油，加入薑片、蒜片、乾蔥及蔥段炒香。'),
(10018, 178898, 7, '加入鯇魚腩，沿鍋邊加入紹興酒，用中小火煮3分鐘。'),
(10019, 178898, 8, '加入調味醬汁炒勻，即成。'),
(10020, 178832, 1, '將醃蘿蔔、青瓜及甘筍切絲。將甘筍炒熟備用。將雞蛋打發。用中火燒熱鍋，加少許油，用中低火煎成蛋皮，放涼切條。'),
(10021, 178832, 2, '白飯加入鹽及麻油調味備用。'),
(10022, 178832, 3, '免治牛肉用砂糖、生抽、日本料理酒及韓國芝麻油醃 30 分鐘。'),
(10023, 178832, 4, '用中火燒熱鍋，加少許油，加入牛肉炒熟，盛起備用。'),
(10024, 178832, 5, '準備壽司蓆，放上一片壽司紫菜(光面向下)，平均鋪上2/3白飯，頂部1/2留空。'),
(10025, 178832, 6, '放上免治牛肉、甘筍、醃蘿蔔、青瓜、醃牛蒡及蛋絲。'),
(10026, 178832, 7, '由低捲起壽司蓆，捲成飯卷。重複以上步驟4次。'),
(10027, 178832, 8, '壽司卷面掃上額外一層芝麻油，切件即成。'),
(10028, 178831, 1, '將雞腿肉洗淨印乾，切粒；日本大蔥切段；蒜頭切成蓉備用。'),
(10029, 178831, 2, '雞腿肉用鹽及蒜蓉醃15分鐘。'),
(10030, 178831, 3, '用竹籤串起雞腿肉及大蔥。'),
(10031, 178831, 4, '將日本豉油、味醂、黃糖、日本料理酒及水拌勻。'),
(10032, 178831, 5, '用中火燒熱鍋，加少許油，加入雞串煎至兩面金黃色。'),
(10033, 178831, 6, '加入已拌勻的醬汁，令兩面均沾上醬汁，煮至收汁即成。'),
(10034, 178920, 1, '蜆浸鹽水30分鐘吐沙，瀝乾備用。'),
(10035, 178920, 2, '用中火將蜆、白酒及月桂葉煮2-3分鐘至至蜆打開，撈起所有蜆，保留蜆汁；將一半蜆去殻，另一半連殼，備用。'),
(10036, 178920, 3, '用同一個鍋，加入牛油煮溶，加入乾蔥及蒜蓉用中小火炒至軟身，加入番紅花及蜆汁，煮滾及稍微收汁。'),
(10037, 178920, 4, '放入蜆肉，加入鹽及黑胡椒調味，最後加入忌廉、番茜及細香蔥。熄火， 蓋上鍋蓋保温，備用。'),
(10038, 178920, 5, '銀鱈魚柳用鹽及黑胡椒調味，表面塗上橄欖油，用大火燒熱鍋，於鍋中放上牛油紙，兩面煎分別煎3-4分鐘或至金黃色熟透。'),
(10039, 178920, 6, '準備一個碗，加入蜆，放上魚柳，淋上番紅花蜆肉汁，灑上番茜及細香蔥，即成。'),
(10040, 178892, 1, '將蘋果切成1厘米厚片，去芯備用。'),
(10041, 178892, 2, '將消化餅打碎。'),
(10042, 178892, 3, '用中火燒熱平底鍋，加入一半牛油煮溶。加入餅碎及砂糖，炒至乾身，放涼備用。'),
(10043, 178892, 4, '用中火燒熱另一個平底鍋，加入餘下的牛油煮溶，加入蘋果片煎至兩面金黃色。'),
(10044, 178892, 5, '轉小火煮5分鐘，煮至稍微軟身。'),
(10045, 178892, 6, '將蘋果片及餅碎依次重複放在碟上，放上百力滋及薄荷葉，即成。'),
(10046, 178830, 1, '將三文魚肉弄碎；蘑菇切片；露筍切段；洋蔥切粒。'),
(10047, 178830, 2, '準備一個鍋，加入長通粉、三文魚肉、蘑菇、洋蔥、淡忌廉、白味噌及適量清水，蓋上鍋蓋，用中高火煮滾。'),
(10048, 178830, 3, '打開鍋蓋，加入露筍拌勻，轉至中小火煮10-12分鐘或至長通粉軟硬適中。'),
(10049, 178830, 4, '轉至中高火收汁，加少許鹽及黑胡椒調味，即成。'),
(10050, 178829, 1, '將蒜頭切成蓉。'),
(10051, 178829, 2, '洗淨雞腿肉，將厚身部份切開攤平，用刀背稍為拍扁。'),
(10052, 178829, 3, '雞肉用鹽及蒜蓉醃15分鐘。'),
(10053, 178829, 4, '在枱上鋪上錫紙，然後鋪上保鮮紙，放上雞肉攤平。'),
(10054, 178829, 5, '在雞肉上放上泡菜，把雞肉捲起，用錫紙包裹妥當，隔水蒸15-20分鐘。'),
(10055, 178829, 6, '除去錫紙及保鮮紙。用中火燒熱鍋，加少許油，加入雞卷煎至金黃色。'),
(10056, 178829, 7, '平均掃上韓式燒肉汁再煎1分鐘，即件即成。'),
(10057, 178828, 1, '將洋蔥、青燈籠椒及甘筍切絲；蒜頭切成蓉備用。'),
(10058, 178828, 2, '豬肉片用薑蓉、味噌、日本豉油、清酒、味醂及黃糖醃15分鐘。'),
(10059, 178828, 3, '用中火燒熱鍋，加少許油，加入蒜蓉、洋蔥及甘筍炒香。'),
(10060, 178828, 4, '加入豬肉片煎1分鐘，再炒至八成熟。'),
(10061, 178828, 5, '加入青燈籠椒炒勻，上碟即成。'),
(10062, 178827, 1, '將椰菜、洋蔥及甘筍切絲；豬肉片切細。'),
(10063, 178827, 2, '用中火燒熱鍋，加少許油，加入豬肉片炒至半熟，加入椰菜、洋蔥及甘筍炒香，盛起備用。'),
(10064, 178827, 3, '用同一個鍋，加入油麵炒香，加入已炒熟的配料炒勻，加入日式炒麵醬炒勻，上碟。'),
(10065, 178827, 4, '唧上蛋黃醬，灑上紫菜粉及木魚碎，即成。'),
(10066, 178774, 1, '將奇異果去皮切半。'),
(10067, 178774, 2, '將奇異果、青檸汁、原味希臘乳酪、鮮奶及蜜糖加入攪拌機打至幼滑。'),
(10068, 178774, 3, '倒入杯中，即成。'),
(10069, 178773, 1, '將士多啤梨洗淨去蒂。'),
(10070, 178773, 2, '將120克士多啤梨打成蓉，餘下的切粒備用。'),
(10071, 178773, 3, '魚膠片用凍水浸軟，隔水座溶備用。'),
(10072, 178773, 4, '將士多啤梨蓉、牛奶、淡忌廉、細砂糖及魚膠片溶液拌勻。'),
(10073, 178773, 5, '倒入模具，加入士多啤梨粒，放入雪櫃冷藏至凝固，即成。'),
(10074, 178844, 1, '先把薯仔刷洗乾淨，以筷子墊底把薯仔切薄片但不完全切斷。'),
(10075, 178844, 2, '把切好的薯仔整個放在鹽水中浸15分鐘，去掉薯仔內的澱粉，防止薯片互相黏連，同時為薯仔調味。'),
(10076, 178844, 3, '把整個薯仔瀝乾水，以廚房紙弄乾。'),
(10077, 178844, 4, '灑上鹽、白胡椒粉及黑胡椒碎以作調味。'),
(10078, 178844, 5, '然後抹上忌廉芝士，灑上芝士碎、紫洋蔥、紅椒及青椒碎。'),
(10079, 178844, 6, '放在焗爐中以200度焗20-25分鐘至金黃色即成；餘下的芝士、洋蔥、燈籠椒可放在小碟子中焗溶，變作芝士醬伴著焗薯來吃。'),
(10080, 178844, 7, '高芷欣的營養小貼士：1. 薯仔作主食其實比米飯更佳，連皮焗薯屬中GI（升糖指數）值的食物，對比白米屬高GI（升糖指數）值，連皮焗薯為主食能令血糖較穩定：2. 焗薯纖維量較白飯為高，以焗薯為主成比白米更好：3. 焗爐是健康煮食的必備之選，可以令餸菜少油之餘也不失香脆口感。'),
(10081, 178846, 1, '用濕廚房紙清潔大啡菇，去蒂及菌褶。'),
(10082, 178846, 2, '大啡菇表面掃上橄欖油，加入鹽及黑胡椒調味。'),
(10083, 178846, 3, '將意大利青醬及2湯匙特級初榨橄欖油 拌勻。'),
(10084, 178846, 4, '反轉大啡菇，加入青醬混合物。'),
(10085, 178846, 5, '將蒜蓉、番茄、番茜及菲達芝士拌勻，加入鹽、砂糖及黑胡椒調味；將混合物加進大啡菇。'),
(10086, 178846, 6, '用中火將大啡菇烤8-10分鐘或直至軟身，最後2分鐘蓋上錫紙。'),
(10087, 178846, 7, '淋上意大利香醋，即成。'),
(10088, 178825, 1, '預熱焗爐至180度；薯仔煮熟壓成蓉。'),
(10089, 178825, 2, '將火腿、蔥、紫洋蔥及三文魚切粒備用。'),
(10090, 178825, 3, '將薯蓉、鹽、黑胡椒、牛油及牛奶拌勻，加入火腿、蔥、紫洋蔥及三文魚拌勻。'),
(10091, 178825, 4, '準備一個焗碗，平鋪薯蓉。'),
(10092, 178825, 5, '薯蓉中間壓陷，加入雞蛋。'),
(10093, 178825, 6, '放入焗爐焗15分鐘，即成。'),
(10094, 178772, 1, '將紅菜頭洗淨去皮切件；番茄、蘋果、粟米及西芹切件；腰果浸洗備用。'),
(10095, 178772, 2, '將紅菜頭、番茄、蘋果、粟米、西芹、腰果、薑及適量水煮滾。'),
(10096, 178772, 3, '蓋上鍋蓋，轉中小火煮1小時。'),
(10097, 178772, 4, '打開鍋蓋，加少許鹽調味，即成。'),
(10098, 178771, 1, '將乾百合、蓮子、桂圓及紅棗浸洗，瀝乾備用。'),
(10099, 178771, 2, '將雪耳浸洗去蒂，撕成細塊。'),
(10100, 178771, 3, '將雪耳、蓮子、桂圓及適量水煮滾，蓋上鍋蓋，轉中小火煮1小時。'),
(10101, 178771, 4, '打開鍋蓋，加入百合及紅棗煮15分鐘。'),
(10102, 178771, 5, '加入冰糖煮至溶化，即成。'),
(10103, 178770, 1, '將豆腐、魷魚及蒟篛切粒；韭黃切段；草菇一開四備用。'),
(10104, 178770, 2, '蝦仁及魷魚用紹興酒、薑蓉、鹽及胡椒粉醃15分鐘。'),
(10105, 178770, 3, '煮滾一鍋水，加入豆腐、蝦仁、魷魚、草菇、蒟篛及新鮮粟米粒煮滾，轉中小火煮20分鐘。'),
(10106, 178770, 4, '將雞蛋打發。在鍋中加入韭黃及蛋液拌勻。'),
(10107, 178770, 5, '將馬蹄粉溶於2湯匙水，加進鍋裡拌勻及煮至濃稠，加入鹽及麻油調味，即成。'),
(10108, 178769, 1, '將薏米及淮山浸洗；節瓜及紅蘿蔔切件。'),
(10109, 178769, 2, '煮滾一鍋水，加入瘦肉汆水5分鐘，撈起瀝乾。'),
(10110, 178769, 3, '將節瓜、紅蘿蔔、瘦肉、生薏米、淮山及適量水煮滾。蓋上鍋蓋，轉中小火煮1小時。'),
(10111, 178769, 4, '加少許鹽調味，即成。'),
(10112, 178776, 1, '預熱焗爐至攝氏185度。'),
(10113, 178776, 2, '將士多啤梨切開4份。'),
(10114, 178776, 3, '將麵粉、砂糖、泡打粉及適量鹽拌勻，將凍牛油刨絲，加入拌勻。'),
(10115, 178776, 4, '加入士多啤梨，輕力拌勻。'),
(10116, 178776, 5, '將雞蛋及忌廉拌勻，慢慢加入麵粉漿，拌勻成麵團。'),
(10117, 178776, 6, '用手輕力搓揉麵團，小心不要壓爛士多啤梨及確保士多啤梨平均分佈。'),
(10118, 178776, 7, '枱上灑上麵粉，將麵團壓至1-1.5吋厚，切成8個三角形或用曲奇模切成適合形狀，放上鋪上牛油紙的焗盤，掃上蛋漿，再灑上砂糖。'),
(10119, 178776, 8, '放入焗爐 焗20-25分鐘，待涼5分鐘，再放架上待涼20分鐘。'),
(10120, 178776, 9, '配以果醬或牛油享用。'),
(10121, 178765, 1, '刮下夾心餅乾餡備用。'),
(10122, 178765, 2, '將餅乾放入保鮮袋，用擀麵棍敲碎。'),
(10123, 178765, 3, '將淡忌廉、牛奶、砂糖及餅乾餡用中火加熱。'),
(10124, 178765, 4, '攪拌至濃稠，一邊加入幼鹽一邊攪拌。'),
(10125, 178765, 5, '放涼後加入餅乾碎拌勻。'),
(10126, 178765, 6, '即成'),
(10127, 178659, 1, '將合掌瓜去籽切件；馬蹄切半；紅蘿蔔去皮切件；無花果及南北杏浸洗。'),
(10128, 178659, 2, '準備一鍋水，加入豬骨汆水至水滾，撈起瀝乾備用。'),
(10129, 178659, 3, '將合掌瓜、紅蘿蔔、馬蹄、豬骨、無花果、南北杏及適量水，用中火煮滾。'),
(10130, 178659, 4, '蓋上鍋蓋，轉中小火煮1.5小時。'),
(10131, 178659, 5, '加少許鹽調味，即成。'),
(10132, 178658, 1, '將絲瓜切件；木耳浸軟切件；蒜頭切成蓉。'),
(10133, 178658, 2, '將豬肉片加入生抽、砂糖、麻油及生粉醃15分鐘。'),
(10134, 178658, 3, '用中火燒熱鍋，加少許油，加入薑片及蒜蓉炒香。'),
(10135, 178658, 4, '加入豬肉片炒至八成熟。'),
(10136, 178658, 5, '加入絲瓜及木耳炒2分鐘。'),
(10137, 178658, 6, '加入米酒炒勻，加少許鹽調味，即成。'),
(10138, 178708, 1, '蝦乾浸開約30分鐘，然後切成碎，留少許不切作點綴之用。'),
(10139, 178708, 2, '蝦仁先把腸挑走（或買現成已挑了的蝦仁或冰鮮蝦仁），然後剁成蝦蓉。'),
(10140, 178708, 3, '把蝦蓉及蝦乾碎、白胡椒及鹽拌混。'),
(10141, 178708, 4, '把玉子豆腐切件然後放在碟子上。'),
(10142, 178708, 5, '把混好的材料用匙子放在玉子豆腐面。'),
(10143, 178708, 6, '然後把蝦乾放在蝦膠上。'),
(10144, 178708, 7, '水滾後以猛火隔水蒸5分鐘，再以中火蒸3-5分鐘。'),
(10145, 178708, 8, '灑上蔥花。'),
(10146, 178708, 9, '即成'),
(10147, 178708, 10, '高芷欣的營養小貼士：鮮蝦及乾蝦各有優點，自己剝蝦蓉能令口感更彈牙，而蝦乾令成品更有蝦香味；玉子豆腐其實並非豆腐，它主要成份是雞蛋，所以富含豐富蛋白質，而且這是一道口感簡單又顏色吸引的餸菜，弄給小孩子食是非常適合。'),
(10148, 178705, 1, '準備兩個碗，分開倒入番薯蓉及紫薯蓉。'),
(10149, 178705, 2, '加入糯米粉及水，把麵糰搓成長條形。'),
(10150, 178705, 3, '將麵糰分成20-24等份。'),
(10151, 178705, 4, '每份麵糰包裹一粒片糖，搓成球狀。'),
(10152, 178705, 5, '煮滾一鍋水，加入糯米糍，用中大火煮5分鐘至浮起。'),
(10153, 178705, 6, '上碟，灑上椰絲。'),
(10154, 178705, 7, '即成'),
(10155, 178657, 1, '將西芹及石斑柳切件；鮮百合浸洗分開；紅蘿蔔切片；蒜頭切成蓉。'),
(10156, 178657, 2, '石斑柳用鹽、胡椒粉、薑蓉、紹興酒及1茶匙生粉醃15分鐘。'),
(10157, 178657, 3, '用中火燒熱鍋，加少許油，加入石斑柳炒至八成熟，盛起備用。'),
(10158, 178657, 4, '用同一個鍋，加入蒜蓉炒香。'),
(10159, 178657, 5, '加入西芹、紅蘿蔔及鮮百合炒2分鐘。'),
(10160, 178657, 6, '加入石斑柳炒勻。'),
(10161, 178657, 7, '將餘下的生粉溶於20毫升水，加進石斑起茨，即成。'),
(10162, 178656, 1, '菜乾浸水30分鐘，瀝乾後切件；蠔豉及陳腎浸洗。'),
(10163, 178656, 2, '將白米洗淨瀝乾，加入鹽及油拌勻醃30分鐘。'),
(10164, 178656, 3, '將排骨用鹽醃1小時。準備一鍋水，加入排骨汆水至水滾，撈起瀝乾。'),
(10165, 178656, 4, '將白米、蠔豉、陳腎、菜乾、排骨及適量水，用中火煮滾。'),
(10166, 178656, 5, '蓋上鍋蓋，轉中小火煮1小時，即成。'),
(10167, 178655, 1, '將已沖洗的乾玫瑰花、洛神花、熱水及冰糖用中小火煮8分鐘，熄火焗3分鐘。'),
(10168, 178655, 2, '撈起玫瑰花及洛神花，加入魚膠粉拌勻至溶化。'),
(10169, 178655, 3, '倒入模具，放入雪櫃冷藏2小時至凝固，即成。'),
(10170, 178651, 1, '將開邊綠豆、蓮子及乾百合浸洗，瀝乾備用。將馬蹄切粒備用。'),
(10171, 178651, 2, '準備一鍋水，加入開邊綠豆、蓮子、乾百合及馬蹄，用中火煮滾，轉中小火煮30分鐘。'),
(10172, 178651, 3, '加入冰糖煮至溶化。'),
(10173, 178651, 4, '將馬蹄粉及1湯匙水拌勻，加入鍋中拌勻及煮至糖水稍為稠身，即成。'),
(10174, 178584, 1, '將蔥切粒；蒜切成蓉。'),
(10175, 178584, 2, '免治豬肉用生抽、砂糖、紹興酒、麻油及生粉醃15分鐘，加蔥粒、薑蓉及蒜蓉拌勻備用。'),
(10176, 178584, 3, '茄子用蝴蝶刀法切片。'),
(10177, 178584, 4, '釀入豬肉。'),
(10178, 178584, 5, '將中筋麵粉及水拌勻，加少許鹽。'),
(10179, 178584, 6, '用中火燒熱鍋，加少許油，茄子沾上麵糊，放入鍋中，用大火煎至兩面金黃色。'),
(10180, 178584, 7, '轉至中小火，蓋上鍋蓋煮至豬肉熟透，即成。'),
(10181, 178617, 1, '將柚子肉撕碎；大蝦去殼去腸；指天椒及芫茜切碎備用。'),
(10182, 178617, 2, '煮滾一鍋水，加入大蝦灼熟，撈起瀝乾備用。'),
(10183, 178617, 3, '將青檸汁、魚露、砂糖、指天椒、芫茜及水拌勻。'),
(10184, 178617, 4, '將柚子肉、花生碎及醬汁拌勻，上碟。'),
(10185, 178617, 5, '放上大蝦，灑上炸乾蔥碎。'),
(10186, 178617, 6, '即成'),
(10187, 178583, 1, '預熱焗爐至攝氏200度，焗盤鋪上鍚紙備用。'),
(10188, 178583, 2, '將茄子及車厘茄及切片，番茜切碎。'),
(10189, 178583, 3, '茄子鋪上焗盤，灑上鹽、黑胡椒及橄欖油。'),
(10190, 178583, 4, '抹上番茄羅勒醬，鋪上水牛芝士、車厘茄及西班牙香腸，再鋪上一層芝士。'),
(10191, 178583, 5, '放入焗爐焗10分鐘或至表面金黃色。'),
(10192, 178583, 6, '灑上番茜碎，即成。'),
(10193, 178616, 1, '預熱焗爐至攝氏180度；準備蛋糕焗盤，噴上食用噴油。'),
(10194, 178616, 2, '將香蕉去皮，用叉子壓成蓉，加入溶化牛油、黃糖、雞蛋及雲呢拿香油，拌勻。'),
(10195, 178616, 3, '準備另一個碗，篩入梳打粉、中筋麵粉及可可粉，加入鹽，再加進香蕉混合物拌勻。'),
(10196, 178616, 4, '加入朱古力及核桃，拌勻。'),
(10197, 178616, 5, '將麵糊倒入準備好的焗盤中，焗20-30分鐘。用牙籤插入蛋糕中心，測試是否焗好。放回焗爐待涼10-15分鐘，再放在架上待涼至暖或室溫。'),
(10198, 178616, 6, '即成'),
(10199, 178616, 7, '小貼士：這款香蕉蛋糕可以在室溫下密閉保存最多4天。'),
(10200, 178618, 1, '把牛油果切開然後在碗中壓爛，變成牛油果醬。'),
(10201, 178618, 2, '紫洋蔥及蒜頭切碎，拌入牛油果醬中。'),
(10202, 178618, 3, '加入檸檬汁、鹽、胡椒粉及黑胡椒於牛油果醬中拌混。'),
(10203, 178618, 4, '把混好的牛油果醬塗在Tortilla墨西哥薄餅上。'),
(10204, 178618, 5, '把芝士碎放平均灑於牛油果醬表面。'),
(10205, 178618, 6, '預熱焗爐，180度焗20分鐘直至芝士變成金黃色。'),
(10206, 178618, 7, '即成'),
(10207, 178665, 1, '將無骨雞腿肉切塊；蒜頭切成蓉。'),
(10208, 178665, 2, '將腐乳、五香粉、蒜蓉、黃糖、生抽及米酒拌勻。'),
(10209, 178665, 3, '加入雞腿肉及生粉拌勻，醃至少1小時。'),
(10210, 178665, 4, '沾上番薯粉，靜置10分鐘。'),
(10211, 178665, 5, '用中火燒熱鍋，加入適量油，加入雞腿肉炸至金黃色。'),
(10212, 178665, 6, '即成'),
(10213, 178613, 1, '預熱焗爐至攝氏100度。'),
(10214, 178613, 2, '洗淨水果，切成約5毫米厚的薄片。'),
(10215, 178613, 3, '焗盤鋪上牛油紙， 放上水果片。'),
(10216, 178613, 4, '放入焗爐焗100分鐘。'),
(10217, 178613, 5, '將白朱古力隔熱水座溶。'),
(10218, 178613, 6, '將白朱古力倒在金屬盤上，放上水果片、提子乾及杏仁。'),
(10219, 178613, 7, '放置室溫冷卻後，放入雪櫃冷藏3小時。'),
(10220, 178613, 8, '即成'),
(10221, 178582, 1, '預熱焗爐至攝氏200度。'),
(10222, 178582, 2, '將茄子切成長片；洋蔥切粒；蒜頭切成蓉；羅勒切碎備用。'),
(10223, 178582, 3, '用中火燒熱鍋，加少許油，加入蒜頭及洋蔥炒香。'),
(10224, 178582, 4, '加入番茄意粉醬煮滾，加入羅勒葉拌勻，熄火備用。'),
(10225, 178582, 5, '茄子沾上中筋麵粉。用中火燒熱另一個鍋，加少許油，加入茄子煎至兩面金黃色，盛起。'),
(10226, 178582, 6, '準備一個焗盤，依次鋪上番茄醬、茄子及水牛芝士，重覆此步驟，最後鋪上多一層番茄醬。'),
(10227, 178582, 7, '灑上巴馬臣芝士碎及麵包糠。'),
(10228, 178582, 8, '放入焗爐焗10分鐘或至表面金黃色，即成。'),
(10229, 178581, 1, '將茄子及布包豆腐切件，用鹽水浸30分鐘備用。'),
(10230, 178581, 2, '將鯪魚肉、蔥粒、麻油、1茶匙砂糖、生粉、鹽及胡椒粉順同一方向拌勻。'),
(10231, 178581, 3, '將辣豆瓣醬、砂糖、老抽及熱水拌勻備用。'),
(10232, 178581, 4, '用中火燒熱鍋，加少許油，加入鯪魚肉壓平，煎成魚餅，放涼後切條備用。'),
(10233, 178581, 5, '用同一個鍋，加少許油，加入蒜蓉炒香，加入茄子煎至軟身。'),
(10234, 178581, 6, '加入魚鬆、布包豆腐及醬汁拌勻，煮2-3分鐘，即成。'),
(10235, 178580, 1, '將蒜頭及指天椒切碎。'),
(10236, 178580, 2, '將茄子切半，用鹽水浸30分鐘備用。'),
(10237, 178580, 3, '用中火燒熱鍋，加少許油，加入蒜頭炒香。'),
(10238, 178580, 4, '加入茄子炒香，加入適量水煮滾，蓋上鍋蓋煮5分鐘或至軟身。'),
(10239, 178580, 5, '加入魚露、生抽及黃糖炒勻。'),
(10240, 178580, 6, '加入金不換、青檸汁及指天椒炒勻，即成。'),
(10241, 178579, 1, '預熱焗爐至攝氏180度，焗盤鋪上鍚紙備用。'),
(10242, 178579, 2, '將蒜頭切成蓉；蔥切粒；指天椒切碎。'),
(10243, 178579, 3, '將蒜蓉、孜然粉、椒鹽、砂糖、指天椒及油拌勻。'),
(10244, 178579, 4, '將茄子切半，放上焗盤，放入焗爐焗10分鐘。'),
(10245, 178579, 5, '取出茄子，界上紋，鋪上蒜蓉，再焗10-12分鐘至表面金黃色，灑上蔥粒，即成。'),
(10246, 178507, 1, '將翠玉瓜、紅尖椒、青尖椒及大蔥切片。'),
(10247, 178507, 2, '將魚乾放入茶包袋，放入鍋中，加入昆布及清水煮滾，用中火煮30分鐘，取出魚乾及昆布。'),
(10248, 178507, 3, '加入翠玉瓜及韓式餃子煮2分鐘。'),
(10249, 178507, 4, '加入紅尖椒、青尖椒、大蔥及年糕煮3分鐘。'),
(10250, 178507, 5, '將雞蛋打散，加入鍋中拌勻成蛋花。'),
(10251, 178507, 6, '加入鹽及胡椒粉調味，上碟。'),
(10252, 178507, 7, '灑上紫菜碎，即成。'),
(10253, 178506, 1, '將薯仔、翠玉瓜及紅尖椒切片；洋蔥及豆腐切粒；蔥切段；金菇洗淨去蒂備用。'),
(10254, 178506, 2, '用中火燒熱鍋，加少許油，加入洋蔥、紅尖椒及蔥段炒香。'),
(10255, 178506, 3, '加入翠玉瓜及薯仔炒香。'),
(10256, 178506, 4, '加入水煮滾，轉中小火煮15分鐘。'),
(10257, 178506, 5, '加入大醬及韓式辣醬拌勻，煮滾。'),
(10258, 178506, 6, '加入金菇、豆腐及豬肉片煮熟，即成。'),
(10259, 178574, 1, '將芒果、紫洋蔥、青辣椒、番茄及紅燈籠椒拌勻。'),
(10260, 178574, 2, '加入青檸汁及青檸皮、蜜糖、芫茜、鹽及黑胡椒調味，拌勻，靜置30分鐘，讓材料入味。'),
(10261, 178574, 3, '燒熱煎鍋，加入適量橄欖油。將帶子印乾，加入鹽調味，放上煎鍋， 每面煎約30秒至1分鐘至金黃色。'),
(10262, 178574, 4, '上碟，淋上芒果莎莎。'),
(10263, 178574, 5, '即成'),
(10264, 178573, 1, '預熱焗爐至攝氏100度。用電動攪拌器將蛋白及檸檬汁攪拌，以中速打發至起泡。'),
(10265, 178573, 2, '分3-4次加入糖粉，以高速打發至挺身。'),
(10266, 178573, 3, '將蛋白分成兩份，一份加入抹茶粉，另一份加入可可粉。'),
(10267, 178573, 4, '於焗盤放上牛油紙，用湯匙或擠花袋塑出喜歡的形狀。'),
(10268, 178573, 5, '放入焗爐焗80分鐘，直到蛋白霜餅乾不黏手。'),
(10269, 178573, 6, '即成'),
(10270, 178505, 1, '將雞腿肉及椰菜切件；洋蔥切絲；甘筍切片；蔥切粒；蒜頭切成蓉。'),
(10271, 178505, 2, '將韓式年糕放入熱水5分鐘泡軟，用手將韓式年糕分開。'),
(10272, 178505, 3, '雞腿肉用韓式辣醬、韓式辣椒粉、蒜蓉、砂糖、胡椒粉、生抽、米酒及韓國芝麻油醃1小時。'),
(10273, 178505, 4, '用中火燒熱鍋，加少許油，加入雞腿肉炒香。'),
(10274, 178505, 5, '加入洋蔥、紅蘿蔔、椰菜及年糕，不斷翻炒至雞腿肉熟透。'),
(10275, 178505, 6, '上碟，灑上蔥粒，即成。'),
(10276, 178504, 1, '將洋蔥切絲；白蘑菇及紅蘿蔔切片；蔥切段；蒜頭切成蓉備用。'),
(10277, 178504, 2, '將韓式年糕放入熱水5分鐘泡軟，用手將韓式年糕分開。'),
(10278, 178504, 3, '牛肉片用生抽、砂糖、米酒及麻油醃15分鐘。'),
(10279, 178504, 4, '用中火燒熱鍋，加少許油，加入牛肉炒至八成熟，盛起。'),
(10280, 178504, 5, '用同一個鍋，加少許油，加入蒜蓉、洋蔥及紅蘿蔔炒香。'),
(10281, 178504, 6, '加入白蘑菇快炒，加入年糕、年糕醬及適量水拌勻，煮滾，轉中小火煮8-10分鐘。'),
(10282, 178504, 7, '加入牛肉及蔥段拌勻，即成。'),
(10283, 178503, 1, '將白蘿蔔去皮切絲；蔥切粒；蒜頭切成蓉。'),
(10284, 178503, 2, '白蘿蔔用鹽醃30分鐘，用水沖走鹽，瀝乾。'),
(10285, 178503, 3, '加入韓式辣椒粉、砂糖、蒜蓉、蔥、魚露及白醋拌勻，即成。'),
(10286, 178502, 1, '將泡菜瀝乾及切絲；魷魚切成圈；蝦仁切半；蔥切段備用。'),
(10287, 178502, 2, '將韓國煎餅粉、雞蛋及水拌勻成漿狀，加入泡菜、蔥、蝦仁及魷魚拌勻。');
INSERT INTO steps (id, recipe_id, step_number , instruction) VALUES
(10288, 178502, 3, '用中火燒熱鍋，加少許油，加入煎餅糊煎至兩面金黃色。重覆此步驟直至煎餅糊用完。'),
(10289, 178502, 4, '切件上碟，即成。'),
(10290, 178456, 1, '預熱焗爐至攝氏180度，焗盤鋪上鍚紙備用。'),
(10291, 178456, 2, '將羅勒葉、紅燈籠椒、青燈籠椒及黃燈籠椒切碎。'),
(10292, 178456, 3, '準備一個鍋，加入紅藜麥及適量清水，用中火煮滾。蓋上鍋蓋，轉至中小火，煮12-15分鐘，熄火備用。'),
(10293, 178456, 4, '番茄切去頂部，用匙羹將中間的肉和籽挖出。'),
(10294, 178456, 5, '將紅藜麥、紅燈籠椒、青燈籠椒、黃燈籠椒、粟米粒、羅勒葉、鹽及黑胡椒拌勻。'),
(10295, 178456, 6, '釀入番茄，放上焗盤，灑上巴馬臣芝士碎。'),
(10296, 178456, 7, '放入焗爐焗10-12分鐘或至表面金黃色，即成。'),
(10297, 178518, 1, '預熱焗爐至攝氏220度，焗盤鋪上鍚紙備用。'),
(10298, 178518, 2, '將甘蔗切成10厘米長條，九層塔葉切碎備用。'),
(10299, 178518, 3, '將蝦膠、九層塔葉、蛋白、生粉、砂糖、鹽、胡椒粉、魚露及麻油拌勻，放入雪櫃冷藏1小時。'),
(10300, 178518, 4, '將蝦膠分成等分，包住甘蔗，甘蔗兩端預留2厘米。'),
(10301, 178518, 5, '放上焗盤，蔗蝦掃上油，放入焗爐焗10-12分鐘或至金黃色。'),
(10302, 178518, 6, '即成'),
(10303, 178455, 1, '將士多啤梨洗淨抹乾，去蒂。'),
(10304, 178455, 2, '將香蕉去皮切段。'),
(10305, 178455, 3, '將士多啤梨、香蕉、奇亞籽及牛奶打至幼滑，即成。'),
(10306, 178517, 1, '預熱焗爐至攝氏200度；將雞胸肉印乾，加入鹽及黑胡椒調味。將雞放在放入焗爐焗12-15分鐘，或直至雞肉熟透，放涼備用。'),
(10307, 178517, 2, '煮滾一鍋鹽水；蘆筍去根切條，每條約2吋，放入滾水煮1分鐘，瀝乾後浸凍水，印乾備用。'),
(10308, 178517, 3, '將蘆筍、車厘茄、青辣椒絲、薄荷葉及芫茜拌勻。'),
(10309, 178517, 4, '準備另一個碗，加入沙律汁食材，擠出新鮮青檸汁，拌勻，加入鹽及黑胡椒調味。'),
(10310, 178517, 5, '將1/2沙律汁放入大碗中與蔬菜拌勻。'),
(10311, 178517, 6, '將雞肉切薄片，放在沙律上。'),
(10312, 178517, 7, '淋上餘下的在沙律汁，加入花生碎，用新鮮的香草裝飾。'),
(10313, 178517, 8, '即成'),
(10314, 178497, 1, '將日式豉油及砂糖拌勻，備用。'),
(10315, 178497, 2, '將壽司飯及飯素紫菜絲拌勻。'),
(10316, 178497, 3, '放入模具中壓實。'),
(10317, 178497, 4, '用小火燒熱平底鍋，將飯糰兩面煎至微黃。'),
(10318, 178497, 5, '取出飯糰，兩面抹上日式豉油，再下鍋煎至表面金黃。'),
(10319, 178497, 6, '灑上紫菜絲，即成。'),
(10320, 178497, 7, '小貼士：壽司飯可用普通白飯或珍珠米飯代替。'),
(10321, 178454, 1, '將洋蔥及紅蘿蔔切粒；白蘑菇切片；蒜頭切成蓉；白米洗淨；野米浸過夜。'),
(10322, 178454, 2, '將野米、白米、雞湯、月桂葉及鹽用中火煮滾，轉中小火煮20-30分鐘。'),
(10323, 178454, 3, '用中火燒熱鍋，加入牛油煮溶，加入蒜蓉、洋蔥及紅蘿蔔炒香。'),
(10324, 178454, 4, '加入白蘑菇及意大利香草炒香。'),
(10325, 178454, 5, '加入野米及白米拌勻，上碟即成。'),
(10326, 178452, 1, '預熱焗爐至攝氏160度，焗盤鋪上牛油紙備用。'),
(10327, 178452, 2, '將核桃及杏仁稍稍壓碎。'),
(10328, 178452, 3, '將燕麥片、南瓜籽、核桃、杏仁、亞麻籽、紅莓乾、藍莓乾及肉桂粉拌勻。'),
(10329, 178452, 4, '加入楓糖漿拌勻。'),
(10330, 178452, 5, '倒入焗盤鋪平，放入焗爐焗30分鐘，期間每10分鐘取出翻拌一次，放涼即成。'),
(10331, 178451, 1, '將洋蔥及番茄乾切碎。將白藜麥及適量水用中火煮滾。蓋上鍋蓋，轉至中小火，煮12-15分鐘。熄火，放涼備用。'),
(10332, 178451, 2, '將白藜麥、硬豆腐、洋蔥、番茄乾、巴馬臣芝士碎、蛋白、中筋麵粉、橄欖油、意大利香草、鹽及黑胡椒拌勻。'),
(10333, 178451, 3, '搓成漢堡丸，放入雪櫃冷藏30分鐘。'),
(10334, 178451, 4, '用中火燒熱鍋，加少許油，加入漢堡丸並壓成餅狀，煎至兩面金黃色，上碟即成。'),
(10335, 178403, 1, '將蜆浸鹽水吐沙30分鐘。'),
(10336, 178403, 2, '將粉絲浸軟；蒜頭切成蓉；蔥切段；絲瓜去皮切件備用。'),
(10337, 178403, 3, '用中火燒熱鍋，加少許油，加入薑片及蒜蓉炒香。'),
(10338, 178403, 4, '加入絲瓜及清酒炒香，加入適量滾水煮滾。'),
(10339, 178403, 5, '加入蜆煮至開口。'),
(10340, 178403, 6, '加入粉絲及蔥段略煮，加少許鹽調味，即成。'),
(10341, 178402, 1, '將苦瓜去籽切片。'),
(10342, 178402, 2, '煮滾一鍋水，加少許鹽，加入苦瓜汆水1分鐘，撈起瀝乾。'),
(10343, 178402, 3, '將雞蛋打散，加入櫻花蝦、鹽、砂糖、胡椒粉及麻油拌勻。'),
(10344, 178402, 4, '用中火燒熱鍋，加少許油，加入苦瓜炒香，鋪平。'),
(10345, 178402, 5, '倒入蛋漿，煎至兩面金黃色。'),
(10346, 178402, 6, '切件，上碟即成。'),
(10347, 178447, 1, '預熱焗爐至攝氏200度；將羊架印乾，起走多餘的脂肪。'),
(10348, 178447, 2, '將茄子切塊，每塊約2厘米，車厘茄切半。將特級初榨橄欖油掃上茄子，用煎鍋煎至兩面金黃色。'),
(10349, 178447, 3, '在將茄子盛起，拍扁蒜頭，和車厘茄一起放上烤盤，灑上奧勒岡、鹽及黑胡椒調味。'),
(10350, 178447, 4, '羊架加入鹽及黑胡椒調味，用同一個煎鍋煎至金黃色。淋上橄欖油，放在同一個烤盤上，放入焗爐焗25-30分鐘至五成熟。'),
(10351, 178447, 5, '在烤焗時間的最後5分鐘，加入黑橄欖。從焗爐中取出烤盤，靜置5分鐘，然後切開。'),
(10352, 178447, 6, '準備醬汁，將薄荷葉、紅酒醋、砂糖、鹽及黑胡椒放入攪拌機，加入3-4湯匙特級初榨橄欖油。將所有材料打勻至幼滑。將醬汁淋在羊架及雜菜上。'),
(10353, 178447, 7, '即成'),
(10354, 178446, 1, '煮滾一鍋水，加入芽菜煮5分鐘。'),
(10355, 178446, 2, '瀝乾，放置室温10分鐘。'),
(10356, 178446, 3, '加入辣椒粉、蒜蓉、鹽及麻油，拌勻。'),
(10357, 178446, 4, '將青瓜片放碟上，放上芽菜。'),
(10358, 178446, 5, '灑上白芝麻。'),
(10359, 178446, 6, '即成'),
(10360, 178401, 1, '節瓜去皮切段，刮出瓜芯；乾冬菇浸軟切粒備用。'),
(10361, 178401, 2, '將免治豬肉、蝦膠、冬菇粒、鹽、麻油、胡椒粉及1/2湯匙生粉拌勻。'),
(10362, 178401, 3, '節瓜內搽少許生粉，釀入肉餡。'),
(10363, 178401, 4, '將雞湯煮滾，排入瓜甫，蓋好並以中火煮5-8分鐘至熟透，上碟。'),
(10364, 178401, 5, '餘下湯汁加入適量生粉水埋芡，淋於瓜甫，即成。'),
(10365, 178400, 1, '將冬瓜去皮切件；鯇魚腩洗淨抹乾，切件；芹菜切段；蒜頭切碎。'),
(10366, 178400, 2, '鯇魚腩用鹽及胡椒粉醃15分鐘，沾上生粉。'),
(10367, 178400, 3, '用中火燒熱鍋，加少許油，加入鯇魚腩煎香，盛起。'),
(10368, 178400, 4, '用中火燒熱另一個鍋，加少許油，加入薑片及蒜頭炒香，加入鯇魚腩及紹興酒，加入雞湯煮滾。'),
(10369, 178400, 5, '加入冬瓜、蠔油、生抽及老抽拌勻，蓋上鍋蓋，煮15-20分鐘。'),
(10370, 178400, 6, '加入芹菜拌勻，即成。'),
(10371, 178399, 1, '將蒜頭及指天椒切碎。'),
(10372, 178399, 2, '將青瓜稍稍去皮，一開四切成長條，拍扁，切件。'),
(10373, 178399, 3, '加入鹽拌勻，醃10分鐘，瀝乾水分備用。'),
(10374, 178399, 4, '將鎮江醋、生抽、砂糖、麻油、蒜蓉、及指天椒拌勻。'),
(10375, 178399, 5, '將青瓜與醬汁拌勻，放入雪櫃冷藏30分鐘，即成。'),
(10376, 178398, 1, '將節瓜去皮切件；分開鹹蛋的蛋黃及蛋白；瘦肉切片。'),
(10377, 178398, 2, '瘦肉用生抽、砂糖、麻油及生粉醃15分鐘。'),
(10378, 178398, 3, '煮滾一鍋水，加入薑片、節瓜、瘦肉及鹹蛋黃，用中火煮20分鐘。'),
(10379, 178398, 4, '加入鹹蛋白拌勻，即成。'),
(10380, 178343, 1, '將金華火腿及小棠菜切碎。'),
(10381, 178343, 2, '白米淘洗後，放入電飯煲，加入雞湯，開始煮飯。'),
(10382, 178343, 3, '用中火燒熱鍋，加少許油，加入薑片炒香，加入金華火腿炒香，加入小棠菜炒勻。'),
(10383, 178343, 4, '飯熟時，加入金華火腿、小棠菜及橄欖油拌勻，即成。'),
(10384, 178382, 1, '將奇異果去皮切片；士多啤梨去蒂切片；火龍果起肉切片；黃桃切片。'),
(10385, 178382, 2, '將白麵包切成三份。'),
(10386, 178382, 3, '將淡忌廉及砂糖打發至七成企身。'),
(10387, 178382, 4, '將淡忌廉抹上白麵包，隨意放上水果。'),
(10388, 178382, 5, '即成'),
(10389, 178342, 1, '將雞全脾及洋蔥切件；蒜頭及乾蔥切碎。'),
(10390, 178342, 2, '雞全脾用鹽、黑胡椒、迷迭香、蒜粉及橄欖油醃15分鐘。'),
(10391, 178342, 3, '將雞全脾沾上中筋麵粉。'),
(10392, 178342, 4, '用中火燒熱鍋，加少許油，加入雞全脾煎至金黃色，盛起備用。'),
(10393, 178342, 5, '用中高火燒熱另一個鍋，加入牛油煮溶，加入蒜蓉及乾蔥炒香，加入洋蔥炒香。'),
(10394, 178342, 6, '加入雞全脾及白酒快炒1分鐘，加入雞湯煮10-12分鐘。'),
(10395, 178342, 7, '7.加入淡忌廉、水牛芝士碎、巴馬臣芝士碎及車打芝士碎拌勻，煮至芝士溶化，即成。'),
(10396, 178380, 1, '準備沙律汁：將青檸汁、青檸皮、橄欖油、白葡萄酒醋、蜜糖、芥末籽醬、蒜蓉、鹽及黑胡椒拌勻。'),
(10397, 178380, 2, '將水蜜桃去核切成4-6塊。'),
(10398, 178380, 3, '燒熱煎鍋，加入水蜜桃兩面分別煎2-3分鐘至金黃色。'),
(10399, 178380, 4, '將沙律菜及幾湯匙沙律汁拌勻。'),
(10400, 178380, 5, '放上車厘茄。'),
(10401, 178380, 6, '將水蜜桃及白毛豬火腿放上沙律，灑上沙律汁及羊奶芝士。'),
(10402, 178380, 7, '即成'),
(10403, 178379, 1, '預熱焗爐至攝氏160度。'),
(10404, 178379, 2, '用小火將牛奶慢慢煮至冒煙。'),
(10405, 178379, 3, '將雞蛋打發，加入砂糖拌勻。'),
(10406, 178379, 4, '將蛋液篩入牛奶。'),
(10407, 178379, 5, '麵包撕成一口大小。'),
(10408, 178379, 6, '焗碗抹上牛油，放入麵包、果乾及牛奶混合物，浸泡15分鐘。'),
(10409, 178379, 7, '放入焗爐，焗30-40分鐘，即成。'),
(10410, 178341, 1, '莧菜去根洗淨及切段；蒜頭切成蓉備用。'),
(10411, 178341, 2, '將皮蛋切件；鹹蛋烚熟切粒。'),
(10412, 178341, 3, '用中火燒熱鍋，加少許油，加入薑片及蒜蓉炒香。'),
(10413, 178341, 4, '加入莧菜略炒，加入雞湯煮滾。'),
(10414, 178341, 5, '加入皮蛋及鹹蛋拌勻。'),
(10415, 178341, 6, '加入砂糖調味，即成。'),
(10416, 178340, 1, '將牛肝菌浸軟；鮮冬菇及白蘑菇切片；洋蔥切粒備用。將雞腿肉切絲，加入鹽及胡椒粉醃15分鐘備用。'),
(10417, 178340, 2, '雞湯用中火煮滾，轉至中小火保溫。'),
(10418, 178340, 3, '用中火燒熱鍋，加少許油，加入雞腿肉煎至八成熟，盛起備用。'),
(10419, 178340, 4, '同一個鍋，加入洋蔥、牛肝菌、鮮冬菇及白蘑菇炒香。'),
(10420, 178340, 5, '加入意大利米炒2-3分鐘，加入白酒。'),
(10421, 178340, 6, '煮至白酒幾乎收乾，加入部份雞湯蓋過米粒，用小火煮滾至米粒吸收湯汁。'),
(10422, 178340, 7, '重覆加雞湯的步驟，加最後一次雞湯時，同時加入雞肉及巴馬臣芝士碎，拌勻至飯煮至稠身。'),
(10423, 178340, 8, '熄火，加入黑胡椒及牛油拌勻，灑上番茜碎，即成。'),
(10424, 178339, 1, '將乾冬菇、瑤柱及蝦米浸發，乾冬菇切絲，瑤柱撕成絲；雞柳切粒；草菇切半備用。'),
(10425, 178339, 2, '用末端的冬瓜，切去少許尾部，令冬瓜可以站立。拿出瓜籽及瓜肉，於冬瓜盅內剩餘1吋厚。將冬瓜肉切粒。'),
(10426, 178339, 3, '雞柳用生抽、砂糖及紹興酒醃15分鐘。'),
(10427, 178339, 4, '將冬瓜盅放在碗內，蒸15-20分鐘。'),
(10428, 178339, 5, '將雞湯煮滾，加入冬瓜粒、冬菇粒、瑤柱、蝦米及草菇再煮滾。'),
(10429, 178339, 6, '蓋上鍋蓋，轉中小火煮15分鐘。'),
(10430, 178339, 7, '加入蝦仁及雞柳煮5分鐘。'),
(10431, 178339, 8, '加少許鹽及胡椒粉調味，將湯加入冬瓜盅，即成。'),
(10432, 178338, 1, '將雞骨洗淨；紫洋蔥、紅蘿蔔及紅蔥頭切件；蒜頭拍扁。'),
(10433, 178338, 2, '準備一鍋水，加入雞骨，用中火煮至微滾，取出雞骨再沖洗，瀝乾備用。'),
(10434, 178338, 3, '準備一個鍋，加入雞骨、紫洋蔥、蒜頭、乾蔥、紅蘿蔔、月桂葉及水，用中火煮滾。'),
(10435, 178338, 4, '蓋上鍋蓋，轉中小火煮3小時，即成。'),
(10436, 178287, 1, '將青燈籠椒去籽切件；蒜頭切成蓉；乾辣椒切粒備用。'),
(10437, 178287, 2, '將大蝦洗淨去殼去腸。'),
(10438, 178287, 3, '蝦仁用鹽、1/4湯匙砂糖、胡椒粉及生粉醃10分鐘。'),
(10439, 178287, 4, '將生抽、米酒、米醋、餘下的砂糖拌勻。'),
(10440, 178287, 5, '用中火燒熱鍋，加少許油，加入薑蓉、蒜蓉及乾辣椒炒香。'),
(10441, 178287, 6, '加入青燈籠椒炒勻，加入蝦球炒熟。'),
(10442, 178287, 7, '加入醬汁炒勻，即成。'),
(10443, 178286, 1, '預熱焗爐至攝氏200度，焗盤鋪上鍚紙；將竹籤浸水備用。'),
(10444, 178286, 2, '將羊腿肉切粒；蒜頭切成蓉。'),
(10445, 178286, 3, '羊腿肉加入孜然粉、甜椒粉、蒜蓉、鹽、砂糖及米酒醃30分鐘。'),
(10446, 178286, 4, '用竹籤串起羊腿肉，放上焗盤。'),
(10447, 178286, 5, '放入焗盤焗10-15分鐘，即成。'),
(10448, 178351, 1, '預熱焗爐至攝氏200度。將蘋果去皮切粒，加入檸檬汁，防止蘋果變色。'),
(10449, 178351, 2, '加入黃糖、中筋麵粉、肉桂粉、雲呢拿香油及提子乾，拌勻。'),
(10450, 178351, 3, '將中筋麵粉、原粒燕麥、黃糖及肉桂粉拌勻。'),
(10451, 178351, 4, '將凍牛油粒刨絲，加進麵粉混合物，用手輕輕拌勻成金寶配料。'),
(10452, 178351, 5, '將蘋果混合物放上焗爐適用的碟上，上面再放上金寶配料。'),
(10453, 178351, 6, '放上焗盤，放入焗爐焗15-20分鐘或至表面變成金黃色。'),
(10454, 178351, 7, '放涼5-10分鐘，趁熱配雲呢拿雪糕享用。'),
(10455, 178329, 1, '準備一個鍋，以中火加熱。'),
(10456, 178329, 2, '加入海鹽，炒至高溫。'),
(10457, 178329, 3, '將鍋內3分2海鹽盛起備用。'),
(10458, 178329, 4, '在海鹽中央放入鵪鶉蛋，並用鹽把蛋完全覆蓋。'),
(10459, 178329, 5, '蓋上鍋蓋，以小火煮5分鐘後熄火。'),
(10460, 178329, 6, '利用鹽的餘溫焗30分鐘。'),
(10461, 178329, 7, '即成'),
(10462, 178285, 1, '將紹菜及大蔥切段；豆腐切片備用。'),
(10463, 178285, 2, '將適量生粉抹勻廣島蠔，用水沖洗乾淨，瀝乾備用。'),
(10464, 178285, 3, '將味噌抹在鍋邊。'),
(10465, 178285, 4, '將紹菜、大蔥、本菇、豆腐及廣島蠔鋪入鍋中。'),
(10466, 178285, 5, '加入水、鰹魚粉、味醂、清酒及砂糖，用中火煮滾。'),
(10467, 178285, 6, '蓋上鍋蓋，轉中小火煮3-5分鐘，即成。'),
(10468, 178283, 1, '將韭菜花切段；蝦乾浸洗及瀝乾；魷魚洗淨界花切件；豆腐乾切片；蒜頭切成蓉。'),
(10469, 178283, 2, '用中火燒熱鍋，加少許油，加入蒜蓉炒香，加入蝦乾、魷魚及豆腐乾略炒。'),
(10470, 178283, 3, '加入韭菜花炒勻，加入紹興酒炒勻。'),
(10471, 178283, 4, '加入XO醬、生抽及砂糖炒勻。'),
(10472, 178283, 5, '加入脆腰果炒勻，即成。'),
(10473, 178282, 1, '將淮山去皮切片；蓮子、生薏米及乾百合浸洗瀝乾備用。'),
(10474, 178282, 2, '準備一鍋水，加入排骨，用中火汆水15分鐘。'),
(10475, 178282, 3, '將淮山、乾百合、蓮子、生薏米、排骨及適量水用中火煮滾。'),
(10476, 178282, 4, '蓋上鍋蓋，轉中小火煮1小時。'),
(10477, 178282, 5, '加少許鹽調味，即成。'),
(10478, 178281, 1, '將北芪、黨參、杞子、圓肉及芡實沖洗備用。'),
(10479, 178281, 2, '將烏雞洗淨。準備一鍋水，加入烏雞，用中火汆水至水滾，撈起瀝乾。'),
(10480, 178281, 3, '將烏雞、北芪、黨參、杞子、芡實、薑片、圓肉及適量水用中火煮滾。'),
(10481, 178281, 4, '蓋上鍋蓋，轉中小火煮1小時。'),
(10482, 178281, 5, '打開鍋蓋，加少許鹽調味，即成。'),
(10483, 178201, 1, '將雞翼洗淨抹乾，加入黑啤、生抽、老抽及黃糖醃1小時，保留醃汁'),
(10484, 178201, 2, '用中火燒熱鍋，加少許油，加入薑片及蒜頭炒香。'),
(10485, 178201, 3, '加入雞翼煎至金黃色，加入醃汁至醃蓋雞翼，煮滾。'),
(10486, 178201, 4, '轉中小火煮至收汁，即成。'),
(10487, 178236, 1, '預熱焗爐至攝氏180度；用廚房紙將硬豆腐完全印乾，切塊；雞蛋打散備用。'),
(10488, 178236, 2, '將粟米片放入密實袋，用麵棍壓碎。'),
(10489, 178236, 3, '將中筋麵粉、甜椒粉、蒜粉、鹽及黑胡椒拌勻。'),
(10490, 178236, 4, '將豆腐順序沾上麵粉混合物、蛋液及粟米片，放上焗盤。'),
(10491, 178236, 5, '放入焗爐焗10分鐘，取出反轉另一面，再焗10分鐘。'),
(10492, 178236, 6, '即成'),
(10493, 178200, 1, '迷迭香切碎備用。'),
(10494, 178200, 2, '預熱焗爐至攝氏180度，焗盤鋪上鍚紙備用。'),
(10495, 178200, 3, '雞翼洗淨抹乾，加入鹽、黑胡椒、1茶匙蒜粉及迷迭香醃15分鐘。'),
(10496, 178200, 4, '將雞翼放上焗盤，雞皮朝下焗8分鐘。'),
(10497, 178200, 5, '反轉另一面再焗8分鐘或至表面金黃色。'),
(10498, 178200, 6, '將巴馬臣芝士碎、餘下的蒜粉、乾番茜碎及橄欖油拌勻。'),
(10499, 178200, 7, '雞翼趁熱沾上芝士碎混合物，即成。'),
(10500, 178234, 1, '將免治豬肉及牛肉、洋蔥、蒜頭、肉桂粉、奧勒岡、番茜及雞蛋拌勻；加入麵包糠，分數次逐少加入，確保肉漿不會太乾；加入鹽及黑胡椒調味。'),
(10501, 178234, 2, '用手將肉漿搓成大小約1寸的肉丸。'),
(10502, 178234, 3, '用中高火燒熱鍋，加少許橄欖油，加入肉丸煎至表面金黃色，備用。'),
(10503, 178234, 4, '用同一個鍋，加入洋蔥及蒜蓉炒香，加入砂糖、鹽及黑胡椒調味。'),
(10504, 178234, 5, '加入罐裝番茄煮滾，加入肉丸煮20分鐘。'),
(10505, 178234, 6, '加入羅勒葉，煮10分鐘直至醬汁濃稠，加入鹽、黑胡椒及意大利黑醋調味。'),
(10506, 178234, 7, '熄火，上碟，灑上巴馬臣芝士及番茜碎，配麵包或意粉享用。'),
(10507, 178234, 8, '即成'),
(10508, 178233, 1, '預熱焗爐至攝氏210度。'),
(10509, 178233, 2, '將迷你熱狗及車打芝士片切半。'),
(10510, 178233, 3, '餃子皮抹上橄欖油，放上芝士片及迷你熱狗。'),
(10511, 178233, 4, '打發雞蛋，餃子皮邊抹上蛋漿黏合。'),
(10512, 178233, 5, '焗盤上鋪上牛油紙，放上熱狗卷，掃上蛋漿。'),
(10513, 178233, 6, '放入焗爐焗6分鐘至金黃色。'),
(10514, 178233, 7, '即成'),
(10515, 178199, 1, '將蒜頭切碎。'),
(10516, 178199, 2, '將雞翼洗淨抹乾，加入4湯匙韓式醃肉汁、薑蓉及蒜蓉醃30分鐘'),
(10517, 178199, 3, '將雞翼沾上中筋麵粉。'),
(10518, 178199, 4, '用中火燒熱鍋，加入適量油，加入雞翼半煎炸至熟透，盛起放上廚房紙吸去多餘油分。'),
(10519, 178199, 5, '將餘下的韓式醃肉汁、韓式辣醬、茄汁及蜜糖拌勻'),
(10520, 178199, 6, '用中火燒熱另一個鍋，加入醬汁煮熱，加入雞翼拌勻。'),
(10521, 178199, 7, '上碟，灑上芝麻碎，即成。'),
(10522, 178198, 1, '將雞翼洗淨抹乾，剪開一半。'),
(10523, 178198, 2, '加入五香粉、胡椒粉、鹽、紹興酒、砂糖、麻油及生粉醃30分鐘。'),
(10524, 178198, 3, '用中火燒熱鍋，加少許油，加入雞翼煎至兩面金黃色，即成。'),
(10525, 178197, 1, '將明太子切半，用匙羮輕輕勺出魚子，棄掉薄膜。'),
(10526, 178197, 2, '將雞翼去骨，加入生抽、紹興酒、麻油、鹽及胡椒粉醃10分鐘。'),
(10527, 178197, 3, '將明太子及蝦膠拌勻。'),
(10528, 178197, 4, '將蝦膠釀入雞翼。'),
(10529, 178197, 5, '用中火燒熱鍋，加少許油，加入雞翼煎至兩面金黃及全熟，即成。'),
(10530, 178196, 1, '將蒜頭拍扁。'),
(10531, 178196, 2, '煮滾一鍋水，加入雞翼汆水3分鐘，撈起瀝乾。'),
(10532, 178196, 3, '將生抽、老抽、紹興酒、水及黃糖拌勻。'),
(10533, 178196, 4, '用中火燒熱鍋，加少許油，加入薑片及蒜頭炒香。'),
(10534, 178196, 5, '加入雞翼炒2分鐘，加入醬汁及八角拌勻。'),
(10535, 178196, 6, '蓋上鍋蓋，轉至中小火煮至收汁，即成。'),
(10536, 178146, 1, '預熱焗爐至攝氏220度，焗盤鋪上鍚紙備用。'),
(10537, 178146, 2, '將番薯去皮切條，用廚房紙印乾水分。'),
(10538, 178146, 3, '加入黃糖、薑粉、甜椒粉、蒜粉、鹽及橄欖油拌勻。'),
(10539, 178146, 4, '鋪上焗盤，放入焗爐焗25-30分鐘。'),
(10540, 178146, 5, '準備牛油果醬：將牛油果起肉切粒壓成蓉，加入檸檬汁、鹽及黑胡椒拌勻。'),
(10541, 178146, 6, '番薯條伴以牛油果醬享用。'),
(10542, 178145, 1, '預熱焗爐至攝氏220度；焗盤鋪上鍚紙；將煙三文魚切半備用。'),
(10543, 178145, 2, '牛油果切半去核，稍稍挖空，放上焗盤。'),
(10544, 178145, 3, '放上煙三文魚，加入雞蛋。'),
(10545, 178145, 4, '放入焗爐焗12-15分鐘。'),
(10546, 178145, 5, '灑上海鹽、黑胡椒及刁草，即成。'),
(10547, 178211, 1, '煮滾一鍋水，加入鹽，加入寬意粉，按包裝指示煮至軟硬適中，撈起瀝乾備用，保留意粉水。'),
(10548, 178211, 2, '用中火燒熱煎鍋，加入橄欖油及牛油煮溶，加入蒜蓉及乾蔥炒香。'),
(10549, 178211, 3, '加入檸檬汁及1湯勺意粉水，煮1分鐘，加入淡忌廉，轉至小火，煮滾。'),
(10550, 178211, 4, '加入意粉拌勻。'),
(10551, 178211, 5, '加入鹽、砂糖及黑胡椒調味。'),
(10552, 178211, 6, '熄火，加入1/2巴馬臣芝士、1/2個檸檬皮及1/2番茜碎拌勻。'),
(10553, 178211, 7, '上碟，灑上餘下的檸檬皮、芝士及番茜碎。'),
(10554, 178211, 8, '即成'),
(10555, 178187, 1, '將九層塔、蒜頭及指天椒切碎。'),
(10556, 178187, 2, '用中小火燒熱平底鍋，加少許油。'),
(10557, 178187, 3, '炒香蒜頭、指天椒及一半九層塔。'),
(10558, 178187, 4, '加入帆立貝，灑上鹽及黑胡椒。'),
(10559, 178187, 5, '將帆立貝兩面煎至金黃色。'),
(10560, 178187, 6, '轉大火煎1分鐘，加入餘下的九層塔炒香。'),
(10561, 178187, 7, '即成'),
(10562, 178144, 1, '將雞胸肉烚熟及切粒；番茄去籽切粒；紫洋蔥及芫茜切碎；雞蛋打發；牛油果去核起肉，用匙背壓成蓉。'),
(10563, 178144, 2, '將牛油果、雞胸肉、番茄粒、紫洋蔥碎、芫茜碎、水牛芝士碎、青檸汁、鹽及黑胡椒拌勻。'),
(10564, 178144, 3, '將饀料放上春卷皮，向內摺，邊角塗上少許蛋液，捲起成春卷狀。'),
(10565, 178144, 4, '用中高火燒熱油鍋，加入足夠份量的油，半煎炸至金黃色。'),
(10566, 178144, 5, '撈起，放在廚紙上吸去油份，即成。'),
(10567, 178143, 1, '將牛油果起肉切片。'),
(10568, 178143, 2, '虎蝦用鹽及黑胡椒調味。'),
(10569, 178143, 3, '將牛油果、羅勒葉、松子、蒜頭、鹽、黑胡椒、橄欖油及檸檬汁用攪拌器打勻。'),
(10570, 178143, 4, '煮滾一鍋水，加少許鹽，加入意粉煮至軟硬適中，撈起瀝乾。'),
(10571, 178143, 5, '加入牛油果青醬拌勻，上碟。'),
(10572, 178143, 6, '用中高火燒熱鍋，加少許油，加入虎蝦煎至兩面金黃色，放上意粉，即成。'),
(10573, 178142, 1, '將牛油果去核起肉。'),
(10574, 178142, 2, '將白桃去皮去核。'),
(10575, 178142, 3, '將牛油果、白桃及牛奶用攪拌器打至幼滑。'),
(10576, 178142, 4, '倒入杯中，灑上杏仁碎，即成。'),
(10577, 178141, 1, '將牛油果、紫洋蔥及溫室青瓜切粒。'),
(10578, 178141, 2, '雞胸肉加入鹽及黑胡椒調味。'),
(10579, 178141, 3, '準備一個鍋，加入藜麥及適量水，用中火煮滾。'),
(10580, 178141, 4, '蓋上鍋蓋，轉至中小火，煮13-15分鐘。熄火，放涼備用。'),
(10581, 178141, 5, '用中火燒熱鍋，加少許油，加入雞胸肉煎至兩面金黃色，加入適量水煮滾，蓋上鍋蓋，煮至雞肉熟透，切片。'),
(10582, 178141, 6, '將牛油果、紫洋蔥、青瓜、藜麥、紅桑子乾、橄欖油、檸檬汁、鹽及黑胡椒拌勻，上碟。'),
(10583, 178141, 7, '放上雞肉，灑上杏仁碎，即成。'),
(10584, 178097, 1, '將五花肉斜切成薄片；溫室青瓜切絲；蒜頭切成蓉；指天椒切碎備用。'),
(10585, 178097, 2, '煮滾一鍋水，加入檸檬汁及五花肉，用中小火煮熟，撈起備用。'),
(10586, 178097, 3, '將粉皮切條。煮滾另一鍋水，加入粉皮煮熟，撈起放入冰水冷卻，撈起備用。'),
(10587, 178097, 4, '將生抽、水、黑醋、麻油、砂糖、辣椒油、蒜蓉及指天椒拌勻。'),
(10588, 178097, 5, '將粉皮、五花肉及青瓜絲鋪上碟，淋上醬汁，即成。'),
(10589, 178096, 1, '將蔥切段；薑切片；將青瓜刨成薄片。'),
(10590, 178096, 2, '煮滾一鍋水，加入薑、蔥及紹興酒，加入雞腿肉煮熟，撕成絲。'),
(10591, 178096, 3, '將雞絲放上青瓜片，捲好，上碟。'),
(10592, 178096, 4, '將麻醬、生抽、白醋、砂糖及麻油拌勻。'),
(10593, 178096, 5, '淋上青瓜卷，即成。'),
(10594, 178155, 1, '將雞蛋、牛奶、番茜碎、巴馬臣芝士碎、鹽及黑胡椒拌勻。'),
(10595, 178155, 2, '將麵包浸入蛋液中。'),
(10596, 178155, 3, '用中火燒熱鍋，加入牛油及少許橄欖油。'),
(10597, 178155, 4, '加入麵包煎至兩面金黃色，上碟。'),
(10598, 178155, 5, '用同一個鍋，加入車厘茄及嫩菠菜快炒。'),
(10599, 178155, 6, '將車厘茄、嫩菠菜及煙三文魚放上西多。'),
(10600, 178155, 7, '即成'),
(10601, 178126, 1, '準備一碗水，加入鹽。'),
(10602, 178126, 2, '用鹽水搓洗檸檬及青檸表面，抹乾。'),
(10603, 178126, 3, '將檸檬及青檸切至約5毫米厚。'),
(10604, 178126, 4, '準備一個玻璃樽，逐層放入檸檬及青檸，加入蜜糖，重覆以上步驟。'),
(10605, 178126, 5, '蓋上樽蓋，放置雪櫃冷藏至少2天。'),
(10606, 178126, 6, '即成'),
(10607, 178095, 1, '茄子洗淨後切塊，用少許鹽醃5分鐘。'),
(10608, 178095, 2, '煮滾一鍋水，加入白醋，加入茄子煮5分鐘。'),
(10609, 178095, 3, '放入冰水浸至冷卻，瀝乾上碟。'),
(10610, 178095, 4, '將味醂、鰹魚醬油、水及砂糖拌勻。'),
(10611, 178095, 5, '淋上茄子，灑上木魚碎，即成。'),
(10612, 178094, 1, '青尖椒去籽去囊切碎；蒜頭及芫茜切碎備用。'),
(10613, 178094, 2, '將皮蛋去殼切件，鋪上碟。'),
(10614, 178094, 3, '將生抽、鎮江醋、辣椒油、花椒油及麻油拌勻。'),
(10615, 178094, 4, '用中火燒熱鍋，加少許油，加入蒜頭及青尖椒炒香，加入米酒炒勻。'),
(10616, 178094, 5, '轉至中小火，加入生抽混合物及砂糖煮至砂糖溶化。'),
(10617, 178094, 6, '熄火放涼，淋上皮蛋，灑上芫茜碎，即成。'),
(10618, 178123, 1, '將洋蔥切絲；青瓜切角；蒜頭切成蓉。'),
(10619, 178123, 2, '煮滾一鍋水，加入紹興酒，加入鮑貝汆水2分鐘，撈起瀝乾，放涼備用。'),
(10620, 178123, 3, '將韓式辣醬、韓式辣椒粉、白醋、砂糖、生抽、麻油及蒜蓉拌勻。'),
(10621, 178123, 4, '加入鮑貝、洋蔥及青瓜拌勻。'),
(10622, 178123, 5, '灑上白芝麻，即成。'),
(10623, 178092, 1, '將蒜頭切碎。'),
(10624, 178092, 2, '煮滾一鍋水，加入雞腳汆水2-3分鐘，放入冰水冷卻，瀝乾備用。'),
(10625, 178092, 3, '用中火燒熱鍋，加少許油，加入薑、八角及蒜蓉炒香。'),
(10626, 178092, 4, '加入雞腳炒香。'),
(10627, 178092, 5, '加入蠔油、鮑汁、生抽、老抽、冰糖及1000毫升水用中高火煮滾。'),
(10628, 178092, 6, '加入花生，蓋上鍋蓋，轉至中小火煮1.5小時，即成。'),
(10629, 178082, 1, '將溫室青瓜、紅燈籠椒、黃燈籠椒、紅蘿蔔及紫椰菜全部切絲備用；蒜頭及指天椒切碎；檬粉煮熟備用。'),
(10630, 178082, 2, '將蘸汁材料拌勻。'),
(10631, 178082, 3, '將米紙浸入溫水10秒，放上砧板。'),
(10632, 178082, 4, '在米紙中央位置，依次放上溫室青瓜、紅蘿蔔、紅燈籠椒、黃燈籠椒、紫椰菜及檬粉，捲起米紙。'),
(10633, 178082, 5, '伴以蘸汁食用。'),
(10634, 178082, 6, '即成'),
(10635, 178027, 1, '將秋葵用鹽搓洗，將上面的毛洗去，洗淨後用廚房紙印乾水分，切片。'),
(10636, 178027, 2, '將熟鹹蛋黃切粒。'),
(10637, 178027, 3, '用中火燒熱鍋，加少許油，加入熟鹹蛋黃，用中小火炒溶至軟滑狀。'),
(10638, 178027, 4, '加入秋葵炒勻，加入砂糖調味，即成。'),
(10639, 178083, 1, '預熱焗爐至攝氏180度；焗盤鋪上牛油紙備用；將牛油及紅糖打發至軟滑鬆發。'),
(10640, 178083, 2, '加入雞蛋及雲呢拿香油，打發1分鐘至拌勻。'),
(10641, 178083, 3, '將中筋麵粉、梳打粉、肉桂粉、薑粉及鹽拌勻。'),
(10642, 178083, 4, '加入至牛油混合物，用刮刀拌勻，加入原粒燕麥、薑糖及黑朱古力片拌勻。'),
(10643, 178083, 5, '舀出麵糊，放上焗盤，每團麵糊相隔8厘米。'),
(10644, 178083, 6, '放入焗爐焗12-14分鐘或至金黃色，待涼。'),
(10645, 178083, 7, '即成'),
(10646, 178026, 1, '將秋葵用鹽搓洗，將上面的毛洗去，洗淨後用廚房紙印乾水分。'),
(10647, 178026, 2, '將秋葵切半刮囊，備用。'),
(10648, 178026, 3, '將蝦滑、麻油、鹽及胡椒粉拌勻。'),
(10649, 178026, 4, '將秋葵中空位置沾上少許生粉，釀入蝦滑。'),
(10650, 178026, 5, '用中火燒熱鍋，加少許油，加入秋葵，蝦滑面朝下，煎至熟透即成。'),
(10651, 178081, 1, '選擇偏硬的紅梨，去皮切半備用。'),
(10652, 178081, 2, '將紅酒煮至微熱。'),
(10653, 178081, 3, '加入黃糖、肉桂條及檸檬。'),
(10654, 178081, 4, '待紅酒微滾時，加入紅梨，用牛油紙覆蓋。'),
(10655, 178081, 5, '煮滾後轉小火，再煮40分鐘，每10分鐘翻面一次。'),
(10656, 178081, 6, '即成'),
(10657, 178025, 1, '預熱焗爐至攝氏220度，焗盤鋪上鍚紙備用。'),
(10658, 178025, 2, '將秋葵用鹽搓洗，將上面的毛洗去，洗淨後用廚房紙印乾水分。'),
(10659, 178025, 3, '加入海鹽、黑胡椒及橄欖油拌勻，放上焗盤。'),
(10660, 178025, 4, '放入焗爐焗10-12分鐘至香脆，即成。'),
(10661, 178024, 1, '將秋葵用鹽搓洗，將上面的毛洗去，洗淨切粒；豆腐切片；紅蘿蔔去皮切片；蔥切粒；三文魚頭洗淨備用。'),
(10662, 178024, 2, '三文魚頭用鹽、胡椒粉及紹興酒醃15分鐘，沾上生粉。'),
(10663, 178024, 3, '用中火燒熱鍋，加少許油，加入薑片炒香，加入三文魚頭煎至兩面金黃色。'),
(10664, 178024, 4, '準備一個鍋，加入三文魚頭、紅蘿蔔、豆腐及適量滾水，用大火煮15分鐘。'),
(10665, 178024, 5, '加入白味噌及秋葵拌勻，煮3-5分鐘。'),
(10666, 178024, 6, '加入蔥粒拌勻，即成。'),
(10667, 178023, 1, '將秋葵用鹽搓洗，將上面的毛洗去。'),
(10668, 178023, 2, '煮滾一鍋水，加入秋葵煮1分鐘，撈起放入冰水冷卻，瀝乾備用。'),
(10669, 178023, 3, '將日式芝麻醬、日本豉油、柚子醋及水拌勻。'),
(10670, 178023, 4, '淋上秋葵，灑上木魚碎，即成。'),
(10671, 178022, 1, '將秋葵用鹽搓洗，將上面的毛洗去，洗淨切粒；乾蔥、蔥、芫茜、檸檬葉及指天椒切碎備用。'),
(10672, 178022, 2, '將西生菜分成一片片，盡量保持碗的形狀。'),
(10673, 178022, 3, '用中高火燒熱鍋，加少許油，加入秋葵及乾蔥炒香，盛起。'),
(10674, 178022, 4, '用同一個鍋，加入免治豬肉炒至鬆散。'),
(10675, 178022, 5, '加入魚露、砂糖及青檸汁炒勻。'),
(10676, 178022, 6, '加入秋葵及乾蔥、蔥、芫茜、檸檬葉及指天椒炒勻。'),
(10677, 178022, 7, '伴以生菜享用，即成。'),
(10678, 177956, 1, '將雞翼洗淨抹乾；蒜頭切成蓉；南乳去衣。'),
(10679, 177956, 2, '將南乳、紹興酒、生抽、老抽、砂糖及麻油拌勻。'),
(10680, 177956, 3, '加入雞翼及蒜蓉拌勻，醃30分鐘。'),
(10681, 177956, 4, '用中火燒熱鍋，加少許油，加入雞翼，轉中小火煎至熟透及兩面金黃色，即成。'),
(10682, 177971, 1, '將蝦去殼去腸，保留蝦頭及蝦殼；2瓣蒜頭切成蓉，3瓣蒜頭切片；蝦、蒜蓉、2湯匙橄欖油及鹽拌勻備用。'),
(10683, 177971, 2, '用小火燒熱鍋，加入餘下的橄欖油、1瓣蒜頭、紅椒片、蝦殼及蝦頭，慢煮10分鐘，逼出蝦的味道。'),
(10684, 177971, 3, '將油倒到碗裡，隔走蝦頭、蝦殼及蒜頭。'),
(10685, 177971, 4, '用中火燒熱同一個鍋，加入蝦油及蒜片，煮1分鐘至蒜片微微金黃色，其間不斷攪拌。'),
(10686, 177971, 5, '加入蝦煮熟，其間不斷攪拌。'),
(10687, 177971, 6, '加少許鹽、黑胡椒、紅椒片及番茜碎，上碟。'),
(10688, 177971, 7, '淋上蝦油及蒜片，加入檸檬裝飾。'),
(10689, 177971, 8, '即成'),
(10690, 177955, 1, '將茄子切件，用鹽水浸30分鐘備用。'),
(10691, 177955, 2, '免治豬肉用鹽、紹興酒及胡椒粉醃15分鐘。'),
(10692, 177955, 3, '用中火燒熱鍋，加少許油，加入茄子煎軟，備用。'),
(10693, 177955, 4, '用中火燒熱同一個鍋，加少許油，加入蒜蓉及薑蓉炒香。'),
(10694, 177955, 5, '加入豬肉炒熟，加入辣豆瓣醬炒勻。'),
(10695, 177955, 6, '加入生抽、水及砂糖炒勻，加入茄子炒勻。'),
(10696, 177955, 7, '加入麻油拌勻，上碟即成。'),
(10697, 177954, 1, '將乾蔥、蒜頭、指天椒及蔥切幼粒；硬豆腐切方粒。'),
(10698, 177954, 2, '煮滾一鍋水，加入鹽及豆腐粒，煮3-4分鐘，瀝起，放上廚房紙完全印乾。'),
(10699, 177954, 3, '將豆腐粒均勻沾上生粉。'),
(10700, 177954, 4, '用中高火燒熱鍋，加少許油，加入豆腐粒煎至金黃色，備用。'),
(10701, 177954, 5, '用中火燒熱同一個鍋，加少許油，加入乾蔥、蒜頭及指天椒炒香。'),
(10702, 177954, 6, '加入豆腐及椒鹽炒勻，加入蔥粒炒勻，即成。'),
(10703, 177974, 1, '鮮奶用中火煮至微暖，熄火。'),
(10704, 177974, 2, '加入砂糖拌勻，放涼備用。'),
(10705, 177974, 3, '將蛋白略為打發，過篩後加入鮮奶混合物拌勻。'),
(10706, 177974, 4, '倒入蒸碗，用錫紙封好。'),
(10707, 177974, 5, '用中火蒸15分鐘，轉中小火再蒸5分鐘。'),
(10708, 177974, 6, '除去鍚紙，放上燕窩。'),
(10709, 177974, 7, '即成'),
(10710, 177953, 1, '將新鮮海底椰及豬腱洗淨；蜜棗、南北杏及核桃浸洗；粟米及紅蘿蔔切件。'),
(10711, 177953, 2, '煮滾一鍋水，加入豬腱用中火汆水5分鐘。'),
(10712, 177953, 3, '將海底椰、粟米、紅蘿蔔、豬腱、蜜棗、南北杏、核桃及適量水用中高火煮滾。'),
(10713, 177953, 4, '轉中小火，蓋上鍋蓋，煮1小時。'),
(10714, 177953, 5, '加少許鹽調味，即成。'),
(10715, 177952, 1, '將蓮子及紅棗浸洗；雞蛋烚熟去殼。'),
(10716, 177952, 2, '將桑寄生洗淨瀝乾，放入魚袋。'),
(10717, 177952, 3, '煮滾一鍋水，加入桑寄生、紅棗及蓮子 用中火煮1小時。'),
(10718, 177952, 4, '取出桑寄生，加入片糖及雞蛋，煮至片糖溶化，即成。'),
(10719, 177951, 1, '將海蝦洗淨去腸及抹乾；洋蔥、蒜頭及乾蔥切碎。'),
(10720, 177951, 2, '將茄汁、生抽、喼汁、砂糖及水拌勻。'),
(10721, 177951, 3, '將大蝦沾上生粉。'),
(10722, 177951, 4, '用中火燒熱鍋，加少許油，加入大蝦煎至轉色備用。'),
(10723, 177951, 5, '用中火燒熱同一個鍋，加少許油，加入薑片及蒜頭炒香，加入洋蔥及乾蔥炒香。'),
(10724, 177951, 6, '加入醬汁炒勻，加入大蝦炒勻，即成。'),
(10725, 177890, 1, '預熱焗爐至攝氏180度。將薯仔去皮及刨成薄片，牛油溶化備用。'),
(10726, 177890, 2, '將牛奶及淡忌廉用中火煮滾。加入薯仔拌勻，加入海鹽、黑胡椒及肉豆蔻粉拌勻。'),
(10727, 177890, 3, '轉至中小火煮20-25分鐘。熄火，加入2/3格魯耶爾芝士碎及牛油拌勻。'),
(10728, 177890, 4, '倒入焗盤鋪好，灑上餘下的格魯耶爾芝士碎。'),
(10729, 177890, 5, '放入焗爐焗35-40分鐘或至薯仔熟透，即成。'),
(10730, 177963, 1, '用廚房紙將豬扒印乾。'),
(10731, 177963, 2, '用刀背將豬扒拍鬆。'),
(10732, 177963, 3, '豬扒用1/2迷迭香碎、黃糖、鹽、黑胡椒及5毫升橄欖油醃30分鐘至2小時；預熱焗爐至攝氏200度。'),
(10733, 177963, 4, '用大火燒熱鍋，加入餘下的橄欖油及豬扒煎3分鐘，直至一面金黃色。'),
(10734, 177963, 5, '反轉，加入餘下的迷迭香碎、提子及雞湯。'),
(10735, 177963, 6, '整個鍋放入焗爐，焗8分鐘或至豬扒熟透，視乎豬扒的厚度。'),
(10736, 177963, 7, '將整個鍋取出，豬扒上碟。'),
(10737, 177963, 8, '放上提子及淋上醬汁，待涼5分鐘，即成。'),
(10738, 177963, 9, '小貼士：沒有可放入焗爐的煎鍋，可將焗盤先放入焗爐一起預熱，豬扒煎好後放上焗盤，再放入焗爐。'),
(10739, 177889, 1, '預熱焗爐至攝氏180度，焗盤鋪上鍚紙備用。'),
(10740, 177889, 2, '預備白醬：用中火燒熱鍋，加入1/2牛油煮至溶化，加入麵粉炒勻。'),
(10741, 177889, 3, '加入牛奶拌勻及煮至濃稠，加入鹽、黑胡椒及肉豆蔻粉調味，轉至中小火保溫備用。'),
(10742, 177889, 4, '將酸種麵包放上焗盤，放入焗爐焗3-4分鐘或至金黃色。'),
(10743, 177889, 5, '酸種麵包塗上餘下的牛油，放上火腿，淋上少許白醬，灑上格魯耶爾芝士碎。'),
(10744, 177889, 6, '放上另一片麵包，淋上少許白醬，灑上格魯耶爾芝士碎。'),
(10745, 177889, 7, '放入焗爐焗至芝士溶化，即成。'),
(10746, 177888, 1, '將煙肉切粒；蘑菇切半；洋蔥切絲；紅蘿蔔切件。'),
(10747, 177888, 2, '將雞腿洗淨抹乾，用鹽及黑胡椒醃10分鐘。'),
(10748, 177888, 3, '用中火燒熱鍋，加入煙肉炒香備用。'),
(10749, 177888, 4, '用同一個鍋，加入雞腿煎香備用。'),
(10750, 177888, 5, '用同一個鍋，加入洋蔥及紅蘿蔔炒香，加入蘑菇炒香。'),
(10751, 177888, 6, '加入中筋麵粉炒勻，加入白蘭地拌勻。'),
(10752, 177888, 7, '加入雞腿、煙肉、番茄膏、紅酒、雞湯、百里香及月桂葉拌勻及煮滾。'),
(10753, 177888, 8, '蓋上鍋蓋，轉中小火煮20-30分鐘，即成。'),
(10754, 177887, 1, '將番茜及乾蔥切碎；凍牛油切粒備用。'),
(10755, 177887, 2, '將比目魚洗淨抹乾，灑上鹽及黑胡椒調味，平均地沾上一層薄薄的中筋麵粉。'),
(10756, 177887, 3, '用中火燒熱鍋，加入20克牛油煮至溶化，加入比目魚煎至兩面金黃色及熟透，上碟。'),
(10757, 177887, 4, '用中小火將乾蔥、白酒及白酒醋煮至蒸發2/3。'),
(10758, 177887, 5, '分次加入餘下的凍牛油，每次加入前確保牛油與白酒混合物完全融合。'),
(10759, 177887, 6, '加入淡忌廉及鹽拌勻，淋上比目魚。'),
(10760, 177887, 7, '灑上番茜碎，即成。'),
(10761, 177886, 1, '煮滾一鍋水，加入白醋，轉中小火，用湯匙將水劃圈成漩渦狀，慢慢加入雞蛋，煮3分鐘或至凝固即可。將羅馬生菜及九芽菜洗淨瀝乾，切件；車厘茄切半。'),
(10762, 177886, 2, '用中火燒熱鍋，加入意大利煙肉炒香，盛起。'),
(10763, 177886, 3, '將羅馬生菜、九芽菜及車厘茄鋪上碟。'),
(10764, 177886, 4, '放上水波蛋，灑上煙肉粒、麵包脆粒及黑胡椒。'),
(10765, 177886, 5, '享用時伴以紅酒醋及橄欖油。'),
(10766, 177885, 1, '預熱焗爐至攝氏210度，焗盤鋪上鍚紙備用。'),
(10767, 177885, 2, '將蘑菇、紅蘿蔔、洋蔥及蒜頭切碎。'),
(10768, 177885, 3, '將扇貝洗淨，用廚房紙完全抹乾後放回貝殼，放上焗盤。'),
(10769, 177885, 4, '用中火燒熱鍋，加入牛油煮至溶化，加入蘑菇、紅蘿蔔、洋蔥及蒜頭炒香。'),
(10770, 177885, 5, '加入中筋麵粉炒勻。'),
(10771, 177885, 6, '加入牛奶及淡忌廉，拌勻至沒有顆粒及醬汁煮至濃稠。'),
(10772, 177885, 7, '加入鹽及黑胡椒調味。'),
(10773, 177885, 8, '淋上扇貝，灑上水牛芝士碎及麵包糠。'),
(10774, 177885, 9, '放入焗爐焗4-6分鐘或至表面金黃色，即成。'),
(10775, 177829, 1, '將牛蒡去皮切片；猴頭菇及雪耳浸洗後去蒂；粟米切段；無花果及蜜棗浸洗。'),
(10776, 177829, 2, '煮滾一鍋水，加入瘦肉汆水3分鐘，撈起瀝乾備用。'),
(10777, 177829, 3, '用中火將猴頭菇、瘦肉、牛蒡、粟米、無花果、蜜棗及適量水煮15分鐘，蓋上鍋蓋煮1小時。'),
(10778, 177829, 4, '加入雪耳，煮30分鐘。'),
(10779, 177829, 5, '加少許鹽調味，即成。'),
(10780, 177828, 1, '將蒜頭切成蓉；菠菜切半；金菇洗淨去蒂及切段；瑤柱浸軟撕成絲。'),
(10781, 177828, 2, '用中火燒熱鍋，加少許油，加入1/2蒜蓉炒香，加入菠菜炒至軟身。'),
(10782, 177828, 3, '加少許鹽及1/4茶匙砂糖調味，上碟。'),
(10783, 177828, 4, '用中火燒熱同一個鍋，加少許油，加入餘下的蒜蓉炒香，加入瑤柱及金菇炒香。'),
(10784, 177828, 5, '加入蠔油、生抽、砂糖及水煮滾。'),
(10785, 177828, 6, '加入生粉水起茨，放在菠菜上即成。'),
(10786, 177827, 1, '預熱焗爐至攝氏200度，焗盤鋪上牛油紙備用。'),
(10787, 177827, 2, '將無鹽牛油置室溫軟化，加入黃糖，用電動打蛋器打發至軟身。'),
(10788, 177827, 3, '分兩次加入雞蛋打勻，加入雲尼拿香油打勻。'),
(10789, 177827, 4, '將中筋麵粉、泡打粉、肉桂粉及鹽過篩混合。'),
(10790, 177827, 5, '加進牛油混合物拌勻，加入燕麥片、紅莓乾及松子拌勻。'),
(10791, 177827, 6, '用雪糕勺將麵糊放上焗盤，輕輕壓扁，放入焗爐焗12-15分鐘至金黃色即成。'),
(10792, 177826, 1, '將木耳浸軟及切絲。'),
(10793, 177826, 2, '豬肉切絲，用生抽、紹興酒、水、生粉及麻油醃15分鐘。'),
(10794, 177826, 3, '煮滾一鍋水，加入芽菜汆水20秒，撈起瀝乾。'),
(10795, 177826, 4, '用中火燒熱鍋，加少許油，加入薑片炒香，加入豬肉炒熟。'),
(10796, 177826, 5, '轉中高火，加入木耳及芽菜快炒。'),
(10797, 177826, 6, '加入蠔油、砂糖、鹽及胡椒粉炒勻，即成。'),
(10798, 177825, 1, '將番薯去皮切件；雪耳浸洗、去蒂及撕成細塊；蓮子浸洗；薑拍扁。'),
(10799, 177825, 2, '將番薯、雪耳、蓮子、薑及適量水煮滾。'),
(10800, 177825, 3, '蓋上鍋蓋，轉中小火煮1小時。'),
(10801, 177825, 4, '加入冰糖煮至溶化，即成。'),
(10802, 177824, 1, '將新鮮淮山去皮切粒；紅棗、桂圓及杞子浸洗。'),
(10803, 177824, 2, '將水煮滾，加入紅棗及桂圓，用中小火煮10分鐘。'),
(10804, 177824, 3, '加入淮山煮10分鐘。'),
(10805, 177824, 4, '加入杞子及冰糖，煮至冰糖溶化，即成。'),
(10806, 177743, 1, '將雞柳切絲；蒜頭切成蓉。'),
(10807, 177743, 2, '雞柳用生抽、砂糖、胡椒粉、米酒、麻油及生粉醃10分鐘。'),
(10808, 177743, 3, '煮滾一鍋水，加入蜜糖豆汆水1分鐘，瀝乾備用。'),
(10809, 177743, 4, '用中火燒熱鍋，加少許油，加入蒜蓉及薑片炒香。'),
(10810, 177743, 5, '加入雞柳炒熟，加入欖菜炒香。'),
(10811, 177743, 6, '加入蜜糖豆炒勻，上碟即成。'),
(10812, 177818, 1, '預熱焗爐至攝氏200度；將白味噌、蜜糖、米醋及橄欖油拌勻，加入鹽及黑胡椒調味。'),
(10813, 177818, 2, '將番薯粒及紫洋蔥粒放上焗盤，加入橄欖油混合物拌勻。'),
(10814, 177818, 3, '放入焗爐焗20-30分鐘或至熟透。'),
(10815, 177818, 4, '將香草沙律醬的材料用攪拌機打至幼滑。'),
(10816, 177818, 5, '將番薯、紫洋蔥及火箭菜上碟。'),
(10817, 177818, 6, '灑上芝麻，淋上香草沙律醬。'),
(10818, 177818, 7, '即成'),
(10819, 177742, 1, '將荷蘭豆洗淨去筋；蒜頭切成蓉。 魷魚洗淨，去皮界十字紋，切件，加入紹興酒及薑蓉醃10分鐘。'),
(10820, 177742, 2, '將蝦醬、米酒、砂糖及水拌勻。'),
(10821, 177742, 3, '煮滾一鍋水，加入魷魚汆水30秒，撈起瀝乾備用。'),
(10822, 177742, 4, '用中火燒熱鍋，加少許油，加入蒜蓉及薑片炒香，加入荷蘭豆炒1-2分鐘。'),
(10823, 177742, 5, '加入鮮魷魚及已拌勻的蝦醬醬汁炒勻，即成。'),
(10824, 177816, 1, '預熱焗爐至攝氏180度；將竹輪卷直切，用竹籤串起。'),
(10825, 177816, 2, '在竹輪卷的坑中放滿車打芝士碎及水牛芝士碎。'),
(10826, 177816, 3, '放入焗爐焗 12分鐘至表面金黃色。'),
(10827, 177816, 4, '灑上紫菜碎。'),
(10828, 177816, 5, '即成'),
(10829, 177741, 1, '將老鼠耳浸軟，蒜頭切成蓉備用。'),
(10830, 177741, 2, '用廚房紙將帶子完全印幹，用紹興酒、鹽、胡椒粉醃10分鐘。'),
(10831, 177741, 3, '將蠔油、生抽、砂糖、麻油及水拌勻備用。'),
(10832, 177741, 4, '煮滾一鍋水，加入蜜糖豆汆水1分鐘，瀝乾備用。'),
(10833, 177741, 5, '用中火燒熱鍋，加少許油，加入帶子煎至兩面金黃色，盛起備用。'),
(10834, 177741, 6, '用中火燒熱同一個鍋，加少許油，加入蒜蓉及薑片炒香，加入蜜糖豆、老鼠耳及帶子快炒。'),
(10835, 177741, 7, '加入已拌勻的醬汁炒勻，上碟即成。'),
(10836, 177740, 1, '將四季豆切段。'),
(10837, 177740, 2, '將日本豉油、味醂、米酒、黃糖及水拌勻備用。'),
(10838, 177740, 3, '煮滾一鍋水，加入四季豆汆水2分鐘，放入冰水冷卻，瀝乾。'),
(10839, 177740, 4, '在牛肉片放上3條四季豆捲好，收口沾上少許生粉。'),
(10840, 177740, 5, '用中火燒熱鍋，加少許油，加入牛肉卷煎熟，收口朝下。'),
(10841, 177740, 6, '加入醬汁煮滾，拌勻即成。'),
(10842, 177739, 1, '將荷蘭豆洗淨去筋，蒜頭切成蓉備用。'),
(10843, 177739, 2, '將豬頸肉切片，用生抽、1茶匙砂糖、胡椒粉、麻油及生粉醃15分鐘。'),
(10844, 177739, 3, '用中火燒熱鍋，加少許油，加入蒜蓉炒香，加入豬頸肉炒至變色。'),
(10845, 177739, 4, '加入紹興酒及水煮滾，蓋上鍋蓋煮至熟透，盛起備用。'),
(10846, 177739, 5, '用同一個鍋，加少許油，加入荷蘭豆炒1分鐘，加入砂糖炒勻。'),
(10847, 177739, 6, '加入豬頸肉及XO醬炒勻，即成。'),
(10848, 177738, 1, '將硬豆腐瀝乾；四季豆切薄片；紅蘿蔔切幼粒。'),
(10849, 177738, 2, '將硬豆腐壓碎，加入四季豆、紅蘿蔔、雞蛋、中筋麵粉、砂糖、鹽及胡椒粉拌勻。'),
(10850, 177738, 3, '將豆腐混合物搓成餅狀。'),
(10851, 177738, 4, '用中火燒熱鍋，加入適量油，加入豆腐餅半煎炸至兩面金黃色，即成。'),
(10852, 177782, 1, '將蝦滑、墨魚滑、蛋白、鹽、胡椒粉、生粉、砂糖、米酒及麻油拌勻。'),
(10853, 177782, 2, '將混合物抹上春卷皮。'),
(10854, 177782, 3, '用刀抹平後，放上另一塊春卷皮。'),
(10855, 177782, 4, '用中火燒熱鍋，加入適量油，加入蝦餅，用中小火半煎炸至兩面金黃。'),
(10856, 177782, 5, '切件上碟，伴以泰式雞醬享用。'),
(10857, 177750, 1, '將牛肋條洗淨切件；紅尖椒切片；蒜頭拍扁。'),
(10858, 177750, 2, '煮滾一鍋水，加入牛肋條汆水3分鐘，撈起，用廚房紙印乾水分。'),
(10859, 177750, 3, '準備一個鍋，加入麻油及薑片，用中小火將薑片爆香。'),
(10860, 177750, 4, '轉至中火，加入蒜頭炒香，加入牛肋條及砂糖炒勻。'),
(10861, 177750, 5, '加入生抽炒勻，加入米酒，蓋上鍋蓋煮10分鐘或至收汁。'),
(10862, 177750, 6, '加入紅尖椒及羅勒拌勻，放入飯盒，即成。'),
(10863, 177781, 1, '砧板蓋上保鮮紙，放上雞胸，用刀將雞胸肉打橫切開，小心不要切斷，令成一塊厚雞胸肉變得更大更薄。'),
(10864, 177781, 2, '雞胸肉蓋上保鮮紙，用麵包棍將雞胸肉均勻壓扁，備用。'),
(10865, 177781, 3, '燒熱鍋，加入橄欖油及牛油，加入蒜蓉及乾蔥碎炒香及變軟。'),
(10866, 177781, 4, '加入菠菜快炒至變軟，盛起放涼。'),
(10867, 177781, 5, '雞胸肉加入鹽及黑胡椒調味。'),
(10868, 177781, 6, '放上白毛豬火腿、水牛芝士及菠菜。'),
(10869, 177781, 7, '將雞胸緊緊捲起。'),
(10870, 177781, 8, '尾部用牙籤固定。'),
(10871, 177781, 9, '燒熱同一個煎鍋，加少許橄欖油，將雞卷煎3-4分鐘至金黃色。'),
(10872, 177781, 10, '放入焗爐，用攝氏200度焗10-12分鐘或至熟透。'),
(10873, 177781, 11, '用同一個煎鍋， 加入白酒及雞湯，煮滾，轉小火煮5分鐘至醬汁收乾一半。'),
(10874, 177781, 12, '加入檸檬汁、鹽、黑胡椒及糖調味。'),
(10875, 177781, 13, '加入番茜碎，熄火。'),
(10876, 177781, 14, '將煮熟的雞卷放涼5分鐘，切件上碟。'),
(10877, 177781, 15, '淋上醬汁。'),
(10878, 177781, 16, '即成'),
(10879, 177749, 1, '將蒜頭切成蓉。雞扒用日本豉油、味醂、日本料理酒、黃糖、蒜蓉及胡椒粉醃30分鐘。'),
(10880, 177749, 2, '將餘下的日本豉油、味醂、黃糖及日本料理酒拌勻備用。'),
(10881, 177749, 3, '用中火燒熱鍋，加少許油，加入雞扒煎熟，雞皮朝下。'),
(10882, 177749, 4, '加入已拌勻的醬汁，煮至收汁。'),
(10883, 177749, 5, '切件，放入飯盒，灑上白芝麻，即成。'),
(10884, 177779, 1, '預熱焗爐至攝氏250度；將杏鮑菇切5-7毫米厚。'),
(10885, 177779, 2, '於表面抹上一層薄薄的橄欖油。'),
(10886, 177779, 3, '灑上鹽、黑胡椒及迷迭香碎。'),
(10887, 177779, 4, '放入焗爐焗5分鐘。'),
(10888, 177779, 5, '反轉杏鮑菇，再焗5分鐘。'),
(10889, 177779, 6, '即成'),
(10890, 177748, 1, '預熱焗爐至攝氏170度，焗盤鋪上鍚紙備用。'),
(10891, 177748, 2, '將鹽麴及白味噌拌勻。'),
(10892, 177748, 3, '將鯖魚洗淨抹乾，兩面塗上鹽麴及白味噌醃30分鐘。'),
(10893, 177748, 4, '焗盤掃上油，放上鯖魚，放入焗爐焗12-15分鐘至熟透。'),
(10894, 177748, 5, '將鯖魚及檸檬放入飯盒，即成。'),
(10895, 177747, 1, '預熱焗爐至攝氏175度，焗盤鋪上鍚紙備用。'),
(10896, 177747, 2, '將壽司飯及飯素拌勻，放入飯盒。'),
(10897, 177747, 3, '將鰻魚放上焗盤，焗10-12分鐘，切粒。'),
(10898, 177747, 4, '將雞蛋及砂糖拌勻。'),
(10899, 177747, 5, '用中火燒熱鍋，加少許油，加入蛋液煎成蛋皮後切成絲。'),
(10900, 177747, 6, '在壽司飯鋪上鰻魚、蛋絲及紫菜絲，即成。'),
(10901, 177746, 1, '用鹽搓洗秋葵，將上面的毛洗去，切去頂部。'),
(10902, 177746, 2, '將豬肉片鋪平，放上秋葵捲好。'),
(10903, 177746, 3, '將白味噌、砂糖、日本豉油、味醂及日本料理酒拌勻備用。'),
(10904, 177746, 4, '用中火燒熱鍋，加少許油，加入豬肉卷煎熟，收口朝下。'),
(10905, 177746, 5, '加入已混合的醬汁拌勻。'),
(10906, 177746, 6, '放入飯盒，灑上白芝麻，即成。'),
(10907, 177745, 1, '將雞柳及紫洋蔥切粒；草菇切半；青瓜切片；雞蛋打發備用。'),
(10908, 177745, 2, '雞柳用生抽、砂糖、麻油及米酒醃15分鐘。'),
(10909, 177745, 3, '用中火燒熱鍋，加少許油，加入紫洋蔥炒香，加入青咖哩醬及椰奶炒香。'),
(10910, 177745, 4, '加入雞肉炒熟，加入草菇炒勻。'),
(10911, 177745, 5, '加入白飯炒至鬆散，加入蛋液炒勻。'),
(10912, 177745, 6, '加入黃糖及魚露調味，加入金不換炒勻。'),
(10913, 177745, 7, '將炒飯及青瓜片放入飯盒，即成。'),
(10914, 177669, 1, '預熱焗爐至攝氏200度，焗盤鋪上鍚紙備用。'),
(10915, 177669, 2, '將薄荷葉、迷迭香及百里香切碎。'),
(10916, 177669, 3, '將羊架洗淨抹乾，用1/2迷迭香、薄荷葉、1/2百里香、鹽及黑胡椒醃30分鐘。'),
(10917, 177669, 4, '將餘下的百里香、迷迭香、麵包糠及巴馬臣芝士碎拌勻。'),
(10918, 177669, 5, '用中火燒熱鍋，加入牛油煮至溶化，加入羊架將四面煎香，放上焗盤。'),
(10919, 177669, 6, '將芥末籽醬及蜜糖拌勻，塗勻羊架。'),
(10920, 177669, 7, '羊架均勻沾上麵包糠混合物，輕輕按壓。'),
(10921, 177669, 8, '放入焗爐焗30-35分鐘，取出後靜置10分鐘，切件上碟即成。'),
(10922, 177751, 1, '預熱焗爐至攝氏220度；將橄欖油、白酒及番紅花絲拌勻。'),
(10923, 177751, 2, '焗盤鋪上鍚紙，放上紅衫魚，加入醃料。'),
(10924, 177751, 3, '灑上薄荷葉碎。'),
(10925, 177751, 4, '加入鹽及黑胡椒調味，醃1小時。'),
(10926, 177751, 5, '放入焗爐焗12-14分鐘，焗至半熟時，用匙羹將醬汁淋在紅衫魚上。'),
(10927, 177751, 6, '將新薯洗淨，放入已加入鹽水的鍋裡，煮8-10分鐘，上碟，用匙羹稍微壓至裂開，淋上焗魚醬汁。'),
(10928, 177751, 7, '放上紅衫魚。'),
(10929, 177751, 8, '即成'),
(10930, 177668, 1, '將火雞胸肉烚熟及撕成絲；布利芝士切片；番茜切碎。'),
(10931, 177668, 2, '將墨西哥薄餅塗上紅莓果醬，依次在一半薄餅放上煙火腿、火雞胸肉、番茜、黑胡椒及布利芝士，對摺成半圓。'),
(10932, 177668, 3, '用中火燒熱鍋，加入墨西哥薄餅，將兩面煎至金黃色及芝士溶化。'),
(10933, 177668, 4, '上碟切半，即成。'),
(10934, 177727, 1, '將牛奶用小火加熱。'),
(10935, 177727, 2, '加入棉花糖，煮至完全溶化。'),
(10936, 177727, 3, '將奶漿過篩倒入杯中，去掉泡沫。'),
(10937, 177727, 4, '放入雪櫃冷藏3小時。'),
(10938, 177727, 5, '灑上士多啤梨香蕉乾及薄荷葉。'),
(10939, 177727, 6, '即成'),
(10940, 177667, 1, '預熱焗爐至攝氏180度；焗盤鋪上鍚紙；將牛油置室溫軟化；迷迭香切碎及蒜頭切成蓉。'),
(10941, 177667, 2, '將片裝水牛芝士切半。'),
(10942, 177667, 3, '將牛油、迷迭香碎及蒜蓉拌勻。'),
(10943, 177667, 4, '將法包分割成2cm厚的等分，不能切穿底部。'),
(10944, 177667, 5, '用中火燒熱鍋，加入煙肉煎熟，盛起。'),
(10945, 177667, 6, '每片法包之間塗上牛油，依次釀入芝士及煙肉。'),
(10946, 177667, 7, '法包表面塗上香草牛油。'),
(10947, 177667, 8, '放入焗爐焗15分鐘或至芝士溶化，即成。'),
(10948, 177666, 1, '將蘑菇切片；洋蔥切絲；蒜頭切碎。'),
(10949, 177666, 2, '雞扒用鹽、黑胡椒、百里香及乾龍蒿碎醃15分鐘。'),
(10950, 177666, 3, '用中火燒熱鍋，加少許油，加入雞扒煎至熟透，上碟。'),
(10951, 177666, 4, '用同一個鍋，加入牛油，用中火煮至溶化，加入蒜蓉、洋蔥及蘑菇，用中高火炒香。'),
(10952, 177666, 5, '加入中筋麵粉炒勻，加入雞湯攪拌至沒有顆粒。'),
(10953, 177666, 6, '煮滾，轉小火煮5分鐘至醬汁濃稠。'),
(10954, 177666, 7, '加入淡忌廉及黑胡椒調味，淋上雞扒即成。'),
(10955, 177665, 1, '將露筍切段，龍脷柳切成薄片備用。'),
(10956, 177665, 2, '龍脷柳用鹽及黑胡椒醃10分鐘。'),
(10957, 177665, 3, '煮滾一鍋水，加少許鹽，加入露筍汆水2分鐘，撈起瀝乾。'),
(10958, 177665, 4, '將露筍放上魚片捲好，收口沾上生粉固定。'),
(10959, 177665, 5, '用中火燒熱鍋，加少許油，加入龍脷柳卷，收口向下，煎至熟透，上碟即成。'),
(10960, 177664, 1, '預熱焗爐至攝氏200度，焗爐鋪上鍚紙。'),
(10961, 177664, 2, '將新薯切半。'),
(10962, 177664, 3, '將新薯、橄欖油、海鹽及黑胡椒拌勻。'),
(10963, 177664, 4, '放上焗盤，放入焗爐焗35-40分鐘或至軟身，放涼。'),
(10964, 177664, 5, '挖空薯仔，將挖出的薯仔壓成蓉。'),
(10965, 177664, 6, '加入蛋黃醬及法式芥末拌勻。'),
(10966, 177664, 7, '放入唧袋，唧入挖空的薯仔，灑上紅椒粉，即成。'),
(10967, 177604, 1, '將排骨洗淨瀝乾切件；金針及雲耳浸至軟身；蔥切粒備用。'),
(10968, 177604, 2, '排骨用頭抽、砂糖、米酒、生粉、油、麻油及水醃15分鐘。'),
(10969, 177604, 3, '加入雲耳及金針拌勻，鋪上大碟。'),
(10970, 177604, 4, '用中高火隔水蒸15-20分鐘或至熟透，灑上蔥粒，即成。'),
(10971, 177680, 1, '預熱焗爐至攝氏200度；南瓜去皮去籽切粒，放上焗盤。'),
(10972, 177680, 2, '加入鹽、黑胡椒、1湯匙橄欖油及少許百里香，拌勻至均勻沾上南瓜。'),
(10973, 177680, 3, '放入焗爐焗25-30分鐘或至軟身，放涼備用。'),
(10974, 177680, 4, '用攪拌機將3/4南瓜及忌廉打成蓉，加入鹽及黑胡椒調味。'),
(10975, 177680, 5, '煮滾一鍋水，加少許鹽，加入意粉，按包裝指示煮至軟硬適中。'),
(10976, 177680, 6, '用中火燒熱鍋，加少許橄欖油，加入煙肉煮2-3分鐘。'),
(10977, 177680, 7, '加入洋蔥及蒜蓉煮5分鐘或至軟身。'),
(10978, 177680, 8, '加入南瓜蓉及蔬菜高湯，轉小火煮至濃稠，熄火。'),
(10979, 177680, 9, '準備一個小碗，加入2大湯匙南瓜醬及蛋黃拌勻至幼滑，倒回原來的南瓜醬，加入巴馬臣芝士碎及嫩菠菜拌勻至所有芝士溶化。'),
(10980, 177680, 10, '加入意粉拌勻至均勻沾上醬汁。如果醬汁太濃稠，加入少許意粉水稀釋。'),
(10981, 177680, 11, '上碟，加入餘下的南瓜粒及額外份量的巴馬臣芝士碎。'),
(10982, 177680, 12, '即成'),
(10983, 177603, 1, '將瑤柱浸軟及撕成絲；蝦乾及粉絲浸軟；絲瓜去皮切件；蔥切粒備用。'),
(10984, 177603, 2, '用中火燒熱鍋，加少許油，預留適量蒜蓉，其餘用小火炒香。'),
(10985, 177603, 3, '加入瑤柱及蝦乾炒香，加少許鹽調味。'),
(10986, 177603, 4, '粉絲加入麻油及生抽拌勻，鋪上碟。鋪上絲瓜、炒香蒜蓉、瑤柱、蝦乾及生蒜蓉。'),
(10987, 177603, 5, '用中高火隔水蒸8-10分鐘。灑上蔥粒，即成。'),
(10988, 177659, 1, '準備一個杯，篩入抹茶粉，加入熱水攪拌。'),
(10989, 177659, 2, '將牛奶及砂糖用小火加熱。'),
(10990, 177659, 3, '用打蛋器打發3-5分鐘，直至打成奶泡。'),
(10991, 177659, 4, '加入牛奶及奶泡於杯中。'),
(10992, 177659, 5, '灑上額外份量的抹茶粉。'),
(10993, 177659, 6, '即成'),
(10994, 177602, 1, '將豬肉切半；豆腐切塊；雞蛋打發；苦瓜去籽後切件，用少許鹽醃10分鐘備用。'),
(10995, 177602, 2, '煮滾一鍋水，加入苦瓜汆水1分鐘，撈起瀝乾備用。'),
(10996, 177602, 3, '用中火燒熱鍋，加少許油，加入豬肉炒至8成熟。'),
(10997, 177602, 4, '加入苦瓜、清酒、味醂及日本豉油炒2分鐘。'),
(10998, 177602, 5, '加入豆腐煮2分鐘。'),
(10999, 177602, 6, '加入蛋液煮至半凝固，炒勻後上碟。'),
(11000, 177602, 7, '灑上木魚碎，即成。'),
(11001, 177601, 1, '將檸檬洗淨後切片備用。'),
(11002, 177601, 2, '將生熟薏米洗淨後浸1小時，瀝乾備用。'),
(11003, 177601, 3, '將生熟薏米及水煮滾。'),
(11004, 177601, 4, '蓋上鍋蓋，轉中小火煮1小時。'),
(11005, 177601, 5, '加入冰糖煮至溶化。'),
(11006, 177601, 6, '熄火，加入檸檬片浸10分鐘，即成。'),
(11007, 177600, 1, '將綠豆、生薏米及百合洗淨，浸1小時，瀝乾備用。'),
(11008, 177600, 2, '將果皮浸軟及刮囊。'),
(11009, 177600, 3, '將綠豆、生薏米、百合、果皮及適量水煮滾。蓋上鍋蓋，轉中小火煮1小時。'),
(11010, 177600, 4, '加入片糖煮至溶化，拌勻後熄火焗1小時即成。'),
(11011, 177599, 1, '將苦瓜去蒂去籽切件；排骨洗淨抹乾；鹹菜洗淨切件；眉豆浸洗備用。'),
(11012, 177599, 2, '準備一鍋水，加入排骨煮滾後汆水3-5分鐘。'),
(11013, 177599, 3, '將排骨、眉豆、薑片及適量水用中火煮滾。'),
(11014, 177599, 4, '加入苦瓜及鹹菜，轉中小火煮1小時，即成。'),
(11015, 177512, 1, '將熟三文魚切碎。'),
(11016, 177512, 2, '將壽司飯、熟三文魚碎、飯素及白芝麻拌勻。'),
(11017, 177512, 3, '用手捏成三角形飯糰。'),
(11018, 177512, 4, '將白味噌、味醂及日本豉油拌勻。'),
(11019, 177512, 5, '用中火燒熱鍋，用廚房紙抹上一層油，放入飯糰，煎至兩面稍微上色。'),
(11020, 177512, 6, '將一面掃上醬油，煎至金黃色；翻轉另一面，重覆同樣步驟，即成。'),
(11021, 177583, 1, '將薯仔及甘筍去皮切片；洋蔥及椰菜切件；本菇洗淨去蒂；豆腐切片；蔥切粒備用。'),
(11022, 177583, 2, '煮滾一鍋水，加入鰹魚昆布粉拌勻煮5分鐘。'),
(11023, 177583, 3, '加入薯仔、洋蔥及紅蘿蔔，蓋上鍋蓋用中火煮15分鐘。'),
(11024, 177583, 4, '加入椰菜、本菇、豆腐、三文魚、白味噌及味醂煮滾。'),
(11025, 177583, 5, '加入無糖豆漿煮熱。'),
(11026, 177583, 6, '灑上蔥粒，即成。'),
(11027, 177595, 1, '將蔬菜洗淨，粟米粒用刀切出放入碗內。粟米芯放入湯鍋裡，加入清雞湯(或蔬菜高湯)及水。'),
(11028, 177595, 2, '蓋上鍋蓋，用中高火煮最少10分鐘。'),
(11029, 177595, 3, '將粟米芯取出，粟米清雞湯盛起備用。'),
(11030, 177595, 4, '同一個湯鍋，用中火燒熱少許橄欖油。加入煙肉煮2-3分鐘至金黃色。'),
(11031, 177595, 5, '加入洋蔥及紅蘿蔔，煮3-5分鐘直至洋蔥變軟身。加入薯仔及蒜頭炒2分鐘。'),
(11032, 177595, 6, '加入中筋麵粉及月桂葉拌勻。'),
(11033, 177595, 7, '加入粟米清雞湯，轉中小火，蓋上鍋蓋煮15分鐘。'),
(11034, 177595, 8, '加入粟米粒，轉中火煮約5分鐘。'),
(11035, 177595, 9, '加入牛奶、忌廉、鹽及黑胡椒，拌勻。'),
(11036, 177595, 10, '放上番茜即可食用。'),
(11037, 177511, 1, '將法國麵包切去頂部及挖空；薯仔去皮切粒；蘑菇切片；煙肉及洋蔥切粒；迷迭香及蒜頭切碎。'),
(11038, 177511, 2, '預熱焗爐至攝氏200度，焗盤鋪上鍚紙備用。'),
(11039, 177511, 3, '用中火燒熱鍋，加入煙肉炒香，加入蒜頭及洋蔥炒香。'),
(11040, 177511, 4, '加入薯仔及蘑菇炒3-4分鐘。'),
(11041, 177511, 5, '加入鹽、黑胡椒、肉豆蔻粉、迷迭香、牛奶及淡忌廉煮滾。'),
(11042, 177511, 6, '轉中小火，蓋上鍋蓋，煮10-12分鐘。'),
(11043, 177511, 7, '打開鍋蓋，拌勻及煮至濃稠。'),
(11044, 177511, 8, '釀入法國麵包，灑上水牛芝士碎，放入焗爐焗 8分鐘或至表面金黃色，即成。'),
(11045, 177582, 1, '將希臘乳酪平舖在金屬盤上。'),
(11046, 177582, 2, '灑上粟米片、堅果碎及士多啤梨乾。'),
(11047, 177582, 3, '放入雪櫃冷凍2小時，即成。'),
(11048, 177510, 1, '將英式鬆餅切半及烤至稍脆；牛油果去核切片。'),
(11049, 177510, 2, '準備荷蘭醬：用微波爐煮溶牛油，用勺盛去表面泡沫及白色的凝固物，使牛油變為澄清牛油。'),
(11050, 177510, 3, '將蛋黃及檸檬汁打勻，隔水加熱及不停攪拌，分次加入澄清牛油，每次與蛋黃完全混合才可再加入牛油，直至醬汁幼滑。'),
(11051, 177510, 4, '加鹽及甜椒粉調味。'),
(11052, 177510, 5, '準備一個篩，加入雞蛋，稍微隔走多餘蛋白。'),
(11053, 177510, 6, '將水煮滾，加入白醋，轉中小火，用湯匙將水劃圈成漩渦狀，慢慢加入雞蛋，煮3分鐘或至凝固即可。'),
(11054, 177510, 7, '在英式鬆餅上放上煙三文魚、牛油果及水波蛋，淋上荷蘭醬，即成。'),
(11055, 177509, 1, '將無鹽牛油隔熱水座溶；香蕉切片。'),
(11056, 177509, 2, '將雞蛋、牛奶、砂糖、鹽及雲呢拿香油拌勻。'),
(11057, 177509, 3, '將低筋麵粉及泡打粉過篩及拌勻，加入雞蛋混合物及無鹽牛油拌勻，靜置至少20分鐘。'),
(11058, 177509, 4, '用中火燒熱鍋，用廚房紙抹上一層油。'),
(11059, 177509, 5, '加入一勺粉漿，轉至中小火，煎至麵糊冒泡，翻轉另一面再煎1分鐘。重覆此步驟直至用完粉漿。'),
(11060, 177509, 6, '在鬆餅塗上榛子醬，放上香蕉片，再鋪上另一塊鬆餅。重覆此步驟5次。'),
(11061, 177509, 7, '放上香蕉片，淋上楓糖，即成。'),
(11062, 177508, 1, '將洋蔥切片；乾蔥及蒜頭切碎。'),
(11063, 177508, 2, '牛肉加入生抽及砂糖醃15分鐘，逐少加入水拌勻，加入生粉拌勻，加入油拌勻。'),
(11064, 177508, 3, '煮滾一鍋水，加少許鹽，加入通粉煮至軟硬適中，瀝乾備用。'),
(11065, 177508, 4, '將忌廉雞湯及1000毫升水煮滾，轉中小火保溫。'),
(11066, 177508, 5, '用中火燒熱鍋，加少許油，加入牛肉，用中高火炒至8成熟備用。'),
(11067, 177508, 6, '用中火燒熱另一個鍋，加少許油，加入蒜蓉、乾蔥及洋蔥炒香。'),
(11068, 177508, 7, '加入花生沙嗲醬炒香，加入生抽、砂糖、麻油及水煮滾。'),
(11069, 177508, 8, '加入牛肉拌勻，煮至醬汁濃稠，熄火。'),
(11070, 177508, 9, '將通粉加入雞湯煮滾，上碟。'),
(11071, 177508, 10, '放上牛肉，即成。'),
(11072, 177507, 1, '將煙肉煎熟；蔥切粒；片裝芝士切半備用。'),
(11073, 177507, 2, '將中筋麵粉及薯粉過篩，開一個小洞，慢慢加入暖水拌勻至沒有顆粒。'),
(11074, 177507, 3, '加入蔥粒及鹽拌勻，靜置10-15分鐘。'),
(11075, 177507, 4, '用中火燒熱鍋，用廚房紙抹上一層油，加入適量粉漿，用中小火煎至半熟，盛起。'),
(11076, 177507, 5, '將雞蛋略為打散，用同一個鍋，加入雞蛋煎至半熟，加入一張餅皮煎至餅皮熟透。'),
(11077, 177507, 6, '翻轉另一面，放上煙肉、肉鬆及芝士。'),
(11078, 177507, 7, '熄火，捲成條狀，切件即成。'),
(11079, 177428, 1, '用綿繩將五花肉綁好；蔥切段。'),
(11080, 177428, 2, '煮滾一鍋水，加入4片薑及五花肉， 汆水5分鐘，撈起瀝乾。'),
(11081, 177428, 3, '用中火燒熱鍋，加少許油，加入五花肉煎香，取出備用。'),
(11082, 177428, 4, '用中火燒熱另一個鍋，加入冰糖，用中小火煮溶。'),
(11083, 177428, 5, '加入五花肉、蔥段、紹興酒、餘下的薑片、頭抽、烏龍茶包及清水，用中火煮滾。'),
(11084, 177428, 6, '蓋上鍋蓋，轉中小火煮1小時。'),
(11085, 177428, 7, '打開鍋蓋，將五花肉翻轉另一面，蓋上鍋蓋再煮1小時，上碟即成。'),
(11086, 177494, 1, '預熱焗爐至攝氏200度；準備2個焗盤，鋪上錫紙，一個焗盤放上三文魚柳，另一個放上車厘茄及蘆筍，淋上橄欖油，加入鹽及黑胡椒調味。'),
(11087, 177494, 2, '放入焗爐焗8-10分鐘或直至三文魚熟透，備用。'),
(11088, 177494, 3, '準備一個鍋，加入藜麥及水或清雞湯，加入鹽調味。'),
(11089, 177494, 4, '蓋上鍋蓋，用中火煮12-15分鐘，直至水份被完全吸收及藜麥軟身。'),
(11090, 177494, 5, '熄火，用叉子盛起藜麥，倒入碗裡待涼。'),
(11091, 177494, 6, '將所有沙律醬材料拌勻，備用。'),
(11092, 177494, 7, '將蘆筍切件，加入藜麥拌勻，上碟。'),
(11093, 177494, 8, '放上火箭葉、三文魚及車厘茄。'),
(11094, 177494, 9, '淋上沙律醬。'),
(11095, 177494, 10, '即成'),
(11096, 177427, 1, '將玄米茶加入熱水泡成茶備用。'),
(11097, 177427, 2, '將雞蛋打發。用中火燒熱鍋，加少許油，加入蛋液煎成蛋皮，切絲備用。'),
(11098, 177427, 3, '在白飯上灑上飯素及紫菜碎，放上蛋絲及梅子。'),
(11099, 177427, 4, '將熱茶加入白飯至3/4滿，即成。'),
(11100, 177486, 1, '預熱焗爐至攝氏200度。'),
(11101, 177486, 2, '將蒜頭磨碎，加入牛油拌勻。'),
(11102, 177486, 3, '麵包塗上蒜蓉牛油，蓋上錫紙，放入焗爐焗7分鐘。'),
(11103, 177486, 4, '灑上水牛芝士碎。'),
(11104, 177486, 5, '放入焗爐再焗10分鐘，即成。'),
(11105, 177426, 1, '將清水、老抽、生抽、冰糖、八角、花椒及甘草用中火煮滾，轉中小火煮10分鐘。 加入豆腐乾煮20分鐘。'),
(11106, 177426, 2, '加入烏龍茶茶包煮10分鐘。'),
(11107, 177426, 3, '熄火，取去茶包，浸豆腐乾1-1.5小時或至入味。'),
(11108, 177426, 4, '即成。'),
(11109, 177425, 1, '將石斑切塊；翠玉瓜及甘筍切片。'),
(11110, 177425, 2, '香片茶葉加入熱水泡1分鐘，將茶及茶葉隔開。'),
(11111, 177425, 3, '石斑塊用鹽、生粉及蛋白醃5分鐘。'),
(11112, 177425, 4, '用中火燒熱鍋，加入適量油，油滾時加入茶葉，用中小火炸至脆身，盛起茶葉，保留油。'),
(11113, 177425, 5, '用中火另一個鍋，加少許油，加入石斑塊用中小火煎至8成熟，盛起備用。'),
(11114, 177425, 6, '將80毫升香片茶、適量鹽及生粉拌勻。'),
(11115, 177425, 7, '用中高火燒熱鍋，加入適量炸過茶葉的油，加入翠玉瓜及甘筍炒軟，加少許砂糖調味。'),
(11116, 177425, 8, '加入石斑塊、香片茶及茶葉炒勻，上碟即成。'),
(11117, 177424, 1, '將乳鴿洗淨瀝乾，蔥切段。'),
(11118, 177424, 2, '煮滾一鍋水，加入乳鴿汆水1分鐘，撈起瀝乾。'),
(11119, 177424, 3, '將清水、生抽、老抽、冰糖、八角、桂皮、花椒及紹興酒煮滾。'),
(11120, 177424, 4, '加入乳鴿，用大火煮滾，轉中小火煮20分鐘。'),
(11121, 177424, 5, '在鑊面鋪上鍚紙，放上玫瑰花、普洱茶葉、黃糖及白米。'),
(11122, 177424, 6, '放上蒸架，放上蔥段及乳鴿，蓋上鍋蓋，用中火煙燻3分鐘。'),
(11123, 177424, 7, '熄火，焗5分鐘，將乳鴿切件即成。'),
(11124, 177423, 1, '將洋蔥切件；蔥切段備用。'),
(11125, 177423, 2, '煮滾一鍋水，加入一半薑片及蔥段、米酒、白醋及豬手，豬手汆水3分鐘，撈起放入冰水冷卻備用。'),
(11126, 177423, 3, '用中火燒熱鍋，加少許油，加入餘下的薑片及洋蔥炒香。'),
(11127, 177423, 4, '加入豬手炒3分鐘。加入八角、桂皮及冰糖炒3分鐘。'),
(11128, 177423, 5, '加入餘下的蔥段、花椒、生抽、紅茶茶包及清水煮滾，蓋上鍋蓋，轉中小火煮1小時。'),
(11129, 177423, 6, '取出茶包，再煮20分鐘，即成。'),
(11130, 177415, 1, '將芝麻醬所有材料用叉或打蛋器混合。如果芝麻醬太杰身，加些少水調稀，切勿一次過加太多水。試味，備用。'),
(11131, 177415, 2, '根據蕎麥麵包裝上的指示將蕎麥麵煮熟。'),
(11132, 177415, 3, '瀝乾，加點油拌勻，備用。'),
(11133, 177415, 4, '雞肉加入鹽和胡椒粉作調味。'),
(11134, 177415, 5, '用焗爐焗至雞肉熟透。'),
(11135, 177415, 6, '將雞肉切件。'),
(11136, 177415, 7, '將蕎麥麵、芫茜、切條紅蘿蔔及青瓜拌勻。'),
(11137, 177415, 8, '放上雞肉。'),
(11138, 177415, 9, '根據個人喜好加入芝麻醬，灑上芝麻作裝飾，暖食和凍食皆可。'),
(11139, 177415, 10, '小貼士：家裡沒有烤箱的話，可在煎鑊加點油，用中火燒熱，加入雞肉炒至金黃色。'),
(11140, 177439, 1, '預熱焗爐至攝氏200度，焗盤鋪上鍚紙及放上烤架備用。'),
(11141, 177439, 2, '將銀鱈魚洗淨抹乾，放入密實袋內。'),
(11142, 177439, 3, '將西京味噌、清酒、味醂、砂糖及薑蓉拌勻，倒入密實袋，令整塊銀鱈魚沾滿醃料。'),
(11143, 177439, 4, '放入雪櫃醃至少2日。'),
(11144, 177439, 5, '抹去銀鱈魚表面的醃料，放上烤架，放入焗爐焗10-12分鐘或至表面金黃色，即成。'),
(11145, 177377, 1, '將薯仔及甘筍去皮切粒；西芹及洋蔥切粒；椰菜及蒜頭切碎。用中火燒熱鍋，加少許油，加入蒜頭及洋蔥炒香，加入甘筍、西芹及薯仔炒4分鐘。'),
(11146, 177377, 2, '加入罐頭去皮番茄、蔬菜高湯、月桂葉及乾羅勒碎拌勻及煮滾，蓋上鍋蓋，轉中小火煮20分鐘。'),
(11147, 177377, 3, '加入粟米粒及椰菜煮10分鐘。'),
(11148, 177377, 4, '加少許鹽及黑胡椒調味，即成。'),
(11149, 177376, 1, '預熱焗爐至攝氏180度；將蘑菇切片；紅燈籠椒、意大利青瓜及紫洋蔥切碎。將雞蛋打發，加入淡忌廉、牛奶、意大利香草、黑胡椒及鹽拌勻。'),
(11150, 177376, 2, '用中火燒熱鍋，加少許油，加入意大利青瓜、紫洋蔥、蘑菇、紅燈籠椒及嫩菠菜炒香，加少許鹽及黑胡椒調味。'),
(11151, 177376, 3, '放入焗盤，灑上車打芝士，倒入蛋液，放入焗爐焗20-25分鐘即成。'),
(11152, 177412, 1, '預熱焗爐至180度，在鬆餅模上掃一層油。'),
(11153, 177412, 2, '用空罐將薄餅切成小塊圓圈，在鬆餅模上。'),
(11154, 177412, 3, '薄餅塗上薄餅醬。'),
(11155, 177412, 4, '灑上馬蘇里拉芝士碎及帕馬森芝士碎。'),
(11156, 177412, 5, '將意大利辣肉腸切小塊，放上薄餅。'),
(11157, 177412, 6, '放入焗爐焗10分鐘。'),
(11158, 177412, 7, '灑上適量百里香。'),
(11159, 177412, 8, '即成'),
(11160, 177375, 1, '將芋頭去皮切粒。煮滾一鍋水，加入西米煮5分鐘，期間不停攪拌。'),
(11161, 177375, 2, '熄火，蓋上鍋蓋焗5分鐘至熟透，過冷水備用。'),
(11162, 177375, 3, '將清水煮滾，加入芋頭，用中火煮20-25分鐘或至軟身。'),
(11163, 177375, 4, '加入冰糖煮至溶化。'),
(11164, 177375, 5, '加入西米略煮，享用時加入花奶，即成。'),
(11165, 177374, 1, '將椰菜、雪菜及豆腐乾切碎；乾冬菇、黑木耳及粉絲浸軟切碎；甘筍去皮切碎。用中火燒熱鍋，加少許油，加入冬菇炒香。'),
(11166, 177374, 2, '加入椰菜、雪菜、黑木耳、甘筍及豆腐乾炒至軟身。'),
(11167, 177374, 3, '加入粉絲炒勻，加入生抽、麻油、鹽及胡椒粉炒勻，放涼備用。'),
(11168, 177374, 4, '將餡料放在餃子皮中間，沾濕餃子皮的邊緣，對摺打褶；重複包餃子步驟。'),
(11169, 177374, 5, '將碟子掃上油，放上餃子，隔水用中火蒸8-10分鐘，即成。'),
(11170, 177373, 1, '預熱焗爐至攝氏180度；焗盤鋪上鍚紙備用。將薯仔去皮切件；煮滾一鍋水，加少許鹽，加入薯仔煮至軟腍，瀝乾。'),
(11171, 177373, 2, '將薯仔及牛油用手提攪拌器打至軟滑。'),
(11172, 177373, 3, '加入牛奶拌勻，加入鹽、黑胡椒及白松露醬拌勻。'),
(11173, 177373, 4, '將薯蓉釀入大啡菇，灑上水牛芝士碎。'),
(11174, 177373, 5, '放入焗爐焗10分鐘或至表面金黃色，即成。'),
(11175, 177372, 1, '將紫椰菜、溫室青瓜及甘筍切絲；車厘茄切半備用。'),
(11176, 177372, 2, '將雞蛋打發；用中火燒熱鍋，加少許油，加入蛋液煎熟，切絲備用。'),
(11177, 177372, 3, '煮滾一鍋水，加入蒟蒻絲煮1分鐘，撈起放入冰水降溫，瀝乾上碟。'),
(11178, 177372, 4, '將芝麻沙律醬及柚子醋混合。'),
(11179, 177372, 5, '將溫室青瓜、甘筍、蛋絲、紫椰菜及車厘茄鋪上蒟蒻絲，淋上柚子芝麻沙律醬，即成。'),
(11180, 177312, 1, '鹽漬櫻花用暖水浸軟，沖走鹽分備用。'),
(11181, 177312, 2, '將透明寒天粉及砂糖拌勻。'),
(11182, 177312, 3, '加入滾水拌勻，稍稍放涼。'),
(11183, 177312, 4, '倒入模具，放入櫻花。'),
(11184, 177312, 5, '放入雪櫃冷藏30分鐘或至凝固，脫模，伴以黑糖蜜及黃豆粉享用。'),
(11185, 177386, 1, '將牛扒醃料在大碟裡全部混合，然後放上牛扒，醃1-4個鐘。'),
(11186, 177386, 2, '將所有香草、蒜頭和紅蔥頭切碎，加入檸檬汁、檸檬皮、白酒醋和橄欖油拌勻，然後用鹽、糖砂和黑胡椒調味，備用。'),
(11187, 177386, 3, '將牛扒取出，用廚房紙印乾。大火燒熱煎鍋，加少許油落煎鍋，放入牛扒大火煎1分鐘後，調低至中火繼續煎2分鐘。'),
(11188, 177386, 4, '反轉煎多2分鐘。'),
(11189, 177386, 5, '將牛扒取出，休息5分鐘後切薄片，上碟後淋上醬汁，即成。'),
(11190, 177386, 6, '可配烤薯仔和其他蔬菜。'),
(11191, 177311, 1, '預熱焗爐至攝氏200度；焗盤鋪上鍚紙備用。'),
(11192, 177311, 2, '將金沙骨洗淨抹乾，用生抽、老抽、麻油、紹興酒、砂糖及生粉醃至少2小時。'),
(11193, 177311, 3, '放上焗盤，放入焗爐焗30分鐘。'),
(11194, 177311, 4, '塗上糖桂花，再焗5分鐘，即成。'),
(11195, 177294, 1, '將奶粉及抹茶粉拌勻。'),
(11196, 177294, 2, '加入煉奶拌勻，用匙羹輕壓至固體狀。'),
(11197, 177294, 3, '放在牛油紙上，搓成條狀切粒。'),
(11198, 177294, 4, '置室温10-15分鐘至稍微硬身，即成。'),
(11199, 177294, 5, '小貼士：奶粉可於烘焙店購買；或可於超市購買咖啡伴侶代替。'),
(11200, 177310, 1, '將已沖洗的乾玫瑰花及熱水用中小火煮8分鐘，熄火焗3分鐘。'),
(11201, 177310, 2, '撈起玫瑰花，加入魚膠粉及砂糖，拌勻至溶化。'),
(11202, 177310, 3, '倒入模具，放入雪櫃冷藏1小時至凝固，即成。'),
(11203, 177309, 1, '將腐竹浸軟；雞蛋烚熟去殼備用。'),
(11204, 177309, 2, '將鮮百合洗淨拆散，浸在水中以防變黑。'),
(11205, 177309, 3, '煮滾一鍋水，加入腐竹，蓋上鍋蓋，用中火煮30分鐘或至溶化。'),
(11206, 177309, 4, '加入鮮百合、冰糖及雞蛋煮3分鐘，即成。'),
(11207, 177308, 1, '甜酒釀放在室溫回溫；煮滾一鍋水，加入小丸子煮至浮起，撈起放入冷水備用。'),
(11208, 177308, 2, '煮滾另一鍋水，加入冰糖煮至溶化。'),
(11209, 177308, 3, '準備三個碗，分別加入小丸子、2湯匙甜酒釀、1湯匙桂花及糖水，即成。'),
(11210, 177307, 1, '將鮮百合洗淨拆散，浸在水中以防變黑。'),
(11211, 177307, 2, '將雪梨去核切件。'),
(11212, 177307, 3, '將雪梨、百合、川貝母粉、冰糖及適量清水放入燉盅。'),
(11213, 177307, 4, '蓋上盅蓋，用中火燉2小時，即成。'),
(11214, 177228, 1, '煮滾一鍋水，加入鵪鶉蛋烚熟，去殼備用。'),
(11215, 177228, 2, '將免治豬肉、蝦膠、生抽、鹽、砂糖、胡椒粉、薑汁、紹興酒、蛋白、生粉及麻油，順同一方向拌勻至起膠，放入雪櫃冷藏20分鐘。'),
(11216, 177228, 3, '將鵪鶉蛋放上燒賣皮中心，包入適量餡料，捏成燒賣。'),
(11217, 177228, 4, '在碟上掃一層油，放上燒賣，開口向下，用中高火隔水蒸15-20分鐘，即成。'),
(11218, 177322, 1, '將蘆筍去皮切段；蝦仁用紹興酒、生粉、鹽及胡椒粉醃10分鐘。'),
(11219, 177322, 2, '將鮮百合洗淨拆散，浸在水中以防變黑。'),
(11220, 177322, 3, '煮滾一鍋水，加入蘆筍汆水30秒，撈起瀝乾。'),
(11221, 177322, 4, '用中火燒熱鍋，加少許油，加入蒜蓉及薑片炒香。'),
(11222, 177322, 5, '加入蝦仁炒至半熟，加入鮮百合及蘆筍炒勻。'),
(11223, 177322, 6, '加入紹興酒炒勻，加少許鹽調味，即成。'),
(11224, 177227, 1, '將花生碎、白芝麻、砂糖及椰絲拌勻備用。'),
(11225, 177227, 2, '將糯米粉逐少加入暖水拌勻，搓成粉團至不黏手，平均分成等分，搓成粒狀。'),
(11226, 177227, 3, '將清水煮滾，加入片糖及薑片，用中火煮滾，轉至中小火，煮至濃稠。'),
(11227, 177227, 4, '煮滾一鍋水，加入丸子，不停攪拌，煮至浮起水面，撈起放入糖水。'),
(11228, 177227, 5, '用中小火煮8分鐘，上碟。'),
(11229, 177227, 6, '灑上花生碎混合物，即成。'),
(11230, 177291, 1, '將雞蛋打發。'),
(11231, 177291, 2, '加入砂糖及牛奶拌勻。'),
(11232, 177291, 3, '將蛋漿過篩倒入碗中。'),
(11233, 177291, 4, '用微波爐保鮮紙包好。'),
(11234, 177291, 5, '用中火隔水蒸10分鐘或至蛋漿凝固。'),
(11235, 177291, 6, '灑上額外份量的砂糖。'),
(11236, 177291, 7, '用火槍燒成焦糖，即成。'),
(11237, 177291, 8, '小貼士：家裡沒有火槍的話，可以用燒熱了的鐵匙羹熨焦砂糖，也可以做出焦糖效果。'),
(11238, 177226, 1, '將雞蛋打發；大菜絲剪碎浸軟，撈起瀝乾備用。'),
(11239, 177226, 2, '將清水煮滾，加入大菜絲煮溶。'),
(11240, 177226, 3, '加入冰糖煮溶。'),
(11241, 177226, 4, '熄火，加入蛋液拌勻成蛋花。'),
(11242, 177226, 5, '倒入模具，放涼後放入雪櫃冷藏1小時或至凝固即成。'),
(11243, 177225, 1, '將水魷洗淨；煮滾一鍋水，加入水魷汆水1分鐘，撈起瀝乾切件。'),
(11244, 177225, 2, '加入生粉拌勻備用。'),
(11245, 177225, 3, '將咖哩醬、海鮮醬、蠔油、砂糖及鹽拌勻。'),
(11246, 177225, 4, '加入水魷拌勻，放在碟上。'),
(11247, 177225, 5, '用中高火隔水蒸5分鐘，即成。'),
(11248, 177224, 1, '預熱焗爐至攝氏180度；焗盤鋪上鍚紙；雞蛋打發；白麵包對角切成4個三角形備用。'),
(11249, 177224, 2, '蝦膠加入胡椒粉、砂糖、鹽、生粉、蛋白及麻油，順同一個方向拌勻。'),
(11250, 177224, 3, '均勻塗上麵包，放上焗盤。'),
(11251, 177224, 4, '掃上蛋液，灑上白芝麻。'),
(11252, 177224, 5, '放入焗爐焗12-15分鐘或至金黃色即成。'),
(11253, 177223, 1, '將雞胸肉恰熟撕成絲；乾冬菇浸軟切片；木耳浸軟切絲；雞蛋打發；蔥切粒備用。'),
(11254, 177223, 2, '鯪魚肉加入蔥粒、紹興酒、麻油、生粉、鹽及胡椒粉，順同一方向攪拌至起膠。'),
(11255, 177223, 3, '煮滾一鍋水，用匙羮將魚膠勺入水中，煮至浮起水面，盛起備用。'),
(11256, 177223, 4, '將雞湯及清水用中火煮滾。'),
(11257, 177223, 5, '加入冬菇及木耳煮滾，蓋上鍋蓋，轉中小火煮8分鐘。'),
(11258, 177223, 6, '加入素翅、雞胸肉及鯪魚肉，加入老抽、生抽及蠔油拌勻，加入馬蹄粉水拌勻。'),
(11259, 177223, 7, '熄火，加入麻油拌勻，加入蛋液拌勻成蛋花，即成。'),
(11260, 177174, 1, '將番茄及豆腐切件。'),
(11261, 177174, 2, '紅衫魚用廚房紙完全印乾，用少許鹽及胡椒粉醃5分鐘，兩面拍上生粉。'),
(11262, 177174, 3, '用中火燒熱鍋，加少許油，加入薑片炒香。加入紅衫魚煎至兩面金黃色。'),
(11263, 177174, 4, '準備一個大鍋，加入紅衫魚及熱水，用大火煮8-10分鐘。'),
(11264, 177174, 5, '加入豆腐及番茄，蓋上鍋蓋，轉中火煮20分鐘，即成。'),
(11265, 177173, 1, '免治豬肉用生抽、紹興酒、麻油、砂糖、鹽、胡椒粉及生粉醃15分鐘。'),
(11266, 177173, 2, '乾冬菇浸軟切粒；蒜頭及乾蔥切碎備用。將豆腐切片，用中火隔水蒸4分鐘。'),
(11267, 177173, 3, '用中火燒熱鍋，加少許油，加入蒜蓉及乾蔥炒香。'),
(11268, 177173, 4, '加入免治豬肉炒至熟透，加入冬菇炒勻。'),
(11269, 177173, 5, '加入生抽、老抽、砂糖、麻油及1湯匙水炒勻。'),
(11270, 177173, 6, '加入生粉水拌勻，放上豆腐，即成。'),
(11271, 177172, 1, '將油炸鬼切段；蔥切粒。'),
(11272, 177172, 2, '將雞蛋、蔥粒及鹽打發拌勻。'),
(11273, 177172, 3, '用中火燒熱鍋，加少許油，加入蛋液煎熟，用鍋鏟分成3等份，盛起備用。'),
(11274, 177172, 4, '用同一個鍋，加入煙肉煎香，盛起備用。'),
(11275, 177172, 5, '將珍珠米飯鋪上保鮮紙，放上蔥花蛋、煙肉、榨菜絲及油炸鬼，從下往上捲成飯卷。'),
(11276, 177172, 6, '切半，取走保鮮紙，即成。'),
(11277, 177171, 1, '花甲浸在鹽水吐沙30分鐘。'),
(11278, 177171, 2, '將蒜頭及指天椒切碎；蔥切粒。'),
(11279, 177171, 3, '用中火燒熱鍋，加少許油，加入蒜蓉及指天椒炒香。'),
(11280, 177171, 4, '加入花甲炒2分鐘，加入米酒，蓋上鍋蓋煮至花甲開口。'),
(11281, 177171, 5, '加入牛油拌至溶化，灑上蔥粒，即成。'),
(11282, 177170, 1, '將洋蔥切絲，紅蘿蔔及薯仔切粒備用。'),
(11283, 177170, 2, '用中火燒熱鍋，加少許油，加入洋蔥炒香。'),
(11284, 177170, 3, '加入蘋果醬、紅蘿蔔及薯仔煮2-3分鐘。'),
(11285, 177170, 4, '加入1400毫升清水煮滾，蓋上鍋蓋，轉中小火煮20分鐘。'),
(11286, 177170, 5, '加入日本咖哩磚攪拌至溶化。'),
(11287, 177170, 6, '加入烏冬及豬肉煮熟，即成。'),
(11288, 177169, 1, '將豆腐切片；娃娃菜及大蔥切段；竹輪切半；本菇洗淨去蒂備用。'),
(11289, 177169, 2, '煮滾1000毫升水，加入味噌、味醂及鰹魚粉拌勻後煮滾。'),
(11290, 177169, 3, '加入娃娃菜、大蔥、竹輪、豆腐、芋絲、本菇、鮮冬菇及牛肉，蓋上鍋蓋煮10-15分鐘。'),
(11291, 177169, 4, '即成。'),
(11292, 177113, 1, '預熱焗爐至攝氏200度，焗盤鋪上鍚紙備用。'),
(11293, 177113, 2, '在鴨胸皮上界上十字紋，灑上鹽及黑胡椒調味。'),
(11294, 177113, 3, '用中大火燒熱煎鍋，加入鴨胸，鴨胸皮朝下，煎至金黃色，反轉再煎至金黃色。'),
(11295, 177113, 4, '放上焗盤，放入焗爐焗6-8分鐘，切片上碟。'),
(11296, 177113, 5, '將紅酒煮至濃稠，加入紅莓果醬拌勻。'),
(11297, 177113, 6, '熄火，加入無鹽牛油拌勻至溶化，淋在鴨胸上，即成。'),
(11298, 177112, 1, '牛柳用生抽、砂糖、黑胡椒及生粉醃30分鐘。'),
(11299, 177112, 2, '煮滾一鍋水，加少許鹽，加入意粉煮至軟硬適中，撈起瀝乾。'),
(11300, 177112, 3, '用中火燒熱鍋，加少許油，加入牛柳炒至8成熟，盛起備用。'),
(11301, 177112, 4, '用中火燒熱另一個鍋，加入橄欖油及蒜片，不斷攪拌直至蒜片變成金黃色。'),
(11302, 177112, 5, '加入洋蔥及蘆筍炒至軟身，加少許鹽及黑胡椒調味。'),
(11303, 177112, 6, '加入意粉及牛柳炒勻，即成。'),
(11304, 177111, 1, '將乾冬菇浸軟及切片；杏鮑菇及紅尖椒切片；蒜頭拍扁；蔥及芹菜切段備用。'),
(11305, 177111, 2, '將雞腿切件，用2湯匙花雕酒、1湯匙老抽、1湯匙生抽及砂糖醃30分鐘。'),
(11306, 177111, 3, '用中火燒熱鍋，加少許油，加入雞腿煎香，盛起備用。'),
(11307, 177111, 4, '用中火燒熱另一個鍋，轉至小火，加入黑麻油加熱，加入薑片及蒜頭炒香。'),
(11308, 177111, 5, '加入雞腿、杏鮑菇、乾冬菇炒勻。'),
(11309, 177111, 6, '加入餘下的花雕酒、老抽、生抽、蠔油及冰糖，轉至中火煮滾，蓋上鍋蓋煮10分鐘。'),
(11310, 177111, 7, '打開鍋蓋，加入紅尖椒、芹菜及蔥段炒勻，即成。'),
(11311, 177110, 1, '將牛腩浸在室溫水中30分鐘。'),
(11312, 177110, 2, '將牛腩印乾，用啤酒、砂糖、胡椒粉及生粉醃1小時。'),
(11313, 177110, 3, '用中火燒熱鍋，加少許油，加入牛腩煎香。'),
(11314, 177110, 4, '加入栗子、鹌鹑蛋、蒜頭、韓國梨蓉、老抽、冰糖及胡椒粉煮滾，蓋上鍋蓋，轉中小火炆40分鐘。'),
(11315, 177110, 5, '打開鍋蓋，加入紅蘿蔔、白蘑菇及大蔥，蓋上鍋蓋煮5-8分鐘，即成。'),
(11316, 177109, 1, '將雞蛋、鹽及少許油拌勻備用。'),
(11317, 177109, 2, '將和牛漢堡扒中心按下凹痕。'),
(11318, 177109, 3, '用中火燒熱鍋，加少許油，加入和牛漢堡扒，用中高火將兩面煎香。'),
(11319, 177109, 4, '轉中小火，加入水，蓋上鍋蓋，煎焗3分鐘或至熟透，上碟。'),
(11320, 177109, 5, '用中火燒熱另一個鍋，加少許油，加入蛋液，轉至中小火，用筷子快速攪拌蛋液至半熟，輕輕放在白飯上。'),
(11321, 177109, 6, '將牛油煮至溶化，加入紅酒及茄汁拌勻，煮至濃稠，淋在蛋包飯上，即成。'),
(11322, 177104, 1, '預熱焗爐至攝氏200度，焗盤鋪上鍚紙備用。'),
(11323, 177104, 2, '將法國麵包切片，塗上蒜蓉牛油，放上焗盤，焗5分鐘或至金黃色，備用。'),
(11324, 177104, 3, '大蜆浸在鹽水中吐沙30分鐘；蒜頭拍扁；蔥切段備用。'),
(11325, 177104, 4, '用中火燒熱鍋，加少許油，加入蒜頭及洋蔥炒香，加入黃咖哩醬炒香。'),
(11326, 177104, 5, '加入大蜆及米酒炒2分鐘，蓋上鍋蓋煮3分鐘或至大蜆開口。'),
(11327, 177104, 6, '加入青尖椒、紅尖椒、蔥段及花奶煮滾。'),
(11328, 177104, 7, '加入蛋液拌勻成蛋花，加入九層塔葉及魚露拌勻，伴以蒜蓉法包，即成。'),
(11329, 176999, 1, '將雪耳及腰果浸水至軟身。'),
(11330, 176999, 2, '將蘋果及雪梨切件去芯；無花果乾切半備用。'),
(11331, 176999, 3, '準備一個鍋，加入蘋果、雪梨、雪耳、腰果、無花果、蜜棗、南北杏及水。'),
(11332, 176999, 4, '用中高火煮30分鐘，蓋上鍋蓋，轉中小火煮1小時。'),
(11333, 176999, 5, '加入鹽調味，即成。'),
(11334, 176998, 1, '將紅豆洗淨浸過夜；薏米及紅棗洗淨浸水至軟身。'),
(11335, 176998, 2, '煮滾一鍋水，加入薏米及紅豆用大火煮滾，轉中火煮1小時或至軟身。'),
(11336, 176998, 3, '加入紅棗及冰糖煮15分鐘。'),
(11337, 176998, 4, '加入牛奶拌勻，即成。'),
(11338, 177089, 1, '將即食麵及粟米片搗碎。'),
(11339, 177089, 2, '將牛奶朱古力隔水加熱溶化。'),
(11340, 177089, 3, '加入即食麵，拌勻。'),
(11341, 177089, 4, '平鋪在金屬盤上，放入雪櫃雪15分鐘。'),
(11342, 177089, 5, '切件。'),
(11343, 177089, 6, '完成'),
(11344, 176997, 1, '秋葵用鹽搓洗，將上面的毛洗去，洗淨切粒備用。'),
(11345, 176997, 2, '將雞蛋、鹽及少許油打發。'),
(11346, 176997, 3, '用中火燒熱鍋，加少許油，加入蒜蓉及洋蔥炒香。'),
(11347, 176997, 4, '加入秋葵、鮮冬菇及本菇炒勻。'),
(11348, 176997, 5, '加少許鹽調味，加入蛋液炒成滑蛋，即成。'),
(11349, 176996, 1, '煮滾一鍋水，加入薑片、蔥段、紹興酒及沙爆魚肚汆水10分鐘。'),
(11350, 176996, 2, '撈起魚肚，瀝乾切粒備用。'),
(11351, 176996, 3, '將粟米蓉及清水煮滾。'),
(11352, 176996, 4, '加入小元貝及魚肚再煮滾，蓋上鍋蓋煮10分鐘。'),
(11353, 176996, 5, '加入生粉水、鹽及胡椒粉拌勻。'),
(11354, 176996, 6, '加入蛋液拌勻成蛋花，上碟。'),
(11355, 176996, 7, '灑上芫荽，即成。'),
(11356, 176995, 1, '煮滾一鍋水，加入紅棗用中火煮15分鐘。'),
(11357, 176995, 2, '蓋上鍋蓋，用中小火煮30分鐘，熄火焗30分鐘。'),
(11358, 176995, 3, '將400毫升紅棗水及黑糖拌勻，用中小火煮至黑糖溶化。'),
(11359, 176995, 4, '將紅棗打成蓉，可酌量加入清水方便打成蓉，過篩。'),
(11360, 176995, 5, '將600毫升紅棗蓉及黑糖紅棗水拌勻。'),
(11361, 176995, 6, '準備一個碗，加入木薯粉、糯米粉及馬蹄粉，逐少加入黑糖紅棗漿，拌勻至順滑，過篩。'),
(11362, 176995, 7, '蒸模掃上油，倒入粉漿，輕輕震幾次敲出氣泡，蓋上保鮮紙。'),
(11363, 176995, 8, '用中火隔水蒸20-25分鐘，脫模即成。'),
(11364, 37706, 1, '將雞洗淨切件，加入生抽、紹興酒、胡椒粉及鹽醃20分鐘。'),
(11365, 37706, 2, '辣椒乾剪成小段；薑去皮切片；蒜頭切成蓉；芫茜洗淨切段。'),
(11366, 37706, 3, '準備炸油鍋，加入足夠份量的油，加入雞件炸至金黃色及熟透，撈起瀝乾多餘油份備用。'),
(11367, 37706, 4, '用同一個鍋，倒出多餘油份，留下適量的油炒香辣椒乾、花椒、薑蓉及蒜蓉。'),
(11368, 37706, 5, '加入花生炒勻，然後加入雞件快炒。'),
(11369, 37706, 6, '加入白芝麻炒勻，上碟，灑上芫茜段即成。'),
(11370, 37723, 1, '西蘭花切成小朵，洗淨備用。'),
(11371, 37723, 2, '燈籠椒洗淨去籽切粒；西芹洗淨切粒；蒜頭切成蓉。'),
(11372, 37723, 3, '煮滾一鍋水，加入鹽及西蘭花汆水至翠綠色，撈出備用。'),
(11373, 37723, 4, '準備白鑊，加入松子仁炒香，取出。'),
(11374, 37723, 5, '大火燒熱鍋，加少許油，炒香蒜蓉，加入西蘭花及適量水份，煮至西蘭花變軟，取出。'),
(11375, 37723, 6, '大火燒熱同一個鍋加少許油，加入粟米粒、燈籠椒、西芹及松子仁炒勻。'),
(11376, 37723, 7, '加入素蠔油、砂糖及胡椒粉調味。'),
(11377, 37723, 8, '上碟，將西蘭花放在旁邊即成。'),
(11378, 176994, 1, '將雪燕浸過夜及洗淨。'),
(11379, 176994, 2, '將木瓜去皮去籽切件，放入燉盅。'),
(11380, 176994, 3, '加入雪燕、紅棗、冰糖及適量清水。'),
(11381, 176994, 4, '用中小火燉20分鐘，即成。'),
INSERT INTO steps (id, recipe_id, step_number , instruction) VALUES
(12550, 39174, 9, '9.取一平底锅，加热切片面包至上色即可，面包表面抹上芥末酱，放上牛肉片，再放上面包片，用牙签固定对切，搭配卷心菜沙拉和酸黄瓜，享用即成。'),
(12551, 39202, 1, '將紅蘿蔔去皮洗淨，切件；'),
(12552, 39202, 2, '洋蔥切件；'),
(12553, 39202, 3, '雞髀肉洗淨，切件備用；'),
(12554, 39202, 4, '在鍋中加入油，加熱，將洋蔥炒至透明色；'),
(12555, 39202, 5, '加入雞肉炒至上色，放入紅蘿蔔及薯仔快炒1分鐘；'),
(12556, 39202, 6, '加入600毫升水，蓋上鍋蓋，煮滾後撈出泡沫，轉中小火燉熟；'),
(12557, 39202, 7, '加入西蘭花煮1分鐘，熄火；'),
(12558, 39202, 8, '加入奶燉小方塊，煮至完全溶化，開火燉5分鐘至濃稠狀；'),
(12559, 39202, 9, '熄火，上碟，即成。'),
(12560, 39170, 1, '預熱焗爐至攝氏230度，鬆餅模噴上食用噴油。'),
(12561, 39170, 2, '將蛋黃、煉奶及雲呢拿香油拌勻備用。'),
(12562, 39170, 3, '準備一個鍋，加入牛奶、淡忌廉、幼糖、麵粉及焙茶粉，用中低火加熱， 不停攪拌，煮至微滾及濃稠，熄火，繼續攪拌至幼滑。'),
(12563, 39170, 4, '慢慢加入蛋黃混合物拌勻，放入雪櫃冷藏2小時。'),
(12564, 39170, 5, '將每塊酥皮捲成卷狀，分成6份，放入12連圓形鬆餅模壓成撻皮，用叉輕輕在撻底部刺上小孔。'),
(12565, 39170, 6, '放入雪櫃冷藏30分鐘定型備用。'),
(12566, 39170, 7, '倒入蛋漿至8成滿，放入焗爐焗12-15分鐘或直至上色，放涼5分鐘，即成'),
(12567, 39172, 1, '將蝦仁剁碎；馬蹄去皮切粒備用。'),
(12568, 39172, 2, '準備一個碗，將剁碎的蝦肉、馬蹄、墨魚滑、蔥粒、薑蓉、台灣米酒、芝麻油、鹽、砂糖及胡椒粉拌勻，加入15克生粉拌勻。'),
(12569, 39172, 3, '將米紙放入水中浸軟，放在砧板上，鋪上拌好的蝦蓉，捲起，表面沾上餘下的生粉。'),
(12570, 39172, 4, '準備炸油鍋，加入足夠份量的油燒熱，加入蝦卷，用中高火炸至稍微金黃色，撈起；油溫上升後再放入，油炸至金黃色。'),
(12571, 39172, 5, '將海山醬、番茄醬、甜辣醬、蒜蓉及砂糖拌勻，灑上蔥粒，配上蝦卷，即成。'),
(12572, 39165, 1, '製作餅底。鬆餅模放入紙模。將消化餅底碎及無鹽牛油溶液混合，倒入紙模，壓成餅底 。放入雪櫃冷藏30分鐘定型備用；'),
(12573, 39165, 2, '製作豆腐芝士層。用電動打蛋器將淡忌廉打至八成企身。'),
(12574, 39165, 3, '將忌廉芝士及幼糖用電動打蛋器打至幼滑，加入豆腐打至幼滑。'),
(12575, 39165, 4, '將魚膠粉及凍水隔熱水座溶拌勻。'),
(12576, 39165, 5, '豆腐漿加入魚膠粉溶液拌勻，加入已打發的淡忌廉及檸檬汁拌勻，倒入鬆餅模至6成滿，冷藏至少1小時定型備用。'),
(12577, 39165, 6, '製作抹茶芝士。將抹茶粉和牛奶拌勻。'),
(12578, 39165, 7, '將忌廉芝士及幼糖用電動打蛋器打軟，篩入抹茶奶拌勻。'),
(12579, 39165, 8, '用電動打蛋器將淡忌廉打發至八成企身 。'),
(12580, 39165, 9, '將魚膠粉及凍水隔熱水座溶拌勻。'),
(12581, 39165, 10, '忌廉芝士混合物加入魚膠粉溶液拌勻，加入已打起的淡忌廉拌勻，過篩。'),
(12582, 39165, 11, '倒入已凝固的豆腐芝士層上，冷藏至少2小時或直至凝固，即成。'),
(12583, 38844, 1, '魚膠片浸凍水至軟身'),
(12584, 38844, 2, '將淡忌廉及砂糖拌勻煮至微滾，直至砂糖溶化，熄火'),
(12585, 38844, 3, '加入魚膠片拌勻'),
(12586, 38844, 4, '加入檸檬汁及玫瑰花精油拌勻'),
(12587, 38844, 5, '將玫瑰花忌廉倒入玻璃器皿中，放入雪櫃冷藏至凝固'),
(12588, 38844, 6, '加上士多啤梨及乾玫瑰花瓣裝飾'),
(12589, 38844, 7, '即成'),
(12590, 39156, 1, '預熱焗爐至攝氏200度；鬆餅模噴上食用噴油備用；'),
(12591, 39156, 2, '製作煙肉蛋多士：焗盤鋪上牛油紙，放上煙肉，放入焗爐焗 5分鐘，備用；'),
(12592, 39156, 3, '將麵包用圓形模具切成圓塊，放入鬆餅模；'),
(12593, 39156, 4, '將煙肉圍住模邊放在麵包上，加入一隻雞蛋及車厘茄；'),
(12594, 39156, 5, '製作燕麥杯：將燕麥、香蕉蓉、榛子醬及牛奶拌勻成漿狀，倒進鬆餅模，用手指輕輕捏出杯形；'),
(12595, 39156, 6, '製作西蘭花芝士焗蛋：準備一個大碗，將雞蛋打發，加入西蘭花、洋蔥碎、車打芝士、鹽及黑胡椒拌勻。將蛋漿倒進鬆餅模；'),
(12596, 39156, 7, '放入焗爐用攝氏180度焗12-15分鐘至熟透；'),
(12597, 39156, 8, '上碟，在燕麥杯加入乳酪、藍莓及堅果，即成。'),
(12598, 39061, 1, '將蝦仁洗淨抹乾，蝦仁及墨魚仔用檸檬汁、橄欖油、鹽及黑胡椒醃10分鐘；'),
(12599, 39061, 2, '將醃青瓜、紫洋蔥、黃燈籠椒及青燈籠椒切碎，車厘茄一開四備用；'),
(12600, 39061, 3, '用大火燒熱鍋，加少許油，加入海鮮炒熟；'),
(12601, 39061, 4, '準備一個大碗，將海鮮及其他切好配料拌勻；'),
(12602, 39061, 5, '加入橙汁及橄欖油拌勻，加入黑胡椒調味；'),
(12603, 39061, 6, '放入雪櫃冷藏30分鐘，即成。'),
(12604, 39057, 1, '將洋蔥及蒜頭切碎備用；'),
(12605, 39057, 2, '煮滾一鍋水，加入八爪魚仔汆水；'),
(12606, 39057, 3, '將薯仔烚10分鐘至稍軟，撈起放涼；'),
(12607, 39057, 4, '將薯仔切粒；用中火燒熱鍋，加少許橄欖油，加入薯仔粒煎至金黃色，盛起備用；'),
(12608, 39057, 5, '用同一個鍋，加入蒜頭及洋蔥炒香；'),
(12609, 39057, 6, '加入八爪魚仔、薯仔、紅椒粉、檸檬汁及百里香炒勻；'),
(12610, 39057, 7, '加入鹽及黑胡椒調味，灑上番茜碎，即成。'),
(12611, 39140, 1, '將火腿切條，放入杯內，加入雞蛋、牛奶、車打芝士碎、黑胡椒及鹽，蓋上杯蓋，搖勻。'),
(12612, 39140, 2, '將蛋液倒入耐熱密實袋。'),
(12613, 39140, 3, '煮滾一鍋水，轉細火，加入耐熱密實袋慢煮15分鐘，每3分鐘反轉密實袋一次。'),
(12614, 39140, 4, '上碟，即成。'),
(12615, 39099, 1, '焗爐預熱至攝氏200度；將煙肉對半；番茄切片；漢堡包橫切備用；'),
(12616, 39099, 2, '將免治牛肉分成12小份，灑上黑胡椒及海鹽。在砧板上輕輕滾成球狀備用（切勿用力按壓）；'),
(12617, 39099, 3, '將煙肉放上焗盤，放入焗爐焗6分鐘，直至表面金黃色，備用；'),
(12618, 39099, 4, '準備另一個焗盤，放上牛肉球壓成圓餅，放入焗爐焗15分鐘；'),
(12619, 39099, 5, '放上車打芝士片及煙肉，備用；'),
(12620, 39099, 6, '將漢堡包放上焗盤，放入焗爐焗3分鐘，直至表面金黃色；'),
(12621, 39099, 7, '將麵包底部放在砧板上，抹上蛋黃醬及芥末，放上牛肉餅、生菜葉、甜酸青瓜醬及番茄；'),
(12622, 39099, 8, '放上麵包面，用牙籤固定，即成。'),
(12623, 39064, 1, '預熱焗爐至攝氏200度；焗盤鋪上牛油紙備用；將紅燈籠椒、青燈籠椒、紫洋蔥及甘筍切碎備用；'),
(12624, 39064, 2, '用中火燒熱鍋，加少許油，將紅燈籠椒、青燈籠椒、紫洋蔥、甘筍及蒜頭翻炒5分鐘；'),
(12625, 39064, 3, '加入免治牛肉，再炒3分鐘；'),
(12626, 39064, 4, '加番茄醬、鹽及黑胡椒調味，炒勻；'),
(12627, 39064, 5, '將急凍批皮用圓形模具切成直徑9厘米的圓塊；'),
(12628, 39064, 6, '放上餡料及芝士，打摺成半圓狀；'),
(12629, 39064, 7, '用叉在邊緣壓紋；'),
(12630, 39064, 8, '放上焗盤，掃上蛋液；'),
(12631, 39064, 9, '放入焗爐焗15-20分鐘或直至表面金黃色，即成。'),
(12632, 39065, 1, '預熱焗爐至攝氏200度；焗盤鋪上牛油紙備用；將蘑菇去蒂，保留蘑菇蒂；洋蔥及辣肉腸切粒備用；'),
(12633, 39065, 2, '將洋蔥、辣肉腸粒、蘑菇蒂及忌廉芝士用攪拌機攪碎，倒到一個大碗；'),
(12634, 39065, 3, '加入麵包糠及番茜碎拌勻至漿狀；'),
(12635, 39065, 4, '釀入蘑菇，灑上水牛芝士碎及黑胡椒；'),
(12636, 39065, 5, '放入焗爐焗12-15分鐘至表面金黃色，即成。'),
(12637, 39098, 1, '預熱焗爐至攝氏160度；將迷迭香切碎；車厘茄對半；櫻桃蘿蔔切片備用；'),
(12638, 39098, 2, '準備一個焗盤，放入車厘茄，表面刷上少許橄欖油，灑上海鹽、黑胡椒、黃糖及迷迭香；'),
(12639, 39098, 3, '放入焗爐焗55分鐘，直至表面稍微縮水及呈現焦糖狀，靜置備用；'),
(12640, 39098, 4, '預熱焗爐至攝氏200度；準備一個焗盤，用油刷在法包表面刷上橄欖油；'),
(12641, 39098, 5, '放入焗爐焗6分鐘，直至表面金黃色；'),
(12642, 39098, 6, '將忌廉芝士及蔥粒拌勻，抹在焗好的麵包片上，每片麵包放上焗車厘茄，少許巴馬火腿片及櫻桃蘿蔔，即成。'),
(12643, 39063, 1, '預熱焗爐至攝氏180度；焗盤鋪上牛油紙；將法包片兩面掃上橄欖油，放上焗盤，放入焗爐焗6分鐘或直至金黃色；'),
(12644, 39063, 2, '將蝦去頭去殼去腸，保留蝦頭備用。洗淨瀝乾，用鹽及白酒醃10分鐘；'),
(12645, 39063, 3, '將蒜頭切片；辣椒去籽切碎；蝦抹乾備用；'),
(12646, 39063, 4, '用中火燒熱鍋，加入橄欖油，爆香蝦頭，待油顏色轉為帶紅後，取出蝦頭；'),
(12647, 39063, 5, '轉中小火，加入蒜片及辣椒煮12-15分鐘，直至蒜片金黃色；'),
(12648, 39063, 6, '轉中火，加入蝦仁炒至熟透；'),
(12649, 39063, 7, '加鹽、1/2茶匙番茜碎及檸檬汁調味；'),
(12650, 39063, 8, '將蝦放上法包，放上蒜片及灑上番茜碎，即成。'),
(12651, 39040, 1, ''),
(12652, 39040, 2, '預備芒果乳酪醬。芒果起肉，將芒果肉、純乳酪、蜜糖及青檸汁用攪拌器打至軟滑。放入雪櫃冷藏1小時備用；'),
(12653, 39040, 3, '製作窩夫蝦棒。將紫洋蔥、羅勒及百里香切碎備用；'),
(12654, 39040, 4, '將蝦去殼去腸，洗淨瀝乾；'),
(12655, 39040, 5, '用中高火燒熱平底鍋，加入橄欖油。加入蝦仁快炒，加鹽、黑胡椒、百里香及羅勒調味；'),
(12656, 39040, 6, '將牛奶、蛋及菜油拌勻；'),
(12657, 39040, 7, '將粟粉、麵粉、泡打粉、砂糖、百里香、黑胡椒、羅勒及紅椒粉拌勻，再加入牛奶混合物及紫洋蔥粒拌勻；'),
(12658, 39040, 8, '用中高火預熱窩夫機，噴上食用噴油；'),
(12659, 39040, 9, '串起蝦仁，沾上麵糊；'),
(12660, 39040, 10, '在窩夫機中放入蝦串，蓋上窩夫機加熱2-3分鐘或至金黃色；'),
(12661, 39042, 1, '煮沸一鍋水，加適量鹽，加入豆腐汆水3分鐘；'),
(12662, 39042, 2, '豆腐瀝乾後用廚房紙吸乾水份，切粒備用；'),
(12663, 39042, 3, '用高火燒熱鍋，加少許油，炒香薑蒜蓉；'),
(12664, 39042, 4, '加入豬肉翻炒2分鐘，加花椒粉及豆瓣醬炒勻；'),
(12665, 39042, 5, '加入生抽、鹽、砂糖及蔥花拌勻，煮2分鐘，盛起備用；'),
(12666, 39042, 6, '用中高火預熱窩夫機，噴上食用噴油；'),
(12667, 39042, 7, '將豆腐與2/3豬肉拌勻，加入麻油及生粉，逐少加入3湯匙麵包糠拌勻成漿狀；'),
(12668, 39042, 8, '搓成小球，沾上餘下的麵包糠；'),
(12669, 39042, 9, '在窩夫機中放入豆腐球，蓋上窩夫機加熱3分鐘或至金黃色；'),
(12670, 39042, 10, '用中火燒熱鍋，加少許油，將餘下的豬肉略炒，加入生粉水起茨淋上豆腐窩夫。完成。'),
(12671, 39047, 1, '將椰菜切碎，灑上鹽醃30分鐘至出水變軟，瀝乾水分備用；'),
(12672, 39047, 2, '將麵粉及水拌勻備用；'),
(12673, 39047, 3, '製作餡料。將豬肉、椰菜、薑蓉、蔥花、芝麻油、生抽、糖及米醋拌勻；'),
(12674, 39047, 4, '將豬肉餡放在餃子皮上包好；'),
(12675, 39047, 5, '把醬汁材料放入碗中，拌勻備用；'),
(12676, 39047, 6, '燒熱平底鍋，加入豬油至溶化，將餃子排好。用大火加熱後, 倒入麵粉水，蓋上鍋蓋。轉中火煮約10分鐘直至水分蒸發及底部呈現金黃，熄火；'),
(12677, 39047, 7, '灑上白芝麻及蔥花，再蓋上鍋蓋焗1分鐘，取出配以醬汁享用。'),
(12678, 39041, 1, '將椰菜切絲備用；豬肉片撒上鹽調味；中筋麵粉過篩；山藥去皮磨蓉；'),
(12679, 39041, 2, '將蛋、中筋麵粉、山藥泥及鰹魚高湯拌勻；'),
(12680, 39041, 3, '加入椰菜和紅薑絲拌勻；'),
(12681, 39041, 4, '用中高火預熱窩夫機，噴上食用噴油，鋪上豬肉片；'),
(12682, 39041, 5, '在窩夫機中倒入粉漿，蓋上窩夫機加熱5分鐘或至熟透；'),
(12683, 39041, 6, '擠上大阪燒醬和蛋黃醬，灑上紫菜碎及鰹魚片即成。'),
(12684, 39115, 1, '將洋蔥切條；蒜頭切粒；煙肉切塊。'),
(12685, 39115, 2, '準備一個鍋，加入洋蔥、蒜頭、煙肉、車厘茄、螺絲粉、水及鹽。'),
(12686, 39115, 3, '蓋上蓋子，用大火煮滾。'),
(12687, 39115, 4, '攪拌材料，轉細火煮10-15分鐘，直至水份完全蒸發。'),
(12688, 39115, 5, '熄火，加入菠菜拌勻。'),
(12689, 39115, 6, '加入黑胡椒調味。'),
(12690, 39115, 7, '完成。'),
(12691, 39044, 1, '預備抹茶淋醬。在鍋內加入水、幼糖及抹茶粉，煮至抹茶粉溶化，邊煮邊攪拌；'),
(12692, 39044, 2, '加入生粉水拌勻；'),
(12693, 39044, 3, '煮至抹茶汁微滾及幼糖完全溶化，放入雪櫃冷藏備用；'),
(12694, 39044, 4, '低筋麵粉、抹茶粉及泡打粉混合過篩備用；'),
(12695, 39044, 5, '將幼糖加入已打發的蛋輕輕拌勻；'),
(12696, 39044, 6, '將白朱古力和無鹽牛油隔熱水溶化，直到呈軟滑狀，放涼備用；'),
(12697, 39044, 7, '分數次加入蛋液輕輕拌匀；'),
(12698, 39044, 8, '將抹茶麵粉分3-4次拌入混合物，均勻後即可停止以免起筋；'),
(12699, 39044, 9, '加入蜜紅豆輕輕拌勻；'),
(12700, 39044, 10, '用中高火預熱窩夫機，噴上食用噴油；'),
(12701, 39044, 11, '在窩夫機中倒入粉漿至3/4滿，蓋上窩夫機加熱3-4分鐘或至粉漿熟透；'),
(12702, 39044, 12, '上碟，伴以抹茶醬即成。'),
(12703, 37391, 1, '將蟹洗淨，切成4件。'),
(12704, 37391, 2, '薯仔、萵筍及鮮淮山去皮後切條；洋蔥切塊。'),
(12705, 37391, 3, '指天椒切碎；大蔥切段、薑去皮切片；芫茜切段。'),
(12706, 37391, 4, '指天椒切碎；大蔥切段、薑去皮切片；芫茜切段。'),
(12707, 37391, 5, '取一个锅，加入足量的水，放入莴笋，山药，汆水，捞出沥干，备用。'),
(12708, 37391, 6, '取一个锅，加入足量的水，放入莴笋，山药，汆水，捞出沥干，备用。'),
(12709, 37391, 7, '用同一鍋水，加入一半花椒及一半生薑片'),
(12710, 37391, 8, '加入蟹件汆水，撈出瀝乾。'),
(12711, 37391, 9, '蟹件加入粟粉、胡椒粉及鹽醃15分鐘。'),
(12712, 37391, 10, '準備炸鍋，加入足夠份的油，將蟹炸至金黃色，撈出放在廚房紙上吸去多餘油份備用。'),
(12713, 37391, 11, '8. 用同一鍋油，加入薯條炸至金黃色，撈出瀝乾油份備用。'),
(12714, 37391, 12, '9. 用小火燒熱鍋，加少許油，加入指天椒及蒜頭炒香，加入大蔥、餘下的薑、八角、餘下的花椒及洋蔥炒香。'),
(12715, 37391, 13, '放入莴笋、山药、土豆，翻炒3-5分钟。'),
(12716, 37391, 14, '放入豆豉酱、料酒、生抽、糖，翻炒均匀。'),
(12717, 37391, 15, '加入蟹件炒勻，加入水，蓋上鍋蓋用小火煮10分鐘。'),
(12718, 37391, 16, '然後轉大火收汁，加鹽調味，灑上芫茜即成。'),
(12719, 37071, 1, '預熱焗爐至攝氏200度。'),
(12720, 37071, 2, '將蒜頭切片；去骨雞脾洗淨，用廚房紙抹乾水份。'),
(12721, 37071, 3, '雞脾加鹽及黑胡椒醃20分鐘。'),
(12722, 37071, 4, '燒熱一個鍋，加少許油，加入蒜片炒香，加入雞脾煎至兩面金黃色，盛起備用。'),
(12723, 37071, 5, '準備一個碗，加入蜂蜜、芥末、蒜粉及橄欖油拌勻成醬汁。'),
(12724, 37071, 6, '將雞脾放在焗盤上，兩面掃上醬汁，放入焗爐焗5分鐘，翻轉再掃上一次醬汁，再焗5分鐘。'),
(12725, 39039, 1, '將番茜、洋蔥及紫洋蔥切碎備用；'),
(12726, 39039, 2, '預備牛油果醬。牛油果起肉，用匙背壓成蓉，加入紫洋蔥碎、番茜碎、蛋黃醬、青檸汁、鹽及黑胡椒拌勻，放入雪櫃冷藏備用；'),
(12727, 39039, 3, '製作蟹餅。用中火燒熱鍋，加少許油，加入洋蔥碎炒香；'),
(12728, 39039, 4, '將蟹肉、蛋黃、80克麵包糠、洋蔥碎、番茜碎、青檸汁、蛋黃醬、鹽及黑胡椒拌勻，放入雪櫃冷藏1小時；'),
(12729, 39039, 5, '用中高火預熱窩夫機，噴上食用噴油；'),
(12730, 39039, 6, '將蟹肉搓成小球，沾上餘下的麵包糠；'),
(12731, 39039, 7, '在窩夫機中放入蟹肉球，蓋上窩夫機加熱3-4分鐘或至金黃色；'),
(12732, 39039, 8, '伴以牛油果醬即成。'),
(12733, 39038, 1, '將蘑菇、煙肉及洋蔥切粒備用；'),
(12734, 39038, 2, '煮滾一鍋水，加適量鹽，按包裝說明煮熟通心粉，撈出瀝乾水備用；'),
(12735, 39038, 3, '用中火煮溶牛油，加入麵粉拌勻，煮至金黃色；'),
(12736, 39038, 4, '慢慢加入牛奶、英式芥末及肉豆蔻粉，轉慢火；'),
(12737, 39038, 5, '加入車打芝士碎，攪拌至芝士溶化，煮至軟滑，熄火；'),
(12738, 39038, 6, '將蘑菇、煙肉、洋蔥、通心粉與芝士汁拌勻，開火一邊加熱一邊攪拌至漿狀；'),
(12739, 39038, 7, '用中高火預熱窩夫機，噴上食用噴油；'),
(12740, 39038, 8, '在窩夫機中倒入通心粉，蓋上窩夫機加熱5分鐘或至金黃色。'),
(12741, 39045, 1, '準備油條。將中筋麵粉、梳打粉、乾酵母、糖及鹽拌勻；'),
(12742, 39045, 2, '將麵粉加入電動打蛋機，慢慢加入油及暖水拌勻成麵糰後，再攪拌4分鐘；'),
(12743, 39045, 3, '把麵糰放在大碗裡，用保鮮紙包好，放室溫靜置1小時；'),
(12744, 39045, 4, '將麵糰用拳頭拍打15次，放到已抹油的工作台上搓麵糰10分鐘；'),
(12745, 39045, 5, '將麵糰放室溫，再發酵至2倍大，把麵糰輕輕用擀麵棍稍為擀平；'),
(12746, 39045, 6, '刮板表面抹少許油，將麵糰切成長條形（大約2厘米x7厘米），每兩條黏在一起，中間用筷子壓一條直線；'),
(12747, 39045, 7, '準備炸鍋，將麵糰放入炸鍋炸至金黃色；'),
(12748, 39045, 8, '準備卷餅；將青瓜切絲；'),
(12749, 39045, 9, '中火燒熱平底鍋，加入少許油，將蔥油餅煎至兩面金黃色；'),
(12750, 39045, 10, '蔥油餅放在砧板上，掃上適量甜麵醬，依序放入油條、芫茜、青瓜絲、油蔥酥、紅蘿蔔絲及辣菜甫；'),
(12751, 39045, 11, '將蔥油餅卷起，再用牛油紙包好固定，切半即成。'),
(12752, 38843, 1, '預熱焗爐至攝氏180度。製作餅底，將消化餅碎加入牛油溶液拌勻，放在餅模內壓平，備用'),
(12753, 38843, 2, '將白朱古力及士多啤梨朱古力分別隔熱水座溶'),
(12754, 38843, 3, '用電動打蛋器將忌廉芝士、砂糖、檸檬皮、檸檬汁及雲呢拿香油攪拌至幼滑，逐隻蛋加入拌勻'),
(12755, 38843, 4, '將芝士漿平均分成2份，分別加入白朱古力和士多啤梨朱古力拌勻'),
(12756, 38843, 5, '將士多啤梨朱古力芝士漿倒入蛋糕模中，放上一層紅桑莓'),
(12757, 38843, 6, '然後倒入白朱古力芝士漿'),
(12758, 38843, 7, '將蛋糕模放在已加入水的焗盤上，蓋上錫紙，放入焗爐焗30分鐘，移開錫紙再焗20-30或直至表面金黃色，取出放涼'),
(12759, 38843, 8, '放入雪櫃冷藏最少6小時或直至芝士蛋糕凝固'),
(12760, 38843, 9, '切件， 放上紅桑莓裝飾，即成'),
(12761, 39034, 1, '將蒜頭切成蓉，泡菜和洋蔥切粒備用；'),
(12762, 39034, 2, '用中高火預熱窩夫機，噴上食用噴油；'),
(12763, 39034, 3, '將飯、泡菜、水牛芝士碎、蒜蓉、洋蔥粒、韓國辣椒醬、泡菜汁、芝麻油及蔥粒拌勻；'),
(12764, 39034, 4, '搓成飯球，放進窩夫機，蓋上窩夫機加熱3分鐘或至金黃色；'),
(12765, 39034, 5, '用中火燒熱鍋，加少許油，加入雞蛋煎成太陽蛋，放上窩夫；'),
(12766, 39034, 6, '灑上芝麻及紫菜，即成。'),
(12767, 38995, 1, '打發雞蛋，加少許鹽及胡椒粉調味；'),
(12768, 38995, 2, '洋蔥切絲；'),
(12769, 38995, 3, '用中高火燒熱鍋，加少許油，加入蝦仁及帶子炒至金黃色，盛起備用；'),
(12770, 38995, 4, '用同一個鍋，加入洋蔥炒香，加入白飯炒至鬆散；'),
(12771, 38995, 5, '將白飯撥開中間形成一個洞，加入雞蛋炒勻，直至飯粒裹上蛋漿；'),
(12772, 38995, 6, '加入海鮮、泡菜、生抽、麻油及胡椒粉炒勻；'),
(12773, 38995, 7, '灑上蔥粒及白芝麻即成。'),
(12774, 39070, 1, '製作薄餅批底：將高筋粉及中筋粉混合，加鹽拌勻；酵母加暖水拌勻'),
(12775, 39070, 2, '將酵母水倒入麵粉中拌勻，搓揉成光滑的麵糰'),
(12776, 39070, 3, '將麵糰包上保鮮紙，放置直至麵糰發酵至一倍大'),
(12777, 39070, 4, '製作羅勒醬：羅勒摘葉去莖，放入電動攪拌器中'),
(12778, 39070, 5, '加入蒜頭、黑椒、松子、檸檬汁及橄欖油'),
(12779, 39070, 6, '將所有材料用慢速打成醬'),
(12780, 39070, 7, '將巴馬臣芝士刨碎，加入羅勒醬中拌勻'),
(12781, 39070, 8, '組合：預熱焗爐至攝氏180度。蘆筍刨皮及斜切片；菇切片；三色椒切條'),
(12782, 39070, 9, '焗盤鋪上錫紙，將薄餅麵糰擀平放在焗盤上'),
(12783, 39070, 10, '在麵糰上平均抹上羅勒醬，放上蔬菜，再加少許羅勒醬'),
(12784, 39070, 11, '將薄餅放入焗爐焗30分鐘，在薄餅灑上巴馬臣芝士碎，入爐再焗5分鐘即成'),
(12785, 39071, 1, '豬腩肉切片，加少許鹽調味'),
(12786, 39071, 2, '椰菜切絲'),
(12787, 39071, 3, '蟹柳汆水拆絲'),
(12788, 39071, 4, '麵粉過篩'),
(12789, 39071, 5, '用300毫升熱水浸泡鰹魚湯包，大約3至4分鐘'),
(12790, 39071, 6, '山芋去皮磨蓉'),
(12791, 39071, 7, '山芋蓉加入雞蛋，再加入3茶匙鰹魚湯、麵粉、蟹柳及椰菜拌勻'),
(12792, 39071, 8, '燒熱鍋加少許油，加入粉漿'),
(12793, 39071, 9, '煎至稍為成型，蓋上鍋蓋煮一會'),
(12794, 39071, 10, '在燒餅上放上豬腩片'),
(12795, 39071, 11, '將燒餅反轉，煎至豬腩片熟透'),
(12796, 39071, 12, '上碟，掃上大阪燒汁'),
(12797, 39071, 13, '擠上日式蛋黃醬，灑上紫菜碎、飛魚籽及木魚花即成'),
(12798, 39056, 1, '將紅皮薯仔切粒。'),
(12799, 39056, 2, '用中火燒熱鍋，加入牛油，加入洋蔥及蒜片爆香。'),
(12800, 39056, 3, '加入紅皮薯仔，煮10分鐘直至金黃色，間中攪拌。'),
(12801, 39056, 4, '加水，蓋上蓋子，再煮5分鐘直至乾身。'),
(12802, 39056, 5, '加入鹽、黑胡椒及甜椒粉調味。'),
(12803, 39056, 6, '灑上芝士碎。'),
(12804, 39056, 7, '熄火，蓋上蓋子將芝士焗溶，即成。'),
(12805, 38994, 1, '洋蔥切塊；番茄及紅蘿蔔切塊；'),
(12806, 38994, 2, '用中高火燒熱鍋，加少許油及牛油，加入洋蔥及蒜蓉炒香；'),
(12807, 38994, 3, '加入紅蘿蔔、番茄及水，調至中小火，蓋上鍋蓋煮15-20分鐘；'),
(12808, 38994, 4, '加入牛肉片煮至半熟，加入咖喱磚；'),
(12809, 38994, 5, '攪拌至溶化；'),
(12810, 38994, 6, '即成。'),
(12811, 38998, 1, '預熱焗爐至攝氏220度；將檸檬、青檸、橙榨汁備用；'),
(12812, 38998, 2, '將乾蔥、蒜、黃燈籠椒及薑用攪拌機打碎，備用；'),
(12813, 38998, 3, '準備一個碗, 加入荳蔻粉、黑胡椒、海鹽、冧酒、法式芥末、生抽、橄欖油、柑橘汁和乾蔥蓉混合物拌勻；'),
(12814, 38998, 4, '雞肉放入醃料醃一晚；'),
(12815, 38998, 5, '將雞肉放在焗盤上，放上百里香，放入焗爐焗30-40分鐘或直至熟透；'),
(12816, 38998, 6, '將雞胸肉切片，配以番茜、芫茜及檸檬角即成。'),
(12817, 39067, 1, '磨碎腰果及杏仁，備用。'),
(12818, 39067, 2, '磨碎棗、杏仁牛油、可可粉、有機麵粉、奇異籽粉、可可碎粒、螺旋藻粉、瑪卡粉和鹽直至幼滑。'),
(12819, 39067, 3, '加入椰子油後拌勻。'),
(12820, 39067, 4, '加入小紅莓、腰果碎及杏仁碎後拌勻。'),
(12821, 39067, 5, '把混合物倒到盤裡，然後鋪上一張保鮮紙，小心壓平表面及確保角落都填滿。'),
(12822, 39067, 6, '放入雪櫃冷藏4至5小時或一晚。切成條狀後即成。'),
(12823, 38993, 1, '洋蔥切絲；番茄切角；'),
(12824, 38993, 2, '雞腿肉加入薑蓉、生抽、紹興酒、麻油、砂糖及黑胡椒醃20分鐘；'),
(12825, 38993, 3, '雞腿肉沾上一層生粉；'),
(12826, 38993, 4, '用中火燒熱鍋，加少許油，加入雞腿肉煎至金黃色及全熟，盛起備用；'),
(12827, 38993, 5, '用中高火燒熱同一個鍋，加入洋蔥炒香，加入番茄煮至軟腍；加入水、茄汁、砂糖、白醋及生抽；'),
(12828, 38993, 6, '煮至微滾；'),
(12829, 38993, 7, '加入雞腿肉煮5分鐘；'),
(12830, 38993, 8, '灑上蔥粒即成。'),
(12831, 38992, 1, '製作和風沙律汁，將菜油、米醋、日本豉油、洋蔥蓉及砂糖拌勻；'),
(12832, 38992, 2, '煮滾一鍋水，加少許鹽，加入意粉煮至軟硬適中；'),
(12833, 38992, 3, '撈起加入凍水中降溫，撈起瀝乾；'),
(12834, 38992, 4, '三文魚加鹽及黑胡椒調味；'),
(12835, 38992, 5, '用中高火燒熱鍋，加少許油，加入三文魚煎至兩面金黃色，盛起；'),
(12836, 38992, 6, '用叉將三文魚肉拆碎；'),
(12837, 38992, 7, '將三文魚肉、意粉、番茄、粟米粒、和風沙律汁及蔥粒拌勻；'),
(12838, 38992, 8, '灑上白芝麻粒即成。'),
(12839, 38991, 1, '南瓜切片；'),
(12840, 38991, 2, '金菇洗淨切去尾部；'),
(12841, 38991, 3, '將豬肉片鋪平，放上一小束金菇捲起，加鹽及黑胡椒調味；'),
(12842, 38991, 4, '用中高火燒熱鍋，加少許油，加入南瓜煎至兩面金黃色，盛起；'),
(12843, 38991, 5, '用同一個鍋，加入豬肉卷煎至金黃色；'),
(12844, 38991, 6, '在豬肉上面掃上照燒汁，煮至豬肉熟透；'),
(12845, 38991, 7, '即成。'),
(12846, 38996, 1, '用中高火燒熱鍋，加少許油，加入洋蔥炒香；'),
(12847, 38996, 2, '加入牛肉片煮至半熟；'),
(12848, 38996, 3, '加入味醂、清酒、日本豉油及砂糖煮滾；'),
(12849, 38996, 4, '加入白玉菇及豆腐煮10-15分鐘，灑上蔥段；'),
(12850, 38996, 5, '即成。'),
(12851, 38997, 1, '準備一個碗，加入酸忌廉、咖哩粉、1/4茶匙海鹽及1/2個青檸汁拌勻，備用；'),
(12852, 38997, 2, '將鷹嘴豆洗淨瀝乾，蔥切段；用攪拌機將鷹嘴豆、蔥段及少許海鹽打成蓉，備用；'),
(12853, 38997, 3, '將蘿蔔仔、青瓜切薄片，浸水；芫茜切碎；紅蘿蔔刨絲，備用；'),
(12854, 38997, 4, '將鷹嘴豆蓉、熟印度香米、芫茜葉碎、紅蘿蔔絲、麵包糠及1湯匙咖哩酸忌廉醬拌勻；'),
(12855, 38997, 5, '準備一個焗盤，將混合物搓成餅狀，放入雪櫃雪20分鐘至定型，備用；'),
(12856, 38997, 6, '中火燒熱平底鍋，加入少許橄欖油，加入咖喱漢堡扒煎直到兩面金黃色；'),
(12857, 38997, 7, '準備一個碗，加入火箭菜、青瓜、蘿蔔仔、少許橄欖油、餘下青檸汁、海鹽及黑胡椒拌勻；'),
(12858, 38997, 8, '咖喱漢堡扒配上蔬菜沙律，淋上咖哩酸忌廉醬，即成。'),
(12859, 38990, 1, '用中火燒熱鍋，加少許油，加入雞蛋煎成太陽蛋；'),
(12860, 38990, 2, '用中火燒熱同一個鍋，加入午餐肉煎至兩面金黃色；'),
(12861, 38990, 3, '白飯加入飯素拌勻；'),
(12862, 38990, 4, '在枱上平鋪一張保鮮紙，放上紫菜，在紫菜上平均鋪上飯；'),
(12863, 38990, 5, '在飯中間位置，放上生菜葉、太陽蛋、車打芝士片及午餐肉；'),
(12864, 38990, 6, '將紫菜四角向內摺；'),
(12865, 38990, 7, '用保鮮紙包裹；'),
(12866, 38990, 8, '放置5分鐘，切半即成。'),
(12867, 38926, 1, '將紅菜頭放入攪拌機中攪拌成蓉；'),
(12868, 38926, 2, '煮滾一鍋水，加入扁意粉煮至軟硬適中，撈起瀝乾備用；'),
(12869, 38926, 3, '抹乾帶子，加鹽及黑胡椒調味；'),
(12870, 38926, 4, '用高火燒熱鍋，加少許油，加入帶子煎至兩面金黃色，盛起備用；'),
(12871, 38926, 5, '用同一個鍋，加入牛油及橄欖油，加紅菜頭蓉入及少許煮意粉的水煮至微滾；'),
(12872, 38926, 6, '加入扁意粉炒勻，加鹽及黑胡椒調味；'),
(12873, 38926, 7, '上碟，在意粉上放上帶子，灑少許巴馬臣芝士碎及番茜碎，即成。'),
(12874, 38963, 1, '牛油果番茄粟米莎莎熱狗：將番茄、紫洋蔥、粟米粒、青檸汁、芫茜、鹽及黑胡椒拌勻。'),
(12875, 38963, 2, '將青醬塗上熱狗包中，中間加入牛油果片。'),
(12876, 38963, 3, '加入熱狗腸及莎莎。'),
(12877, 38963, 4, '牛油果番茄粟米莎莎熱狗：即成。'),
(12878, 38963, 5, '青瓜蟹柳沙律熱狗：將蟹柳撕碎；青瓜切絲。'),
(12879, 38963, 6, '將蟹柳絲、青瓜絲、芝麻醬及日式蛋黃醬拌勻。'),
(12880, 38963, 7, '熱狗包中間加入熱狗腸及沙律。'),
(12881, 38963, 8, '青瓜蟹柳沙律熱狗：即成。'),
(12882, 38963, 9, 'XO醬吞拿魚熱狗：將吞拿魚、紫洋蔥、XO醬及蛋黃醬拌勻。'),
(12883, 38963, 10, '熱狗包中間加入熱狗腸及XO醬吞拿魚。'),
(12884, 38963, 11, '灑上蔥粒。'),
(12885, 38963, 12, 'XO醬吞拿魚熱狗：即成。'),
(12886, 38925, 1, '預熱焗爐至攝氏180度；紅菜頭放入攪拌機中攪拌成蓉；'),
(12887, 38925, 2, '將雞蛋打發，加入紅菜頭蓉拌勻，加入雲呢拿香油及菜油拌至幼滑；'),
(12888, 38925, 3, '準備一個大碗，加入砂糖，篩入可可粉、低筋粉及泡打粉拌勻；'),
(12889, 38925, 4, '在麵粉中間開個洞，加入紅菜頭蓉慢慢拌勻成粉漿；'),
(12890, 38925, 5, '將粉漿倒入鬆餅模中至3/4滿；'),
(12891, 38925, 6, '放入焗爐焗25-30分鐘或直至金黃色及熟透；'),
(12892, 38925, 7, '取出放涼5分鐘，放在架上放涼至室溫；'),
(12893, 38925, 8, '將牛油打至軟滑，慢慢加入糖霜拌勻至滑溜；'),
(12894, 38925, 9, '慢慢加入牛奶拌勻至忌廉狀，拌入紅菜頭成糖霜；'),
(12895, 38925, 10, '糖霜放入唧袋，唧在鬆餅上即成。'),
(12896, 38935, 1, '檸檬切片備用；'),
(12897, 38935, 2, '將紅石榴洗淨切半，用木勺敲敲外殼直至果肉掉下；'),
(12898, 38935, 3, '用調酒棍將紅石榴果肉搗50下，加入砂糖拌勻；'),
(12899, 38935, 4, '準備一個乾淨的密封罐，將紅石榴果醬放入密封罐，放入雪櫃冷藏備用；'),
(12900, 38935, 5, '玻璃杯中加入冰塊、紅石榴茶醬及蘇打水拌勻，放入檸檬片和薄荷葉，即成；'),
(12901, 38935, 6, '或將熱水倒入茶杯內，加入適量的紅石榴果醬拌勻，放上柠檬片，即成。'),
(12902, 38924, 1, '預熱焗爐至攝氏200度；將紅菜頭洗淨切去頭尾、去皮，然後切塊；'),
(12903, 38924, 2, '紅菜頭放在焗盤中，加入橄欖油、一半百里香、鹽及黑胡椒拌勻；'),
(12904, 38924, 3, '放入焗爐焗30-45分鐘或直至紅菜頭軟腍，取出；'),
(12905, 38924, 4, '將洋蔥、大蔥及西芹切件；'),
(12906, 38924, 5, '燒熱鍋，加入牛油及橄欖油，加入蒜頭、洋蔥、大蔥及西芹炒香；'),
(12907, 38924, 6, '加入紅菜頭煮約5分鐘；'),
(12908, 38924, 7, '加入白酒，然後加入雞湯、餘下的百里香及月桂葉煮滾；'),
(12909, 38924, 8, '調至小火，蓋上鍋蓋煮30分鐘，然後取出百里香及月桂葉；'),
(12910, 38924, 9, '用手提攪拌機中攪拌至幼滑，加入淡忌廉煮至微滾；'),
(12911, 38924, 10, '加鹽及黑胡椒調味；'),
(12912, 38924, 11, '上碟，灑少許橄欖油及番茜碎，即成。'),
(12913, 38923, 1, '用手提攪拌機將急凍桑莓、砂糖、紅菜頭汁及檸檬汁攪拌至幼滑；'),
(12914, 38923, 2, '將混合物倒入雪條模中，插入雪條棍，放入冰箱冷凍5-6小時或直至凝固；'),
(12915, 38923, 3, '朱古力隔熱水座溶， 然後放涼至室溫；'),
(12916, 38923, 4, '將雪條脫模，唧上朱古力，然後灑上食用裝飾；'),
(12917, 38923, 5, '即成。'),
(12918, 38934, 1, '將橙汁及肉桂條煮滾後，放涼備用；'),
(12919, 38934, 2, '將蘋果切粒；橙及檸檬切片，備用；'),
(12920, 38934, 3, '準備一個大玻璃器皿，加入蘋果粒、檸檬片、橙片、黑加侖子及砂糖。用調酒棍擠出果汁；'),
(12921, 38934, 4, '加入橙汁、冧酒及蜜桃香甜酒拌勻；'),
(12922, 38934, 5, '放入適量冰粒，加入紅酒及檸檬梳打，拌勻即成。'),
(12923, 38922, 1, '將青瓜切半去籽；'),
(12924, 38922, 2, '青瓜切條；醃黃蘿蔔切條；'),
(12925, 38922, 3, '將蟹肉加入蛋黃醬、檸檬汁、鹽及黑胡椒；'),
(12926, 38922, 4, '準備另一隻碗，白飯加入紅菜頭汁拌勻；'),
(12927, 38922, 5, '將紫菜放在竹蓆上，將紅菜頭飯平均放在紫菜上；'),
(12928, 38922, 6, '在飯上面加上蟹肉、青瓜及醃黃蘿蔔；'),
(12929, 38922, 7, '將竹蓆捲起成飯卷；'),
(12930, 38922, 8, '切件即成。'),
(12931, 38921, 1, '將意大利黑醋、法式芥末及蜜糖拌勻；'),
(12932, 38921, 2, '慢慢加入初榨橄欖油攪拌至完全混合，加入鹽及黑胡椒調味，成為蜜糖芥末黑醋汁，備用；'),
(12933, 38921, 3, '青瓜去籽後切片；車厘茄切半；'),
(12934, 38921, 4, '紅菜頭切件；'),
(12935, 38921, 5, '將沙律菜、紅菜頭、水牛芝士波、車厘茄及青瓜拌勻；'),
(12936, 38921, 6, '上碟，淋上蜜糖芥末黑醋汁即成。'),
(12937, 38865, 1, '乾蔥切幼粒；蒜頭磨蓉；'),
(12938, 38865, 2, '雞髀肉加入黑啤、蜜糖、蒜蓉、生抽、法式芥末、乾辣椒碎及黑胡椒拌勻；'),
(12939, 38865, 3, '放入雪櫃冷藏醃最少1小時 (醃過夜味道更佳)；'),
(12940, 38865, 4, '用竹籤串起雞髀肉，留起醃料備用；'),
(12941, 38865, 5, '用中高火燒熱鍋，加少許油，加入乾蔥炒香；'),
(12942, 38865, 6, '加入醃料煮滾，稠至中火，煮至醬汁濃稠；'),
(12943, 38865, 7, '用中高火預熱電烤爐；將串燒放在烤架上，在雞髀肉上掃上醬汁；不時反轉串燒及掃上醬汁，直至雞肉熟透；'),
(12944, 38865, 8, '灑上芫茜碎，即成。'),
(12945, 38864, 1, '用中火預熱電烤爐；將菠蘿去皮，切件；'),
(12946, 38864, 2, '用大火將菠蘿汁及黑糖煮滾；調至中火，煮至醬汁濃稠，熄火備用；'),
(12947, 38864, 3, '用豬肉片捲起車厘茄；'),
(12948, 38864, 4, '用竹籤順序串起豬肉卷及菠蘿，灑上鹽及黑胡椒調味；'),
(12949, 38864, 5, '在烤架上放上串燒，不時反轉串燒及掃上菠蘿汁，燒至豬肉金黃色及菠蘿焦糖化；'),
(12950, 38864, 6, '即成。'),
(12951, 39048, 1, '將五花肉放進冷水，用中小火煮熟。'),
(12952, 39048, 2, '煮熟後，將五花肉切成3厘米厚大小。'),
(12953, 39048, 3, '燒熱鍋，加少許油，爆香蔥、薑、蒜和辣椒，然後加入五花肉拌炒。'),
(12954, 39048, 4, '加入兩種生抽，然後加入冰糖和老抽。'),
(12955, 39048, 5, '加入水和紹興酒，要鋪過鍋內的肉，水及酒的比例為1:1。'),
(12956, 39048, 6, '放入滷包，以中火加熱90分鐘即成。'),
(12957, 38902, 1, '將烘焗杏仁、急凍香蕉、1湯匙蜜糖及凍杏仁奶，放入攪拌機打至幼滑；'),
(12958, 38902, 2, '倒入杯中即成；'),
(12959, 38902, 3, '準備一個鍋，加入朱古力奶及即食燕麥煮至稠身；'),
(12960, 38902, 4, '倒入杯中，灑上提子乾即成；'),
(12961, 38902, 5, '準備一個寬口杯，依次序放入粟米片、水蜜桃片及希臘乳酪；'),
(12962, 38902, 6, '淋上少許蜜糖，即成。'),
(12963, 38915, 1, '將粘米粉、澄麵粉及綠茶粉拌勻。'),
(12964, 38915, 2, '加入100毫升水拌勻至沒有顆粒。'),
(12965, 38915, 3, '將餘下的水及黃糖煮溶。'),
(12966, 38915, 4, '趁熱加入粉漿，不停攪拌。'),
(12967, 38915, 5, '倒入小碗裡，用中高火蒸2分鐘直至中間凹陷。'),
(12968, 38915, 6, '加入紅豆，蒸12分鐘直至熟透，熄火，靜置10分鐘，即成。'),
(12969, 38863, 1, '將南薑、香茅及乾蔥切幼粒；'),
(12970, 38863, 2, '將南薑、香茅、乾蔥、青檸汁、冬蔭醬、魚露及砂糖拌勻成醃料；'),
(12971, 38863, 3, '將雞翼洗淨並切半；'),
(12972, 38863, 4, '雞翼加入醃料醃過夜；'),
(12973, 38863, 5, '用中火預熱電烤爐；在烤架盤放上雞翼，不時反轉雞翼燒至金黃色及熟透；'),
(12974, 38863, 6, '即成。'),
(12975, 38988, 1, '大蝦加入適量Cajun粉、鹽及黑胡椒醃一晚。洋蔥切條'),
(12976, 38988, 2, '羅勒摘下葉子'),
(12977, 38988, 3, '燒熱鍋，加少許油，將大蝦煎至兩面金黃色'),
(12978, 38988, 4, '煮滾一鍋水，加入扁意粉煮至軟身'),
(12979, 38988, 5, '在煎蝦的鍋內加入洋蔥及燈籠椒炒熟，加1/2湯匙Cajun粉調味'),
(12980, 38988, 6, '將大蝦取出備用，加入淡忌廉及糖調味'),
(12981, 38988, 7, '加入意粉炒勻'),
(12982, 38988, 8, '加入大蝦及羅勒炒勻即成'),
(12983, 37281, 1, '材料1'),
(12984, 37281, 2, '材料2'),
(12985, 37281, 3, '把蒜，乾蔥，薑，南乳，生抽，蒸酒，南薑，五味粉，八角，雞粉，糖放入攪拌機攪碎成醃料'),
(12986, 37281, 4, '把醃料均勻地塗上雞扒的表面和底部醃1小時。'),
(12987, 37281, 5, '拿出來風乾3小時'),
(12988, 37281, 6, '把上皮料拌勻，在雞皮上塗上薄薄一層'),
(12989, 37281, 7, '把無油炸鍋調至180°C，雞皮向上炸20分鐘，反轉底部再炸10分鐘'),
(12990, 37281, 8, '把雞扒切成小塊，完成'),
(12991, 37281, 9, '木耳浸軟備用'),
(12992, 37281, 10, '甘筍刨皮切絲'),
(12993, 37281, 11, '黃椒和紅椒去籽，切絲'),
(12994, 37281, 12, '蓮藕去皮切片'),
(12995, 37281, 13, '把泡菜，泡菜汁，BB蛋王醬和帕馬森芝士拌勻成醬汁'),
(12996, 37281, 14, '在大碗內把甘荀，蓮藕，黃椒，紅椒，生菜，木耳和醬汁拌勻，完成'),
(12997, 38862, 1, '豬皮及水魷洗淨，瀝乾後切件；'),
(12998, 38862, 2, '乾蔥及蒜頭切幼粒；'),
(12999, 38862, 3, '用中高火燒熱鍋，加少許油，加入洋蔥、乾蔥及蒜頭炒香；'),
(13000, 38862, 4, '加入咖喱醬、花生醬、XO醬、椰奶、蠔油、砂糖、生抽及水拌勻；'),
(13001, 38862, 5, '將醬汁煮至微滾，煮15分鐘，熄火；加入炸豬皮、水魷及炸魚蛋醃過夜；'),
(13002, 38862, 6, '用中高火預熱電烤爐；用竹籤順序串起炸魚蛋、炸豬皮及水魷；'),
(13003, 38862, 7, '在烤架上放上串燒，不時反轉串燒，燒至金黃色及熟透；'),
(13004, 38862, 8, '即成。'),
(13005, 36991, 1, '材料1'),
(13006, 36991, 2, '材料2'),
(13007, 36991, 3, '牛扒切絲，加入醃料醃至少20分鐘或放置過夜亦可。'),
(13008, 36991, 4, '將洋蔥切絲。'),
(13009, 36991, 5, '將一鍋水煮滾，加入長通粉，煮12分鐘，或按包裝指示時間煮至意粉軟硬適中。 撈起備用。'),
(13010, 36991, 6, '用細火熱鍋，加入牛油，炒香蒜蓉及半個洋蔥。'),
(13011, 36991, 7, '加入牛肉炒至半生熟，調至大火炒香。'),
(13012, 36991, 8, '加入長通粉，轉細火，加入剩餘洋蔥、黑橄欖、加水拌勻。'),
(13013, 36991, 9, '加入HP Sauce、喼汁拌勻，加入鹽及黑胡椒調味。'),
(13014, 36991, 10, '上碟後，放上番茜裝飾。可按個人喜好灑上黑胡椒調味'),
(13015, 38861, 1, '用中火預熱電烤爐；清理香茅，並把頭部削尖；'),
(13016, 38861, 2, '將蝦膠、墨魚膠、洋蔥、粟米粒、蛋黃醬、麵包糠、芫茜、紅椒粉、鹽及胡椒粉拌勻；'),
(13017, 38861, 3, '將墨魚蝦膠搓成圓形，包在香茅上；'),
(13018, 38861, 4, '在烤架上掃油，放上香茅串；'),
(13019, 38861, 5, '不時反轉串燒，燒至金黃色及熟透，即成。'),
(13020, 38901, 1, '預熱焗爐至攝氏180度；將花生放上焗盤上焗7分鐘直至金黃色，待涼備用；'),
(13021, 38901, 2, '燒熱白鑊，中小火將白芝麻炒至金黃色，待涼備用；'),
(13022, 38901, 3, '準備一塊矽膠墊，上面抹上少許油，備用；'),
(13023, 38901, 4, '準備一個鍋，加入粟米糖漿、幼糖、海鹽及水，用中小火慢煮4分鐘煮滾，間中搖晃鍋子，不需攪拌；'),
(13024, 38901, 5, '幼糖溶化後，用木勺攪拌，直到糖漿舀起時呈現線狀；'),
(13025, 38901, 6, '加入白芝麻及花生，快速攪拌成球狀，放在矽膠墊上，灑上水果乾，快速用擀麵棍壓成約2厘米厚；'),
(13026, 38901, 7, '冷卻後，切塊。用糯米紙及糖紙將水果糖獨立包好；'),
(13027, 38901, 8, '即成。'),
(13028, 36721, 1, '在饭表面放上虾及蚬，再放入焗炉焗10分钟，直至海鲜焗熟'),
(13029, 36721, 2, '出炉，放上红椒件，洒上番茜碎，伴以柠檬汁享用即成。'),
(13030, 36721, 3, '番茜切碎；洋葱切粒'),
(13031, 36721, 4, '蚬吐沙後洗净；鸡肉切件'),
(13032, 36721, 5, '烧热锅，加少许橄榄油，加入蒜头及洋葱粒炒香，加入米炒匀'),
(13033, 36721, 6, '灒白酒'),
(13034, 36721, 7, '加入西班牙番茄酱'),
(13035, 36721, 8, '加入煮热的鸡/鱼汤，调至高火煮一会，间中搅拌，加盐及黑胡椒调味。加入番红花丝及烟熏甜红椒粉'),
(13036, 36721, 9, '加入鸡肉，然後在饭表面放上西班牙腊肠'),
(13037, 36721, 10, '将锅放入已预热至摄氏180度的焗炉焗5分钟'),
(13038, 38859, 1, '用中火預熱電烤爐；用竹籤串起士多啤梨；'),
(13039, 38859, 2, '水蜜桃去皮去核切塊，用竹籤串起；'),
(13040, 38859, 3, '蛋糕切厚片，兩面抹上牛油；'),
(13041, 38859, 4, '將蛋糕、水蜜桃及士多啤梨放在烤架上；'),
(13042, 38859, 5, '不時反轉，燒至金黃色；'),
(13043, 38859, 6, '上碟，即成。'),
(13044, 36511, 1, '將南瓜去皮、去核、切粒'),
(13045, 36511, 2, '將洋蔥切粒；蒜頭去皮切半'),
(13046, 36511, 3, '燒熱鍋，下少許油，再加入牛油煮至溶'),
(13047, 36511, 4, '加入南瓜，然後加入洋蔥及蒜頭炒至金黃色'),
(13048, 36511, 5, '加入雞湯及水煮滾'),
(13049, 36511, 6, '南瓜軟腍後，將所有材料放入攪拌機中攪拌'),
(13050, 36511, 7, '加鹽及黑胡椒調味，上碟，加上淡忌廉，伴似多士享用'),
(13051, 38858, 1, '煮滾一鍋水，加入新薯煮15分鐘，盛起瀝乾放涼；'),
(13052, 38858, 2, '將新薯切半；'),
(13053, 38858, 3, '燈籠椒去籽及切件；'),
(13054, 38858, 4, '蒜頭去皮拍扁；'),
(13055, 38858, 5, '將百里香及迷迭香切碎；'),
(13056, 38858, 6, '將橄欖油、意大利黑醋、百里香、迷迭香、蒜頭及牛扒香料拌勻成醃料；'),
(13057, 38858, 7, '牛扒粒加入1/2醃料醃30分鐘；'),
(13058, 38858, 8, '用中高火預熱電烤爐；將餘下的醃料加入新薯及燈籠椒中拌勻；'),
(13059, 38858, 9, '用竹籤順序串起新薯、燈籠椒及牛扒；'),
(13060, 38858, 10, '在烤架上放上串燒，不時反轉，直至燒至金黃色，即成。'),
(13061, 36061, 1, '將雞件洗淨後抹乾'),
(13062, 36061, 2, '將大盤放在爐上開火加熱，加入牛油和橄欖油'),
(13063, 36061, 3, '牛油溶化後，加入雞件煎5分鐘至兩面金黃色'),
(13064, 36061, 4, '加鹽拌勻'),
(13065, 36061, 5, '蓋上錫紙煮一會'),
(13066, 36061, 6, '打開錫紙再煮5分鐘，期間將雞件翻轉，將雞件盛起，保留盤中的湯汁'),
(13067, 36061, 7, '將牛油紙濕水，包裹麵包，在麵包上加少許橄欖油及百里香'),
(13068, 36061, 8, '放入焗爐焗10分鐘'),
(13069, 36061, 9, '將乾蔥切粒'),
(13070, 36061, 10, '蘑菇切片'),
(13071, 36061, 11, '乾蔥及蘑菇加入大盤中炒一會'),
(13072, 36061, 12, '加入白酒及雞湯煮成汁'),
(13073, 36061, 13, '加入雞件燴一會'),
(13074, 36061, 14, '在雞件上加入沙律菜及串茄'),
(13075, 36061, 15, '將焗熱的麵包放在盤上一併上菜即成'),
(13076, 38806, 1, '將蛋黃醬、奇妙醬、生抽及芝麻油拌勻成豉油蛋黃醬；'),
(13077, 38806, 2, '韭菜切碎；洋蔥切絲；'),
(13078, 38806, 3, '將叉燒切粒；'),
(13079, 38806, 4, '打發雞蛋，加鹽及胡椒粉調味；'),
(13080, 38806, 5, '用中高火燒熱鍋，加入洋蔥炒香，加入叉燒快炒；'),
(13081, 38806, 6, '倒入蛋液，炒至雞蛋半熟，加入韭菜炒勻，熄火；'),
(13082, 38806, 7, '豬仔包切半，兩面抹上豉油蛋黃醬；'),
(13083, 38806, 8, '放上叉燒炒蛋，即成。'),
(13084, 35881, 1, '把番茄洗淨，挖去內裏的囊'),
(13085, 35881, 2, '把牛肉、洋蔥、芫茜、松子仁混合。打入一隻蛋，再放入胡椒或鹽調味，最後放蔥粒和橄欖油，也可加入迷迭香增加香味。可加入一匙麵粉增加材料稠度'),
(13086, 35881, 3, '在烤盤內塗上牛油，灑上蒜瓣和紅蔥頭'),
(13087, 35881, 4, '把拌好的食材釀入番茄'),
(13088, 35881, 5, '蓋好番茄，灑上麵包糠，再塗上牛油和灑少量橄欖油和鹽'),
(13089, 35881, 6, '把番茄放入烤盤並烤約20分鐘取出即可'),
(13090, 38805, 1, '椰菜及紫洋蔥切成幼絲；'),
(13091, 38805, 2, '煮滾一鍋水，加鹽，加入龍蝦煮至熟透；'),
(13092, 38805, 3, '撈起龍蝦，浸入冰水中，瀝乾後去殼；'),
(13093, 38805, 4, '將龍蝦肉切成小粒；'),
(13094, 38805, 5, '將日式蛋黃醬、檸檬汁、辣椒仔辣汁、甜椒粉、鹽及黑胡椒拌勻；'),
(13095, 38805, 6, '龍蝦肉加入椰菜、紫洋蔥及沙律醬拌勻；'),
(13096, 38805, 7, '用中火燒熱鍋，加入牛油，加入麵包煎至兩面金黃色；'),
(13097, 38805, 8, '將龍蝦沙律放在2片麵包中，灑上法蔥粒即成。'),
(13098, 38840, 1, '將鷹嘴豆洗淨瀝乾備用；車厘茄用攪拌機打成蓉備用；'),
(13099, 38840, 2, '將洋蔥切粒；蒜頭切成蓉；芫茜切碎備用；'),
(13100, 38840, 3, '加熱平底鍋，加入少許油，加入蒜蓉、薑蓉及洋蔥粒炒至金黃色；'),
(13101, 38840, 4, '加入鷹嘴豆快炒2分鐘，加入雞湯、車厘茄蓉及茄膏煮滾；'),
(13102, 38840, 5, '加入印度綜合香料及咖哩粉煮至濃稠，加入砂糖及海鹽調味；'),
(13103, 38840, 6, '配上煮熟的印度香米，用芫茜裝飾，即成。'),
(13104, 35511, 1, '洋蔥及薯仔去皮後切塊；甘筍去皮後切件'),
(13105, 35511, 2, '牛肉及青蘋果切粒'),
(13106, 35511, 3, '燒熱鍋加少許橄欖油，加入洋蔥、薯仔及甘筍炒香'),
(13107, 35511, 4, '當洋蔥開始變透明，加入牛肉粒翻炒'),
(13108, 35511, 5, '當牛肉表面開始熟時，加入牛奶及水煮滾'),
(13109, 35511, 6, '加入咖喱磚煮至溶化，不時攪拌'),
(13110, 35511, 7, '加入青蘋果粒煮滾'),
(13111, 35511, 8, '熄火後加入蜜糖拌勻'),
(13112, 38799, 1, '將豬扒用刀背拍鬆，加入紹興酒、生抽、砂糖、生粉及麻油醃20分鐘；'),
(13113, 38799, 2, '番茄及青瓜切片；'),
(13114, 38799, 3, '將蛋黃醬、蘋果醬及法式芥末拌勻，放入雪櫃冷藏30分鐘；'),
(13115, 38799, 4, '用中火燒熱鍋，加少許油，將豬扒煎至金黃色及熟透；'),
(13116, 38799, 5, '將菠蘿包打橫切半，兩面抹上蘋果芥末醬；'),
(13117, 38799, 6, '在菠蘿包上放上生菜葉，然後放上番茄、青瓜、豬扒及菠蘿；蓋上另一半菠蘿包，即成。'),
(13118, 38870, 1, '將牛油分別放在3個碗裡，放置室温軟化，攪拌至稍為鬆發。'),
(13119, 38870, 2, '分別加入迷迭香、黑松露醬及楓糖漿，拌勻。'),
(13120, 38870, 3, '將牛油紙鋪平，放上迷迭香牛油捲起，扭實兩邊牛油紙。重覆以上步驟捲起黑松露牛油及楓糖漿牛油。'),
(13121, 38870, 4, '將牛油放入雪櫃冷藏至凝固，即成。'),
(13122, 38795, 1, '預熱焗爐至攝氏200度；製作南瓜忌廉芝士醬，將南瓜蒸至軟腍後放涼；'),
(13123, 38795, 2, '將忌廉芝士、南瓜、砂糖及肉桂粉拌勻，放入雪櫃冷藏1小時；'),
(13124, 38795, 3, '番茄切成2厘米厚片，焗盤上放上牛油紙，然後放上番茄；'),
(13125, 38795, 4, '將蒜頭稍微壓碎，放在番茄上，灑上百里香、鹽、黑胡椒及橄欖油；'),
(13126, 38795, 5, '放入焗爐焗30-45分鐘直至番茄汁焗至金黃色；'),
(13127, 38795, 6, '將百吉圈打橫切半，抹上南瓜忌廉芝士醬；'),
(13128, 38795, 7, '放上番茄、酸青瓜，即成。'),
(13129, 39072, 1, '將蔥切粒'),
(13130, 39072, 2, '將小菜心及香脆花瓜瀝乾後切碎'),
(13131, 39072, 3, '免治豬肉加入小菜心和香脆花瓜拌勻'),
(13132, 39072, 4, '加入小菜心剩下的醬油拌勻'),
(13133, 39072, 5, '加入蔥粒、蛋白、胡椒粉、醬油拌勻'),
(13134, 39072, 6, '將肉餅放在碟內鋪平，中間挖個洞，放入蛋黃'),
(13135, 39072, 7, '大同電鍋內放入蒸架，放入肉餅，加1量杯水，蓋上鍋蓋，按鍵開始煮'),
(13136, 39072, 8, '煮至鍋掣跳至保溫即可取出，灑少許蔥粒裝飾即成'),
(13137, 38832, 1, '將西蘭花切粒；洋蔥切絲；紅蘿蔔滾刀切件備用；'),
(13138, 38832, 2, '準備一個碗，加入老抽、日本米酒、蠔油、味噌、砂糖及黑胡椒拌勻備用；'),
(13139, 38832, 3, '加熱平底鍋，加入牛油煮溶，加入洋蔥絲及紅蘿蔔快炒3分鐘；'),
(13140, 38832, 4, '加入雞湯及醬汁煮滾，加入肥牛片；'),
(13141, 38832, 5, '加入西蘭花煮1分鐘，撈起放入碗裡；'),
(13142, 38832, 6, '將收汁的牛肉放入碗裡，灑上白芝麻及蔥花裝飾，即成。'),
(13143, 38790, 1, '將蒜粉、洋蔥粉、紅椒粉、乾奧勒岡、甜椒粉、鹽及黑胡椒拌勻成Cajun粉；'),
(13144, 38790, 2, '蝦仁灑上Cajun粉醃5分鐘；'),
(13145, 38790, 3, '將紫洋蔥、西芹及番茄切粒；'),
(13146, 38790, 4, '用中高火燒熱鍋，加少許油，將蝦煎約2-3分鐘至金黃色，盛起放涼；'),
(13147, 38790, 5, '將蝦仁、紫洋蔥、西芹、番茄、水瓜柳、蛋黃醬、檸檬汁、鹽及黑胡椒拌勻；'),
(13148, 38790, 6, '將牛角包打橫切半，放上九芽菜及蝦仁；'),
(13149, 38790, 7, '灑上法蔥粒即成。'),
(13150, 38789, 1, '預熱焗爐至攝氏180度；瀝乾番茄乾及切碎；'),
(13151, 38789, 2, '將忌廉芝士、番茄乾、全籽芥末醬及蜜糖拌勻成番茄乾醬；'),
(13152, 38789, 3, '番茄切片；紫洋蔥切圈；'),
(13153, 38789, 4, '焗盤上放上牛油紙，放上一堆燒牛肉；'),
(13154, 38789, 5, '在燒牛肉上面加上2片芝士，焗至芝士稍為溶化；'),
(13155, 38789, 6, '將意大利香草包打橫切半，抹上番茄乾醬；'),
(13156, 38789, 7, '將生菜葉放在一片香草包上，加上番茄、紫洋蔥及芝士燒牛肉；'),
(13157, 38789, 8, '放上另一片香草包，即成。'),
(13158, 38723, 1, '免治豬肉加入紅蘿蔔、蛋白、蒜蓉、薑汁、紹興酒、蠔油、粟粉、砂糖、鹽、胡椒粉、蔥粒及芫茜碎拌勻；'),
(13159, 38723, 2, '將雞蛋打發，加入鹽及胡椒粉調味；'),
(13160, 38723, 3, '用中火燒熱鍋，加少許油，在鍋中加入一勺蛋液，煎成蛋皮；重覆以上步驟，將所有蛋液煎成蛋皮；'),
(13161, 38723, 4, '將蛋皮鋪在枱上，平均鋪上免治豬肉餡，蛋皮頂端預留1/2吋；'),
(13162, 38723, 5, '從底部開始向上捲起，蒸20分鐘或直至豬肉熟透；'),
(13163, 38723, 6, '切件即成。'),
(13164, 38722, 1, '將韓式辣椒醬及蛋黃醬拌勻；'),
(13165, 38722, 2, '將蛋打發，加鹽及胡椒粉調味；'),
(13166, 38722, 3, '煮滾一鍋水，加入韓式粉絲煮至軟腍，撈起瀝乾備用；'),
(13167, 38722, 4, '用中火燒熱鍋，加少許油，加入一勺蛋液煎成蛋皮；'),
(13168, 38722, 5, '重覆以上步驟，將所有蛋液煎成蛋皮，盛起放涼；'),
(13169, 38722, 6, '用同一個鍋，加少許油，加入洋蔥炒香，加入紅蘿蔔、三色椒、菠菜及韓式粉絲拌勻；'),
(13170, 38722, 7, '加入生抽、砂糖及芝麻油拌勻，盛起備用；'),
(13171, 38722, 8, '在竹蓆上放上蛋皮，然後放上紫菜；中間加入韓式粉絲；'),
(13172, 38722, 9, '捲起竹蓆後，將蛋卷切件；'),
(13173, 38722, 10, '灑上白芝麻粒，配上香辣蛋黃醬，即成。'),
(13174, 38780, 1, '準備一個碗，塗上橄欖油，備用；'),
(13175, 38780, 2, '煮滾一鍋水，加入適量鹽，加洗淨的菠菜煮1分鐘，撈出瀝乾，放入冰水備用；'),
(13176, 38780, 3, '將菠菜切碎，蘑菇切粒，放入碗裡，加入橄欖油、鹽及黑胡椒，拌勻備用；'),
(13177, 38780, 4, '將蘑菇及菠菜均勻鋪在碗裡，打入雞蛋，灑上少許橄欖油、番茜碎、海鹽及黑胡椒；'),
(13178, 38780, 5, '用保鮮紙包好，放入微波爐加熱5分鐘；'),
(13179, 38780, 6, '灑上黑醋，即成。'),
(13180, 38808, 1, '香橙沙冰（不用攪拌機）：切開鮮橙，留一片橙肉作裝飾用，其他撕成果粒。將果粒加到橙汁中，拌勻。'),
(13181, 38808, 2, '將混合物倒入密實袋，擠出空氣，封口。'),
(13182, 38808, 3, '放入雪櫃，雪至完全結冰。靜置5-10分鐘。'),
(13183, 38808, 4, '用手弄碎後唧入杯中。'),
(13184, 38808, 5, '加上預留的橙肉片裝飾，即成。'),
(13185, 38808, 6, '花冰蜂蜜綠茶：將玫瑰花及桂花放入冰格，加入水，放入雪櫃雪至完全結冰。'),
(13186, 38808, 7, '將綠茶茶葉倒入茶壺，加入熱水泡開至適合濃度。'),
(13187, 38808, 8, '將茶葉隔開，加入蜂蜜拌勻，靜置降溫至室溫。'),
(13188, 38808, 9, '將冰粒加入杯裡，加入蜂蜜綠茶，即成。'),
(13189, 38818, 1, '煮滾一鍋鹽水，加入蔥段、薑片及雞翼；水滾後轉小火，將雞翼浸熟，放涼備用；'),
(13190, 38818, 2, '將紅蔥頭切碎；'),
(13191, 38818, 3, '中火燒熱鍋，加油炒香紅蔥頭；'),
(13192, 38818, 4, '加入白米炒勻；'),
(13193, 38818, 5, '加入雞湯及少許浸雞鹽水；'),
(13194, 38818, 6, '將香茅拍扁；'),
(13195, 38818, 7, '將香茅、班蘭葉加入米飯；'),
(13196, 38818, 8, '蓋上蓋煮至飯熟透；'),
(13197, 38818, 9, '淋上泰式黑醬油拌食。'),
(13198, 38720, 1, '芒果切半，切出果肉；'),
(13199, 38720, 2, '將芒果肉放入攪拌機攪拌至幼滑；'),
(13200, 38720, 3, '將蛋黃醬、芒果汁及蜜糖拌勻成芒果蛋黃醬，放入雪櫃冷藏1小時；'),
(13201, 38720, 4, '將蒜蓉、青檸皮、青檸汁、蜜糖、橄欖油、紅椒粉、鹽及黑胡椒拌勻；'),
(13202, 38720, 5, '加入蝦仁醃1小時；'),
(13203, 38720, 6, '將米洗淨，放入電飯煲中，加入椰奶及適量水，按鍵將米煮熟；'),
(13204, 38720, 7, '用中火燒熱鍋，加少許油，加入蝦仁每邊煎約2分鐘直至金黃色，備用；'),
(13205, 38720, 8, '椰漿飯煮熟後，加入芫茜碎拌勻；'),
(13206, 38720, 9, '在墨西哥薄餅上放上芒果蛋黃醬、椰漿飯、蝦仁、番茄及再唧上芒果蛋黃醬；'),
(13207, 38720, 10, '將墨西哥薄餅捲起即成。'),
(13208, 38719, 1, '將雞蛋分開打入碗中；'),
(13209, 38719, 2, '煮滾一鍋水，加入少許白醋；'),
(13210, 38719, 3, '用匙羮在水中打圈造成漩渦，慢慢加入雞蛋煮2-3分鐘成水波蛋；'),
(13211, 38719, 4, '取出水波蛋，放在廚房紙上吸去多餘水份。重覆以上步驟煮另一隻蛋；'),
(13212, 38719, 5, '牛油果切半去核；'),
(13213, 38719, 6, '用匙羮將牛油果肉中間部份取出，將水波蛋放在牛油果上，蓋上另一半牛油果；'),
(13214, 38719, 7, '用2片煙肉垂直包裏牛油果，然後用1片煙肉打橫包裏牛油果；'),
(13215, 38719, 8, '燒熱鍋，加少許油，加入煙肉牛油果煎至金黃色及脆身；'),
(13216, 38719, 9, '即成。'),
(13217, 38718, 1, '將水果黄瓜及黃蘿蔔切條；將蟹柳切半；'),
(13218, 38718, 2, '煮滾一鍋水，加入蕎麥麵煮至軟腍；'),
(13219, 38718, 3, '撈起蕎麥麵過冷河，瀝乾備用；'),
(13220, 38718, 4, '在竹蓆上放上紫菜，中間放上蕎麥麵；'),
(13221, 38718, 5, '加上蟹柳、青瓜及黃蘿蔔；'),
(13222, 38718, 6, '將竹蓆捲起成麵卷；'),
(13223, 38718, 7, '切件即成。'),
(13224, 38769, 1, '將南薑切片；椰菜切幼絲；指天椒切粒，備用；'),
(13225, 38769, 2, '將鴨髀洗淨瀝乾水份，用鹽搓鴨皮表面醃一晚，備用；'),
(13226, 38769, 3, '將蒜頭、紅蔥頭、南薑片、陳皮、八角、小茴香、黑胡椒，芫荽籽粉及肉桂粉放入湯袋；'),
(13227, 38769, 4, '準備一個湯鍋，加入水、鴨髀、調味料湯袋、老抽、生抽及雞湯煮滾，轉中小火，蓋上鍋蓋，燜煮1.5小時；'),
(13228, 38769, 5, '準備蘸醬。將蒜蓉、指天椒粒、蜜糖、白醋及蔥花拌勻，備用；'),
(13229, 38769, 6, '將鴨髀及椰菜絲上碟，灑上芫荽，配上蘸醬，即成。'),
(13230, 38717, 1, '將日式蛋黃醬和士拉差辣椒醬拌勻；'),
(13231, 38717, 2, '加入唧袋中，放入雪櫃冷藏30分鐘；'),
(13232, 38717, 3, '將雞蛋打發，加鹽及胡椒粉調味；'),
(13233, 38717, 4, '將紫菜切成稍為比煎鍋小的大小；'),
(13234, 38717, 5, '用中火燒熱鍋，掃少許油；'),
(13235, 38717, 6, '加入一層薄薄的蛋漿，煎成蛋皮；'),
(13236, 38717, 7, '放上紫菜及芝士片；'),
(13237, 38717, 8, '由上而下捲成蛋卷，將推卷推到上方。加入另一層薄薄的蛋漿，捲成蛋卷，將推卷推到上方；'),
(13238, 38717, 9, '加入另一層薄薄的蛋漿，加上紫菜及芝士片，加入最後一層蛋漿，捲成蛋卷；'),
(13239, 38717, 10, '切件上碟；'),
(13240, 38717, 11, '唧上蛋黃醬及香辣蛋黃醬，即成。'),
(13241, 37780, 1, '魚膠片浸在凍水中至軟身。'),
(13242, 37780, 2, '小紅莓汁加入砂糖用小火煮至砂糖溶化。'),
(13243, 37780, 3, '加入已浸軟的魚膠片拌勻，倒入傾斜放置的玻璃杯中。'),
(13244, 37780, 4, '將4粒士多啤梨切粒，加入小紅莓汁中，放入雪櫃2小時凝固成啫喱。'),
(13245, 37780, 5, '餘下的士多啤梨加入糖粉用攪拌器攪碎。'),
(13246, 37780, 6, '將淡忌廉打發至七成挺身，加入士多啤梨汁拌勻。'),
(13247, 37780, 7, '在啫喱上唧上士多啤梨忌廉。'),
(13248, 37780, 8, '將甜忌廉打發至挺身，唧在上面，加上士多啤梨、士多啤梨餅乾條 及薄荷葉裝飾即成。'),
(13249, 38653, 1, '預熱焗爐至攝氏170度；將雞洗淨抹乾；將蒜瓣拆開但不要去皮；'),
(13250, 38653, 2, '將雞放在焗盤上，取一半牛油在雞表面抹勻，然後灑上粗鹽及黑胡椒調味；'),
(13251, 38653, 3, '將蒜瓣放在雞隻底部及旁邊；'),
(13252, 38653, 4, '在焗盤上榨出橙汁，並在盤內加入一半份量的水；'),
(13253, 38653, 5, '入爐焗30分鐘；'),
(13254, 38653, 6, '將雞取出，在雞表面掃上盤上的醬汁，再入爐焗30分鐘；'),
(13255, 38653, 7, '將餘下的牛油在雞表面抹勻，並加入餘下的水；'),
(13256, 38653, 8, '再入爐焗30分鐘直至雞皮香脆及雞肉熟透；'),
(13257, 38653, 9, '將雞取出放置20分鐘，盛起醬汁；'),
(13258, 38653, 10, '將蒜瓣去皮後放入鍋中，用中火加熱；'),
(13259, 38653, 11, '灑上中筋粉拌勻，加入雞汁拌勻，直至醬汁滑溜無顆粒；'),
(13260, 38653, 12, '焗雞伴以醬汁享用即成。'),
(13261, 38650, 1, '蒜頭去皮；將其中2粒磨蓉，備用；'),
(13262, 38650, 2, '將米洗淨，放入電飯煲中，加水浸15分鐘；'),
(13263, 38650, 3, '加入餘下原粒蒜頭及鰹魚湯料，按鍵將飯煮熟；'),
(13264, 38650, 4, '預熱焗爐至攝氏180度；蒜蓉加入燒汁拌勻；'),
(13265, 38650, 5, '洗淨魷魚，去皮瀝乾；'),
(13266, 38650, 6, '將蒜頭飯釀入魷魚筒內；'),
(13267, 38650, 7, '魷魚筒表面掃上蒜蓉燒汁；'),
(13268, 38650, 8, '放入焗爐焗5分鐘；'),
(13269, 38650, 9, '取出，掃上蒜蓉燒汁，再焗10分鐘或至魷魚熟透；'),
(13270, 38650, 10, '取出切件；'),
(13271, 38650, 11, '擠上日式蛋黃醬，灑上芝麻粒即成。'),
(13272, 38652, 1, '蒜頭去皮切片；'),
(13273, 38652, 2, '排骨加入紹興酒、生抽、蒜蓉、粟粉及胡椒粉醃20分鐘；'),
(13274, 38652, 3, '用中火燒熱鍋，加少許油，加入蒜片炸至金黃色，盛起備用；'),
(13275, 38652, 4, '排骨沾上天婦羅炸粉；'),
(13276, 38652, 5, '用中高火炸至金黃色，撈起放在廚房紙上吸去多餘油份；'),
(13277, 38652, 6, '準備一個鍋，加入橙汁及蜜糖煮至濃稠；'),
(13278, 38652, 7, '加入排骨及炸蒜片拌勻；'),
(13279, 38652, 8, '灑上芝麻粒即成。'),
(13280, 38708, 1, '準備一個碗，加入免治火雞肉、30克帕梅森芝士絲、麵包糠、羅勒葉、百里香、辣椒粉、茴香粉、1湯匙番茜碎及1湯匙蒜蓉，用手拌勻，搓成丸狀，放入冰格冷藏20分鐘，備用；'),
(13281, 38708, 2, '加熱平底鍋，加入適量橄欖油，加入肉丸煎至表面金黃色；'),
(13282, 38708, 3, '加入罐頭車厘茄、茄膏、糖、鹽及黑胡椒拌勻，用中火煮15-20分鐘，直至肉丸熟透，備用；'),
(13283, 38708, 4, '將少許橄欖油、剩下蒜蓉和1湯匙番茜碎拌勻，抹在麵包上；'),
(13284, 38708, 5, '加熱平底鍋，加入少許橄欖油，加入麵包煎至金黃色；'),
(13285, 38708, 6, '將肉丸上碟，灑上餘下的帕梅森芝士絲及番茜碎；'),
(13286, 38708, 7, '配上麵包，即成。'),
(13287, 38738, 1, '準備一個茶壺，加入普洱茶葉及乾菊花。'),
(13288, 38738, 2, '加入熱水，沖泡至適合濃度。'),
(13289, 38738, 3, '將普洱茶葉及菊花撈起，菊花留起備用；將魚膠粉及適量室溫水，攪拌至完全溶化。'),
(13290, 38738, 4, '加入乾桂花、蜂蜜及魚膠溶液，拌勻。'),
(13291, 38738, 5, '準備啫喱模，加入菊花及普洱茶。'),
(13292, 38738, 6, '放入雪櫃雪2小時至凝固。'),
(13293, 38738, 7, '將茶凍脫模，即成。'),
(13294, 38648, 1, '預熱焗爐至攝氏180度；蒜頂打橫切去頂部；'),
(13295, 38648, 2, '將蒜頭放在焗盤上，灑上橄欖油、鹽及黑胡椒；'),
(13296, 38648, 3, '蓋上錫紙，放入焗爐焗45分鐘至1小時，直至蒜頭軟腍及表皮金黃色；'),
(13297, 38648, 4, '取出放涼，將蒜瓣擠出；'),
(13298, 38648, 5, '準備一個碗，加入焗蒜粒壓成蓉，加入牛油拌勻；'),
(13299, 38648, 6, '在法包片上抹上蒜蓉牛油，放入焗爐焗5分鐘至微金黃色；'),
(13300, 38648, 7, '然後放上番茄粒、鹽、黑胡椒及巴馬臣芝士碎；'),
(13301, 38648, 8, '放入焗爐再焗5分鐘至芝士溶化；'),
(13302, 38648, 9, '取出，灑上意大利黑醋醬及番茜碎即成。'),
(13303, 38647, 1, '蒜芯洗淨切粒；'),
(13304, 38647, 2, '用大火煮滾一鍋水，加入雞件；'),
(13305, 38647, 3, '轉至中火煮至微滾，去除浮沫；'),
(13306, 38647, 4, '準備煎鍋，用中火燒熱加入芝麻油。加入白胡椒粒及一半蒜頭炒香；'),
(13307, 38647, 5, '將白胡椒粒及蒜頭加入雞湯中煮45分鐘；'),
(13308, 38647, 6, '將少許雞湯放入攪拌機中，加入餘下的蒜頭及紹興酒攪拌至滑溜，備用；'),
(13309, 38647, 7, '在雞湯中加入粉絲煮至軟身；'),
(13310, 38647, 8, '加入魚露、蒜芯及蒜蓉漿拌勻；'),
(13311, 38647, 9, '即成。'),
(13312, 38646, 1, '大蝦洗淨去腸，抹乾後備用；'),
(13313, 38646, 2, '用中火燒熱鍋，加入芝麻油，將蒜頭炒香；'),
(13314, 38646, 3, '加入大蝦，轉至中高火煮1-2分鐘；'),
(13315, 38646, 4, '加入紹興酒，蓋上鍋蓋煮至蒜頭軟腍及大蝦熟透；'),
(13316, 38646, 5, '加鹽調味；'),
(13317, 38646, 6, '灑上蔥粒及芫茜碎即成。'),
(13318, 38693, 1, '預熱焗爐至攝氏175度，準備一個焗盤（28厘米×20厘米）備用；將蕃薯洗淨去皮切開一半；'),
(13319, 38693, 2, '放入蒸箱蒸40分鐘，直到熟透，壓成蓉，備用；'),
(13320, 38693, 3, '用攪拌機將蕃薯蓉及雪糕混合；'),
(13321, 38693, 4, '加入淡忌廉及酸忌廉拌勻，倒入焗盤，放入焗爐焗30分鐘；'),
(13322, 38693, 5, '將棉花糖放在蕃薯蓉上，每粒相距1厘米；'),
(13323, 38693, 6, '再用攝氏200度的焗爐，焗6分鐘，直到表面金黃色，切片；'),
(13324, 38693, 7, '灑上杏仁片，即成。'),
(13325, 39927, 1, '預熱焗爐至攝氏180度。撕去紅菜頭的葉。'),
(13326, 39927, 2, '用錫紙包裹紅菜頭，放入焗爐焗，每15分鐘檢查一次，直至熟透為止。(大約焗1小時)'),
(13327, 39927, 3, '取出紅菜頭放涼，撕去外皮，切片。'),
(13328, 39927, 4, '製作醬汁，乾蔥去皮及切碎；將薑切幼粒；芫茜切碎。'),
(13329, 39927, 5, '將乾蔥粒、薑、芫茜、壽司醋及蒜蓉拌勻成醬汁。'),
(13330, 39927, 6, '紅菜頭上碟，淋上醬汁即成。'),
(13331, 38645, 1, '蜆浸在鹽水中30分鐘吐沙，瀝乾備用；'),
(13332, 38645, 2, '豆豉洗淨浸水15分鐘；'),
(13333, 38645, 3, '蒜頭、乾蔥切成蓉；紅辣椒切片；'),
(13334, 38645, 4, '將水、蠔油、生抽、砂糖及粟粉拌勻成芡汁；'),
(13335, 38645, 5, '用中火燒熱鍋，加少許油，加入乾蔥、蒜蓉及豆豉炒香；'),
(13336, 38645, 6, '加入蜆煮2-3分鐘；'),
(13337, 38645, 7, '加入紹興酒及芡汁煮至蜆開口及醬汁濃稠；'),
(13338, 38645, 8, '加入紅辣椒及蔥段拌勻即成。'),
(13339, 38584, 1, '將榴槤肉去核；'),
(13340, 38584, 2, '將榴槤肉、牛奶及砂糖拌勻；'),
(13341, 38584, 3, '將淡忌廉打發至挺身；'),
(13342, 38584, 4, '慢慢加入榴槤混合物，拌勻；'),
(13343, 38584, 5, '倒入密封容器；'),
(13344, 38584, 6, '放入冰格冷藏2小時，或直至定型；'),
(13345, 38584, 7, '即成。'),
(13346, 38582, 1, '準備餅底，將消化餅碎及融化牛油拌勻；'),
(13347, 38582, 2, '將拌勻的餅皮材料倒入蛋糕模，壓平，放入雪櫃冷藏30分鐘；'),
(13348, 38582, 3, '準備餡料，將魚膠粉及水拌勻，隔水加熱至魚膠粉至完全融化；'),
(13349, 38582, 4, '將榴槤去核，果肉放入攪拌機稍微攪拌；'),
(13350, 38582, 5, '準備一個碗，加入淡忌廉及砂糖，打至挺身；'),
(13351, 38582, 6, '加入魚膠溶液及榴槤肉，拌勻；'),
(13352, 38582, 7, '將榴槤慕絲倒入焗模中，將模具輕敲枱面令大氣泡消失；'),
(13353, 38582, 8, '用膠刮掃平頂部，放入雪櫃冷藏最少4小時，或直至定型；'),
(13354, 38582, 9, '去模，即成。'),
(13355, 38581, 1, '預熱焗爐至攝氏180度；將牛油、砂糖、蛋黃、中筋麵粉及鹽，用手拌勻至滑身；'),
(13356, 38581, 2, '加入雲呢拿香油及榴槤肉拌勻；'),
(13357, 38581, 3, '枱上灑上少許麵粉，揉壓至麵團表面光滑；'),
(13358, 38581, 4, '用保鮮紙包好麵糰，放入雪櫃冷藏1小時；'),
(13359, 38581, 5, '麵糰蓋上牛油紙，擀成1厘米厚；'),
(13360, 38581, 6, '用曲奇模印曲奇形狀出，放入焗爐焗8-10分鐘或直至金黃色；'),
(13361, 38581, 7, '即成。'),
(13362, 38629, 1, '準備一個大盤，加入益力多。'),
(13363, 38629, 2, '將益力多放入冰格雪3-4小時，直至變冰。'),
(13364, 38629, 3, '將紅蘋果及青蘋果切片，放入鹽水泡浸，以免蘋果片變色。'),
(13365, 38629, 4, '用叉將益力多冰刮成碎冰。'),
(13366, 38629, 5, '將益力多沙冰倒到玻璃杯裡，加入士多啤梨粒、蘋果片及士多啤梨果醬。'),
(13367, 38629, 6, '放上薄荷葉裝飾，即成。'),
(13368, 38630, 1, '將薑去皮切片；燈籠椒及青辣椒切件，備用；'),
(13369, 38630, 2, '將蝦去殼去腸，洗淨瀝乾備用；'),
(13370, 38630, 3, '準備青咖哩醬：將所有材料及少許水，用攪拌機打成蓉，備用；'),
(13371, 38630, 4, '加熱平底鍋，加入橄欖油，加入蝦仁快炒，加入燈籠椒、4湯匙青咖哩醬及椰奶，快炒1分鐘，上碟；'),
(13372, 38630, 5, '灑上番茜碎即成。'),
(13373, 38552, 1, '準備一個碗，加入雞蛋及砂糖拌勻；'),
(13374, 38552, 2, '篩入低筋麵粉及生粉拌勻；'),
(13375, 38552, 3, '慢慢加入牛奶攪拌至沒有顆粒；'),
(13376, 38552, 4, '加入融化牛油拌勻；'),
(13377, 38552, 5, '放入雪櫃冷藏30分鐘；'),
(13378, 38552, 6, '用中低火燒熱平底鍋，掃上一層油，舀一勺麵糊，煎至兩面金黃色；'),
(13379, 38552, 7, '重覆至所有麵糊用完，待涼備用；'),
(13380, 38552, 8, '將榴槤去核，果肉放入攪拌機稍微攪拌；'),
(13381, 38552, 9, '準備一個碗，加入淡忌廉及砂糖，打至挺身；'),
(13382, 38552, 10, '慢慢加入榴槤肉，拌勻；'),
(13383, 38552, 11, '將一塊班戟放在碟上，塗上榴槤忌廉，放上另一塊班戟。重覆至達到理想厚度；'),
(13384, 38552, 12, '用保鮮紙包好，放入雪櫃冷藏最少3小時，或直至定型；'),
(13385, 38552, 13, '切件，即成。'),
(13386, 38627, 1, '將綠色意大利青瓜、洋蔥、大蔥及西芹切件備用；'),
(13387, 38627, 2, '燒滾一鍋水，加入鹽，加入洗淨的菠菜灼熟，瀝乾切碎備用；'),
(13388, 38627, 3, '燒熱平底鍋，加入適量橄欖油、洋蔥、蒜頭及少許海鹽，炒至變軟；'),
(13389, 38627, 4, '加入綠色意大利青瓜及西芹快炒4分鐘，加入雞湯煮2分鐘；'),
(13390, 38627, 5, '將所有材料倒入攪拌機中攪拌至幼滑，倒入湯鍋裡，加熱煮至濃稠，加入海鹽及黑胡椒調味；'),
(13391, 38627, 6, '加入切碎的菠菜煮1分鐘；'),
(13392, 38627, 7, '即成。'),
(13393, 178604, 1, '準備一個鍋，加入清酒、味醂及糖，煮至微滾。'),
(13394, 178604, 2, '加入白味噌攪拌至溶化，熄火。加入鹽麴拌勻。'),
(13395, 178604, 3, '將銀鱈魚及醃料放入密實袋，放入雪櫃醃一晚。'),
